/**
 * Centralised configuration loader — validates all LOOP_* env vars via Zod (§10).
 */

import { z } from 'zod';

/**
 * Correct boolean env-var parser. `z.coerce.boolean()` uses `Boolean(value)`,
 * which treats ANY non-empty string (including "false"/"0") as `true` — a
 * well-known Zod footgun that made e.g. `LOOP_REQUIRE_AUTH=false` enable auth.
 * This helper parses the conventional truthy strings ("true"/"1"/"yes"/"on")
 * as true and everything else (incl. "false"/"0"/"no"/"off"/"") as false,
 * falling back to `def` when the variable is unset.
 */
const booleanEnv = (def: boolean) =>
  z.preprocess((v) => {
    if (v === undefined || v === null || v === '') return def;
    if (typeof v === 'boolean') return v;
    const s = String(v).trim().toLowerCase();
    return s === 'true' || s === '1' || s === 'yes' || s === 'on';
  }, z.boolean());

const configSchema = z.object({
  // §10.1 Core
  LOOP_PORT: z.coerce.number().default(3000),
  LOOP_HOST: z.string().default('0.0.0.0'),
  // Per-IP API rate limit. Self-hosted deployments often serve many users from
  // a shared IP (NAT/office/team server), so the default is generous and fully
  // configurable; set LOOP_RATE_LIMIT_MAX=0 to disable.
  LOOP_RATE_LIMIT_MAX: z.coerce.number().default(1000),
  LOOP_RATE_LIMIT_WINDOW: z.string().default('1 minute'),
  LOOP_LOG_LEVEL: z.enum(['trace', 'debug', 'info', 'warn', 'error', 'fatal']).default('info'),
  LOOP_ENV: z.enum(['development', 'test', 'production']).default('development'),
  LOOP_DATA_DIR: z.string().default('./data'),
  LOOP_ENCRYPTION_KEY: z.string().min(32).default('dev-key-change-me-please-32chars!'),

  // §10.2 Database
  LOOP_DB_TYPE: z.enum(['sqlite', 'postgres']).default('sqlite'),
  LOOP_DB_PATH: z.string().default('./data/loop.db'),
  LOOP_DB_HOST: z.string().optional(),
  LOOP_DB_PORT: z.coerce.number().optional(),
  LOOP_DB_NAME: z.string().optional(),
  LOOP_DB_USER: z.string().optional(),
  LOOP_DB_PASSWORD: z.string().optional(),
  LOOP_DB_SSL: booleanEnv(false),

  // §10.3 Redis (Scale)
  LOOP_REDIS_URL: z.string().optional(),
  LOOP_REDIS_PASSWORD: z.string().optional(),

  // §10.4 Execution engine
  LOOP_MAX_CONCURRENT: z.coerce.number().default(50),
  LOOP_EXECUTION_TIMEOUT_MS: z.coerce.number().default(300_000),
  LOOP_NODE_TIMEOUT_MS: z.coerce.number().default(30_000),
  // V1.1 M1 (F3): workflow-level timeout — bounds an entire execute() run.
  // Falls back to 300s; a per-workflow definition.settings.workflow_timeout_ms
  // overrides this when present.
  LOOP_WORKFLOW_TIMEOUT_MS: z.coerce.number().default(300_000),
  // V1.4 M2 (F-2): size cap (bytes) for the node output persisted into a
  // `node_succeeded` event payload. Oversized outputs are stored as a truncated
  // marker `{__truncated__, size, preview}` so large outputs cannot bloat the
  // append-only execution_events table.
  LOOP_EVENT_OUTPUT_MAX_BYTES: z.coerce.number().default(65_536),
  LOOP_DEFAULT_RETRY_COUNT: z.coerce.number().default(3),
  LOOP_DEFAULT_BACKOFF: z.enum(['exponential', 'linear', 'fixed']).default('exponential'),
  LOOP_DEFAULT_BACKOFF_INITIAL_MS: z.coerce.number().default(1000),

  // §10.5 Sandbox
  LOOP_SANDBOX_TYPE: z.enum(['gvisor', 'firecracker']).default('gvisor'),
  LOOP_SANDBOX_URL: z.string().default('http://localhost:4000'),
  LOOP_SANDBOX_MEMORY_MB: z.coerce.number().default(256),
  LOOP_SANDBOX_CPU_SECONDS: z.coerce.number().default(30),
  LOOP_SANDBOX_POOL_SIZE: z.coerce.number().default(3),

  // §10.6 LLM providers
  // The router tries vendors in LOOP_LLM_FALLBACK_CHAIN order (circuit-broken
  // per vendor). Cloud vendors activate when their key is set; Ollama is
  // always registered (local loopback, no key). Full matrix in docs/AI接入指南.md.
  LOOP_LLM_PRIMARY: z.string().default('ollama'),
  LOOP_LLM_FALLBACK_CHAIN: z.string().default('ollama,openai,anthropic'),
  LOOP_LLM_TIMEOUT_MS: z.coerce.number().default(120_000),
  // Ollama (local, always registered)
  LOOP_LLM_OLLAMA_URL: z.string().default('http://localhost:11434'),
  LOOP_LLM_OLLAMA_MODEL: z.string().optional(),
  // OpenAI
  LOOP_LLM_OPENAI_KEY: z.string().optional(),
  LOOP_LLM_OPENAI_BASE_URL: z.string().optional(),
  LOOP_LLM_OPENAI_MODEL: z.string().optional(),
  // Anthropic (native Messages API)
  LOOP_LLM_ANTHROPIC_KEY: z.string().optional(),
  LOOP_LLM_ANTHROPIC_BASE_URL: z.string().optional(),
  LOOP_LLM_ANTHROPIC_MODEL: z.string().optional(),
  // Google Gemini (native generateContent API)
  LOOP_LLM_GEMINI_KEY: z.string().optional(),
  LOOP_LLM_GEMINI_BASE_URL: z.string().optional(),
  LOOP_LLM_GEMINI_MODEL: z.string().optional(),
  // Azure OpenAI (deployment-based)
  LOOP_LLM_AZURE_ENDPOINT: z.string().optional(),
  LOOP_LLM_AZURE_KEY: z.string().optional(),
  LOOP_LLM_AZURE_MODEL: z.string().optional(),
  LOOP_LLM_AZURE_API_VERSION: z.string().optional(),
  // OpenAI-compatible cloud vendors (DeepSeek / Qwen / Kimi / GLM / Groq / …)
  LOOP_LLM_DEEPSEEK_KEY: z.string().optional(),
  LOOP_LLM_DEEPSEEK_MODEL: z.string().optional(),
  LOOP_LLM_DEEPSEEK_BASE_URL: z.string().optional(),
  LOOP_LLM_QWEN_KEY: z.string().optional(),
  LOOP_LLM_QWEN_MODEL: z.string().optional(),
  LOOP_LLM_QWEN_BASE_URL: z.string().optional(),
  LOOP_LLM_MOONSHOT_KEY: z.string().optional(),
  LOOP_LLM_MOONSHOT_MODEL: z.string().optional(),
  LOOP_LLM_MOONSHOT_BASE_URL: z.string().optional(),
  LOOP_LLM_ZHIPU_KEY: z.string().optional(),
  LOOP_LLM_ZHIPU_MODEL: z.string().optional(),
  LOOP_LLM_ZHIPU_BASE_URL: z.string().optional(),
  LOOP_LLM_SILICONFLOW_KEY: z.string().optional(),
  LOOP_LLM_SILICONFLOW_MODEL: z.string().optional(),
  LOOP_LLM_SILICONFLOW_BASE_URL: z.string().optional(),
  LOOP_LLM_GROQ_KEY: z.string().optional(),
  LOOP_LLM_GROQ_MODEL: z.string().optional(),
  LOOP_LLM_MISTRAL_KEY: z.string().optional(),
  LOOP_LLM_MISTRAL_MODEL: z.string().optional(),
  LOOP_LLM_TOGETHER_KEY: z.string().optional(),
  LOOP_LLM_TOGETHER_MODEL: z.string().optional(),
  LOOP_LLM_XAI_KEY: z.string().optional(),
  LOOP_LLM_XAI_MODEL: z.string().optional(),
  // Local OpenAI-compatible inference servers (enabled when the URL is set)
  LOOP_LLM_VLLM_URL: z.string().optional(),
  LOOP_LLM_VLLM_MODEL: z.string().optional(),
  LOOP_LLM_LMSTUDIO_URL: z.string().optional(),
  LOOP_LLM_LMSTUDIO_MODEL: z.string().optional(),
  // Custom OpenAI-compatible endpoints as a JSON array:
  // [{"name":"myai","base_url":"https://…/v1","api_key":"…","model":"…"}]
  LOOP_LLM_EXTRA_PROVIDERS: z.string().optional(),

  // §10.7 ODW agents
  LOOP_VAULT_URL: z.string().optional(),
  LOOP_VAULT_API_KEY: z.string().optional(),
  LOOP_DESK_URL: z.string().optional(),
  LOOP_DESK_API_KEY: z.string().optional(),
  LOOP_RECAP_URL: z.string().optional(),
  LOOP_RECAP_API_KEY: z.string().optional(),

  // §10.8 Auth
  LOOP_JWT_SECRET: z.string().default('dev-jwt-secret-change-me'),
  LOOP_JWT_ACCESS_TTL: z.string().default('15m'),
  LOOP_JWT_REFRESH_TTL: z.string().default('7d'),
  // When true, /api/v1/* routes require a valid API key or JWT. Defaults to
  // false (open) for backward compatibility — health/ready/metrics/webhooks are
  // always public regardless of this flag.
  LOOP_REQUIRE_AUTH: booleanEnv(false),
  // Static API key accepted via `Authorization: Bearer <key>` or `x-api-key`.
  // Optional: when unset, only JWT bearer tokens authenticate.
  LOOP_API_KEY: z.string().optional(),
  // V1.3 (F-RBAC-Loop): RBAC role mapped to a valid static API key. JWT callers
  // get their role from the `role`/`roles` claim instead. Defaults to `admin`
  // so single-user/dev setups with a static key keep full access.
  LOOP_API_KEY_ROLE: z.enum(['admin', 'editor', 'viewer']).default('admin'),

  // §10.9 Egress
  LOOP_EGRESS_DEFAULT_POLICY: z.enum(['allow', 'deny']).default('deny'),
  LOOP_AIRGAP_MODE: booleanEnv(false),
  // Decision applied when NO egress policies are configured at all. Defaults
  // to 'allow' so a fresh deployment can still call the ODW agents; set to
  // 'deny' (or add policies) to lock a deployment down. Once any policy
  // exists, evaluation is default-deny for non-matching targets.
  LOOP_EGRESS_UNCONFIGURED_POLICY: z.enum(['allow', 'deny']).default('allow'),
  // V1.7 (SSRF hardening): private/reserved targets (loopback/RFC1918/
  // link-local/CGNAT) are ALWAYS rejected when false — including via the
  // unconfigured `allow` short-circuit and via matching allow policies. The
  // ODW suite itself runs its sibling connectors on a private network, so the
  // suite compose files set this to true explicitly.
  LOOP_EGRESS_ALLOW_PRIVATE: booleanEnv(false),
  // V1.7 (L-8): first-admin bootstrap — when set, the login route has a real
  // user to authenticate BEFORE any user management UI exists.
  LOOP_BOOTSTRAP_ADMIN_USERNAME: z.string().optional(),
  LOOP_BOOTSTRAP_ADMIN_PASSWORD: z.string().optional(),
  LOOP_BOOTSTRAP_ADMIN_EMAIL: z.string().optional(),

  // §10.10 Observability
  LOOP_METRICS_ENABLED: booleanEnv(true),
  LOOP_OTEL_ENABLED: booleanEnv(false),
  LOOP_OTEL_ENDPOINT: z.string().optional(),
});

export type LoopConfig = z.infer<typeof configSchema>;

export function loadConfig(): LoopConfig {
  const result = configSchema.safeParse(process.env);
  if (!result.success) {
    console.error('Invalid configuration:', result.error.format());
    process.exit(1);
  }
  const cfg = result.data;

  // Production guardrails (S3): the development defaults are publicly known
  // values — the encryption key derives every secret-at-rest key and the JWT
  // secret lets anyone forge admin tokens. Refuse to boot with them.
  if (cfg.LOOP_ENV === 'production') {
    const fatal: string[] = [];
    if (cfg.LOOP_ENCRYPTION_KEY === 'dev-key-change-me-please-32chars!') {
      fatal.push('LOOP_ENCRYPTION_KEY is still the public development default — every encrypted secret would be readable by anyone');
    }
    if (cfg.LOOP_JWT_SECRET === 'dev-jwt-secret-change-me' && cfg.LOOP_REQUIRE_AUTH) {
      fatal.push('LOOP_JWT_SECRET is still the public development default while LOOP_REQUIRE_AUTH=true — tokens could be forged');
    }
    if (fatal.length > 0) {
      console.error('Refusing to start with insecure configuration (LOOP_ENV=production):');
      for (const line of fatal) console.error(`  - ${line}`);
      process.exit(1);
    }
    if (!cfg.LOOP_REQUIRE_AUTH) {
      console.warn('WARNING: LOOP_REQUIRE_AUTH is disabled while LOOP_ENV=production — every API route is open to the network.');
    }
  }

  return cfg;
}

