/**
 * Authentication + role-based access control (RBAC) guard for the public HTTP
 * API (§11, V1.3 M2 F-RBAC-Loop).
 *
 * Backward-compatible by design: enforcement is gated behind `LOOP_REQUIRE_AUTH`
 * (default false / unset = fully open). When enabled, every `/api/v1/*` request
 * must present either:
 *   - a static API key via `Authorization: Bearer <LOOP_API_KEY>` or `x-api-key`, or
 *   - a valid HS256 JWT (signed with `LOOP_JWT_SECRET`) via `Authorization: Bearer <jwt>`.
 *
 * Roles (V1.3): `admin` > `editor` > `viewer`. The role is resolved from the
 * JWT `role`/`roles` claim, or — for a static API key — from `LOOP_API_KEY_ROLE`
 * (default `admin`, dev-friendly). Routes are guarded by minimum role:
 *   - reads (GET workflows/executions/connectors) → `viewer+`
 *   - writes (POST/PUT/DELETE workflows, POST execute) → `editor+`
 *   - admin routes (`/api/v1/audit`) → `admin`
 * Public endpoints are always exempt: `/health`, `/ready`, `/metrics`, and the
 * webhook entrypoint `/webhooks/*` (webhooks authenticate via their own HMAC).
 *
 * On success the authenticated principal AND role are attached to the request
 * (`request.authPrincipal` / `request.authRole`) so routes can attribute writes
 * and apply explicit `requireRole(min)` guards.
 */

import type { FastifyRequest, FastifyReply } from 'fastify';
import * as jose from 'jose';
import { createHash, timingSafeEqual } from 'node:crypto';
import { AuthenticationError, ForbiddenError } from '@loop/types';
import { createLogger } from '@loop/observability';
import type { LoopConfig } from '../config.js';

/** RBAC roles, ordered by privilege (V1.3 M2). */
export type Role = 'admin' | 'editor' | 'viewer';

/** Numeric privilege ranking used for "minimum role" comparisons. */
const ROLE_RANK: Record<Role, number> = { viewer: 1, editor: 2, admin: 3 };

declare module 'fastify' {
  interface FastifyRequest {
    /** Authenticated principal (user id for JWT, 'system' for a static API key). */
    authPrincipal?: string;
    /** Resolved RBAC role (V1.3). Present only once authentication succeeded. */
    authRole?: Role;
  }
}

const logger = createLogger({ name: 'loop:api:auth', component: 'api' });

/** Path prefixes that are always public, even when auth is enforced. */
const PUBLIC_PREFIXES = ['/health', '/ready', '/webhooks', '/api/v1/auth/login'] as const;

/** The service account a valid static API key authenticates as. */
const API_KEY_PRINCIPAL = 'system';

/** True when a string is a known RBAC role. */
export function normalizeRole(value: unknown): Role | undefined {
  if (value === 'admin' || value === 'editor' || value === 'viewer') return value;
  return undefined;
}

/** True when `actual` satisfies a `min` minimum-role requirement. */
export function roleSatisfies(actual: Role, min: Role): boolean {
  return ROLE_RANK[actual] >= ROLE_RANK[min];
}

/**
 * Resolve an RBAC role from verified JWT claims. Honours a scalar `role` claim
 * first, then an array `roles` claim (highest privilege wins). A JWT with no
 * recognisable role claim defaults to least privilege (`viewer`).
 */
export function roleFromClaims(payload: jose.JWTPayload): Role {
  const direct = normalizeRole(payload['role']);
  if (direct) return direct;

  const roles = payload['roles'];
  if (Array.isArray(roles)) {
    let best: Role | undefined;
    for (const entry of roles) {
      const candidate = normalizeRole(entry);
      if (candidate && (best === undefined || ROLE_RANK[candidate] > ROLE_RANK[best])) {
        best = candidate;
      }
    }
    if (best) return best;
  }

  return 'viewer';
}

/** True when the given request URL targets a protected `/api/v1/*` route. */
export function isProtectedPath(url: string): boolean {
  const path = url.split('?')[0] ?? url;
  if (PUBLIC_PREFIXES.some((p) => path === p || path.startsWith(`${p}/`))) {
    return false;
  }
  return path.startsWith('/api/v1/');
}

/**
 * Minimum role required for a request, or `null` when the route is exempt
 * (public prefixes and non-`/api/v1` paths). Reads need `viewer+`, admin
 * routes need `admin`, and every other write verb needs `editor+`.
 */
export function requiredRoleFor(method: string, url: string): Role | null {
  const path = url.split('?')[0] ?? url;
  if (PUBLIC_PREFIXES.some((p) => path === p || path.startsWith(`${p}/`))) {
    return null;
  }
  if (!path.startsWith('/api/v1/')) return null;

  // Admin-only system routes.
  if (path === '/api/v1/audit' || path.startsWith('/api/v1/audit/')) {
    return 'admin';
  }

  const verb = method.toUpperCase();
  if (verb === 'GET' || verb === 'HEAD') return 'viewer';
  return 'editor'; // POST / PUT / DELETE / PATCH
}

/** Extract a bearer token from the Authorization header, if present. */
function extractBearer(request: FastifyRequest): string | undefined {
  const header = request.headers['authorization'];
  if (typeof header === 'string' && header.toLowerCase().startsWith('bearer ')) {
    const token = header.slice(7).trim();
    return token.length > 0 ? token : undefined;
  }
  return undefined;
}

/**
 * Constant-time string comparison (L2). Both sides are hashed first so the
 * comparison length is fixed and no length leak reveals a prefix of the key.
 */
function secretsEqual(a: string, b: string): boolean {
  const ha = createHash('sha256').update(a).digest();
  const hb = createHash('sha256').update(b).digest();
  return timingSafeEqual(ha, hb);
}

/** An authenticated identity: who the caller is plus their RBAC role. */
interface Identity {
  principal: string;
  role: Role;
}

/**
 * Resolve the authenticated identity (principal + role) from the request
 * credentials. Returns null when no presented credential is valid.
 */
async function resolveIdentity(
  request: FastifyRequest,
  apiKey: string | undefined,
  apiKeyRole: Role,
  jwtSecret: Uint8Array,
): Promise<Identity | null> {
  const headerKey = request.headers['x-api-key'];
  const bearer = extractBearer(request);

  // 1. Static API key (x-api-key header or bearer token matching the key).
  const presentedKey =
    (typeof headerKey === 'string' && headerKey.length > 0 ? headerKey : undefined) ?? bearer;
  if (presentedKey && apiKey && secretsEqual(presentedKey, apiKey)) {
    return { principal: API_KEY_PRINCIPAL, role: apiKeyRole };
  }

  // 2. JWT bearer token.
  if (bearer) {
    try {
      const { payload } = await jose.jwtVerify(bearer, jwtSecret);
      if (typeof payload.sub === 'string' && payload.sub.length > 0) {
        return { principal: payload.sub, role: roleFromClaims(payload) };
      }
    } catch {
      // Not a valid JWT — fall through to reject.
      logger.debug('Bearer token failed JWT verification');
    }
  }

  return null;
}

/**
 * Resolve a principal from a single presented token (V1.1 M2, F5).
 *
 * Used by transports that cannot use the full header-based flow — notably the
 * `GET /ws/executions/:id` WebSocket upgrade, where browsers authenticate via a
 * `?token=` query value. Accepts either the static API key or a valid JWT.
 * Returns null when the token is absent or invalid.
 */
export async function resolveTokenPrincipal(
  token: string | undefined,
  config: LoopConfig,
): Promise<string | null> {
  if (!token) return null;

  // 1. Static API key.
  const apiKey = config.LOOP_API_KEY;
  if (apiKey && secretsEqual(token, apiKey)) {
    return API_KEY_PRINCIPAL;
  }

  // 2. JWT bearer token.
  try {
    const { payload } = await jose.jwtVerify(token, new TextEncoder().encode(config.LOOP_JWT_SECRET));
    if (typeof payload.sub === 'string' && payload.sub.length > 0) {
      return payload.sub;
    }
  } catch {
    logger.debug('Presented token failed JWT verification');
  }

  return null;
}

/**
 * Route-level minimum-role guard factory (V1.3 M2).
 *
 * Returns a preHandler that rejects the request with 403 when the authenticated
 * role (set by the auth guard) is below `min`. Backward compatible: when auth is
 * disabled no role is attached, so the guard is a no-op (open access).
 */
export function requireRole(min: Role) {
  return async function roleGuard(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
    const role = request.authRole;
    if (role === undefined) return; // Auth off → open (backward compatible).
    if (!roleSatisfies(role, min)) {
      throw new ForbiddenError(`Role '${role}' does not satisfy the required '${min}' role`);
    }
  };
}

/**
 * Build the onRequest auth + RBAC guard hook bound to the given config.
 * The hook is a no-op while `LOOP_REQUIRE_AUTH` is false (open access).
 */
export function createAuthGuard(config: LoopConfig) {
  const requireAuth = config.LOOP_REQUIRE_AUTH;
  const apiKey = config.LOOP_API_KEY;
  const apiKeyRole = config.LOOP_API_KEY_ROLE;
  const jwtSecret = new TextEncoder().encode(config.LOOP_JWT_SECRET);

  return async function authGuard(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
    if (!requireAuth) return; // Backward-compatible: open by default.
    if (!isProtectedPath(request.url)) return; // Public endpoints bypass auth.

    const identity = await resolveIdentity(request, apiKey, apiKeyRole, jwtSecret);
    if (!identity) {
      throw new AuthenticationError('AUTH_MISSING', 'A valid API key or JWT is required');
    }
    request.authPrincipal = identity.principal;
    request.authRole = identity.role;

    // Route-level RBAC: enforce the minimum role for this method + path.
    const required = requiredRoleFor(request.method, request.url);
    if (required && !roleSatisfies(identity.role, required)) {
      throw new ForbiddenError(
        `Role '${identity.role}' is not permitted to ${request.method} ${request.url.split('?')[0]} (requires '${required}')`,
      );
    }
  };
}

/**
 * Global error handler — converts errors to standard API envelope (§12.1).
 */

import type { FastifyError, FastifyReply, FastifyRequest } from 'fastify';
import { LoopError } from '@loop/types';
import { getCorrelationContext } from '@loop/observability';
import { createLogger } from '@loop/observability';

const logger = createLogger({ name: 'loop:api:errorHandler', component: 'api' });

export function errorHandler(error: FastifyError | LoopError | Error, request: FastifyRequest, reply: FastifyReply): void {
  const ctx = getCorrelationContext();
  const request_id = ctx?.request_id ?? 'unknown';

  if (error instanceof LoopError) {
    logger.warn({ code: error.code, statusCode: error.statusCode, message: error.message }, 'Loop error');
    reply.status(error.statusCode).send({
      success: false,
      error: {
        code: error.code,
        message: error.message,
        details: error.details,
      },
      meta: {
        request_id,
        timestamp: new Date().toISOString(),
      },
    });
    return;
  }

  // Fastify validation errors (Zod / JSON schema)
  const err = error as FastifyError;
  if (err.validation) {
    reply.status(400).send({
      success: false,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Request validation failed',
        details: err.validation,
      },
      meta: { request_id, timestamp: new Date().toISOString() },
    });
    return;
  }

  // Rate limiting — @fastify/rate-limit raises a FastifyError with statusCode
  // 429 (code FST_RATE_LIMIT). Map it to the proper RATE_LIMIT_EXCEEDED code
  // instead of falling through to INTERNAL_ERROR.
  const rateLimited = (err.statusCode === 429 || err.code === 'FST_RATE_LIMIT');
  if (rateLimited) {
    reply.status(429).send({
      success: false,
      error: {
        code: 'RATE_LIMIT_EXCEEDED',
        message: 'Rate limit exceeded',
      },
      meta: { request_id, timestamp: new Date().toISOString() },
    });
    return;
  }

  // Unique-constraint violations surface as 409, not 500 (A2). Concurrent
  // workflow updates, duplicate secret names and duplicate trigger ids all
  // previously landed in the generic 500 branch.
  const errCode = (error as FastifyError).code ?? '';
  const constraintLike = typeof error.message === 'string'
    && (/UNIQUE constraint failed/i.test(error.message) || errCode === 'SQLITE_CONSTRAINT_UNIQUE' || errCode === '23505');
  if (constraintLike) {
    reply.status(409).send({
      success: false,
      error: { code: 'CONFLICT_DUPLICATE', message: 'Resource conflicts with an existing record (duplicate name or concurrent version update)' },
      meta: { request_id, timestamp: new Date().toISOString() },
    });
    return;
  }

  // Unexpected errors
  logger.error({ error: String(error), stack: error.stack }, 'Unhandled error');
  reply.status((error as FastifyError).statusCode ?? 500).send({
    success: false,
    error: {
      code: 'INTERNAL_ERROR',
      message: process.env['LOOP_ENV'] === 'production' ? 'Internal server error' : error.message,
    },
    meta: { request_id, timestamp: new Date().toISOString() },
  });
}

/**
 * Request ID hook — generates a unique request_id per request and sets up
 * correlation context for downstream logging (§12.4).
 *
 * Uses AsyncLocalStorage via runWithCorrelation so that any downstream code
 * can call getCorrelationContext() to retrieve the request_id.
 */

import type { FastifyRequest, FastifyReply } from 'fastify';
import { generateRequestId, runWithCorrelation } from '@loop/observability';

export async function requestIdHook(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const requestId = (request.headers['x-request-id'] as string) ?? generateRequestId();

  // Attach to request for downstream handlers (routes read this for response meta)
  (request as unknown as Record<string, unknown>)['requestId'] = requestId;

  // Wrap the remaining request lifecycle inside a correlation context.
  // Fastify's onRequest hook runs before the route handler; by storing the
  // context on the request we ensure getCorrelationContext() is available
  // when the route handler executes within the same async scope.
  (request as unknown as Record<string, unknown>)['correlationContext'] = { request_id: requestId };

  // Run downstream in correlation context (covers handlers invoked synchronously after this hook)
  runWithCorrelation({ request_id: requestId }, () => {});
}

/**
 * Trace ID hook — V1.5 M1 (F-3, TR1) distributed tracing entry point.
 *
 * Reads the inbound `X-Trace-Id` header (generating a UUIDv4 when absent),
 * attaches it to the request, and runs the remainder of the request lifecycle
 * inside a correlation context carrying `trace_id`. Downstream code reads it via
 * `getCorrelationContext()`; the pino mixin (`correlationMixin`) stamps it onto
 * every structured log line, and the connector adapters forward it outbound as
 * `X-Trace-Id` (TR2). Best-effort: it never alters the business response.
 *
 * Runs AFTER `requestIdHook`, so the request_id it attached is reused here to
 * keep a single coherent correlation context for the whole request.
 */

import type { FastifyRequest, FastifyReply } from 'fastify';
import { randomUUID } from 'node:crypto';
import { runWithCorrelation } from '@loop/observability';

export function traceIdHook(request: FastifyRequest, _reply: FastifyReply, done: () => void): void {
  const traceId = (request.headers['x-trace-id'] as string | undefined) ?? randomUUID();
  const requestId =
    ((request as unknown as Record<string, unknown>)['requestId'] as string | undefined) ??
    (request.headers['x-request-id'] as string | undefined) ??
    traceId;

  // Expose on the request for handlers that prefer reading it directly.
  (request as unknown as Record<string, unknown>)['traceId'] = traceId;
  (request as unknown as Record<string, unknown>)['correlationContext'] = { request_id: requestId, trace_id: traceId };

  // Run the rest of the lifecycle within the correlation context so handlers,
  // the structured-log mixin, and connector outbound calls share this trace_id.
  runWithCorrelation({ request_id: requestId, trace_id: traceId }, done);
}

/**
 * Raw-body capture for byte-exact webhook HMAC verification (tsd §11.6).
 *
 * Fastify v4's content-type parser receives a wrapper object whose `.raw` is
 * the Node IncomingMessage the route handler sees as `request.raw` — attaching
 * the buffer to the wrapper itself is invisible to handlers (found via a live
 * probe: the previous attach left `request.raw.rawBody` undefined and every
 * non-canonical JSON signature failed). Both the API server and the
 * integration test helper must register THIS parser so tests exercise the same
 * byte-exact path as production.
 */
import type { FastifyInstance } from 'fastify';

export function attachRawBodyParser(app: Pick<FastifyInstance, 'addContentTypeParser'>): void {
  app.addContentTypeParser('application/json', { parseAs: 'buffer' }, (req, body, done) => {
    // The parser's first arg is typed as the raw IncomingMessage but is
    // actually the Fastify request wrapper at runtime; `.raw` exists on the
    // wrapper, so cover both shapes.
    const wrapper = req as { raw?: { rawBody?: Buffer }; rawBody?: Buffer };
    const target = wrapper.raw ?? wrapper;
    target.rawBody = body as Buffer;
    const text = (body as Buffer).toString('utf8');
    if (text.length === 0) {
      done(null, undefined);
      return;
    }
    try {
      done(null, JSON.parse(text));
    } catch (err) {
      (err as { statusCode?: number }).statusCode = 400;
      done(err as Error, undefined);
    }
  });
}

