import React, { useCallback, useMemo } from 'react';
import ReactFlow, {
  addEdge,
  useNodesState,
  useEdgesState,
  Controls,
  MiniMap,
  Background,
  type Connection,
  type Edge,
  type Node,
  type NodeChange,
  type EdgeChange,
} from 'reactflow';
import 'reactflow/dist/style.css';
import { ConnectorNode } from './nodes/ConnectorNode';
import { ControlNode } from './nodes/ControlNode';
import { CodeNode } from './nodes/CodeNode';
import { CustomEdge } from './edges/CustomEdge';

const nodeTypes = {
  connector: ConnectorNode,
  control: ControlNode,
  code: CodeNode,
};

const edgeTypes = {
  custom: CustomEdge,
};

interface CanvasEditorProps {
  initialNodes?: Node[];
  initialEdges?: Edge[];
  onNodesChange?: (nodes: Node[]) => void;
  onEdgesChange?: (edges: Edge[]) => void;
}

export function CanvasEditor({ initialNodes = [], initialEdges = [], onNodesChange, onEdgesChange }: CanvasEditorProps) {
  const [nodes, setNodes, onNodesChangeInternal] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChangeInternal] = useEdgesState(initialEdges);

  const onConnect = useCallback(
    (params: Connection) => setEdges((eds) => addEdge({ ...params, type: 'custom' }, eds)),
    [setEdges],
  );

  const handleNodesChange = useCallback(
    (changes: NodeChange[]) => {
      onNodesChangeInternal(changes);
      onNodesChange?.(nodes);
    },
    [nodes, onNodesChange, onNodesChangeInternal],
  );

  const handleEdgesChange = useCallback(
    (changes: EdgeChange[]) => {
      onEdgesChangeInternal(changes);
      onEdgesChange?.(edges);
    },
    [edges, onEdgesChange, onEdgesChangeInternal],
  );

  return (
    <div style={{ width: '100%', height: '100%' }}>
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={handleNodesChange}
        onEdgesChange={handleEdgesChange}
        onConnect={onConnect}
        nodeTypes={nodeTypes}
        edgeTypes={edgeTypes}
        fitView
      >
        <Controls />
        <MiniMap />
        <Background />
      </ReactFlow>
    </div>
  );
}

import React from 'react';
import type { Node } from 'reactflow';

interface RetryConfig {
  max_attempts?: number;
  backoff?: string;
  initial_delay_ms?: number;
}

interface NodeConfigPanelProps {
  node: Node | null;
  onConfigChange: (nodeId: string, config: Record<string, unknown>) => void;
}

export function NodeConfigPanel({ node, onConfigChange }: NodeConfigPanelProps) {
  if (!node) {
    return (
      <div style={{ width: '300px', borderLeft: '1px solid #e5e7eb', padding: '16px', color: '#6b7280' }}>
        Select a node to configure
      </div>
    );
  }

  const config = (node.data.config ?? {}) as Record<string, unknown>;

  const handleChange = (key: string, value: string) => {
    onConfigChange(node.id, { ...config, [key]: value });
  };

  return (
    <div style={{ width: '300px', borderLeft: '1px solid #e5e7eb', padding: '16px', overflowY: 'auto' }}>
      <h3 style={{ margin: '0 0 4px 0', fontSize: '16px', fontWeight: 600 }}>{node.data.label}</h3>
      <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '16px' }}>{node.type}</div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
