interface DashboardData {
  workflows: Workflow[];
  executions: Execution[];
  ready: { status: string; checks: Record<string, string> } | null;
}

function useDashboardData(refreshKey: number) {
  const [data, setData] = useState<DashboardData | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    // Child-request failures must surface, not masquerade as an empty state.
    const failure = (label: string) => (e: unknown) => {
      throw new Error(`${label}: ${String(e)}`);
    };
    Promise.all([
      api.listWorkflows({ per_page: 100 }).catch(failure('workflows')),
      api.listExecutions({ per_page: 100 }).catch(failure('executions')),
      api.ready().catch(() => null),
    ]).then(([wf, ex, ready]) => {
      if (!alive) return;
      setData({ workflows: wf.data ?? [], executions: ex.data ?? [], ready });
      setError(null);
    }).catch((e) => alive && setError(String(e)));
    return () => {
      alive = false;
    };
  }, [refreshKey]);

  return { data, error };
}

