/** Render a typed config value as an editable string. */
function fieldToString(spec: FieldSpec, value: unknown): string {
  if (value === undefined || value === null) return '';
  if (spec.type === 'list') return Array.isArray(value) ? value.join(', ') : String(value);
  if (spec.type === 'json') return JSON.stringify(value, null, 2);
  return String(value);
}

/** Parse an edited string back into the typed config value. */
function stringToField(spec: FieldSpec, raw: string): unknown {
  const s = raw.trim();
  if (s === '') return undefined;
  switch (spec.type) {
    case 'number': {
      const n = Number(s);
      if (Number.isNaN(n)) throw new Error(`${spec.label} must be a number`);
      return n;
    }
    case 'boolean':
      return s === 'true';
    case 'list':
      return s.split(',').map((v) => v.trim()).filter(Boolean);
    case 'json':
      return JSON.parse(s) as unknown;
    default:
      return raw;
  }
}

function ConfigPanel({
  node,
  onChange,
  onDelete,
}: {
  node: Node;
  onChange: (id: string, config: Record<string, unknown>) => void;
  onDelete: (id: string) => void;
}) {
  const config = (node.data.config ?? {}) as Record<string, unknown>;
  const type = fullNodeType(node);
  const specs = FIELD_SPECS[type] ?? [];
  const specKeys = new Set(specs.map((s) => s.key));
  const extraKeys = Object.keys(config).filter((k) => !specKeys.has(k));

  const [mode, setMode] = useState<'form' | 'json'>(specs.length > 0 ? 'form' : 'json');
  const [values, setValues] = useState<Record<string, string>>(() => {
    const init: Record<string, string> = {};
    for (const spec of specs) init[spec.key] = fieldToString(spec, config[spec.key]);
    return init;
  });
  const [extraDraft, setExtraDraft] = useState<string>(() =>
    JSON.stringify(Object.fromEntries(extraKeys.map((k) => [k, config[k]])), null, 2),
  );
  const [draft, setDraft] = useState<string>(() => JSON.stringify(config, null, 2));
  const [parseError, setParseError] = useState<string | null>(null);

  useEffect(() => {
    const init: Record<string, string> = {};
    for (const spec of specs) init[spec.key] = fieldToString(spec, config[spec.key]);
    setValues(init);
    const extras = Object.keys(config).filter((k) => !specKeys.has(k));
    setExtraDraft(JSON.stringify(Object.fromEntries(extras.map((k) => [k, config[k]])), null, 2));
    setDraft(JSON.stringify(config, null, 2));
    setParseError(null);
    setMode(specs.length > 0 ? 'form' : 'json');
    // Reset everything when switching nodes; the spec objects are derived
    // deterministically from `type` so they need not be dependencies.
  }, [node.id, type]);

  const setField = (key: string, v: string) => setValues((prev) => ({ ...prev, [key]: v }));

  const applyForm = () => {
    try {
      const next: Record<string, unknown> = {};
      for (const spec of specs) {
        const parsed = stringToField(spec, values[spec.key] ?? '');
        if (parsed !== undefined) next[spec.key] = parsed;
      }
      const extraRaw = extraDraft.trim();
      if (extraRaw && extraRaw !== '{}') {
        const extra = JSON.parse(extraRaw) as Record<string, unknown>;
        Object.assign(next, extra);
      }
      setParseError(null);
      onChange(node.id, next);
    } catch (e) {
      setParseError(e instanceof Error ? e.message : 'Invalid value');
    }
  };

  const applyJson = () => {
    try {
      const parsed = JSON.parse(draft) as Record<string, unknown>;
      setParseError(null);
      onChange(node.id, parsed);
    } catch {
      setParseError('Invalid JSON');
    }
  };

  return (
    <div className="w-72 shrink-0 border-l border-ink-700/60 bg-ink-900/60 backdrop-blur-md flex flex-col">
      <div className="px-4 py-3.5 border-b border-ink-700/60">
        <div className="text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500">
          Node config
        </div>
        <div className="font-display font-semibold text-ink-100 mt-0.5 flex items-center gap-2">
          <span
            className="w-2.5 h-2.5 rounded-full"
            style={{ background: nodeTypeColor(String(node.data.connectorType ?? node.data.controlType ?? 'code')) }}
          />
          {node.id}
        </div>
        <div className="font-mono text-[11px] text-ink-400 mt-0.5">{type}</div>
        <div className="flex gap-1 mt-2.5">
          {(['form', 'json'] as const).map((m) => (
            <button
              key={m}
              onClick={() => setMode(m)}
              disabled={m === 'form' && specs.length === 0}
              className={
                'px-2.5 py-1 rounded-md text-[10px] font-display font-semibold uppercase tracking-wider border transition-all disabled:opacity-40 ' +
                (mode === m
                  ? 'bg-volt-glow border-volt/30 text-volt'
                  : 'border-ink-700 text-ink-400 hover:text-ink-200')
              }
            >
              {m === 'form' ? 'Form' : 'JSON'}
            </button>
          ))}
        </div>
      </div>
      <div className="flex-1 p-4 overflow-y-auto">
        {mode === 'form' ? (
          <div className="space-y-3.5">
            {specs.map((spec) => (
              <div key={spec.key}>
                <label className="block text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500 mb-1.5">
                  {spec.label}
                  {spec.hint && <span className="normal-case font-body font-normal text-ink-600"> ({spec.hint})</span>}
                </label>
                {spec.type === 'textarea' ? (
                  <textarea
                    className="input resize-none text-xs"
                    rows={4}
                    spellCheck={false}
                    placeholder={spec.placeholder}
                    value={values[spec.key] ?? ''}
                    onChange={(e) => setField(spec.key, e.target.value)}
                  />
                ) : spec.type === 'select' ? (
                  <select
                    className="input"
                    value={values[spec.key] ?? ''}
                    onChange={(e) => setField(spec.key, e.target.value)}
                  >
                    <option value="">—</option>
                    {spec.options?.map((o) => (
                      <option key={o} value={o}>
                        {o}
                      </option>
                    ))}
                    {/* keep values outside the suggestion list selectable */}
                    {values[spec.key] && !spec.options?.includes(values[spec.key] ?? '') && (
                      <option value={values[spec.key]}>{values[spec.key]}</option>
                    )}
                  </select>
                ) : spec.type === 'boolean' ? (
                  <select
                    className="input"
                    value={values[spec.key] ?? ''}
                    onChange={(e) => setField(spec.key, e.target.value)}
                  >
                    <option value="">—</option>
                    <option value="true">true</option>
                    <option value="false">false</option>
                  </select>
                ) : spec.type === 'json' ? (
                  <textarea
                    className="input resize-none font-mono text-xs"
                    rows={5}
                    spellCheck={false}
                    placeholder={spec.placeholder ?? '{}'}
                    value={values[spec.key] ?? ''}
                    onChange={(e) => setField(spec.key, e.target.value)}
                  />
                ) : (
                  <input
                    className={spec.type === 'number' ? 'input' : 'input'}
                    type={spec.type === 'number' ? 'number' : 'text'}
                    placeholder={spec.placeholder}
                    value={values[spec.key] ?? ''}
                    onChange={(e) => setField(spec.key, e.target.value)}
                  />
                )}
              </div>
            ))}

            <div>
              <label className="block text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500 mb-1.5">
                Additional fields (JSON)
              </label>
              <textarea
                className="input resize-none font-mono text-xs"
                rows={4}
                spellCheck={false}
                placeholder="{}"
                value={extraDraft}
                onChange={(e) => setExtraDraft(e.target.value)}
              />
            </div>
          </div>
        ) : (
          <>
            <label className="block text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500 mb-1.5">
              Config (JSON)
            </label>
            <textarea
              className="input font-mono text-xs resize-none"
              rows={14}
              spellCheck={false}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
            />
          </>
        )}
        {parseError && <div className="text-xs text-bad mt-2">{parseError}</div>}
        <div className="text-[11px] text-ink-500 mt-3 leading-relaxed">
          Reference outputs with{' '}
          <code className="font-mono text-volt">{'{{node_id.output.field}}'}</code> and trigger data with{' '}
          <code className="font-mono text-volt">{'{{trigger.payload.x}}'}</code>.
        </div>
      </div>
      <div className="p-4 border-t border-ink-700/60 space-y-2">
        <button className="btn-primary w-full justify-center" onClick={mode === 'form' ? applyForm : applyJson}>
          <Icon name="check" />
          Apply config
        </button>
        <button className="btn-danger w-full justify-center" onClick={() => onDelete(node.id)}>
          <Icon name="trash" />
          Delete node
        </button>
      </div>
    </div>
  );
}

export function WorkflowEditor() {
  const { id } = useParams<{ id: string }>();
  const [workflow, setWorkflow] = useState<Workflow | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState<{ kind: 'ok' | 'err'; text: string } | null>(null);
  const [validation, setValidation] = useState<{ valid: boolean; errors: string[]; warnings: string[] } | null>(null);
  const [paletteQuery, setPaletteQuery] = useState('');

  useEffect(() => {
    if (!id) return;
    api
      .getWorkflow(id)
      .then((wf) => {
        setWorkflow(wf);
        const def = wf.definition;
        setNodes((def?.nodes ?? []).map(toRfNode));
        setEdges((def?.edges ?? []).map(toRfEdge));
      })
      .catch((e) => setLoadError(e instanceof Error ? e.message : String(e)));
  }, [id, setNodes, setEdges]);

  const showToast = useCallback((kind: 'ok' | 'err', text: string) => {
    setToast({ kind, text });
    setTimeout(() => setToast(null), 3200);
  }, []);

  const onConnect = useCallback(
    (params: Connection) => {
      setEdges((eds) =>
        addEdge(
          {
            ...params,
            id: `edge_${Date.now()}`,
            animated: true,
          },
          eds,
        ),
      );
      setDirty(true);
    },
    [setEdges],
  );

  const addNode = useCallback(
    (item: PaletteItem) => {
      const idx = nodes.length;
      const nodeId = `node_${idx + 1}`;
      const kind = rfKind(item.type);
      const [prefix, operation] = item.type.split('.');
      const newNode: Node =
        kind === 'control'
          ? {
              id: nodeId,
              type: 'control',
              position: { x: 80 + (idx % 4) * 220, y: 80 + Math.floor(idx / 4) * 140 },
              data: { controlType: operation, label: operation, config: {} },
            }
          : kind === 'code'
            ? {
                id: nodeId,
                type: 'code',
                position: { x: 80 + (idx % 4) * 220, y: 80 + Math.floor(idx / 4) * 140 },
                data: { language: operation, label: nodeId, config: {} },
              }
            : {
                id: nodeId,
                type: 'connector',
                position: { x: 80 + (idx % 4) * 220, y: 80 + Math.floor(idx / 4) * 140 },
                data: { connectorType: prefix, operation, label: item.label, config: {} },
              };
      setNodes((nds) => [...nds, newNode]);
      setDirty(true);
      setSelectedId(nodeId);
    },
    [nodes.length, setNodes],
  );

  const updateNodeConfig = useCallback(
    (nodeId: string, config: Record<string, unknown>) => {
      setNodes((nds) =>
        nds.map((n) => (n.id === nodeId ? { ...n, data: { ...n.data, config } } : n)),
      );
      setDirty(true);
      showToast('ok', 'Config applied');
    },
    [setNodes, showToast],
  );

  const deleteNode = useCallback(
    (nodeId: string) => {
      setNodes((nds) => nds.filter((n) => n.id !== nodeId));
      setEdges((eds) => eds.filter((e) => e.source !== nodeId && e.target !== nodeId));
      setSelectedId(null);
      setDirty(true);
    },
    [setNodes, setEdges],
  );

  const buildDefinition = useCallback((): WorkflowDefinition => {
    return {
      version: workflow?.definition?.version ?? '1.0',
      nodes: nodes.map((n) => ({
        id: n.id,
        type:
          n.type === 'control'
            ? `control.${n.data.controlType}`
            : n.type === 'code'
              ? `code.${n.data.language ?? 'typescript'}`
              : `${n.data.connectorType}.${n.data.operation}`,
        position: { x: Math.round(n.position.x), y: Math.round(n.position.y) },
        config: (n.data.config ?? {}) as Record<string, unknown>,
      })),
      edges: edges.map((e) => ({
        id: e.id,
        source: e.source,
        source_port: e.sourceHandle ?? 'output',
        target: e.target,
        target_port: e.targetHandle ?? 'input',
      })),
      variables: workflow?.definition?.variables ?? {},
      metadata: workflow?.definition?.metadata ?? { name: workflow?.name ?? '', description: '', tags: [] },
    };
  }, [nodes, edges, workflow]);

  const save = useCallback(async () => {
    if (!id) return;
    setSaving(true);
    try {
      const definition = buildDefinition();
      await api.updateWorkflow(id, { definition });
      setDirty(false);
      showToast('ok', 'Workflow saved');
    } catch (e) {
      showToast('err', e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }, [id, buildDefinition, showToast]);

  const validate = useCallback(async () => {
    if (!id) return;
    try {
      if (dirty) await save();
      const result = await api.validateWorkflow(id);
      setValidation(result);
    } catch (e) {
      showToast('err', e instanceof Error ? e.message : String(e));
    }
  }, [id, dirty, save, showToast]);

  const run = useCallback(async () => {
    if (!id) return;
    try {
      if (dirty) await save();
      const result = await api.executeWorkflow(id);
      showToast('ok', `Execution ${shortId(result.execution_id)} started`);
    } catch (e) {
      showToast('err', e instanceof Error ? e.message : String(e));
    }
  }, [id, dirty, save, showToast]);

  const selectedNode = useMemo(() => nodes.find((n) => n.id === selectedId) ?? null, [nodes, selectedId]);
  const categories = useMemo(() => [...new Set(PALETTE.map((p) => p.category))], []);
  // Searchable palette (n8n-style): match on label, dotted type or category.
  const paletteMatches = useMemo(() => {
    const q = paletteQuery.trim().toLowerCase();
    if (!q) return null;
    return PALETTE.filter(
      (p) =>
        p.label.toLowerCase().includes(q) ||
        p.type.toLowerCase().includes(q) ||
        p.category.toLowerCase().includes(q),
    );
  }, [paletteQuery]);
  const dark = useTheme() === 'dark';

  if (loadError) {
    return (
      <div className="p-8">
        <div className="text-bad text-sm">Failed to load workflow: {loadError}</div>
        <Link to="/workflows" className="btn-ghost mt-4 inline-flex">
          <Icon name="arrowLeft" /> Back to workflows
        </Link>
      </div>
    );
  }
  if (!workflow) return <LoadingBlock label="Loading editor…" />;

  return (
    <div className="h-screen flex flex-col">
      {/* ── Editor toolbar ──────────────────────────────────────────────── */}
      <div className="shrink-0 flex items-center gap-3 px-5 py-3 border-b border-ink-700/60 bg-ink-900/70 backdrop-blur-md">
        <Link to="/workflows" className="btn-ghost !px-2.5" title="Back">
          <Icon name="arrowLeft" />
        </Link>
        <div className="min-w-0">
          <div className="font-display font-semibold text-ink-100 truncate">{workflow.name}</div>
          <div className="font-mono text-[10px] text-ink-500">
            v{workflow.version} · {nodes.length} nodes · {edges.length} edges
          </div>
        </div>
        <StatusBadge status={workflow.status} />
        {dirty && <span className="tag text-warn border-warn/40">unsaved</span>}

        <div className="ml-auto flex items-center gap-2">
          <ThemeToggle />
          <button className="btn-ghost" onClick={validate}>
            <Icon name="check" />
            Validate
          </button>
          <button className="btn-ghost" onClick={run}>
            <Icon name="play" />
            Run
          </button>
          <button className="btn-primary" onClick={save} disabled={saving || !dirty}>
            {saving ? 'Saving…' : 'Save'}
          </button>
        </div>
      </div>

      {/* ── Validation banner ───────────────────────────────────────────── */}
      {validation && (
        <div
          className={
            'shrink-0 px-5 py-2.5 text-sm border-b flex items-center gap-3 animate-fade-in ' +
            (validation.valid
              ? 'bg-good/10 border-good/30 text-good'
              : 'bg-bad/10 border-bad/30 text-bad')
          }
        >
          <Icon name={validation.valid ? 'check' : 'x'} />
          <span>
            {validation.valid ? 'Topology valid' : `Invalid: ${validation.errors.join('; ')}`}
            {validation.warnings.length > 0 && (
              <span className="text-ink-400"> · {validation.warnings.length} warning(s)</span>
            )}
          </span>
          <button className="ml-auto text-ink-400 hover:text-ink-200" onClick={() => setValidation(null)}>
            <Icon name="x" />
          </button>
        </div>
      )}

      {/* ── Body: palette + canvas + config ─────────────────────────────── */}
      <div className="flex-1 flex min-h-0">
        {/* Palette */}
        <div className="w-56 shrink-0 border-r border-ink-700/60 bg-ink-900/60 backdrop-blur-md overflow-y-auto">
          <div className="px-4 py-3.5 border-b border-ink-700/60">
            <div className="text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500">
              Node palette
            </div>
            <div className="relative mt-2.5">
              <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-ink-500 pointer-events-none">
                <Icon name="search" className="w-3.5 h-3.5" />
              </span>
              <input
                className="input !pl-7 !py-1.5 !text-xs"
                placeholder="Search nodes…"
                value={paletteQuery}
                onChange={(e) => setPaletteQuery(e.target.value)}
                aria-label="Search node palette"
              />
            </div>
          </div>
          {paletteMatches ? (
            <div className="px-4 py-3">
              {paletteMatches.length === 0 ? (
                <div className="text-[11px] text-ink-500 py-2">
                  No nodes match “{paletteQuery.trim()}”.
                </div>
              ) : (
                <div className="space-y-1.5">
                  {paletteMatches.map((item) => (
                    <button
                      key={item.type}
                      onClick={() => addNode(item)}
                      className="w-full flex items-center gap-2.5 px-2.5 py-2 rounded-md border border-ink-700/70 bg-ink-800/50 hover:border-ink-600 hover:bg-ink-750 hover:translate-x-0.5 transition-all text-left"
                    >
                      <span
                        className="w-6 h-6 rounded flex items-center justify-center text-xs shrink-0"
                        style={{ background: `${nodeTypeColor(item.type)}22`, color: nodeTypeColor(item.type) }}
                      >
                        {item.icon}
                      </span>
                      <span>
                        <span className="block text-xs font-medium text-ink-200">{item.label}</span>
                        <span className="block font-mono text-[10px] text-ink-500">{item.type}</span>
                      </span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          ) : (
          <>
          {categories.map((cat) => (
            <div key={cat} className="px-4 py-3">
              <div className="text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500 mb-2">
                {cat}
              </div>
              <div className="space-y-1.5">
                {PALETTE.filter((p) => p.category === cat).map((item) => (
                  <button
                    key={item.type}
                    onClick={() => addNode(item)}
                    className="w-full flex items-center gap-2.5 px-2.5 py-2 rounded-md border border-ink-700/70 bg-ink-800/50 hover:border-ink-600 hover:bg-ink-750 hover:translate-x-0.5 transition-all text-left"
                  >
                    <span
                      className="w-6 h-6 rounded flex items-center justify-center text-xs shrink-0"
                      style={{ background: `${nodeTypeColor(item.type)}22`, color: nodeTypeColor(item.type) }}
                    >
                      {item.icon}
                    </span>
                    <span>
                      <span className="block text-xs font-medium text-ink-200">{item.label}</span>
                      <span className="block font-mono text-[10px] text-ink-500">{item.type}</span>
                    </span>
                  </button>
                ))}
              </div>
            </div>
          ))}
          </>
          )}
        </div>

        {/* Canvas */}
        <div className="flex-1 min-w-0 relative">
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            nodeTypes={nodeTypes}
            fitView
            onNodeClick={(_, node) => setSelectedId(node.id)}
            onPaneClick={() => setSelectedId(null)}
            proOptions={{ hideAttribution: true }}
          >
            <Background
              variant={BackgroundVariant.Dots}
              gap={24}
              size={1.5}
              color={dark ? '#3a342e' : '#d6cfc0'}
            />
            <Controls />
            <MiniMap
              nodeColor={(n) =>
                n.type === 'control'
                  ? '#f59e0b'
                  : n.type === 'code'
                    ? '#ec4899'
                    : nodeTypeColor(String(n.data.connectorType))
              }
              maskColor={dark ? 'rgba(12,10,8,0.7)' : 'rgba(246,242,236,0.7)'}
            />
          </ReactFlow>
          {nodes.length === 0 && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="text-center text-ink-500">
                <div className="text-3xl mb-2">⑂</div>
                <div className="text-sm">Add nodes from the palette to start building</div>
              </div>
            </div>
          )}
        </div>

        {/* Config panel */}
        {selectedNode && (
          <ConfigPanel node={selectedNode} onChange={updateNodeConfig} onDelete={deleteNode} />
        )}
      </div>

      {/* ── Toast ───────────────────────────────────────────────────────── */}
      {toast && (
        <div
          className={
            'fixed bottom-6 right-6 z-50 px-4 py-2.5 rounded-md border text-sm font-medium animate-slide-up shadow-panel ' +
            (toast.kind === 'ok'
              ? 'bg-ink-800/95 border-good/40 text-good'
              : 'bg-ink-800/95 border-bad/40 text-bad')
          }
        >
          {toast.text}
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { api, timeAgo, type TemplateSummary, type Workflow, type WorkflowDefinition } from '../lib/api';
import { useWorkflowStore } from '../store/workflows';
import { Card, EmptyState, Icon, LoadingBlock, StatusBadge } from '../components/ui';

const BLANK_DEFINITION: WorkflowDefinition = {
  version: '1.0',
  nodes: [],
  edges: [],
  variables: {},
  metadata: { name: '', description: '', tags: [] },
};

/**
 * Two-step creation wizard (Zapier-style):
 *   Step 1 — pick a starting point: featured industry template or blank canvas.
 *   Step 2 — name / describe / tag it (prefilled from the template).
 * Also links out to the full marketplace for browsing all templates.
 */
function CreateWorkflowModal({
  onClose,
  onCreated,
}: {
  onClose: () => void;
  onCreated: (wf: Workflow) => void;
}) {
  const navigate = useNavigate();
  const createWorkflow = useWorkflowStore((s) => s.createWorkflow);
  const [step, setStep] = useState<1 | 2>(1);
  const [picked, setPicked] = useState<TemplateSummary | null>(null);
  const [featured, setFeatured] = useState<TemplateSummary[] | null>(null);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [tags, setTags] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Featured templates for the quick-pick grid — degrade to blank-only on failure.
  useEffect(() => {
    let alive = true;
    api
      .listTemplates({ featured: true })
      .then((r) => alive && setFeatured(r.templates))
      .catch(() => alive && setFeatured([]));
    return () => {
      alive = false;
    };
  }, []);

  const pick = (t: TemplateSummary | null) => {
    setPicked(t);
    setName(t?.name ?? '');
    setDescription(t?.description ?? '');
    setTags(t ? t.tags.slice(0, 4).join(', ') : '');
    setError(null);
    setStep(2);
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    setBusy(true);
    setError(null);
    try {
      let wf: Workflow;
      if (picked) {
        wf = await api.instantiateTemplate(picked.id, {
          name: name.trim(),
          ...(description.trim() ? { description: description.trim() } : {}),
        });
      } else {
        const tagList = tags.split(',').map((t) => t.trim()).filter(Boolean);
        const definition: WorkflowDefinition = {
          ...BLANK_DEFINITION,
          metadata: { name: name.trim(), description: description.trim(), tags: tagList },
        };
        wf = await createWorkflow({
          name: name.trim(),
          description: description.trim(),
          definition,
          tags: tagList,
        });
      }
      onCreated(wf);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
      setBusy(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 bg-ink-950/70 backdrop-blur-sm flex items-center justify-center animate-fade-in"
      onClick={onClose}
    >
      <div
        className="panel w-full max-w-lg p-6 animate-slide-up"
        onClick={(e) => e.stopPropagation()}
      >
        {step === 1 && (
          <>
            <h2 className="font-display font-bold text-lg text-ink-100 mb-1">New workflow</h2>
            <p className="text-sm text-ink-400 mb-5">Start from a proven template or a blank canvas.</p>

            <div className="space-y-2.5">
              <button
                type="button"
                onClick={() => pick(null)}
                className="w-full flex items-center gap-3.5 px-4 py-3.5 rounded-lg border border-dashed border-ink-600 hover:border-volt/50 hover:bg-volt-glow/40 transition-all text-left"
              >
                <span className="w-9 h-9 rounded-md bg-ink-800 border border-ink-700 flex items-center justify-center text-ink-300 shrink-0">
                  <Icon name="plus" />
                </span>
                <span>
                  <span className="block text-sm font-display font-semibold text-ink-100">Start from scratch</span>
                  <span className="block text-xs text-ink-400 mt-0.5">
                    Build node by node with the visual editor.
                  </span>
                </span>
              </button>

              {featured === null && (
                <div className="text-xs text-ink-500 font-mono px-1 py-2">Loading templates…</div>
              )}

              {featured && featured.length > 0 && (
                <div>
                  <div className="text-[10px] font-display font-semibold uppercase tracking-widest text-ink-500 mb-2 px-1 mt-3">
                    Recommended templates
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {featured.slice(0, 6).map((t) => (
                      <button
                        key={t.id}
                        type="button"
                        onClick={() => pick(t)}
                        className="flex items-start gap-2.5 px-3 py-2.5 rounded-lg border border-ink-700 bg-ink-800/50 hover:border-ink-600 hover:bg-ink-750 transition-all text-left"
                      >
                        <span className="text-lg leading-none shrink-0" aria-hidden>
                          {t.icon}
                        </span>
                        <span className="min-w-0">
                          <span className="block text-xs font-display font-semibold text-ink-100 truncate">
                            {t.name}
                          </span>
                          <span className="block text-[10px] font-mono uppercase tracking-wider text-ink-500 truncate">
                            {t.industry} · {t.node_count} nodes
                          </span>
                        </span>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="mt-5 pt-4 border-t border-ink-700/60 flex items-center justify-between">
              <button
                type="button"
                className="text-xs text-volt hover:text-volt/80 font-medium"
                onClick={() => {
                  onClose();
                  navigate('/templates');
                }}
              >
                Browse all templates →
              </button>
              <button type="button" className="btn-ghost" onClick={onClose}>
                Cancel
              </button>
            </div>
          </>
        )}

        {step === 2 && (
          <>
            <div className="flex items-center justify-between mb-1">
              <h2 className="font-display font-bold text-lg text-ink-100">
                {picked ? 'Create from template' : 'New workflow'}
              </h2>
              <button className="btn-ghost !px-2 !py-1.5" onClick={onClose} aria-label="Close">
                <Icon name="x" />
              </button>
            </div>
            <p className="text-sm text-ink-400 mb-4">
              {picked ? (
                <>
                  From{' '}
                  <span className="text-ink-200">
                    {picked.icon} {picked.name}
                  </span>{' '}
                  ·{' '}
                  <button
                    type="button"
                    className="text-volt hover:text-volt/80"
                    onClick={() => setStep(1)}
                  >
                    change
                  </button>
                </>
              ) : (
                'An empty DAG you compose in the visual editor.'
              )}
            </p>
            <form onSubmit={submit} className="space-y-4">
              <div>
                <label className="block text-xs font-display font-semibold uppercase tracking-wider text-ink-400 mb-1.5">
                  Name
                </label>
                <input
                  className="input"
                  autoFocus
                  placeholder="e.g. nightly-knowledge-digest"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-xs font-display font-semibold uppercase tracking-wider text-ink-400 mb-1.5">
                  Description
                </label>
                <textarea
                  className="input resize-none"
                  rows={3}
                  placeholder="What does this workflow automate?"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-xs font-display font-semibold uppercase tracking-wider text-ink-400 mb-1.5">
                  Tags <span className="text-ink-500 normal-case font-body font-normal">(comma separated)</span>
                </label>
                <input
                  className="input"
                  placeholder="automation, vault"
                  value={tags}
                  onChange={(e) => setTags(e.target.value)}
                />
              </div>
              {error && <div className="text-sm text-bad">{error}</div>}
              <div className="flex justify-end gap-2 pt-2">
                <button type="button" className="btn-ghost" onClick={() => setStep(1)}>
                  <Icon name="arrowLeft" />
                  Back
                </button>
                <button type="submit" className="btn-primary" disabled={busy || !name.trim()}>
                  {busy ? 'Creating…' : picked ? 'Create from template' : 'Create workflow'}
                </button>
              </div>
            </form>
          </>
        )}
      </div>
    </div>
  );
}

export function Workflows() {
  const navigate = useNavigate();
  // V1.1 M2 (F4): workflow list state lives in the global Zustand store.
  const workflows = useWorkflowStore((s) => s.workflows);
  const loaded = useWorkflowStore((s) => s.loaded);
  const loadError = useWorkflowStore((s) => s.error);
  const load = useWorkflowStore((s) => s.load);
  const deleteWorkflow = useWorkflowStore((s) => s.deleteWorkflow);

  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [showCreate, setShowCreate] = useState(false);
  const [actionBusy, setActionBusy] = useState<string | null>(null);

  useEffect(() => {
    void load({ per_page: 100 });
  }, [load]);

  const filtered = useMemo(() => {
    return workflows.filter((w) => {
      if (statusFilter !== 'all' && w.status !== statusFilter) return false;
      if (search) {
        const q = search.toLowerCase();
        return (
          w.name.toLowerCase().includes(q) ||
          w.description.toLowerCase().includes(q) ||
          w.tags.some((t) => t.toLowerCase().includes(q))
        );
      }
      return true;
    });
  }, [workflows, search, statusFilter]);

  const runWorkflow = async (wf: Workflow) => {
    setActionBusy(wf.id);
    try {
      const result = await api.executeWorkflow(wf.id);
      navigate(`/executions/${result.execution_id}`);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setActionBusy(null);
    }
  };

  const archiveWorkflow = async (wf: Workflow) => {
    setActionBusy(wf.id);
    try {
      await deleteWorkflow(wf.id);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setActionBusy(null);
    }
  };

  return (
    <div className="p-8 max-w-[1400px] mx-auto">
      <div className="flex items-end justify-between mb-8">
        <div>
          <div className="text-[11px] font-mono uppercase tracking-widest text-volt mb-1.5">
            Authoring
          </div>
          <h1 className="font-brand text-3xl tracking-tight text-ink-100">Workflows</h1>
          <p className="text-sm text-ink-400 mt-1">
            DAG-based automations chaining Vault, Desk and Recap agents.
          </p>
        </div>
        <button className="btn-primary" onClick={() => setShowCreate(true)}>
          <Icon name="plus" />
          New workflow
        </button>
      </div>

      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-3 mb-5">
        <div className="relative flex-1 min-w-[220px] max-w-sm">
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-ink-500">
            <Icon name="search" />
          </span>
          <input
            className="input pl-9"
            placeholder="Search by name, description or tag…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-1.5">
          {['all', 'draft', 'active', 'archived'].map((s) => (
            <button
              key={s}
              onClick={() => setStatusFilter(s)}
              className={
                'px-3 py-1.5 rounded-md text-xs font-display font-semibold capitalize transition-all border ' +
                (statusFilter === s
                  ? 'bg-volt-glow border-volt/30 text-volt'
                  : 'border-ink-700 text-ink-400 hover:text-ink-200 hover:border-ink-600')
              }
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      {(error ?? loadError) && (
        <div className="mb-4 text-sm text-bad bg-bad/10 border border-bad/30 rounded-md px-4 py-2.5">
          {error ?? loadError}
        </div>
      )}

      {!loaded ? (
        <LoadingBlock label="Loading workflows…" />
      ) : filtered.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Icon name="workflow" className="w-6 h-6" />}
            title={workflows.length === 0 ? 'No workflows yet' : 'Nothing matches your filters'}
            hint={
              workflows.length === 0
                ? 'Create your first workflow to start orchestrating the sovereign agent suite.'
                : 'Try a different search term or status filter.'
            }
            action={
              workflows.length === 0 ? (
                <button className="btn-primary" onClick={() => setShowCreate(true)}>
                  <Icon name="plus" />
                  Create workflow
                </button>
              ) : undefined
            }
          />
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {filtered.map((wf, i) => (
            <Card key={wf.id} hover className="p-5 flex flex-col animate-slide-up" >
              <div style={{ animationDelay: `${i * 40}ms` }} className="flex flex-col flex-1">
                <div className="flex items-start justify-between gap-3">
                  <Link
                    to={`/workflows/${wf.id}`}
                    className="font-display font-semibold text-ink-100 hover:text-volt transition-colors leading-snug"
                  >
                    {wf.name}
                  </Link>
                  <StatusBadge status={wf.status} />
                </div>
                <p className="text-sm text-ink-400 mt-2 line-clamp-2 flex-1">
                  {wf.description || 'No description'}
                </p>

                <div className="flex flex-wrap gap-1.5 mt-3">
                  {wf.tags.map((t) => (
                    <span key={t} className="tag">
                      {t}
                    </span>
                  ))}
                  <span className="tag text-ink-500">v{wf.version}</span>
                  <span className="tag text-ink-500">
                    {wf.definition?.nodes?.length ?? 0} nodes
                  </span>
                </div>

                <div className="flex items-center justify-between mt-4 pt-3 border-t border-ink-700/60">
                  <span className="text-[11px] text-ink-500 font-mono">
                    updated {timeAgo(wf.updated_at)}
                  </span>
                  <div className="flex items-center gap-1.5">
                    <button
                      className="btn-ghost !px-2.5 !py-1.5"
                      title="Run now"
                      disabled={actionBusy === wf.id}
                      onClick={() => runWorkflow(wf)}
                    >
                      <Icon name="play" className="w-3.5 h-3.5" />
                    </button>
                    <Link className="btn-ghost !px-2.5 !py-1.5" title="Edit" to={`/workflows/${wf.id}`}>
                      <Icon name="edit" className="w-3.5 h-3.5" />
                    </Link>
                    <button
                      className="btn-danger !px-2.5 !py-1.5"
                      title="Archive"
                      disabled={actionBusy === wf.id || wf.status === 'archived'}
                      onClick={() => archiveWorkflow(wf)}
                    >
                      <Icon name="trash" className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}

      {showCreate && (
        <CreateWorkflowModal
          onClose={() => setShowCreate(false)}
          onCreated={(wf) => {
            setShowCreate(false);
            navigate(`/workflows/${wf.id}`);
          }}
        />
      )}
    </div>
  );
}

/**
 * Execution store (V1.1 M2, F4/F5) — global state for a live execution.
 *
 * Holds the current execution + its node rows and folds real-time WebSocket
 * events into them. The pure `reduceNodes` helper is exported so pages that
 * keep their own local state (e.g. ExecutionDetail) can apply the same stream
 * events without depending on the store instance.
 */

import { create } from 'zustand';
import { api, type Execution, type NodeExecution } from '../lib/api';
import type { ExecutionStreamEvent } from '../api/client';

export type NodeStatus = NodeExecution['status'];

/** Build a fresh node row from a stream event (used when none exists yet). */
function blankNode(event: ExecutionStreamEvent, status: NodeStatus): NodeExecution {
  const ts = event.timestamp ?? new Date().toISOString();
  return {
    id: event.nodeId ?? '',
    execution_id: event.executionId ?? '',
    node_id: event.nodeId ?? '',
    node_type: event.nodeType ?? '',
    status,
    input: {},
    output: event.output ?? {},
    error: event.error ?? null,
    started_at: status === 'running' ? ts : null,
    completed_at: status === 'running' ? null : ts,
    retry_count: 0,
  };
}

/**
 * Purely fold a single stream event into a node list (immutably). Handles the
 * initial `snapshot` (merge any previously-unseen nodes) and the per-node
 * transitions emitted by the engine EventBus.
 */
export function reduceNodes(nodes: NodeExecution[], event: ExecutionStreamEvent): NodeExecution[] {
  if (event.type === 'snapshot') {
    const byId = new Map(nodes.map((n) => [n.node_id, n]));
    for (const snap of event.nodes ?? []) {
      if (!byId.has(snap.nodeId)) {
        byId.set(snap.nodeId, {
          id: snap.nodeId,
          execution_id: event.executionId ?? '',
          node_id: snap.nodeId,
          node_type: snap.nodeType,
          status: snap.status,
          input: {},
          output: snap.output ?? {},
          error: snap.error ?? null,
          started_at: null,
          completed_at: null,
          retry_count: 0,
        });
      }
    }
    return [...byId.values()];
  }

  if (!event.nodeId) return nodes;
  const ts = event.timestamp ?? new Date().toISOString();
  const idx = nodes.findIndex((n) => n.node_id === event.nodeId);

  if (event.type === 'node_started') {
    const existing = idx >= 0 ? nodes[idx]! : null;
    const updated: NodeExecution = existing
      ? { ...existing, status: 'running', node_type: event.nodeType ?? existing.node_type, started_at: existing.started_at ?? ts }
      : blankNode(event, 'running');
    if (idx >= 0) {
      const copy = nodes.slice();
      copy[idx] = updated;
      return copy;
    }
    return [...nodes, updated];
  }

  if (event.type === 'node_succeeded' || event.type === 'node_failed' || event.type === 'node_skipped') {
    const status: NodeStatus =
      event.type === 'node_succeeded' ? 'succeeded' : event.type === 'node_failed' ? 'failed' : 'skipped';
    const existing = idx >= 0 ? nodes[idx]! : blankNode(event, status);
    const updated: NodeExecution = {
      ...existing,
      status,
      completed_at: ts,
      output: event.output ?? existing.output,
      error: event.error ?? existing.error,
    };
    if (idx >= 0) {
      const copy = nodes.slice();
      copy[idx] = updated;
      return copy;
    }
    return [...nodes, updated];
  }

  return nodes;
}

export interface ExecutionStore {
  execution: Execution | null;
  nodes: NodeExecution[];
  connected: boolean;
  error: string | null;
  setConnected: (connected: boolean) => void;
  load: (id: string) => Promise<void>;
  applyEvent: (event: ExecutionStreamEvent) => void;
  reset: () => void;
}

export const useExecutionStore = create<ExecutionStore>((set, get) => ({
  execution: null,
  nodes: [],
  connected: false,
  error: null,

  setConnected: (connected) => set({ connected }),

  async load(id) {
    try {
      const execution = await api.getExecution(id);
      set({ execution, nodes: execution.nodes ?? [], error: null });
    } catch (err) {
      set({ error: err instanceof Error ? err.message : String(err) });
    }
  },

  applyEvent(event) {
    const nodes = reduceNodes(get().nodes, event);
    const execution = get().execution;
    let nextExecution = execution;
    if (execution) {
      if (event.type === 'execution_succeeded') {
        nextExecution = { ...execution, status: 'succeeded' };
      } else if (event.type === 'execution_failed') {
        nextExecution = { ...execution, status: 'failed', error: event.error ?? execution.error };
      } else if (event.type === 'snapshot' && typeof event.status === 'string') {
        nextExecution = { ...execution, status: event.status as Execution['status'] };
      }
    }
    set({ nodes, ...(nextExecution ? { execution: nextExecution } : {}) });
  },

  reset: () => set({ execution: null, nodes: [], connected: false, error: null }),
}));

/**
 * Workflow store (V1.1 M2, F4) — global state for the workflow list.
 *
 * Wraps the REST layer so components can read workflows and trigger
 * create/archive without threading callbacks through the tree.
 */

import { create } from 'zustand';
import { api, type Workflow, type WorkflowDefinition } from '../lib/api';

export interface CreateWorkflowInput {
  name: string;
  description: string;
  definition: WorkflowDefinition;
  tags?: string[];
}

export interface WorkflowStore {
  workflows: Workflow[];
  /** True once the first load has completed (success or failure). */
  loaded: boolean;
  loading: boolean;
  error: string | null;
  load: (params?: { status?: string; search?: string; per_page?: number }) => Promise<void>;
  createWorkflow: (input: CreateWorkflowInput) => Promise<Workflow>;
  /** Archives (soft-deletes) a workflow and drops it from the local list. */
  deleteWorkflow: (id: string) => Promise<void>;
}

export const useWorkflowStore = create<WorkflowStore>((set, get) => ({
  workflows: [],
  loaded: false,
  loading: false,
  error: null,

  async load(params) {
    set({ loading: true, error: null });
    try {
      const result = await api.listWorkflows({
        per_page: params?.per_page ?? 100,
        status: params?.status,
        search: params?.search,
      });
      set({ workflows: result.data ?? [], loaded: true, loading: false });
    } catch (err) {
      set({ error: err instanceof Error ? err.message : String(err), loading: false, loaded: true });
    }
  },

  async createWorkflow(input) {
    const workflow = await api.createWorkflow(input);
    set({ workflows: [workflow, ...get().workflows] });
    return workflow;
  },

  async deleteWorkflow(id) {
    await api.archiveWorkflow(id);
    set({ workflows: get().workflows.filter((w) => w.id !== id) });
  },
}));

/**
 * Loop Control Plane server — multi-instance management (Scale tier only).
 * Stub entry point.
 */

import Fastify from 'fastify';
import { createLogger } from '@loop/observability';

const logger = createLogger({ name: 'loop:control-plane', component: 'control-plane' });

const app = Fastify({ logger: false });

app.get('/health', async () => ({ status: 'ok' }));
app.get('/api/v1/fleet', async () => ({ instances: [] }));

const port = parseInt(process.env['LOOP_CONTROL_PLANE_PORT'] ?? '3001', 10);
app.listen({ port, host: '0.0.0.0' }).then(() => {
  logger.info({ port }, 'Control plane started (stub)');
}).catch((err) => {
  logger.fatal({ error: String(err) }, 'Control plane failed');
  process.exit(1);
