/**
 * ODW Recap connector — meeting intelligence (team-server).
 *
 * Targets the real Recap team-server HTTP API (see INTEGRATION_CONTRACT.md §3):
 *   - POST /auth/login   {email,password} → {token}
 *   - GET  /meetings/    (Bearer JWT)
 *   - GET  /meetings/{id}
 *   - POST /meetings/
 *   - POST /sync
 *   - GET  /health
 *
 * Auth is JWT Bearer. The token is resolved (in priority order) from the
 * operation input (`token`), the resolved secrets (`api_key`), or the instance
 * config (`api_key`).
 */

import { request } from 'undici';
import type { ConnectorAdapter, ExecuteParams, ExecuteResult } from '../interface.js';
import type { ConnectorCapabilities } from '@loop/types';
import { UpstreamError } from '@loop/types';
import { createLogger } from '@loop/observability';
import { traceHeaders } from '../trace.js';

const logger = createLogger({ name: 'loop:connectors:recap', component: 'connectors' });

const DEFAULT_BASE_URL = 'http://localhost:8080';

export class RecapAdapter implements ConnectorAdapter {
  readonly type = 'recap';

  async execute(params: ExecuteParams): Promise<ExecuteResult> {
    const baseUrl = (params.config?.['base_url'] as string) || DEFAULT_BASE_URL;
    const token =
      (params.input['token'] as string | undefined) ??
      params.secrets?.['api_key'] ??
      (params.config?.['api_key'] as string | undefined) ??
      '';
    // V1.1 M1 (F2): best-effort idempotency key forwarded as an upstream header.
    const idemKey = params.idempotencyKey;

    switch (params.operation) {
      case 'login':
        return this.login(baseUrl, params.input, idemKey, params);
      case 'list_meetings':
        return this.callRecap(baseUrl, token, 'GET', '/meetings/', undefined, idemKey, params);
      case 'get_meeting':
        return this.callRecap(baseUrl, token, 'GET', `/meetings/${String(params.input['id'])}`, undefined, idemKey, params);
      case 'create_meeting':
        return this.callRecap(baseUrl, token, 'POST', '/meetings/', params.input, idemKey, params);
      case 'sync':
        return this.callRecap(baseUrl, token, 'POST', '/sync', params.input, idemKey, params);
      default:
        throw new Error(`Unknown Recap operation: ${params.operation}`);
    }
  }

  async healthCheck(baseUrl: string = DEFAULT_BASE_URL): Promise<boolean> {
    try {
      const response = await request(`${baseUrl}/health`, { method: 'GET' });
      await response.body.text();
      return response.statusCode === 200;
    } catch (err) {
      logger.warn({ error: String(err) }, 'Recap health check failed');
      return false;
    }
  }

  getCapabilities(): ConnectorCapabilities {
    return {
      node_types: [
        'recap.login',
        'recap.list_meetings',
        'recap.get_meeting',
        'recap.create_meeting',
        'recap.sync',
      ],
      input_types: ['Meeting', 'string'],
      output_types: ['Meeting', 'Meeting[]', 'string'],
    };
  }

  /** POST /auth/login → {token}. No Bearer required. */
  private async login(baseUrl: string, input: Record<string, unknown>, idempotencyKey?: string, io?: Pick<ExecuteParams, 'egress' | 'signal'>): Promise<ExecuteResult> {
    const data = await this.callRecap(baseUrl, '', 'POST', '/auth/login', {
      email: input['email'] ?? '',
      password: input['password'] ?? '',
    }, idempotencyKey, io);
    return { output: { token: data.output['token'] ?? '' } };
  }

  private async callRecap(
    baseUrl: string,
    token: string,
    method: 'GET' | 'POST',
    path: string,
    body?: Record<string, unknown>,
    idempotencyKey?: string,
    io?: Pick<ExecuteParams, 'egress' | 'signal'>,
  ): Promise<ExecuteResult> {
    try {
      const url = `${baseUrl}${path}`;
      await io?.egress?.check(url);
      const response = await request(url, {
        method,
        headers: {
          ...(body ? { 'content-type': 'application/json' } : {}),
          ...(token ? { authorization: `Bearer ${token}` } : {}),
          ...(idempotencyKey ? { 'idempotency-key': idempotencyKey } : {}),
          ...traceHeaders(),
        },
        body: body ? JSON.stringify(body) : undefined,
        signal: io?.signal,
      });
      if (response.statusCode >= 400) {
        // Consume the body so undici can release the socket back to the pool.
        await response.body.text().catch(() => {});
        throw new UpstreamError('UPSTREAM_RECAP_UNAVAILABLE', `Recap returned ${response.statusCode}`);
      }
      const text = await response.body.text();
      if (!text) return { output: {} };
      try {
        return { output: JSON.parse(text) as Record<string, unknown> };
      } catch {
        // Non-JSON from the sibling service almost always means the URL points
        // at the wrong host/port — fail loudly instead of smuggling garbage
        // into workflow outputs as `{ text }`.
        throw new UpstreamError(
          'UPSTREAM_RECAP_BAD_RESPONSE',
          `Recap at ${baseUrl} returned non-JSON content (check LOOP_RECAP_URL)`,
        );
      }
    } catch (err) {
      if (err instanceof UpstreamError) throw err;
      logger.error({ error: String(err) }, 'Recap call failed');
      throw new UpstreamError('UPSTREAM_RECAP_UNAVAILABLE', String(err));
    }
  }
}

import { createLogger } from '@loop/observability';
import type { ConnectorAdapter } from './interface.js';

const logger = createLogger({ name: 'loop:connectors:registry', component: 'connectors' });

/**
 * Connector registry — manages adapter instances and provides lookup.
 * Adapters are registered by type.  Instances are keyed by a unique instance ID.
 */
export class ConnectorRegistry {
  private adapters = new Map<string, ConnectorAdapter>();
  private instances = new Map<string, { adapterType: string; config: Record<string, unknown> }>();
  private capabilitiesCache = new Map<string, { caps: Awaited<ReturnType<ConnectorAdapter['getCapabilities']>>; expiresAt: number }>();

  /** Register an adapter type. */
  registerAdapter(adapter: ConnectorAdapter): void {
    this.adapters.set(adapter.type, adapter);
    logger.info({ type: adapter.type }, 'Adapter registered');
  }

  /** Register a connector instance (a configured adapter). */
  registerInstance(instanceId: string, adapterType: string, config: Record<string, unknown>): void {
    if (!this.adapters.has(adapterType)) {
      throw new Error(`Unknown adapter type: ${adapterType}`);
    }
    this.instances.set(instanceId, { adapterType, config });
  }

  /** Remove a connector instance (used when a DB row is deleted). */
  unregisterInstance(instanceId: string): boolean {
    return this.instances.delete(instanceId);
  }

  /** Get an adapter by type. */
  getAdapter(type: string): ConnectorAdapter | undefined {
    return this.adapters.get(type);
  }

  /** Get the adapter type for an instance. */
  getInstanceAdapterType(instanceId: string): string | undefined {
    return this.instances.get(instanceId)?.adapterType;
  }

  /** Get instance config. */
  getInstanceConfig(instanceId: string): Record<string, unknown> | undefined {
    return this.instances.get(instanceId)?.config;
  }

  /** List all registered instances. */
  listInstances(): string[] {
    return [...this.instances.keys()];
  }

  /** Get capabilities for a connector type (cached 5 min — §7.2). */
  async getCapabilities(type: string) {
    const cached = this.capabilitiesCache.get(type);
    if (cached && cached.expiresAt > Date.now()) return cached.caps;

    const adapter = this.adapters.get(type);
    if (!adapter) return undefined;

    const caps = adapter.getCapabilities();
    this.capabilitiesCache.set(type, { caps, expiresAt: Date.now() + 5 * 60 * 1000 });
    return caps;
  }

  /**
   * Probe all registered instances in parallel and report per-instance health.
   * Uses each instance's configured base_url (falling back to the adapter
   * default), bounded by `timeoutMs` so /ready never hangs on a dead sibling.
   */
  async healthCheckAll(timeoutMs = 2500): Promise<Map<string, boolean>> {
    const entries = [...this.instances.entries()];
    const probes = entries.map(async ([id, inst]) => {
      const adapter = this.adapters.get(inst.adapterType);
      if (!adapter) return [id, false] as const;
      const configured = inst.config?.['base_url'];
      const baseUrl = typeof configured === 'string' ? configured : undefined;
      const timeout = new Promise<boolean>((resolve) => {
        const t = setTimeout(() => resolve(false), timeoutMs);
        if (typeof t.unref === 'function') t.unref();
      });
      try {
        const ok = await Promise.race([Promise.resolve(adapter.healthCheck(baseUrl)), timeout]);
        return [id, Boolean(ok)] as const;
      } catch {
        return [id, false] as const;
      }
    });
    const results = await Promise.all(probes);
    return new Map(results);
  }
}

/**
 * V1.5 M1 (F-3, TR2): best-effort outbound distributed-trace propagation for
 * connector adapters.
 *
 * `traceHeaders()` returns an `x-trace-id` header carrying the current request's
 * trace_id when a correlation context is active (i.e. the connector runs inside a
 * traced Loop request via `runWithCorrelation`), or an empty object otherwise.
 * Adapters spread it into their outbound HTTP requests so Vault/Desk/Recap can
 * correlate their own logs against the originating Loop request.
 *
 * This adds ONLY a header — the request/response contract is unchanged
 * (INTEGRATION_CONTRACT.md §4), exactly like the existing best-effort
 * `idempotency-key` header.
 */

import { getCorrelationContext } from '@loop/observability';

export function traceHeaders(): Record<string, string> {
  const traceId = getCorrelationContext()?.trace_id;
  return traceId !== undefined ? { 'x-trace-id': traceId } : {};
}

