/**
 * Network call interceptor — wraps undici to enforce egress policies.
 */

import { request as undiciRequest, type Dispatcher } from 'undici';
import { lookup } from 'node:dns';
import { promisify } from 'node:util';
import { isIP } from 'node:net';
import { createLogger } from '@loop/observability';
import type { EgressEngine } from './engine.js';
import { LoopError } from '@loop/types';

const logger = createLogger({ name: 'loop:egress:interceptor', component: 'egress' });

const lookupAll: (hostname: string, opts: { all: true }) => Promise<Array<{ address: string; family: number }>> =
  promisify(lookup) as unknown as typeof lookupAll;

/** IPv4 private / reserved ranges (CIDR first-address + mask bits). */
const PRIVATE_V4_RANGES: Array<[string, number]> = [
  ['0.0.0.0', 8], // "this" network
  ['10.0.0.0', 8], // RFC1918
  ['100.64.0.0', 10], // CGNAT
  ['127.0.0.0', 8], // loopback
  ['169.254.0.0', 16], // link-local (incl. cloud metadata 169.254.169.254)
  ['172.16.0.0', 12], // RFC1918
  ['192.0.0.0', 24], // IETF protocol assignments
  ['192.168.0.0', 16], // RFC1918
  ['198.18.0.0', 15], // benchmarking
  ['224.0.0.0', 4], // multicast
  ['240.0.0.0', 4], // reserved / broadcast
];

function ipv4ToInt(ip: string): number {
  const parts = ip.split('.');
  // eslint-disable-next-line no-bitwise
  return ((Number(parts[0]) << 24) | (Number(parts[1]) << 16) | (Number(parts[2]) << 8) | Number(parts[3])) >>> 0;
}

function ipv4InCidr(ip: string, cidrBase: string, prefixBits: number): boolean {
  if (prefixBits === 0) return true;
  // eslint-disable-next-line no-bitwise
  const mask = prefixBits >= 32 ? 0xffffffff : (0xffffffff << (32 - prefixBits)) >>> 0;
  return (ipv4ToInt(ip) & mask) === (ipv4ToInt(cidrBase) & mask);
}

/** True for loopback/private/reserved IPv4 addresses (RFC1918, CGNAT, link-local, …). */
export function isPrivateIPv4(ip: string): boolean {
  return PRIVATE_V4_RANGES.some(([base, bits]) => ipv4InCidr(ip, base, bits));
}

/** True for loopback/ULA/link-local/unspecified/v4-mapped-private IPv6 addresses. */
export function isPrivateIPv6(ip: string): boolean {
  const normalized = ip.toLowerCase().replace(/^\[|\]$/g, '');
  if (normalized === '::1' || normalized === '::') return true;
  // v4-mapped (::ffff:a.b.c.d) — evaluate the embedded IPv4.
  const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/.exec(normalized);
  if (mapped) return isPrivateIPv4(mapped[1]!);
  const first = normalized.split(':')[0] ?? '';
  if (first.length === 0) return false;
  // fc00::/7 unique-local and fe80::/10 link-local by leading 16 bits.
  const high16 = Number.parseInt(first.padEnd(4, '0'), 16);
  if (Number.isFinite(high16)) {
    // eslint-disable-next-line no-bitwise
    if (((high16 & 0xfe00) >>> 0) === 0xfc00) return true;
    // eslint-disable-next-line no-bitwise
    if (((high16 & 0xffc0) >>> 0) === 0xfe80) return true;
  }
  return false;
}

/** True when the literal IP string is a private/reserved address (v4 or v6). */
export function isPrivateIp(ip: string): boolean {
  const family = isIP(ip);
  if (family === 4) return isPrivateIPv4(ip);
  if (family === 6) return isPrivateIPv6(ip);
  return false;
}

/**
 * Resolve a URL's host and return the first private/reserved address it would
 * reach, or null. Literal IPs are checked directly; hostnames are resolved via
 * DNS with `all: true` so an answer mixing public and private records is still
 * caught. DNS failure returns null (the request itself will fail downstream).
 */
export async function firstPrivateAddress(url: string): Promise<string | null> {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  const host = parsed.hostname.replace(/^\[|\]$/g, '');
  if (isIP(host) !== 0) return isPrivateIp(host) ? host : null;
  try {
    const records = await lookupAll(host, { all: true });
    for (const record of records) {
      if (isPrivateIp(record.address)) return record.address;
    }
  } catch {
    return null;
  }
  return null;
}

export class EgressInterceptor {
  constructor(private engine: EgressEngine) {}

  /** Make an HTTP request that is subject to egress policy. */
  async request(url: string, opts?: Dispatcher.RequestOptions) {
    const decision = await this.engine.evaluate(url);
    if (!decision.allowed) {
      logger.warn({ url, reason: decision.reason }, 'Egress blocked');
      throw new LoopError('NODE_EGRESS_BLOCKED', `Egress blocked: ${decision.reason}`, 403);
    }
    return undiciRequest(url, opts);
  }
}

/** Options controlling when the gate enforces policy evaluation. */
export interface EgressGateOptions {
  /** Kill switch — when true, every outbound call is blocked (fail closed). */
  airgap: boolean;
  /**
   * Decision applied when no egress policies are configured at all. `allow`
   * keeps a fresh deployment usable (the product's whole point is calling the
   * ODW agents over HTTP); set to `deny` (or add a policy) to lock down.
   */
  unconfiguredPolicy: 'allow' | 'deny';
  /**
   * V1.7 (SSRF hardening): when false (default), private/reserved targets
   * (loopback, RFC1918, CGNAT, link-local incl. cloud metadata endpoints) are
   * rejected UNCONDITIONALLY — before the unconfigured-policy short-circuit
   * and regardless of any allow policy, so a `generic.rest_call` node cannot
   * be pointed at `169.254.169.254` or the API's own loopback listener.
   * Self-hosted suites that legitimately target sibling services on a private
   * network set this to true explicitly.
   */
  allowPrivate?: boolean;
}

/**
 * The single choke point every outbound connector call must pass through.
 *
 * Historically `EgressEngine`/`EgressInterceptor` existed but were never wired
 * into the execution path, so `LOOP_AIRGAP_MODE` and every egress policy were
 * dead config — any workflow node could reach arbitrary hosts (SSRF). Adapters
 * receive the gate via `ExecuteParams.egress` and must `check(url)` before
 * dispatching.
 */
export class EgressGate {
  constructor(
    private engine: EgressEngine,
    private opts: EgressGateOptions,
  ) {}

  /** Throw a 403 `NODE_EGRESS_BLOCKED` error when the URL may not be reached. */
  async check(url: string): Promise<void> {
    if (this.opts.airgap) {
      logger.warn({ url }, 'Egress blocked (airgap mode)');
      throw new LoopError('NODE_EGRESS_BLOCKED', 'Airgap mode is enabled — all outbound network calls are blocked', 403);
    }
    // V1.7 (SSRF hardening): the private-range blocklist applies even when no
    // policy is configured (and even when an allow policy matches) — it was
    // previously possible to reach 169.254.169.254 / 127.0.0.1 / RFC1918 via
    // the unconfigured `allow` short-circuit below.
    if (!this.opts.allowPrivate) {
      const privateAddr = await firstPrivateAddress(url);
      if (privateAddr !== null) {
        logger.warn({ url, address: privateAddr }, 'Egress blocked (private/reserved address)');
        throw new LoopError(
          'NODE_EGRESS_BLOCKED',
          `Egress blocked: '${privateAddr}' is a private/reserved address (set LOOP_EGRESS_ALLOW_PRIVATE=true only on trusted private networks)`,
          403,
        );
      }
    }
    if (!(await this.engine.isConfigured())) {
      if (this.opts.unconfiguredPolicy === 'deny') {
        logger.warn({ url }, 'Egress blocked (no policies configured, default deny)');
        throw new LoopError('NODE_EGRESS_BLOCKED', 'Egress blocked: no egress policies configured and the default policy is deny', 403);
      }
      return;
    }
    const decision = await this.engine.evaluate(url);
    if (!decision.allowed) {
      logger.warn({ url, reason: decision.reason }, 'Egress blocked');
      throw new LoopError('NODE_EGRESS_BLOCKED', `Egress blocked: ${decision.reason}`, 403);
    }
  }
}

/**
 * DNS resolution + IP geolocation for egress policy evaluation.
 */

import { lookup } from 'node:dns';
import { promisify } from 'node:util';

const lookupAsync = promisify(lookup);

/**
 * Resolve a hostname to an IPv4 address (best-effort — returns the hostname
 * itself when DNS fails). Async on purpose: the previous implementation
 * invoked the callback-based `lookup` but returned before it fired, so the
 * "resolved IP" was always the hostname and IP-range/region policies never
 * matched.
 */
export async function resolveIP(hostname: string): Promise<string> {
  try {
    // promisify(lookup) yields a plain address string under the default
    // wrapper and `{ address, family }` under dns.lookup's custom promisify —
    // accept both shapes.
    const result = (await lookupAsync(hostname, { family: 4 })) as string | { address?: string };
    const address = typeof result === 'string' ? result : result?.address;
    return address ?? hostname;
  } catch {
    return hostname;
  }
}

/**
 * IP geolocation lookup (stub).
 * In production, use a GeoIP database (e.g., MaxMind).
 * Returns a region code or empty string.
 */
export function lookupRegion(_ip: string): string {
  // Stub: no GeoIP database available
  return '';
}

/**
 * Circuit breaker pattern for external service calls (§6.5).
 */

import { createLogger } from '@loop/observability';
import { metricsRegistry } from '@loop/observability';

const logger = createLogger({ name: 'loop:engine:circuitBreaker', component: 'engine' });

export type CircuitBreakerState = 'closed' | 'open' | 'half_open';

export class CircuitBreaker {
  private state: CircuitBreakerState = 'closed';
  private failures = 0;
  private lastFailure = 0;
  private readonly metrics = metricsRegistry();

  constructor(
    private name: string,
    private threshold = 5,
    private cooldownMs = 30_000,
  ) {}

  /** Execute a function through the circuit breaker. */
  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === 'open') {
      if (Date.now() - this.lastFailure > this.cooldownMs) {
        this.state = 'half_open';
        logger.info({ name: this.name }, 'Circuit breaker → half_open');
        this.updateMetric();
      } else {
        throw new Error(`Circuit breaker '${this.name}' is open`);
      }
    }

    try {
      const result = await fn();
      if (this.state === 'half_open') {
        this.state = 'closed';
        this.failures = 0;
        logger.info({ name: this.name }, 'Circuit breaker → closed');
        this.updateMetric();
      }
      return result;
    } catch (err) {
      this.failures++;
      this.lastFailure = Date.now();
      if (this.failures >= this.threshold) {
        this.state = 'open';
        logger.warn({ name: this.name, failures: this.failures }, 'Circuit breaker → open');
        this.updateMetric();
      }
      throw err;
    }
  }

  getState(): CircuitBreakerState {
    return this.state;
  }

  reset(): void {
    this.state = 'closed';
    this.failures = 0;
    this.lastFailure = 0;
    this.updateMetric();
  }

  private updateMetric(): void {
    const stateValue = this.state === 'closed' ? 0 : this.state === 'open' ? 1 : 2;
    this.metrics.circuitBreakerState.set({ connector_type: this.name }, stateValue);
  }
}

/**
 * Parse a workflow definition into a DAG structure.
 */

import type { WorkflowDefinition, WorkflowNode, WorkflowEdge } from '@loop/types';

export interface DAG {
  nodes: Map<string, WorkflowNode>;
  edges: WorkflowEdge[];
  adjacency: Map<string, string[]>;
  reverseAdjacency: Map<string, string[]>;
}

export function parseDAG(definition: WorkflowDefinition): DAG {
  const nodes = new Map<string, WorkflowNode>();
  const adjacency = new Map<string, string[]>();
  const reverseAdjacency = new Map<string, string[]>();

  for (const node of definition.nodes) {
    nodes.set(node.id, node);
    adjacency.set(node.id, []);
    reverseAdjacency.set(node.id, []);
  }

  for (const edge of definition.edges) {
    adjacency.get(edge.source)?.push(edge.target);
    reverseAdjacency.get(edge.target)?.push(edge.source);
  }

  return { nodes, edges: definition.edges, adjacency, reverseAdjacency };
}

/**
 * EventBus — lightweight in-process pub/sub for real-time execution events
 * (V1.1 M2, F5).
 *
 * The executor publishes node/execution status transitions here; the API
 * layer's `GET /ws/executions/:id` WebSocket route subscribes per executionId
 * and forwards events to connected clients. This decouples the engine from any
 * transport: the engine knows nothing about WebSockets, and the WS route knows
 * nothing about how executions run.
 *
 * Subscribers are keyed by executionId so a disconnect can clean up exactly the
 * subscriptions it owns (no cross-execution leakage, no unbounded growth).
 * Delivery is synchronous and best-effort: a throwing listener is isolated so
 * it can never break the publishing executor or other subscribers.
 */

import { createLogger } from '@loop/observability';
import type { ExecutionEventType, NodeExecutionStatus, ExecutionStatus } from '@loop/types';

const logger = createLogger({ name: 'loop:engine:eventBus', component: 'engine' });

/**
 * A real-time execution event published on the bus. Mirrors the durable event
 * log's `ExecutionEventType` discriminator (V1.1 M1) but carries the fields a
 * live monitor needs (status, output, error, timing) rather than a persisted id.
 */
export interface ExecutionBusEvent {
  /** Lifecycle discriminator, e.g. `node_started` / `node_succeeded`. */
  type: ExecutionEventType;
  executionId: string;
  /** Present for node-level events; omitted for execution-level events. */
  nodeId?: string;
  nodeType?: string;
  /** Current status of the node or execution this event concerns. */
  status: NodeExecutionStatus | ExecutionStatus;
  /** ISO-8601 timestamp of when the event was emitted. */
  timestamp: string;
  /** Node output — populated on `node_succeeded`. */
  output?: Record<string, unknown>;
  /** Error message — populated on `node_failed` / `execution_failed`. */
  error?: string;
  /** Wall-clock node duration in ms — populated on `node_succeeded`. */
  durationMs?: number;
  /**
   * V1.2 M3 (F-Loop-1): set on every event emitted by a sub-workflow
   * invocation, pointing at the parent execution that triggered it. Lets a
   * monitor reconstruct the parent→child execution tree (nested view). Absent
   * for root executions.
   */
  parentExecutionId?: string;
}

/** A subscriber callback invoked with each event for its executionId. */
export type ExecutionBusListener = (event: ExecutionBusEvent) => void;

/**
 * In-process publish/subscribe hub for execution events, keyed by executionId.
 * Create one per process (see the exported `executionEventBus` singleton) or
 * inject a dedicated instance for isolated testing.
 */
export class EventBus {
  private readonly subscribers = new Map<string, Set<ExecutionBusListener>>();

  /**
   * Subscribe to events for a single execution. Returns an unsubscribe
   * function that removes exactly this listener (idempotent).
   */
  subscribe(executionId: string, listener: ExecutionBusListener): () => void {
    let set = this.subscribers.get(executionId);
    if (!set) {
      set = new Set();
      this.subscribers.set(executionId, set);
    }
    set.add(listener);

    return () => {
      this.unsubscribe(executionId, listener);
    };
  }

  /** Remove a specific listener for an execution (no-op if absent). */
  unsubscribe(executionId: string, listener: ExecutionBusListener): void {
    const set = this.subscribers.get(executionId);
    if (!set) return;
    set.delete(listener);
    if (set.size === 0) {
      // Drop the empty bucket so long-running processes don't accumulate keys.
      this.subscribers.delete(executionId);
    }
  }

  /** Remove ALL subscribers for an execution (per-execution cleanup). */
  clear(executionId: string): void {
    this.subscribers.delete(executionId);
  }

  /** Number of active subscribers for an execution (mainly for tests). */
  subscriberCount(executionId: string): number {
    return this.subscribers.get(executionId)?.size ?? 0;
  }

  /**
   * Publish an event to every subscriber registered for its executionId.
   * Synchronous and best-effort: a listener that throws is logged and isolated
   * so it cannot disrupt the publisher or the remaining listeners.
   */
  publish(event: ExecutionBusEvent): void {
    const set = this.subscribers.get(event.executionId);
    if (!set || set.size === 0) return;
    // Iterate over a snapshot so a listener that unsubscribes during delivery
    // cannot skip siblings mid-iteration.
    for (const listener of [...set]) {
      try {
        listener(event);
      } catch (err) {
        logger.warn(
          { executionId: event.executionId, type: event.type, error: String(err) },
          'EventBus listener threw — isolated and continuing',
        );
      }
    }
  }
}

/**
 * Process-wide singleton shared by the executor (publisher) and the API
 * WebSocket route (subscriber). Both import this instance so events flow
 * without explicit wiring.
 */
export const executionEventBus = new EventBus();

/**
 * EventLog — best-effort execution event recording (V1.1 M1, F1 durable recovery).
 *
 * Wraps `StateStore.events.append` so the executor and recovery can record
 * lifecycle events without ever breaking execution: a write failure is logged
 * as a warning and swallowed. The event log is an audit / resume aid, not a
 * source of truth — losing an event must never fail a workflow.
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';
import type { ExecutionEventType } from '@loop/types';

const logger = createLogger({ name: 'loop:engine:eventLog', component: 'engine' });

/**
 * Record an execution event on a best-effort basis.
 *
 * Never throws: any store error is caught and logged at warn level so event
 * recording cannot interrupt the surrounding execution.
 */
export async function recordEvent(
  store: StateStore,
  executionId: string,
  eventType: ExecutionEventType,
  nodeId?: string,
  payload?: Record<string, unknown>,
): Promise<void> {
  try {
    await store.events.append({
      id: randomUUID(),
      execution_id: executionId,
      event_type: eventType,
      node_id: nodeId,
      payload,
      created_at: Date.now(),
    });
  } catch (err) {
    logger.warn(
      { executionId, eventType, nodeId, error: String(err) },
      'Failed to record execution event (best-effort) — continuing',
    );
  }
}

/**
 * Main execution executor — processes nodes in topological order (§6.1).
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import { metricsRegistry } from '@loop/observability';
// V1.6 M1 (F-2, SP3): execution/node lifecycle spans (best-effort observability).
import { startSpan, runInSpan } from '@loop/observability';
import { LoopError, type WorkflowDefinition, type WorkflowNode, type ExecutionStatus } from '@loop/types';
import type { StateStore } from '@loop/state';
import type { ConnectorRegistry } from '@loop/connectors';
import { computeLevels, topologicalSort } from './scheduler.js';
import { executeWithRetry, type RetryConfig } from './retry.js';
import { BranchNode, DelayNode } from './nodes/index.js';
import { recordEvent } from './eventLog.js';
import { EventBus, executionEventBus, type ExecutionBusEvent } from './eventBus.js';

const logger = createLogger({ name: 'loop:engine:executor', component: 'engine' });
const metrics = metricsRegistry();

/** Default workflow-level timeout (V1.1 M1, F3). Env-overridable, 300s fallback. */
function defaultWorkflowTimeoutMs(): number {
  const raw = process.env['LOOP_WORKFLOW_TIMEOUT_MS'];
  const parsed = raw === undefined ? Number.NaN : Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 300_000;
}

/**
 * Default sub-workflow recursion ceiling (V1.2 M3, F-Loop-1). Env-overridable,
 * 5 fallback — bounds `workflow.invoke` nesting so a cyclic definition cannot
 * recurse without limit.
 */
function defaultMaxSubWorkflowDepth(): number {
  const raw = process.env['LOOP_SUBWORKFLOW_MAX_DEPTH'];
  const parsed = raw === undefined ? Number.NaN : Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 5;
}

/**
 * Default size cap (bytes) for the node output persisted into a
 * `node_succeeded` event payload (V1.4 M2, F-2). Env-overridable, 64KB
 * fallback — bounds what a single event may store so large outputs cannot
 * bloat the append-only `execution_events` table.
 */
function defaultEventOutputMaxBytes(): number {
  const raw = process.env['LOOP_EVENT_OUTPUT_MAX_BYTES'];
  const parsed = raw === undefined ? Number.NaN : Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 65_536;
}

/** Leading characters of the serialised output retained in a truncated marker. */
const EVENT_OUTPUT_PREVIEW_CHARS = 1024;

/**
 * V1.4 M2 (F-2): cap a node output for persistence into a `node_succeeded`
 * event payload. When the JSON-serialised output fits within `maxBytes` it is
 * returned unchanged; otherwise a small truncated marker
 * `{ __truncated__: true, size, preview }` is returned instead, so oversized
 * outputs cannot bloat the append-only events table. `size` is the original
 * serialised byte length; `preview` is a short leading slice of the JSON.
 */
function capOutputForEvent(
  output: Record<string, unknown>,
  maxBytes: number,
): Record<string, unknown> {
  const serialized = JSON.stringify(output) ?? '';
  const size = Buffer.byteLength(serialized, 'utf8');
  if (size <= maxBytes) {
    return output;
  }
  const preview = serialized.slice(0, Math.max(0, Math.min(EVENT_OUTPUT_PREVIEW_CHARS, maxBytes)));
  return { __truncated__: true, size, preview };
}

export interface ExecutorContext {
  executionId: string;
  workflowId: string;
  triggerPayload: Record<string, unknown>;
  nodeOutputs: Map<string, Record<string, unknown>>;
  /**
   * V1.1 M1 (F1/F2): outputs of nodes already `succeeded` for this execution,
   * loaded at start. Used to skip re-dispatch on resume / idempotent retry.
   */
  completedOutputs: Map<string, Record<string, unknown>>;
  /**
   * V1.2 M3 (F-Loop-1): sub-workflow recursion depth. `0` for a root execution;
   * each `workflow.invoke` child runs at parent depth + 1 and is rejected past
   * `maxSubWorkflowDepth`.
   */
  depth: number;
  /**
   * V1.2 M3: the execution that invoked this one as a sub-workflow. Absent for
   * root executions; stamped onto every emitted event so monitors can rebuild
   * the parent→child tree.
   */
  parentExecutionId?: string;
  /**
   * V1.2 M3: definition keys already on the invocation stack — used for cycle
   * detection so a self-invoking workflow fails fast instead of recursing to
   * the depth ceiling.
   */
  visited: Set<string>;
  /**
   * V1.7 (branch wiring): runtime decision of each executed `control.branch`
   * node — which outgoing port ('true'/'false') fired. Scheduler-level pruning
   * reads this to drop nodes reachable only via the non-taken port.
   */
  branchDecisions: Map<string, 'true' | 'false'>;
  /**
   * V1.7 (branch wiring): nodes pruned this run because every incoming edge
   * comes from a non-taken branch port (directly or transitively). Edges out
   * of a skipped node are dead, so pruning cascades level by level.
   */
  skippedNodes: Set<string>;
  /**
   * V1.7 (L-6): `definition.variables` defaults resolved once per execution —
   * backs `{{variables.*}}` interpolation in both configs and branch conditions.
   */
  variables: Record<string, unknown>;
}

/**
 * V1.2 M3 (F-Loop-1): optional recursion context threaded through
 * `execute()` for sub-workflow invocation. Root callers omit it entirely
 * (backward compatible); the engine supplies it when recursing into a child.
 */
export interface ExecuteOptions {
  /** Recursion depth of this execution (default 0 = root). */
  depth?: number;
  /** Parent execution id when this execution is a sub-workflow invocation. */
  parentExecutionId?: string;
  /** Definition keys already on the invocation stack (cycle detection). */
  visited?: Set<string>;
}

export class ExecutionExecutor {
  constructor(
    private store: StateStore,
    private connectors: ConnectorRegistry,
    private maxConcurrent = 50,
    private nodeTimeoutMs = 30_000,
    private workflowTimeoutMs: number = defaultWorkflowTimeoutMs(),
    // V1.1 M2 (F5): real-time status fan-out. Defaults to the process-wide
    // singleton the WS route subscribes to; inject a dedicated bus in tests.
    private eventBus: EventBus = executionEventBus,
    // V1.2 M3 (F-Loop-1): ceiling for `workflow.invoke` recursion depth.
    private maxSubWorkflowDepth: number = defaultMaxSubWorkflowDepth(),
    // V1.4 M2 (F-2): size cap (bytes) for the node output persisted into a
    // `node_succeeded` event payload. Oversized outputs are stored as a
    // truncated marker instead of the full payload (see capOutputForEvent).
    private eventOutputMaxBytes: number = defaultEventOutputMaxBytes(),
    // Egress policy gate enforced before every outbound connector call.
    // Structural type — the engine does not depend on @loop/egress.
    private egressGate?: { check(url: string): Promise<void> },
    // V1.7 (L-2 secrets wiring): resolves a named secret for a connector
    // instance from the encrypted secrets store, before falling back to the
    // instance's inline config. Supplied by the API server; absent in tests.
    private secretResolver?: (name: string, scope: 'connector', scopeId: string) => Promise<string | null>,
    // V1.7 (L-9): executor-wide default retry applied when a node carries no
    // explicit `retry` block. Backward compatible — omitted keeps the historic
    // zero-retry behaviour (the API server passes LOOP_DEFAULT_RETRY_*).
    private defaultRetry?: RetryConfig,
  ) {}

  /** V1.7 (L-10): in-flight executions on this executor (see drain()). */
  private activeRuns = 0;

  /**
   * V1.7 (L-10): wait for in-flight executions to settle (bounded). The API
   * server's SIGTERM path drains before app.close() so side effects are not
   * severed mid-flight; recovery remains the safety net for the remainder.
   */
  async drain(timeoutMs: number): Promise<boolean> {
    const deadline = Date.now() + timeoutMs;
    while (this.activeRuns > 0 && Date.now() < deadline) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    return this.activeRuns === 0;
  }

  /**
   * Publish a real-time node/execution status event (V1.1 M2, F5). Best-effort:
   * the EventBus isolates listener errors, so this can never break execution.
   */
  private emit(event: ExecutionBusEvent): void {
    this.eventBus.publish(event);
  }

  /**
   * V1.2 M3 (F-Loop-1): the partial event fields that tag an event as belonging
   * to a sub-workflow invocation. Spread into every emitted event so a monitor
   * can reconstruct the parent→child execution tree. Empty for root executions.
   */
  private parentMarker(ctx: ExecutorContext): { parentExecutionId?: string } {
    return ctx.parentExecutionId !== undefined ? { parentExecutionId: ctx.parentExecutionId } : {};
  }

  /**
   * Execute a workflow from start to finish. Resolves with the final per-node
   * output map so a `workflow.invoke` parent can surface a child's outputs
   * (V1.2 M3); root callers may ignore the return value. `options` carries
   * sub-workflow recursion state and is supplied by the engine itself when it
   * recurses into a child — external callers leave it unset.
   *
   * V1.6 M1 (F-2, SP3): the whole run is wrapped in a `loop.execution` span;
   * every node span started below it is auto-parented to that span via the
   * tracing AsyncLocalStorage context. Best-effort — tracing never changes
   * the execution result, and an unsampled/no-op span makes this a thin
   * pass-through.
   */
  async execute(
    executionId: string,
    definition: WorkflowDefinition,
    triggerPayload: Record<string, unknown>,
    options?: ExecuteOptions,
  ): Promise<Map<string, Record<string, unknown>>> {
    const span = startSpan('loop.execution', {
      'execution.id': executionId,
      'workflow.id': definition.metadata?.name ?? '',
      'execution.depth': options?.depth ?? 0,
    });
    let failed = false;
    try {
      return await runInSpan(span, () =>
        this.executeInner(executionId, definition, triggerPayload, options),
      );
    } catch (err) {
      failed = true;
      span.setAttr('error.message', String(err));
      throw err;
    } finally {
      span.end(failed ? 'error' : 'ok');
    }
  }

  /** The execution pipeline proper (see `execute` for the public contract). */
  private async executeInner(
    executionId: string,
    definition: WorkflowDefinition,
    triggerPayload: Record<string, unknown>,
    options?: ExecuteOptions,
  ): Promise<Map<string, Record<string, unknown>>> {
    const startTime = Date.now();
    // V1.7 (L-6): resolve `definition.variables` defaults once so both config
    // interpolation and branch conditions can reference `{{variables.*}}`.
    const variables: Record<string, unknown> = {};
    for (const [name, def] of Object.entries(definition.variables ?? {})) {
      variables[name] = (def as { default?: unknown } | undefined)?.default;
    }
    const ctx: ExecutorContext = {
      executionId,
      workflowId: definition.metadata?.name ?? '',
      triggerPayload,
      nodeOutputs: new Map(),
      completedOutputs: new Map(),
      depth: options?.depth ?? 0,
      ...(options?.parentExecutionId !== undefined ? { parentExecutionId: options.parentExecutionId } : {}),
      visited: options?.visited ?? new Set<string>(),
      branchDecisions: new Map(),
      skippedNodes: new Set(),
      variables,
    };
    this.activeRuns++;

    // V1.1 M1 (F1 resume / F2 idempotency): seed the context with outputs of
    // nodes that already succeeded for this execution so a resumed run skips
    // them instead of re-dispatching (and re-triggering side effects).
    await this.loadCompletedOutputs(executionId, ctx);

    // Transition execution to running
    await this.store.executions.updateStatus(executionId, {
      status: 'running',
      started_at: new Date().toISOString(),
    });
    metrics.activeExecutions.inc();
    await recordEvent(this.store, executionId, 'execution_started', undefined, {
      resumed: ctx.completedOutputs.size > 0,
    });
    this.emit({
      type: 'execution_started',
      executionId,
      status: 'running',
      timestamp: new Date().toISOString(),
      ...this.parentMarker(ctx),
    });

    // V1.1 M1 (F3): bound the WHOLE execution with a workflow-level timeout.
    // Per-definition `settings.workflow_timeout_ms` wins over the executor default.
    const workflowTimeoutMs = definition.settings?.workflow_timeout_ms ?? this.workflowTimeoutMs;
    const controller = new AbortController();
    let workflowTimedOut = false;
    const timer = setTimeout(() => {
      workflowTimedOut = true;
      controller.abort();
    }, workflowTimeoutMs);

    try {
      // Group nodes into topological levels; nodes within a level have no
      // inter-dependencies and run in parallel (§6.2). Levels run sequentially
      // so downstream nodes observe upstream outputs.
      const levels = computeLevels(definition.nodes, definition.edges);

      if (levels.length === 0) {
        // Empty workflow succeeds immediately
        await this.completeExecution(executionId, 'succeeded', startTime, undefined, ctx.workflowId, ctx.parentExecutionId);
        await recordEvent(this.store, executionId, 'execution_succeeded');
        return ctx.nodeOutputs;
      }

      for (const level of levels) {
        // Cooperative cancellation (M3): the API cancel route flips the row to
        // 'cancelled'; stop scheduling further levels instead of racing it.
        const current = await this.store.executions.getById(executionId);
        if (current?.status === 'cancelled') {
          throw new LoopError('EXECUTION_CANCELLED', `Execution '${executionId}' was cancelled`, 400);
        }
        // V1.7 (branch wiring): prune nodes whose every incoming edge is off a
        // non-taken branch port (or descends from a pruned node) BEFORE the
        // level runs — a decided branch must not execute both arms.
        const activeLevel = await this.pruneInactiveNodes(level, ctx, definition);
        const settled = await this.executeLevel(activeLevel, ctx, definition, controller.signal);
        // Abort the execution on the first node failure in this level; later
        // levels must not run (mirrors the previous fail-fast semantics).
        const failure = settled.find((r) => r.status === 'rejected');
        if (failure) {
          throw (failure as PromiseRejectedResult).reason;
        }
      }

      await this.completeExecution(executionId, 'succeeded', startTime, undefined, ctx.workflowId, ctx.parentExecutionId);
      await recordEvent(this.store, executionId, 'execution_succeeded');
      return ctx.nodeOutputs;
    } catch (err) {
      // A workflow-level timeout supersedes the underlying node abort error so
      // the persisted reason is unambiguous.
      const errorMsg = workflowTimedOut
        ? `Workflow '${executionId}' timed out after ${workflowTimeoutMs}ms (workflow_timeout)`
        : String(err);
      const finalErr = workflowTimedOut
        ? new LoopError('WORKFLOW_TIMEOUT', errorMsg, 500)
        : err;
      logger.error({ executionId, error: errorMsg }, 'Execution failed');
      await this.completeExecution(executionId, 'failed', startTime, errorMsg, ctx.workflowId, ctx.parentExecutionId);
      await recordEvent(this.store, executionId, 'execution_failed', undefined, {
        error: errorMsg,
        reason: workflowTimedOut ? 'workflow_timeout' : 'node_error',
      });
      throw finalErr;
    } finally {
      clearTimeout(timer);
      metrics.activeExecutions.dec();
      this.activeRuns--;
    }
  }

  /**
   * V1.7 (branch wiring): drop level nodes that are unreachable under the
   * branch decisions taken so far. A node is inactive when it HAS incoming
   * edges and every one of them is dead: an edge is dead when its source was
   * pruned, or when its source is a decided branch node and the edge's
   * `source_port` is not the taken port. Roots (no incoming edges) always run;
   * merge nodes survive on any single live incoming edge. Pruned nodes get a
   * `skipped` node_executions row + event so replay shows why they never ran,
   * and are recorded in `ctx.skippedNodes` so their own outgoing edges die
   * (pruning cascades through subsequent levels).
   */
  private async pruneInactiveNodes(
    level: WorkflowNode[],
    ctx: ExecutorContext,
    definition: WorkflowDefinition,
  ): Promise<WorkflowNode[]> {
    const active: WorkflowNode[] = [];
    for (const node of level) {
      const incoming = (definition.edges ?? []).filter((e) => e.target === node.id);
      const live = incoming.some((e) => {
        if (ctx.skippedNodes.has(e.source)) return false;
        const decision = ctx.branchDecisions.get(e.source);
        if (decision === undefined) return true;
        return e.source_port === decision;
      });
      if (live || incoming.length === 0) {
        active.push(node);
        continue;
      }
      ctx.skippedNodes.add(node.id);
      const nodeExecId = randomUUID();
      await this.store.nodeExecutions.create({
        id: nodeExecId,
        execution_id: ctx.executionId,
        node_id: node.id,
        node_type: node.type,
        input: node.config,
        idempotency_key: `${ctx.executionId}:${node.id}`,
      });
      await this.store.nodeExecutions.updateStatus(nodeExecId, {
        status: 'skipped',
        completed_at: new Date().toISOString(),
      });
      await recordEvent(this.store, ctx.executionId, 'node_skipped', node.id, {
        reason: 'branch_not_taken',
      });
      this.emit({
        type: 'node_skipped',
        executionId: ctx.executionId,
        nodeId: node.id,
        nodeType: node.type,
        status: 'skipped',
        timestamp: new Date().toISOString(),
        ...this.parentMarker(ctx),
      });
      logger.info({ executionId: ctx.executionId, nodeId: node.id }, 'Node skipped — branch not taken');
    }
    return active;
  }

  /**
   * Load already-succeeded node outputs for an execution into the context so
   * resume / idempotent retry can skip them. Best-effort: a read failure simply
   * leaves the maps empty (the run proceeds as a fresh execution).
   */
  private async loadCompletedOutputs(executionId: string, ctx: ExecutorContext): Promise<void> {
    try {
      const existing = await this.store.nodeExecutions.listByExecution(executionId);
      for (const ne of existing) {
        if (ne.status === 'succeeded') {
          ctx.completedOutputs.set(ne.node_id, ne.output);
          // Also expose to downstream variable interpolation ({{node_X.output.*}}).
          ctx.nodeOutputs.set(ne.node_id, ne.output);
        }
      }
    } catch (err) {
      logger.warn({ executionId, error: String(err) }, 'Failed to preload completed node outputs — running fresh');
    }
  }

  /**
   * Execute every node in a topological level concurrently, bounded by
   * `maxConcurrent`. Uses Promise.allSettled so one failing node does not
   * prevent its siblings from completing; the caller inspects the settled
   * results and fails the execution if any node rejected.
   */
  private async executeLevel(
    level: WorkflowNode[],
    ctx: ExecutorContext,
    definition: WorkflowDefinition,
    signal?: AbortSignal,
  ): Promise<PromiseSettledResult<void>[]> {
    const limit = Math.max(1, this.maxConcurrent);
    const settled: PromiseSettledResult<void>[] = [];

    for (let i = 0; i < level.length; i += limit) {
      // Stop scheduling further batches once the workflow deadline has passed —
      // nodes in later batches would otherwise fire connector calls nobody
      // awaits (side effects continuing after timeout).
      if (signal?.aborted) break;
      const batch = level.slice(i, i + limit);
      const batchResults = await Promise.allSettled(
        batch.map((node) => this.executeNode(node, ctx, definition, signal)),
      );
      settled.push(...batchResults);
    }

    return settled;
  }

  /**
   * Bound a node execution with a timeout. The caller-supplied controller is
   * aborted when the deadline elapses (so the in-flight connector call — which
   * observes the same signal — stops making network calls) and the returned
   * promise rejects with a NODE_TIMEOUT error, so a hung adapter cannot stall
   * the whole execution. An externally aborted controller (workflow-level
   * timeout) rejects with WORKFLOW_TIMEOUT.
   *
   * V1.1 M1 (F3): the workflow-level timeout aborts the controller, so every
   * in-flight node rejects with a WORKFLOW_TIMEOUT error instead of hanging.
   */
  private withTimeout<T>(controller: AbortController, promise: Promise<T>, ms: number, nodeId: string): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      // Always attach a no-op rejection handler first: if the controller is
      // already aborted (or aborts before the promise settles) the main
      // `promise.then` below may never attach, and an unhandled rejection
      // would crash the process (Node ≥15 default).
      promise.catch(() => {});

      // Distinguish the two abort causes: when the timer fires it aborts the
      // same controller this promise listens on, so the listener must not
      // race it to the rejection with a WORKFLOW_TIMEOUT.
      let timedOut = false;
      const timer = setTimeout(() => {
        timedOut = true;
        controller.abort();
        reject(new LoopError('NODE_TIMEOUT', `Node '${nodeId}' timed out after ${ms}ms`, 500));
      }, ms);

      const onAbort = (): void => {
        if (timedOut) return;
        clearTimeout(timer);
        reject(new LoopError('WORKFLOW_TIMEOUT', `Node '${nodeId}' aborted by workflow timeout (workflow_timeout)`, 500));
      };

      if (controller.signal.aborted) {
        clearTimeout(timer);
        onAbort();
        return;
      }
      controller.signal.addEventListener('abort', onAbort, { once: true });

      const cleanup = (): void => {
        clearTimeout(timer);
        controller.signal.removeEventListener('abort', onAbort);
      };

      promise.then(
        (value) => {
          cleanup();
          resolve(value);
        },
        (err) => {
          cleanup();
          reject(err);
        },
      );
    });
  }

  /**
   * V1.6 M1 (F-2, SP3): wrap the node lifecycle in a `loop.node` span. Started
   * inside the active `loop.execution` context, so it is auto-parented to the
   * execution span; a `workflow.invoke` child execution started below it is in
   * turn parented to this node span. Best-effort — never changes node results.
   */
  private async executeNode(
    node: WorkflowNode,
    ctx: ExecutorContext,
    definition: WorkflowDefinition,
    signal?: AbortSignal,
  ): Promise<void> {
    const span = startSpan('loop.node', {
      'node.id': node.id,
      'node.type': node.type,
      'execution.id': ctx.executionId,
    });
    let failed = false;
    try {
      return await runInSpan(span, () => this.executeNodeInner(node, ctx, definition, signal));
    } catch (err) {
      failed = true;
      span.setAttr('error.message', String(err));
      throw err;
    } finally {
      span.end(failed ? 'error' : 'ok');
    }
  }

  private async executeNodeInner(node: WorkflowNode, ctx: ExecutorContext, _definition: WorkflowDefinition, signal?: AbortSignal): Promise<void> {
    // Workflow deadline already passed — do not start new connector work.
    if (signal?.aborted) {
      throw new LoopError('WORKFLOW_TIMEOUT', `Node '${node.id}' aborted by workflow timeout (workflow_timeout)`, 500);
    }

    // V1.1 M1 (F1 resume / F2 idempotency): if this node already succeeded for
    // this execution, skip dispatch entirely and reuse its stored output — no
    // connector call, no duplicate side effects.
    const completed = ctx.completedOutputs.get(node.id);
    if (completed !== undefined) {
      ctx.nodeOutputs.set(node.id, completed);
      this.restoreBranchDecision(node, completed, ctx);
      logger.info({ executionId: ctx.executionId, nodeId: node.id }, 'Skipping already-succeeded node (resume/idempotent)');
      await recordEvent(this.store, ctx.executionId, 'node_skipped', node.id, { reason: 'already_succeeded' });
      this.emit({
        type: 'node_skipped',
        executionId: ctx.executionId,
        nodeId: node.id,
        nodeType: node.type,
        status: 'skipped',
        timestamp: new Date().toISOString(),
        ...this.parentMarker(ctx),
      });
      return;
    }

    const startTime = Date.now();
    // V1.1 M1 (F2): stable idempotency key per (execution, node).
    const idempotencyKey = `${ctx.executionId}:${node.id}`;

    // Resolve the node-execution row to write against. If a prior interrupted
    // attempt already created a row for this key, reuse it (reset to running)
    // instead of inserting a duplicate — the unique index on idempotency_key
    // would otherwise reject the insert. A succeeded row found here is treated
    // as an idempotent hit and skipped.
    let nodeExecId: string;
    const existingByKey = await this.store.nodeExecutions.findByIdempotencyKey(idempotencyKey);
    if (existingByKey) {
      if (existingByKey.status === 'succeeded') {
        ctx.nodeOutputs.set(node.id, existingByKey.output);
        ctx.completedOutputs.set(node.id, existingByKey.output);
        this.restoreBranchDecision(node, existingByKey.output, ctx);
        await recordEvent(this.store, ctx.executionId, 'node_skipped', node.id, { reason: 'idempotent_hit' });
        this.emit({
          type: 'node_skipped',
          executionId: ctx.executionId,
          nodeId: node.id,
          nodeType: node.type,
          status: 'skipped',
          timestamp: new Date().toISOString(),
          ...this.parentMarker(ctx),
        });
        return;
      }
      nodeExecId = existingByKey.id;
      await this.store.nodeExecutions.updateStatus(nodeExecId, {
        status: 'running',
        started_at: new Date().toISOString(),
        retry_count: existingByKey.retry_count + 1,
      });
    } else {
      nodeExecId = randomUUID();
      await this.store.nodeExecutions.create({
        id: nodeExecId,
        execution_id: ctx.executionId,
        node_id: node.id,
        node_type: node.type,
        input: node.config,
        idempotency_key: idempotencyKey,
      });
      await this.store.nodeExecutions.updateStatus(nodeExecId, {
        status: 'running',
        started_at: new Date().toISOString(),
      });
    }

    await recordEvent(this.store, ctx.executionId, 'node_started', node.id);
    this.emit({
      type: 'node_started',
      executionId: ctx.executionId,
      nodeId: node.id,
      nodeType: node.type,
      status: 'running',
      timestamp: new Date().toISOString(),
      ...this.parentMarker(ctx),
    });

    try {
      // V1.7 (branch wiring): `control.branch` is evaluated on the RAW
      // condition, before resolveVariables — generic interpolation strips the
      // {{…}} quotes and would turn string comparisons into bare-word (falsy)
      // references, inverting the branch semantics.
      let resolvedInput: Record<string, unknown>;
      if (node.type === 'workflow.invoke') {
        // Deep interpolation must NOT descend into the inline child
        // `definition` — its own {{trigger.payload.*}} references resolve
        // against the CHILD's payload at execution, not the parent's here
        // (pre-interpolating them with the parent context blanked the child's
        // references). `inputs` IS interpolated: parent values flow in.
        resolvedInput = {};
        for (const [key, value] of Object.entries(node.config)) {
          resolvedInput[key] = key === 'definition' ? value : this.resolveValue(value, ctx);
        }
      } else if (node.type === 'control.branch') {
        const condition = typeof node.config['condition'] === 'string' ? (node.config['condition'] as string) : '';
        const met = BranchNode.evaluateBranch(condition, this.branchContext(ctx));
        const decision: 'true' | 'false' = met ? 'true' : 'false';
        ctx.branchDecisions.set(node.id, decision);
        resolvedInput = { condition, condition_met: met, branch: decision };
      } else {
        // Resolve variable interpolation
        resolvedInput = this.resolveVariables(node.config, ctx);
      }

      // A per-node controller fuses the workflow-level signal with the node
      // timeout: both abort THIS controller, and the fused signal is what the
      // connector observes — so a timed-out node stops making HTTP calls
      // instead of continuing its side effects in the background.
      const controller = new AbortController();
      const forwardAbort = (): void => controller.abort();
      if (signal?.aborted) controller.abort();
      else signal?.addEventListener('abort', forwardAbort, { once: true });

      // Execute with retry, bounded by the node timeout (per-node override or
      // the executor-wide default). Retries stop once the controller aborts.
      try {
        const retryConfig = node.retry ?? this.defaultRetry ?? { max_attempts: 0, backoff: 'fixed' as const, initial_delay_ms: 0 };
        const timeoutMs = node.timeout_ms ?? this.nodeTimeoutMs;
        const result = await this.withTimeout(
          controller,
          executeWithRetry(
            async () => this.dispatchNode(node, resolvedInput, ctx, idempotencyKey, controller.signal),
            retryConfig,
            (attempt, error) => {
              logger.warn({ nodeId: node.id, attempt, error: String(error) }, 'Node retry');
            },
            controller.signal,
          ),
          timeoutMs,
          node.id,
        );

        // Store output
        ctx.nodeOutputs.set(node.id, result);

        // Transition to succeeded
        await this.store.nodeExecutions.updateStatus(nodeExecId, {
          status: 'succeeded',
          completed_at: new Date().toISOString(),
          output: result,
        });
        await recordEvent(this.store, ctx.executionId, 'node_succeeded', node.id, {
          duration_ms: Date.now() - startTime,
          // V1.4 M2 (F-2): persist the node output (size-capped) so replay can
          // reconstruct full node outputs from the event log. Oversized outputs
          // are stored as a `{__truncated__, size, preview}` marker.
          output: capOutputForEvent(result, this.eventOutputMaxBytes),
        });
        this.emit({
          type: 'node_succeeded',
          executionId: ctx.executionId,
          nodeId: node.id,
          nodeType: node.type,
          status: 'succeeded',
          timestamp: new Date().toISOString(),
          output: result,
          durationMs: Date.now() - startTime,
          ...this.parentMarker(ctx),
        });

        const duration = (Date.now() - startTime) / 1000;
        metrics.nodeDuration.observe({ node_type: node.type, workflow_id: ctx.workflowId }, duration);
      } finally {
        signal?.removeEventListener('abort', forwardAbort);
      }
    } catch (err) {
      await this.store.nodeExecutions.updateStatus(nodeExecId, {
        status: 'failed',
        completed_at: new Date().toISOString(),
        error: String(err),
      });
      await recordEvent(this.store, ctx.executionId, 'node_failed', node.id, { error: String(err) });
      this.emit({
        type: 'node_failed',
        executionId: ctx.executionId,
        nodeId: node.id,
        nodeType: node.type,
        status: 'failed',
        timestamp: new Date().toISOString(),
        error: String(err),
        ...this.parentMarker(ctx),
      });
      metrics.nodeErrorsTotal.inc({ node_type: node.type, error_type: 'execution_error' });
      throw err;
    }
  }

  private async dispatchNode(
    node: WorkflowNode,
    input: Record<string, unknown>,
    ctx: ExecutorContext,
    idempotencyKey?: string,
    signal?: AbortSignal,
  ): Promise<Record<string, unknown>> {
    // V1.2 M3 (F-Loop-1): `workflow.invoke` is an engine built-in, NOT a
    // connector — intercept it before connector routing so it recurses into a
    // child execution on the same executor (reusing timeout/events/idempotency).
    if (node.type === 'workflow.invoke') {
      return this.invokeSubWorkflow(node, input, ctx);
    }

    // V1.7 (L-4): `control.delay` is an engine built-in — actually wait (bounded
    // by the node timeout wrapping this dispatch).
    if (node.type === 'control.delay') {
      const raw = input['duration_ms'] ?? input['duration'];
      const ms = Number(raw);
      if (!Number.isFinite(ms) || ms < 0) {
        throw new LoopError('VALIDATION_INVALID', `control.delay node '${node.id}' requires a non-negative numeric duration_ms`, 400);
      }
      await DelayNode.delay(Math.floor(ms));
      return { delayed_ms: Math.floor(ms) };
    }

    // V1.7 (L-4): approval/loop/parallel are NOT executed yet — make the
    // pass-through observable instead of silently pretending the node worked.
    if (node.type === 'control.approval' || node.type === 'control.loop' || node.type === 'control.parallel') {
      logger.warn(
        { nodeId: node.id, nodeType: node.type, executionId: ctx.executionId },
        'Control node type is not implemented yet — passing through without pausing (see NEXT_STEPS)',
      );
    }

    // Determine connector type from node type (e.g. "vault.search" → "vault")
    const connectorType = node.type.split('.')[0] ?? node.type;
    const operation = node.type.split('.').slice(1).join('.') ?? 'execute';

    const adapter = this.connectors.getAdapter(connectorType);
    if (!adapter) {
      // Control nodes (e.g. "control.condition") pass through input as output.
      // Unknown connector types are logged as warnings for debuggability.
      if (!connectorType.startsWith('control')) {
        logger.warn(
          { nodeId: node.id, nodeType: node.type, connectorType },
          'No adapter registered for connector type — passing input as output',
        );
      }
      return input;
    }

    const instanceId = this.connectors.listInstances().find((id) => {
      return this.connectors.getInstanceAdapterType(id) === connectorType;
    });

    const config = instanceId ? this.connectors.getInstanceConfig(instanceId) : {};
    // Surface the instance's api_key (when present) as a secret so adapters can
    // authenticate upstream calls (INTEGRATION_CONTRACT.md §4.2). V1.7 (L-2):
    // the encrypted secrets store is consulted first (set via
    // POST /api/v1/connectors), with the instance's inline config as fallback
    // (env-registered instances legitimately carry their key inline).
    let apiKey: string | undefined;
    if (instanceId && this.secretResolver) {
      const resolved = await this.secretResolver('api_key', 'connector', instanceId);
      if (resolved !== null) apiKey = resolved;
    }
    if (apiKey === undefined && typeof config?.['api_key'] === 'string' && (config['api_key'] as string).length > 0) {
      apiKey = config['api_key'] as string;
    }
    const secrets = apiKey !== undefined ? { api_key: apiKey } : undefined;
    // V1.1 M1 (F2): forward the idempotency key so connectors can best-effort
    // propagate it upstream (e.g. an `Idempotency-Key` header). Optional — the
    // request/response contract is unchanged (INTEGRATION_CONTRACT.md §4).
    // Adapters must consult `egress` before every outbound call and forward
    // `signal` so timeouts/airgap actually stop the network work.
    const result = await adapter.execute({
      operation,
      input,
      config,
      secrets,
      idempotencyKey,
      ...(this.egressGate ? { egress: this.egressGate } : {}),
      ...(signal ? { signal } : {}),
    });
    return result.output;
  }

  /**
   * V1.7 (branch wiring): context handed to the restricted condition
   * evaluator. Supports `{{trigger.payload.*}}`, `{{variables.*}}` and
   * `{{<nodeId>.output.*}}` references against this execution's state.
   */
  private branchContext(ctx: ExecutorContext): Record<string, unknown> {
    const context: Record<string, unknown> = {
      trigger: { payload: ctx.triggerPayload },
      variables: ctx.variables,
    };
    for (const [id, output] of ctx.nodeOutputs) {
      context[id] = { output };
    }
    return context;
  }

  /**
   * V1.7 (branch wiring): on resume/idempotent skip of a completed branch
   * node, rebuild its decision from the persisted output so downstream pruning
   * still sees which port fired.
   */
  private restoreBranchDecision(node: WorkflowNode, output: Record<string, unknown> | undefined, ctx: ExecutorContext): void {
    if (node.type !== 'control.branch' || !output) return;
    const branch = output['branch'];
    if (branch === 'true' || branch === 'false') {
      ctx.branchDecisions.set(node.id, branch);
    }
  }

  /** Resolve {{variable}} references in config values. */
  private resolveVariables(config: Record<string, unknown>, ctx: ExecutorContext): Record<string, unknown> {
    const resolved: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(config)) {
      resolved[key] = this.resolveValue(value, ctx);
    }
    return resolved;
  }

  /**
   * V1.7 (L-6): interpolate DEEP — nested objects and arrays inside node
   * configs (e.g. a generic REST `body` object) previously kept their literal
   * `{{…}}` text and were sent upstream verbatim.
   */
  private resolveValue(value: unknown, ctx: ExecutorContext): unknown {
    if (typeof value === 'string') {
      return this.interpolateString(value, ctx);
    }
    if (Array.isArray(value)) {
      return value.map((item) => this.resolveValue(item, ctx));
    }
    if (value !== null && typeof value === 'object') {
      const out: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
        out[k] = this.resolveValue(v, ctx);
      }
      return out;
    }
    return value;
  }

  private interpolateString(template: string, ctx: ExecutorContext): string {
    return template.replace(/\{\{([^}]+)\}\}/g, (_match, varPath: string) => {
      const path = varPath.trim();
      if (path.startsWith('trigger.payload.')) {
        // Traverse the dotted path segment by segment so nested payloads
        // (`trigger.payload.data.customer.id`) resolve; the previous flat
        // lookup silently emitted an empty string for any nesting.
        const key = path.slice('trigger.payload.'.length);
        const value = key
          .split('.')
          .reduce<unknown>(
            (obj, segment) =>
              obj !== null && typeof obj === 'object' ? (obj as Record<string, unknown>)[segment] : undefined,
            ctx.triggerPayload,
          );
        return value === undefined || value === null ? '' : String(value);
      }
      // V1.7 (L-6): workflow-level variables (`{{variables.name}}`) resolve to
      // the definition's declared default — previously they interpolated to an
      // empty string, silently corrupting downstream URLs/recipients.
      if (path.startsWith('variables.')) {
        const segments = path.slice('variables.'.length).split('.');
        const value = segments.reduce<unknown>(
          (obj, segment) =>
            obj !== null && typeof obj === 'object' ? (obj as Record<string, unknown>)[segment] : undefined,
          ctx.variables,
        );
        return value === undefined || value === null ? '' : String(value);
      }
      // Node outputs: look the reference up against the raw node id first
      // (works for any id shape, incl. hyphens/UUIDs), falling back to the
      // legacy `node_X` prefixed-id convention.
      const outputMatch = path.match(/^([\w-]+)\.output\.(.+)$/);
      if (outputMatch) {
        const rawId = outputMatch[1]!;
        const outputKey = outputMatch[2]!;
        const nodeOutput = ctx.nodeOutputs.get(rawId) ?? ctx.nodeOutputs.get(`node_${rawId}`);
        return String(this.resolveOutputPath(nodeOutput, outputKey) ?? '');
      }
      return '';
    });
  }

  /**
   * Resolve a (possibly dotted) output key against a node's output. A flat key
   * wins unchanged (V1.0/V1.1 behaviour); when absent, the key is traversed as
   * a nested path so sub-workflow outputs are reachable, e.g.
   * `{{node_sub.output.outputs.node_c1.value}}` (V1.2 M3, S3).
   */
  private resolveOutputPath(nodeOutput: Record<string, unknown> | undefined, outputKey: string): unknown {
    if (nodeOutput === undefined) return undefined;
    if (outputKey in nodeOutput) return nodeOutput[outputKey];
    let current: unknown = nodeOutput;
    for (const segment of outputKey.split('.')) {
      if (current === null || typeof current !== 'object') return undefined;
      current = (current as Record<string, unknown>)[segment];
    }
    return current;
  }

  private async completeExecution(
    executionId: string,
    status: 'succeeded' | 'failed',
    startTime: number,
    error?: string,
    workflowId?: string,
    parentExecutionId?: string,
  ): Promise<void> {
    const duration = Date.now() - startTime;
    // Guarded transition: never overwrite a terminal status. Without the guard
    // an executor completion raced (and reverted) an API-initiated cancel.
    const applied = await this.store.executions.completeIfActive(executionId, {
      status,
      completed_at: new Date().toISOString(),
      duration_ms: duration,
      ...(error !== undefined ? { error } : {}),
    });
    let finalStatus: ExecutionStatus = status;
    if (!applied) {
      const current = await this.store.executions.getById(executionId);
      if (current) finalStatus = current.status;
    }
    metrics.executionsTotal.inc({ workflow_id: workflowId ?? 'unknown', status: finalStatus });
    metrics.executionDuration.observe({ workflow_id: workflowId ?? 'unknown' }, duration / 1000);
    // V1.1 M2 (F5): real-time terminal status for live monitors.
    this.emit({
      type: finalStatus === 'succeeded' ? 'execution_succeeded' : 'execution_failed',
      executionId,
      status: finalStatus,
      timestamp: new Date().toISOString(),
      durationMs: duration,
      ...(error !== undefined ? { error } : {}),
      ...(parentExecutionId !== undefined ? { parentExecutionId } : {}),
    });
  }

  /**
   * V1.2 M3 (F-Loop-1): execute a `workflow.invoke` node. Resolves the child
   * definition (inline `input.definition` object, or load by `input.workflow_id`),
   * maps `input.inputs` onto the child's `trigger.payload`, and recursively runs
   * the child on the SAME executor — so the child reuses the workflow timeout,
   * EventBus fan-out, idempotency and resume machinery. Returns
   * `{ outputs, status: 'succeeded' }` (the child's final per-node outputs) so
   * downstream parent nodes can reference them; a failing child throws, failing
   * this parent node. Recursion is bounded by `maxSubWorkflowDepth` plus a
   * visited-set cycle guard.
   */
  private async invokeSubWorkflow(
    node: WorkflowNode,
    input: Record<string, unknown>,
    ctx: ExecutorContext,
  ): Promise<Record<string, unknown>> {
    const childDepth = ctx.depth + 1;
    if (childDepth > this.maxSubWorkflowDepth) {
      throw new LoopError(
        'SUBWORKFLOW_DEPTH_EXCEEDED',
        `Sub-workflow recursion depth ${childDepth} exceeds the maximum of ${this.maxSubWorkflowDepth} (node '${node.id}')`,
        400,
        { node_id: node.id, depth: childDepth, max_depth: this.maxSubWorkflowDepth },
      );
    }

    // Resolve the child definition: an inline object wins, else load by id.
    const inline = input['definition'];
    const workflowIdInput = input['workflow_id'];
    let childDefinition: WorkflowDefinition;
    let childWorkflowId: string | undefined;
    let childVersion: number = 1;

    if (inline !== undefined && inline !== null && typeof inline === 'object' && !Array.isArray(inline)) {
      const candidate = inline as WorkflowDefinition;
      // Stored definitions pass authoring validation on save; an inline
      // definition bypasses that path entirely, so run a structural check
      // here — otherwise a malformed/cyclic inline graph is silently
      // "partially executed and successful" (computeLevels drops cycle nodes).
      validateInlineDefinition(candidate, node.id);
      childDefinition = candidate;
    } else if (typeof workflowIdInput === 'string' && workflowIdInput.length > 0) {
      const loaded = await this.store.workflows.getById(workflowIdInput);
      if (!loaded) {
        throw new LoopError('NOT_FOUND_WORKFLOW', `Sub-workflow '${workflowIdInput}' not found (node '${node.id}')`, 404);
      }
      childDefinition = loaded.definition;
      childWorkflowId = loaded.id;
      childVersion = loaded.version;
    } else {
      throw new LoopError(
        'VALIDATION_REQUIRED',
        `workflow.invoke node '${node.id}' requires an inline 'definition' object or a 'workflow_id'`,
        400,
      );
    }

    // Cycle guard: a definition already on the invocation stack means an
    // infinite loop — fail fast instead of recursing to the depth ceiling.
    const key = subWorkflowKey(childDefinition, childWorkflowId);
    if (ctx.visited.has(key)) {
      throw new LoopError(
        'SUBWORKFLOW_DEPTH_EXCEEDED',
        `Sub-workflow invocation cycle detected at '${key}' (node '${node.id}')`,
        400,
        { node_id: node.id, cycle: key },
      );
    }

    // Input mapping (S3): parent node `input.inputs` → child `trigger.payload`.
    const rawInputs = input['inputs'];
    const childPayload =
      rawInputs !== undefined && rawInputs !== null && typeof rawInputs === 'object' && !Array.isArray(rawInputs)
        ? (rawInputs as Record<string, unknown>)
        : {};

    // Resolve a valid `workflow_id` FK for the child execution row. Stored
    // sub-workflows use their own id; inline definitions reuse the parent
    // execution's workflow_id so the child execution and its node/event rows
    // satisfy FK constraints without persisting a synthetic workflow.
    if (childWorkflowId === undefined) {
      const parentExecution = await this.store.executions.getById(ctx.executionId);
      if (!parentExecution) {
        throw new LoopError(
          'INTERNAL_ERROR',
          `Parent execution '${ctx.executionId}' not found for sub-workflow invocation`,
          500,
        );
      }
      childWorkflowId = parentExecution.workflow_id;
      childVersion = parentExecution.workflow_version;
    }

    const childExecutionId = randomUUID();
    await this.store.executions.create({
      id: childExecutionId,
      workflow_id: childWorkflowId,
      // The stored workflow's current version, or (for inline definitions
      // reusing the parent's FK) the parent execution's version — a hardcoded
      // 1 resolved stale definitions during replay.
      workflow_version: childVersion,
      trigger_type: 'event',
      trigger_payload: childPayload,
    });

    const visited = new Set(ctx.visited);
    visited.add(key);

    // Recurse on the same executor; a child failure propagates up and fails
    // this parent node (execute() re-throws the terminal error).
    const childOutputs = await this.execute(childExecutionId, childDefinition, childPayload, {
      depth: childDepth,
      parentExecutionId: ctx.executionId,
      visited,
    });

    // Output return (S3): expose the child's final per-node outputs.
    const outputs: Record<string, Record<string, unknown>> = {};
    for (const [nodeId, output] of childOutputs) {
      outputs[nodeId] = output;
    }
    return { outputs, status: 'succeeded' };
  }
}

/**
 * V1.2 M3: stable identity for a sub-workflow definition used by the cycle
 * guard — the stored workflow id when known, else the definition's name, else a
 * fingerprint of its node ids.
 */
function subWorkflowKey(definition: WorkflowDefinition, workflowId?: string): string {
  if (workflowId !== undefined) return `id:${workflowId}`;
  const name = definition.metadata?.name;
  if (name !== undefined && name.length > 0) return `name:${name}`;
  return `nodes:${definition.nodes.map((n) => n.id).join(',')}`;
}

/**
 * Structural validation for inline sub-workflow definitions. Stored
 * definitions are validated at authoring time; inline ones arrive straight
 * from node input, so a malformed graph (missing nodes/edges, dangling edge
 * references, duplicate node ids) must fail fast instead of being silently
 * dropped level-by-level by the scheduler.
 */
function validateInlineDefinition(definition: WorkflowDefinition, nodeId: string): void {
  if (!definition || !Array.isArray(definition.nodes)) {
    throw new LoopError('VALIDATION_INVALID', `workflow.invoke node '${nodeId}': inline definition has no nodes array`, 400);
  }
  const ids = new Set<string>();
  for (const n of definition.nodes) {
    if (!n || typeof n.id !== 'string' || n.id.length === 0 || typeof n.type !== 'string' || n.type.length === 0) {
      throw new LoopError('VALIDATION_INVALID', `workflow.invoke node '${nodeId}': inline definition contains a node without a string id/type`, 400);
    }
    if (ids.has(n.id)) {
      throw new LoopError('VALIDATION_INVALID', `workflow.invoke node '${nodeId}': duplicate node id '${n.id}' in inline definition`, 400);
    }
    ids.add(n.id);
  }
  for (const e of definition.edges ?? []) {
    if (!e || !ids.has(e.source) || !ids.has(e.target)) {
      throw new LoopError('VALIDATION_INVALID', `workflow.invoke node '${nodeId}': inline definition edge references an unknown node`, 400);
    }
  }
  // Cycles: this is the only definition entry point that bypasses authoring's
  // detectCycle. computeLevels silently truncates cyclic graphs — the nodes on
  // the cycle vanish and the sub-workflow reports success with missing output.
  try {
    topologicalSort(definition.nodes, definition.edges ?? []);
  } catch {
    throw new LoopError('VALIDATION_INVALID', `workflow.invoke node '${nodeId}': inline definition contains a dependency cycle`, 400);
  }
}

/**
 * Control flow node handlers — branch, loop, parallel, approval, delay (§6.1, §6.6).
 */

import { createLogger } from '@loop/observability';

const logger = createLogger({ name: 'loop:engine:nodes', component: 'engine' });

// ─── Branch ───────────────────────────────────────────────────────────────────

/**
 * Tokens for the restricted condition language. Only the constructs below are
 * recognised — anything else makes evaluation fail closed (false). Conditions
 * in workflow definitions previously went through `new Function`, which let a
 * workflow author execute arbitrary JavaScript inside the API process (RCE).
 */
type Token =
  | { kind: 'number'; value: number }
  | { kind: 'string'; value: string }
  | { kind: 'ident'; value: string }
  | { kind: 'op'; value: string };

const OPERATORS = [
  '===', '!==', '==', '!=', '>=', '<=', '&&', '||',
  '>', '<', '!', '(', ')',
] as const;

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    const ch = input[i]!;
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
      i++;
      continue;
    }
    // String literal ('…' or "…") — no escapes, conditions compare scalars.
    if (ch === '\'' || ch === '"') {
      const end = input.indexOf(ch, i + 1);
      if (end === -1) throw new Error('unterminated string literal');
      tokens.push({ kind: 'string', value: input.slice(i + 1, end) });
      i = end + 1;
      continue;
    }
    // Number literal.
    if (/[0-9]/.test(ch) || (ch === '-' && /[0-9]/.test(input[i + 1] ?? ''))) {
      const match = /^-?[0-9]+(\.[0-9]+)?/.exec(input.slice(i))!;
      tokens.push({ kind: 'number', value: Number(match[0]) });
      i += match[0].length;
      continue;
    }
    // Identifier / keyword (true, false, null, or a bare reference).
    if (/[A-Za-z_]/.test(ch)) {
      const match = /^[A-Za-z_][A-Za-z0-9_]*/.exec(input.slice(i))!;
      tokens.push({ kind: 'ident', value: match[0] });
      i += match[0].length;
      continue;
    }
    // Operator / paren.
    const op = OPERATORS.find((o) => input.startsWith(o, i));
    if (op === undefined) throw new Error(`unexpected character '${ch}'`);
    tokens.push({ kind: 'op', value: op });
    i += op.length;
  }
  return tokens;
}

/** Truthiness of a evaluated condition value (JS semantics for scalars). */
function isTruthy(value: ConditionValue): boolean {
  return value !== null && value !== undefined && value !== false && value !== 0 && value !== '';
}

type ConditionValue = string | number | boolean | null | undefined;

/** Equality across scalars — strict when types match, string-compared otherwise. */
function looseEquals(a: ConditionValue, b: ConditionValue): boolean {
  if (a === b) return true;
  if (a === null || a === undefined || b === null || b === undefined) return false;
  if (typeof a === typeof b) return false;
  return String(a) === String(b);
}

/** Numeric ordering for scalar comparisons (string-compared when mixed). */
function compareOrder(a: ConditionValue, b: ConditionValue): number {
  // Unresolved references (null/undefined) must never satisfy a comparison —
  // fail with NaN so every relational operator returns false.
  if (a === null || a === undefined || b === null || b === undefined) return Number.NaN;
  const na = typeof a === 'number' ? a : Number(a);
  const nb = typeof b === 'number' ? b : Number(b);
  if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
  const sa = String(a);
  const sb = String(b);
  return sa < sb ? -1 : sa > sb ? 1 : 0;
}

/**
 * Recursive-descent evaluator for the restricted grammar:
 *   or      := and ( '||' and )*
 *   and     := cmp ( '&&' cmp )*
 *   cmp     := unary ( ('=='|'!='|'==='|'!=='|'>'|'<'|'>='|'<=') unary )?
 *   unary   := '!' unary | '(' or ')' | literal
 *   literal := number | string | 'true' | 'false' | 'null'
 */
class ConditionParser {
  private pos = 0;

  constructor(private tokens: Token[]) {}

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  private eatOp(value: string): boolean {
    const t = this.peek();
    if (t && t.kind === 'op' && t.value === value) {
      this.pos++;
      return true;
    }
    return false;
  }

  parse(): ConditionValue {
    const value = this.parseOr();
    if (this.pos !== this.tokens.length) throw new Error('trailing tokens in condition');
    return value;
  }

  private parseOr(): ConditionValue {
    let left = this.parseAnd();
    while (this.eatOp('||')) {
      const right = this.parseAnd();
      left = isTruthy(left) || isTruthy(right);
    }
    return left;
  }

  private parseAnd(): ConditionValue {
    let left = this.parseCmp();
    while (this.eatOp('&&')) {
      const right = this.parseCmp();
      left = isTruthy(left) && isTruthy(right);
    }
    return left;
  }

  private parseCmp(): ConditionValue {
    const left = this.parseUnary();
    const t = this.peek();
    if (t && t.kind === 'op' && ['==', '!=', '===', '!==', '>', '<', '>=', '<='].includes(t.value)) {
      this.pos++;
      const right = this.parseUnary();
      switch (t.value) {
        case '==':
        case '===':
          return looseEquals(left, right);
        case '!=':
        case '!==':
          return !looseEquals(left, right);
        case '>': return compareOrder(left, right) > 0;
        case '<': return compareOrder(left, right) < 0;
        case '>=': return compareOrder(left, right) >= 0;
        case '<=': return compareOrder(left, right) <= 0;
      }
    }
    return left;
  }

  private parseUnary(): ConditionValue {
    if (this.eatOp('!')) {
      return !isTruthy(this.parseUnary());
    }
    return this.parsePrimary();
  }

  private parsePrimary(): ConditionValue {
    const t = this.peek();
    if (t === undefined) throw new Error('unexpected end of condition');
    if (t.kind === 'op' && t.value === '(') {
      this.pos++;
      const value = this.parseOr();
      if (!this.eatOp(')')) throw new Error('missing closing parenthesis');
      return value;
    }
    this.pos++;
    if (t.kind === 'number') return t.value;
    if (t.kind === 'string') return t.value;
    if (t.kind === 'ident') {
      if (t.value === 'true') return true;
      if (t.value === 'false') return false;
      if (t.value === 'null') return null;
      // Bare references (post-interpolation leftovers) are unknown → falsy.
      return undefined;
    }
    throw new Error(`unexpected token '${t.value}'`);
  }
}

export class BranchNode {
  /**
   * V1.7 (branch wiring): public entry for the executor. Evaluates a single
   * `control.branch` condition against an execution context
   * (`trigger.payload.*`, `variables.*`, `<nodeId>.output.*`) and reports
   * which port fired.
   */
  static evaluateBranch(condition: string, context: Record<string, unknown>): boolean {
    return this.evalCondition(condition, context);
  }

  /** Evaluate a branch condition and return the selected branch ID. */
  static evaluate(conditions: Array<{ id: string; condition: string }>, context: Record<string, unknown>): string | null {
    for (const branch of conditions) {
      if (this.evalCondition(branch.condition, context)) {
        return branch.id;
      }
    }
    return null;
  }

  private static evalCondition(condition: string, context: Record<string, unknown>): boolean {
    // Restricted expression evaluator — NO `new Function`/eval. Interpolated
    // `{{reference}}` values are JSON-encoded (so strings stay quoted, numbers
    // stay numeric) and only comparison/logic operators are recognised. Any
    // parse failure fails closed (false), as before.
    try {
      const expr = condition.replace(/\{\{([^}]+)\}\}/g, (_match, path: string) => {
        const value = path.split('.').reduce((obj: unknown, key: string) => {
          if (obj && typeof obj === 'object') return (obj as Record<string, unknown>)[key];
          return undefined;
        }, context);
        // JSON.stringify(undefined) is undefined — emit the bare word so the
        // parser treats it as an unknown (falsy) reference.
        const serialized = JSON.stringify(value) ?? 'undefined';
        return serialized;
      });
      const value = new ConditionParser(tokenize(expr)).parse();
      return isTruthy(value);
    } catch (err) {
      logger.debug({ condition, error: String(err) }, 'Condition evaluation failed — treating as false');
      return false;
    }
  }
}

// ─── Loop ─────────────────────────────────────────────────────────────────────

export class LoopNode {
  /** Check if a loop should continue iterating. */
  static shouldContinue(condition: string, context: Record<string, unknown>, iteration: number, maxIterations = 1000): boolean {
    if (iteration >= maxIterations) {
      logger.warn({ iteration, maxIterations }, 'Loop hit max iterations');
      return false;
    }
    return BranchNode.evaluate([{ id: 'continue', condition }], context) === 'continue';
  }
}

// ─── Parallel ─────────────────────────────────────────────────────────────────

export class ParallelNode {
  /** Execute multiple branches in parallel and wait for all to complete. */
  static async executeAll<T>(fns: Array<() => Promise<T>>): Promise<T[]> {
    return Promise.all(fns.map((fn) => fn()));
  }
}

// ─── Approval ─────────────────────────────────────────────────────────────────

export class ApprovalNode {
  /** Pause execution for human approval (returns a waitpoint token). */
  static createWaitpoint(executionId: string, nodeId: string): string {
    return `approval:${executionId}:${nodeId}`;
  }
}

// ─── Delay ────────────────────────────────────────────────────────────────────

export class DelayNode {
  /** Pause execution for a specified duration. */
  static async delay(durationMs: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, durationMs));
  }
}

/**
 * Execution recovery on application startup (§8.4).
 * Finds interrupted executions and either resumes or marks them as failed.
 *
 * Interrupted = any non-terminal execution owned by the previous (now dead)
 * process: 'running' (died mid-execution) or 'pending' (created but never
 * dispatched). When a dispatcher is injected, recoverable executions are
 * re-dispatched to the executor — resetting to 'pending' alone leaves them
 * stuck because nothing polls the store (bugs 12/13).
 */

import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';
import type { WorkflowExecution } from '@loop/types';
import { recordEvent } from './eventLog.js';

const logger = createLogger({ name: 'loop:engine:recovery', component: 'engine' });

/** Re-dispatches a recovered execution to the executor. */
export type RecoveryDispatcher = (execution: WorkflowExecution) => Promise<void>;

export class ExecutionRecovery {
  constructor(
    private store: StateStore,
    private dispatcher?: RecoveryDispatcher,
  ) {}

  /** Run recovery — called once on startup. */
  async recover(): Promise<{ recovered: number; failed: number }> {
    const interrupted = await this.store.executions.findInterrupted();
    let recovered = 0;
    let failed = 0;

    for (const execution of interrupted) {
      const nodeExecs = await this.store.nodeExecutions.listByExecution(execution.id);
      const lastCompleted = nodeExecs.filter((n) => n.status === 'succeeded').pop();

      if (!lastCompleted && execution.status === 'running') {
        // Died mid-execution with zero completed nodes — the in-flight node's
        // side effects are ambiguous, so re-running is not safe. Mark failed.
        await this.store.executions.updateStatus(execution.id, {
          status: 'failed',
          error: 'Interrupted by system restart',
          completed_at: new Date().toISOString(),
        });
        logger.info({ executionId: execution.id }, 'Marked non-recoverable execution as failed');
        failed++;
        continue;
      }

      // Recoverable: 'running' with completed nodes (resume — the executor
      // skips already-succeeded nodes) or 'pending' that never started.
      const reason = lastCompleted ? 'resume_from_last_succeeded' : 'never_started';
      await this.store.executions.updateStatus(execution.id, {
        status: 'pending',
      });
      // V1.1 M1 (F1): audit the recovery so the resume is traceable.
      await recordEvent(this.store, execution.id, 'execution_recovered', undefined, {
        last_succeeded_node: lastCompleted?.node_id ?? null,
        reason,
      });

      if (this.dispatcher) {
        try {
          await this.dispatcher(execution);
        } catch (err) {
          // Dispatch failed (e.g. workflow archived) — settle to a terminal
          // state instead of leaving the record pending again.
          await this.store.executions.updateStatus(execution.id, {
            status: 'failed',
            error: `Recovery dispatch failed: ${String(err)}`,
            completed_at: new Date().toISOString(),
          });
          logger.warn({ executionId: execution.id, error: String(err) }, 'Recovery dispatch failed');
          failed++;
          continue;
        }
      }

      logger.info(
        { executionId: execution.id, lastNode: lastCompleted?.node_id ?? null, reason },
        'Recovered execution — reset to pending and re-dispatched',
      );
      recovered++;
    }

    logger.info({ recovered, failed, total: interrupted.length }, 'Execution recovery complete');
    return { recovered, failed };
  }
}

/**
 * Event-sourced replay (V1.3 M1, F-Loop-1).
 *
 * Two capabilities, both built on the append-only `execution_events` log
 * (V1.1 M1):
 *
 *  - `reconstructExecution(store, executionId)` folds the event stream back
 *    into an `ExecutionSnapshot` (execution status + per-node states +
 *    timeline). The fold itself (`foldExecutionEvents`) is a PURE function —
 *    it only reads events and never touches connectors or mutates state.
 *
 *  - `replayExecution(executor, store, executionId, { dryRun })` defaults to a
 *    READ-ONLY dry-run: it reconstructs the snapshot and, against the workflow
 *    definition, decides per node whether a re-run WOULD execute it
 *    (`would-run`), skip it because it already succeeded
 *    (`skipped-because-succeeded`), or marks the prior failure point
 *    (`failed`) — WITHOUT invoking any connector (no side effects). Only when
 *    explicitly asked (`dryRun === false`) does it really re-execute, reusing
 *    the V1.1 resume path (`executor.execute`) that skips succeeded nodes.
 */

import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';
import {
  NotFoundError,
  type ExecutionEvent,
  type ExecutionSnapshot,
  type ExecutionStatus,
  type NodeReplayDecision,
  type NodeSnapshot,
  type ReplayResult,
  type SnapshotTimelineEntry,
  type WorkflowDefinition,
  type WorkflowExecution,
} from '@loop/types';
import type { ExecutionExecutor } from './executor.js';
import { computeLevels } from './scheduler.js';

const logger = createLogger({ name: 'loop:engine:replay', component: 'engine' });

/** Coerce an unknown event-payload value to a plain record, or undefined. */
function asRecord(value: unknown): Record<string, unknown> | undefined {
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return undefined;
}

/** Extract a string field from an event payload, or undefined. */
function asString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

/**
 * PURE fold of an ordered event stream into an execution snapshot.
 *
 * Reads only the supplied events — no I/O, no side effects — so it is fully
 * deterministic and trivially testable: the same event sequence always yields
 * the same snapshot. Events are expected in ascending `created_at` order (as
 * returned by `events.listByExecution`); later events win for a given node.
 */
export function foldExecutionEvents(executionId: string, events: ExecutionEvent[]): ExecutionSnapshot {
  const nodeStates = new Map<string, NodeSnapshot>();
  const timeline: SnapshotTimelineEntry[] = [];
  let status: ExecutionStatus = 'pending';
  let startedAt: string | undefined;
  let endedAt: string | undefined;
  let error: string | undefined;

  const setNode = (nodeId: string, patch: NodeSnapshot): void => {
    const existing = nodeStates.get(nodeId);
    nodeStates.set(nodeId, { ...existing, ...patch });
  };

  for (const event of events) {
    const timestamp = new Date(event.created_at).toISOString();
    const payload = event.payload ?? {};
    const nodeId = event.node_id ?? undefined;
    let detail: string | undefined;

    switch (event.event_type) {
      case 'execution_started':
        status = 'running';
        startedAt = timestamp;
        break;
      case 'execution_recovered':
        // A recovered execution is re-queued for resume → treat as running.
        status = 'running';
        detail = asString(payload['last_succeeded_node']);
        break;
      case 'execution_succeeded':
        status = 'succeeded';
        endedAt = timestamp;
        break;
      case 'execution_failed':
        status = 'failed';
        endedAt = timestamp;
        error = asString(payload['error']) ?? error;
        detail = error;
        break;
      case 'node_started':
        if (nodeId) setNode(nodeId, { status: 'running' });
        break;
      case 'node_succeeded': {
        if (nodeId) {
          // V1.4 M2 (F-2): the executor persists the node output (size-capped)
          // in the payload. Read it back into the snapshot verbatim — a
          // `{__truncated__: true, size, preview}` marker for an oversized
          // output is a plain record and is preserved unchanged. Old events
          // without `output` leave snapshot.output undefined (backward compat).
          const output = asRecord(payload['output']);
          setNode(nodeId, { status: 'succeeded', ...(output !== undefined ? { output } : {}) });
        }
        break;
      }
      case 'node_failed': {
        const nodeError = asString(payload['error']);
        if (nodeId) {
          setNode(nodeId, { status: 'failed', ...(nodeError !== undefined ? { error: nodeError } : {}) });
        }
        detail = nodeError;
        break;
      }
      case 'node_skipped':
        if (nodeId) setNode(nodeId, { status: 'skipped' });
        detail = asString(payload['reason']);
        break;
      default:
        // Unknown future event types are still recorded on the timeline.
        break;
    }

    timeline.push({
      type: event.event_type,
      ...(nodeId !== undefined ? { nodeId } : {}),
      timestamp,
      ...(detail !== undefined ? { detail } : {}),
    });
  }

  return {
    executionId,
    status,
    nodeStates,
    ...(startedAt !== undefined ? { startedAt } : {}),
    ...(endedAt !== undefined ? { endedAt } : {}),
    ...(error !== undefined ? { error } : {}),
    timeline,
  };
}

/**
 * Reconstruct an execution's state from its event log (read-only).
 * Thin async wrapper over the pure `foldExecutionEvents`.
 */
export async function reconstructExecution(store: StateStore, executionId: string): Promise<ExecutionSnapshot> {
  const events = await store.events.listByExecution(executionId);
  return foldExecutionEvents(executionId, events);
}

/**
 * Resolve the workflow definition an execution ran, preferring the exact
 * version snapshot (`workflowDefinitions`) and falling back to the live
 * workflow definition. Throws NOT_FOUND_WORKFLOW when neither is available.
 */
async function resolveDefinition(store: StateStore, execution: WorkflowExecution): Promise<WorkflowDefinition> {
  const versioned = await store.workflowDefinitions.getByWorkflowAndVersion(
    execution.workflow_id,
    execution.workflow_version,
  );
  if (versioned) return versioned.definition;

  const workflow = await store.workflows.getById(execution.workflow_id);
  if (workflow) return workflow.definition;

  throw new NotFoundError('WORKFLOW', execution.workflow_id);
}

/**
 * Compute the dry-run replay decision for every node in the definition, in
 * topological order. Mirrors the V1.1 resume semantics: succeeded/skipped
 * nodes are NOT re-dispatched; everything else (failed / running / never-run)
 * WOULD run. A previously-failed node is surfaced as `failed` (the failure
 * point that a real re-run would retry).
 */
export function computeReplayDecisions(
  definition: WorkflowDefinition,
  snapshot: ExecutionSnapshot,
): NodeReplayDecision[] {
  const ordered = computeLevels(definition.nodes, definition.edges).flat();
  const decisions: NodeReplayDecision[] = [];

  for (const node of ordered) {
    const state = snapshot.nodeStates.get(node.id);
    let decision: NodeReplayDecision['decision'];
    let reason: string;

    if (state === undefined || state.status === 'pending' || state.status === 'running') {
      decision = 'would-run';
      reason =
        state === undefined
          ? 'never reached in the original run — would execute on replay'
          : `last seen '${state.status}' (not completed) — would execute on replay`;
    } else if (state.status === 'succeeded' || state.status === 'skipped') {
      decision = 'skipped-because-succeeded';
      reason = `already '${state.status}' — resume skips re-dispatch (no side effects)`;
    } else {
      decision = 'failed';
      reason = state.error
        ? `previously failed (${state.error}) — would be retried on re-execution`
        : 'previously failed — would be retried on re-execution';
    }

    decisions.push({
      nodeId: node.id,
      nodeType: node.type,
      decision,
      reason,
    });
  }

  return decisions;
}

/** Options for `replayExecution`. */
export interface ReplayOptions {
  /**
   * Default `true` — read-only replay that produces decisions WITHOUT invoking
   * connectors. Set `false` to really re-execute via the V1.1 resume path.
   */
  dryRun?: boolean;
}

/**
 * Replay an execution.
 *
 * Default (`dryRun === true`): reconstruct the snapshot and compute per-node
 * decisions only — NO connector is invoked and NO state is mutated, so the
 * replay is side-effect-free and safe for audit / fault reproduction.
 *
 * With `dryRun === false`: re-execute via `executor.execute`, which reuses the
 * V1.1 resume path (already-succeeded nodes are skipped, only the remainder is
 * re-dispatched). The re-run outcome is attached as `rerun`.
 */
export async function replayExecution(
  executor: ExecutionExecutor,
  store: StateStore,
  executionId: string,
  options: ReplayOptions = {},
): Promise<ReplayResult> {
  const dryRun = options.dryRun !== false; // default true

  const execution = await store.executions.getById(executionId);
  if (!execution) {
    throw new NotFoundError('EXECUTION', executionId);
  }

  const snapshot = await reconstructExecution(store, executionId);
  const definition = await resolveDefinition(store, execution);
  const decisions = computeReplayDecisions(definition, snapshot);

  if (dryRun) {
    logger.info({ executionId, nodes: decisions.length }, 'Dry-run replay (read-only, no side effects)');
    return { executionId, dryRun: true, snapshot, decisions };
  }

  // Real re-execution via the V1.1 resume path (skips succeeded nodes).
  logger.info({ executionId }, 'Replaying execution (dryRun=false) — re-executing non-succeeded nodes');
  try {
    const outputs = await executor.execute(executionId, definition, execution.trigger_payload ?? {});
    const after = await store.executions.getById(executionId);
    return {
      executionId,
      dryRun: false,
      snapshot,
      decisions,
      rerun: {
        status: after?.status ?? 'running',
        outputs: Object.fromEntries(outputs),
      },
    };
  } catch (err) {
    const message = String(err);
    return {
      executionId,
      dryRun: false,
      snapshot,
      decisions,
      rerun: { status: 'failed', error: message },
    };
  }
}

/**
 * Serialise a snapshot's `nodeStates` Map into a plain record for JSON
 * transport (HTTP responses). Everything else passes through unchanged.
 */
export function snapshotToJson(snapshot: ExecutionSnapshot): Omit<ExecutionSnapshot, 'nodeStates'> & {
  nodeStates: Record<string, NodeSnapshot>;
} {
  return { ...snapshot, nodeStates: Object.fromEntries(snapshot.nodeStates) };
}

/**
 * Topological sort (Kahn's algorithm) + level-based scheduling (§6.2).
 * Nodes at the same topological level can execute in parallel.
 */

import type { WorkflowNode, WorkflowEdge } from '@loop/types';
import { ValidationError } from '@loop/types';

export interface ExecutionPlan {
  /** Nodes in topological order. */
  sortedNodes: WorkflowNode[];
  /** Nodes grouped by execution level (same level = can run in parallel). */
  levels: WorkflowNode[][];
}

/** Topological sort using Kahn's algorithm. Throws WorkflowValidationError on cycle. */
export function topologicalSort(nodes: WorkflowNode[], edges: WorkflowEdge[]): WorkflowNode[] {
  const inDegree = new Map<string, number>();
  const adjacency = new Map<string, string[]>();
  const nodeMap = new Map<string, WorkflowNode>();

  for (const node of nodes) {
    inDegree.set(node.id, 0);
    adjacency.set(node.id, []);
    nodeMap.set(node.id, node);
  }

  for (const edge of edges) {
    adjacency.get(edge.source)?.push(edge.target);
    inDegree.set(edge.target, (inDegree.get(edge.target) ?? 0) + 1);
  }

  const queue: string[] = [];
  for (const [nodeId, degree] of inDegree) {
    if (degree === 0) queue.push(nodeId);
  }

  const sorted: string[] = [];
  while (queue.length > 0) {
    const current = queue.shift()!;
    sorted.push(current);
    for (const neighbor of adjacency.get(current) ?? []) {
      const newDegree = (inDegree.get(neighbor) ?? 1) - 1;
      inDegree.set(neighbor, newDegree);
      if (newDegree === 0) queue.push(neighbor);
    }
  }

  if (sorted.length !== nodes.length) {
    throw new ValidationError('Circular dependency detected in workflow');
  }

  return sorted.map((id) => nodeMap.get(id)!);
}

/** Group nodes by topological level for parallel execution. */
export function computeLevels(nodes: WorkflowNode[], edges: WorkflowEdge[]): WorkflowNode[][] {
  const inDegree = new Map<string, number>();
  const adjacency = new Map<string, string[]>();
  const nodeMap = new Map<string, WorkflowNode>();

  for (const node of nodes) {
    inDegree.set(node.id, 0);
    adjacency.set(node.id, []);
    nodeMap.set(node.id, node);
  }

  for (const edge of edges) {
    adjacency.get(edge.source)?.push(edge.target);
    inDegree.set(edge.target, (inDegree.get(edge.target) ?? 0) + 1);
  }

  const levels: WorkflowNode[][] = [];
  let currentLevel = nodes.filter((n) => (inDegree.get(n.id) ?? 0) === 0);

  while (currentLevel.length > 0) {
    levels.push(currentLevel);
    const nextLevel: WorkflowNode[] = [];
    for (const node of currentLevel) {
      for (const neighbor of adjacency.get(node.id) ?? []) {
        const newDegree = (inDegree.get(neighbor) ?? 1) - 1;
        inDegree.set(neighbor, newDegree);
        if (newDegree === 0) {
          const neighborNode = nodeMap.get(neighbor);
          if (neighborNode) nextLevel.push(neighborNode);
        }
      }
    }
    currentLevel = nextLevel;
  }

  return levels;
}

/** Build a full execution plan with sorted order and parallel levels. */
export function buildExecutionPlan(nodes: WorkflowNode[], edges: WorkflowEdge[]): ExecutionPlan {
  return {
    sortedNodes: topologicalSort(nodes, edges),
    levels: computeLevels(nodes, edges),
  };
}

/**
 * Execution state machine — enforces valid state transitions (§6.1, §4.3).
 */

import { createLogger } from '@loop/observability';

const logger = createLogger({ name: 'loop:engine:stateMachine', component: 'engine' });

export type ExecutionState = 'pending' | 'running' | 'succeeded' | 'failed' | 'cancelled' | 'paused';
export type NodeState = 'pending' | 'running' | 'succeeded' | 'failed' | 'skipped';

const EXECUTION_TRANSITIONS: Record<ExecutionState, ExecutionState[]> = {
  pending: ['running', 'cancelled'],
  running: ['succeeded', 'failed', 'cancelled', 'paused'],
  succeeded: [],
  failed: [],
  cancelled: [],
  paused: ['running', 'cancelled', 'failed'],
};

const NODE_TRANSITIONS: Record<NodeState, NodeState[]> = {
  pending: ['running', 'skipped'],
  running: ['succeeded', 'failed'],
  succeeded: [],
  failed: [],
  skipped: [],
};

export class StateMachine {
  /** Validate and apply an execution state transition. Throws on invalid transition. */
  static transitionExecution(from: ExecutionState, to: ExecutionState): void {
    const allowed = EXECUTION_TRANSITIONS[from];
    if (!allowed || !allowed.includes(to)) {
      throw new Error(`Invalid execution state transition: ${from} → ${to}`);
    }
    logger.debug({ from, to }, 'Execution state transition');
  }

  /** Validate and apply a node state transition. Throws on invalid transition. */
  static transitionNode(from: NodeState, to: NodeState): void {
    const allowed = NODE_TRANSITIONS[from];
    if (!allowed || !allowed.includes(to)) {
      throw new Error(`Invalid node state transition: ${from} → ${to}`);
    }
    logger.debug({ from, to }, 'Node state transition');
  }

  /** Check if a transition is valid without applying it. */
  static isValidExecutionTransition(from: ExecutionState, to: ExecutionState): boolean {
    return EXECUTION_TRANSITIONS[from]?.includes(to) ?? false;
  }

  static isValidNodeTransition(from: NodeState, to: NodeState): boolean {
    return NODE_TRANSITIONS[from]?.includes(to) ?? false;
  }
}

/**
 * Anthropic provider — native Messages API.
 */

import { request } from 'undici';
import { UpstreamError } from '@loop/types';
import type { LLMProvider, CompletionRequest, CompletionResponse, ProviderIO } from './interface.js';

const DEFAULT_TIMEOUT_MS = 120_000;

export class AnthropicProvider implements LLMProvider {
  readonly name = 'anthropic';
  readonly defaultModel?: string;

  constructor(
    private apiKey: string | undefined,
    defaultModel = 'claude-3-5-haiku-latest',
    private baseUrl: string = 'https://api.anthropic.com/v1',
    private timeoutMs: number = DEFAULT_TIMEOUT_MS,
  ) {
    this.defaultModel = defaultModel;
  }

  async complete(req: CompletionRequest, io?: ProviderIO): Promise<CompletionResponse> {
    const systemMsg = req.messages.find((m) => m.role === 'system');
    const nonSystemMsg = req.messages.filter((m) => m.role !== 'system');

    const url = `${this.baseUrl}/messages`;
    await io?.egress?.check(url);

    const response = await request(url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': this.apiKey ?? '',
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify({
        model: req.model,
        max_tokens: req.max_tokens ?? 4096,
        ...(systemMsg ? { system: systemMsg.content } : {}),
        ...(req.temperature !== undefined ? { temperature: req.temperature } : {}),
        messages: nonSystemMsg,
      }),
      signal: io?.signal ?? AbortSignal.timeout(this.timeoutMs),
    });

    if (response.statusCode >= 400) {
      const detail = await response.body.text().catch(() => '');
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Anthropic returned ${response.statusCode}: ${detail.slice(0, 500)}`);
    }

    const data = await response.body.json() as {
      content?: Array<{ text: string }>;
      usage?: { input_tokens: number; output_tokens: number };
      stop_reason?: string;
      error?: { message?: string };
    };
    if (data.error) {
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Anthropic returned an error: ${data.error.message ?? 'unknown'}`);
    }
    return {
      content: (data.content ?? []).map((c) => c.text ?? '').join(''),
      model: req.model,
      usage: {
        prompt_tokens: data.usage?.input_tokens ?? 0,
        completion_tokens: data.usage?.output_tokens ?? 0,
        total_tokens: (data.usage?.input_tokens ?? 0) + (data.usage?.output_tokens ?? 0),
      },
      finish_reason: data.stop_reason ?? 'end_turn',
    };
  }

  async isAvailable(): Promise<boolean> {
    return !!this.apiKey;
  }
}

/**
 * Azure OpenAI provider — deployment-based chat completions.
 */

import { request } from 'undici';
import { UpstreamError } from '@loop/types';
import type { LLMProvider, CompletionRequest, CompletionResponse, ProviderIO } from './interface.js';

const DEFAULT_TIMEOUT_MS = 120_000;

export class AzureOpenAIProvider implements LLMProvider {
  readonly name = 'azure';
  readonly defaultModel?: string;

  constructor(
    private endpoint: string,
    private apiKey: string | undefined,
    defaultModel?: string,
    private apiVersion: string = '2024-02-15-preview',
    private timeoutMs: number = DEFAULT_TIMEOUT_MS,
  ) {
    this.defaultModel = defaultModel;
  }

  async complete(req: CompletionRequest, io?: ProviderIO): Promise<CompletionResponse> {
    const url = `${this.endpoint}/openai/deployments/${encodeURIComponent(req.model)}/chat/completions?api-version=${this.apiVersion}`;
    await io?.egress?.check(url);

    const response = await request(url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'api-key': this.apiKey ?? '',
      },
      body: JSON.stringify({ messages: req.messages, temperature: req.temperature, max_tokens: req.max_tokens }),
      signal: io?.signal ?? AbortSignal.timeout(this.timeoutMs),
    });

    if (response.statusCode >= 400) {
      const detail = await response.body.text().catch(() => '');
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Azure OpenAI returned ${response.statusCode}: ${detail.slice(0, 500)}`);
    }

    const data = await response.body.json() as {
      choices?: Array<{ message?: { content: string }; finish_reason?: string }>;
      usage?: { prompt_tokens: number; completion_tokens: number; total_tokens: number };
    };
    return {
      content: data.choices?.[0]?.message?.content ?? '',
      model: req.model,
      usage: data.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
      finish_reason: data.choices?.[0]?.finish_reason ?? 'stop',
    };
  }

  async isAvailable(): Promise<boolean> {
    return !!this.apiKey && !!this.endpoint;
  }
}

