/**
 * Factory — builds an LLMRouter from LoopConfig (env vars).
 *
 * Which providers get instantiated:
 *   - Cloud vendors: instantiated when their API key is configured.
 *   - Local servers (ollama): always instantiated (loopback default, no key).
 *   - Local servers (vllm / lmstudio): instantiated only when their URL is
 *     explicitly set, so a stray default URL never hijacks the fallback chain.
 *   - Custom OpenAI-compatible endpoints: via LOOP_LLM_EXTRA_PROVIDERS JSON.
 *
 * Bedrock/Vertex remain stubs and are never registered (see their files).
 */

import { createLogger } from '@loop/observability';
import { PROVIDER_PRESETS } from './presets.js';
import { OpenAICompatibleProvider } from './openai.js';
import { AnthropicProvider } from './anthropic.js';
import { GeminiProvider } from './gemini.js';
import { OllamaProvider } from './ollama.js';
import { AzureOpenAIProvider } from './azure.js';
import { LLMRouter } from './router.js';
import type { LLMProvider } from './interface.js';

const logger = createLogger({ name: 'loop:llm:factory', component: 'llm' });

/** Minimal shape of the config the factory needs (subset of LoopConfig). */
export interface LLMFactoryConfig {
  LOOP_LLM_PRIMARY: string;
  LOOP_LLM_FALLBACK_CHAIN: string;
  LOOP_LLM_TIMEOUT_MS?: number;
  LOOP_LLM_OLLAMA_URL?: string;
  LOOP_LLM_OLLAMA_MODEL?: string;
  LOOP_LLM_OPENAI_KEY?: string;
  LOOP_LLM_OPENAI_BASE_URL?: string;
  LOOP_LLM_OPENAI_MODEL?: string;
  LOOP_LLM_ANTHROPIC_KEY?: string;
  LOOP_LLM_ANTHROPIC_BASE_URL?: string;
  LOOP_LLM_ANTHROPIC_MODEL?: string;
  LOOP_LLM_GEMINI_KEY?: string;
  LOOP_LLM_GEMINI_BASE_URL?: string;
  LOOP_LLM_GEMINI_MODEL?: string;
  LOOP_LLM_AZURE_ENDPOINT?: string;
  LOOP_LLM_AZURE_KEY?: string;
  LOOP_LLM_AZURE_MODEL?: string;
  LOOP_LLM_AZURE_API_VERSION?: string;
  // OpenAI-compatible cloud vendors (key-gated, preset base URLs).
  LOOP_LLM_DEEPSEEK_KEY?: string;
  LOOP_LLM_DEEPSEEK_MODEL?: string;
  LOOP_LLM_DEEPSEEK_BASE_URL?: string;
  LOOP_LLM_QWEN_KEY?: string;
  LOOP_LLM_QWEN_MODEL?: string;
  LOOP_LLM_QWEN_BASE_URL?: string;
  LOOP_LLM_MOONSHOT_KEY?: string;
  LOOP_LLM_MOONSHOT_MODEL?: string;
  LOOP_LLM_MOONSHOT_BASE_URL?: string;
  LOOP_LLM_ZHIPU_KEY?: string;
  LOOP_LLM_ZHIPU_MODEL?: string;
  LOOP_LLM_ZHIPU_BASE_URL?: string;
  LOOP_LLM_SILICONFLOW_KEY?: string;
  LOOP_LLM_SILICONFLOW_MODEL?: string;
  LOOP_LLM_SILICONFLOW_BASE_URL?: string;
  LOOP_LLM_GROQ_KEY?: string;
  LOOP_LLM_GROQ_MODEL?: string;
  LOOP_LLM_MISTRAL_KEY?: string;
  LOOP_LLM_MISTRAL_MODEL?: string;
  LOOP_LLM_TOGETHER_KEY?: string;
  LOOP_LLM_TOGETHER_MODEL?: string;
  LOOP_LLM_XAI_KEY?: string;
  LOOP_LLM_XAI_MODEL?: string;
  // Local OpenAI-compatible servers (URL-gated).
  LOOP_LLM_VLLM_URL?: string;
  LOOP_LLM_VLLM_MODEL?: string;
  LOOP_LLM_LMSTUDIO_URL?: string;
  LOOP_LLM_LMSTUDIO_MODEL?: string;
  // Custom OpenAI-compatible endpoints, JSON array:
  // [{"name":"myai","base_url":"https://…/v1","api_key":"…","model":"…"}]
  LOOP_LLM_EXTRA_PROVIDERS?: string;
}

/** Cloud vendors that use the OpenAI-compatible client with a preset URL. */
const COMPAT_KEY_GATED: Array<{ name: string; keyVar: keyof LLMFactoryConfig; modelVar: keyof LLMFactoryConfig; baseUrlVar?: keyof LLMFactoryConfig }> = [
  { name: 'deepseek', keyVar: 'LOOP_LLM_DEEPSEEK_KEY', modelVar: 'LOOP_LLM_DEEPSEEK_MODEL', baseUrlVar: 'LOOP_LLM_DEEPSEEK_BASE_URL' },
  { name: 'qwen', keyVar: 'LOOP_LLM_QWEN_KEY', modelVar: 'LOOP_LLM_QWEN_MODEL', baseUrlVar: 'LOOP_LLM_QWEN_BASE_URL' },
  { name: 'moonshot', keyVar: 'LOOP_LLM_MOONSHOT_KEY', modelVar: 'LOOP_LLM_MOONSHOT_MODEL', baseUrlVar: 'LOOP_LLM_MOONSHOT_BASE_URL' },
  { name: 'zhipu', keyVar: 'LOOP_LLM_ZHIPU_KEY', modelVar: 'LOOP_LLM_ZHIPU_MODEL', baseUrlVar: 'LOOP_LLM_ZHIPU_BASE_URL' },
  { name: 'siliconflow', keyVar: 'LOOP_LLM_SILICONFLOW_KEY', modelVar: 'LOOP_LLM_SILICONFLOW_MODEL', baseUrlVar: 'LOOP_LLM_SILICONFLOW_BASE_URL' },
  { name: 'groq', keyVar: 'LOOP_LLM_GROQ_KEY', modelVar: 'LOOP_LLM_GROQ_MODEL' },
  { name: 'mistral', keyVar: 'LOOP_LLM_MISTRAL_KEY', modelVar: 'LOOP_LLM_MISTRAL_MODEL' },
  { name: 'together', keyVar: 'LOOP_LLM_TOGETHER_KEY', modelVar: 'LOOP_LLM_TOGETHER_MODEL' },
  { name: 'xai', keyVar: 'LOOP_LLM_XAI_KEY', modelVar: 'LOOP_LLM_XAI_MODEL' },
];

export function createLLMRouter(cfg: LLMFactoryConfig): LLMRouter {
  const timeoutMs = cfg.LOOP_LLM_TIMEOUT_MS;
  const providers: LLMProvider[] = [];

  // Local-first: Ollama is always registered (loopback default, keyless).
  providers.push(new OllamaProvider(cfg.LOOP_LLM_OLLAMA_URL ?? 'http://localhost:11434', cfg.LOOP_LLM_OLLAMA_MODEL, timeoutMs));

  if (cfg.LOOP_LLM_OPENAI_KEY) {
    providers.push(new OpenAICompatibleProvider('openai', cfg.LOOP_LLM_OPENAI_KEY, cfg.LOOP_LLM_OPENAI_BASE_URL ?? PROVIDER_PRESETS['openai']!.baseUrl, cfg.LOOP_LLM_OPENAI_MODEL ?? PROVIDER_PRESETS['openai']!.defaultModel, timeoutMs));
  }
  if (cfg.LOOP_LLM_ANTHROPIC_KEY) {
    providers.push(new AnthropicProvider(cfg.LOOP_LLM_ANTHROPIC_KEY, cfg.LOOP_LLM_ANTHROPIC_MODEL, cfg.LOOP_LLM_ANTHROPIC_BASE_URL, timeoutMs));
  }
  if (cfg.LOOP_LLM_GEMINI_KEY) {
    providers.push(new GeminiProvider(cfg.LOOP_LLM_GEMINI_KEY, cfg.LOOP_LLM_GEMINI_MODEL, cfg.LOOP_LLM_GEMINI_BASE_URL, timeoutMs));
  }
  if (cfg.LOOP_LLM_AZURE_ENDPOINT && cfg.LOOP_LLM_AZURE_KEY) {
    providers.push(new AzureOpenAIProvider(cfg.LOOP_LLM_AZURE_ENDPOINT, cfg.LOOP_LLM_AZURE_KEY, cfg.LOOP_LLM_AZURE_MODEL, cfg.LOOP_LLM_AZURE_API_VERSION, timeoutMs));
  }

  for (const vendor of COMPAT_KEY_GATED) {
    const apiKey = cfg[vendor.keyVar] as string | undefined;
    if (!apiKey) continue;
    const preset = PROVIDER_PRESETS[vendor.name]!;
    providers.push(
      new OpenAICompatibleProvider(
        vendor.name,
        apiKey,
        (vendor.baseUrlVar !== undefined ? (cfg[vendor.baseUrlVar] as string | undefined) : undefined) ?? preset.baseUrl,
        (cfg[vendor.modelVar] as string | undefined) ?? preset.defaultModel,
        timeoutMs,
      ),
    );
  }

  if (cfg.LOOP_LLM_VLLM_URL) {
    providers.push(new OpenAICompatibleProvider('vllm', undefined, cfg.LOOP_LLM_VLLM_URL, cfg.LOOP_LLM_VLLM_MODEL ?? 'local-model', timeoutMs));
  }
  if (cfg.LOOP_LLM_LMSTUDIO_URL) {
    providers.push(new OpenAICompatibleProvider('lmstudio', undefined, cfg.LOOP_LLM_LMSTUDIO_URL, cfg.LOOP_LLM_LMSTUDIO_MODEL ?? 'local-model', timeoutMs));
  }

  // Custom OpenAI-compatible endpoints (self-hosted gateways, niche vendors…).
  if (cfg.LOOP_LLM_EXTRA_PROVIDERS) {
    try {
      const extras = JSON.parse(cfg.LOOP_LLM_EXTRA_PROVIDERS) as Array<{ name?: string; base_url?: string; api_key?: string; model?: string }>;
      for (const extra of Array.isArray(extras) ? extras : []) {
        if (!extra?.name || !extra?.base_url) {
          logger.warn({ extra }, 'LOOP_LLM_EXTRA_PROVIDERS entry missing name/base_url — skipped');
          continue;
        }
        providers.push(new OpenAICompatibleProvider(extra.name, extra.api_key, extra.base_url, extra.model ?? 'default', timeoutMs));
      }
    } catch (err) {
      logger.error({ error: String(err) }, 'LOOP_LLM_EXTRA_PROVIDERS is not valid JSON — ignored');
    }
  }

  // Sanity-check the primary + fallback chain against what was registered.
  const names = new Set(providers.map((p) => p.name));
  const chain = cfg.LOOP_LLM_FALLBACK_CHAIN.split(',').map((s) => s.trim()).filter(Boolean);
  const resolvedChain = chain.filter((n) => names.has(n));
  if (resolvedChain.length === 0) {
    // Guarantee at least the primary (or ollama) is in the chain.
    resolvedChain.push(names.has(cfg.LOOP_LLM_PRIMARY) ? cfg.LOOP_LLM_PRIMARY : 'ollama');
  }
  if (resolvedChain.length < chain.length) {
    logger.warn(
      { configured: chain, resolved: resolvedChain, registered: [...names] },
      'Some providers in LOOP_LLM_FALLBACK_CHAIN are not configured — they will be skipped',
    );
  }

  // Reorder providers so the primary and the configured chain come first;
  // any registered-but-unlisted providers remain as last-resort tail.
  const ordered = [
    ...resolvedChain.map((name) => providers.find((p) => p.name === name)!),
    ...providers.filter((p) => !resolvedChain.includes(p.name)),
  ];

  logger.info({ providers: ordered.map((p) => p.name), primary: resolvedChain[0] }, 'LLM router built');
  return new LLMRouter(ordered);
}

// Re-export for type consumers.
export type { LLMProvider };

/**
 * Google Gemini provider — native `generateContent` API.
 *
 * (Gemini also exposes an OpenAI-compatible endpoint; use the `openai`
 * compatible client pointed at `…/v1beta/openai` if you prefer a single
 * client. This native client avoids that indirection.)
 */

import { request } from 'undici';
import { UpstreamError } from '@loop/types';
import type { LLMProvider, CompletionRequest, CompletionResponse, ProviderIO } from './interface.js';

const DEFAULT_TIMEOUT_MS = 120_000;

interface GeminiContent {
  role: 'user' | 'model';
  parts: Array<{ text: string }>;
}

export class GeminiProvider implements LLMProvider {
  readonly name = 'gemini';
  readonly defaultModel?: string;

  constructor(
    private apiKey: string | undefined,
    defaultModel = 'gemini-2.0-flash',
    private baseUrl: string = 'https://generativelanguage.googleapis.com/v1beta',
    private timeoutMs: number = DEFAULT_TIMEOUT_MS,
  ) {
    this.defaultModel = defaultModel;
  }

  async complete(req: CompletionRequest, io?: ProviderIO): Promise<CompletionResponse> {
    if (!this.apiKey) {
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', 'Gemini provider is not configured (missing LOOP_LLM_GEMINI_KEY)');
    }

    const system = req.messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n');
    const contents: GeminiContent[] = req.messages
      .filter((m) => m.role !== 'system')
      .map((m) => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: m.content }] }));

    const url = `${this.baseUrl}/models/${encodeURIComponent(req.model)}:generateContent`;
    await io?.egress?.check(url);

    const response = await request(url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-goog-api-key': this.apiKey,
      },
      body: JSON.stringify({
        ...(system ? { systemInstruction: { parts: [{ text: system }] } } : {}),
        contents,
        generationConfig: {
          ...(req.temperature !== undefined ? { temperature: req.temperature } : {}),
          ...(req.max_tokens !== undefined ? { maxOutputTokens: req.max_tokens } : {}),
        },
      }),
      signal: io?.signal ?? AbortSignal.timeout(this.timeoutMs),
    });

    if (response.statusCode >= 400) {
      const detail = await response.body.text().catch(() => '');
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Gemini returned ${response.statusCode}: ${detail.slice(0, 500)}`);
    }

    const data = await response.body.json() as {
      candidates?: Array<{ content?: { parts?: Array<{ text?: string }> }; finishReason?: string }>;
      usageMetadata?: { promptTokenCount?: number; candidatesTokenCount?: number; totalTokenCount?: number };
      error?: { message?: string };
    };
    if (data.error) {
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Gemini returned an error: ${data.error.message ?? 'unknown'}`);
    }

    const text = (data.candidates?.[0]?.content?.parts ?? [])
      .map((p) => p.text ?? '')
      .join('');
    const prompt = data.usageMetadata?.promptTokenCount ?? 0;
    const completion = data.usageMetadata?.candidatesTokenCount ?? 0;
    return {
      content: text,
      model: req.model,
      usage: { prompt_tokens: prompt, completion_tokens: completion, total_tokens: data.usageMetadata?.totalTokenCount ?? prompt + completion },
      finish_reason: data.candidates?.[0]?.finishReason ?? 'STOP',
    };
  }

  async isAvailable(): Promise<boolean> {
    return !!this.apiKey;
  }
}

/**
 * Ollama local LLM provider — native `/api/chat` + `/api/embed`.
 */

import { request } from 'undici';
import { UpstreamError } from '@loop/types';
import type { LLMProvider, CompletionRequest, CompletionResponse, EmbeddingRequest, EmbeddingResponse, ProviderIO } from './interface.js';

const DEFAULT_TIMEOUT_MS = 300_000; // local models can be slow on cold start

export class OllamaProvider implements LLMProvider {
  readonly name = 'ollama';
  readonly defaultModel?: string;

  constructor(
    private baseUrl: string = 'http://localhost:11434',
    defaultModel?: string,
    private timeoutMs: number = DEFAULT_TIMEOUT_MS,
  ) {
    this.defaultModel = defaultModel;
  }

  async complete(req: CompletionRequest, io?: ProviderIO): Promise<CompletionResponse> {
    const url = `${this.baseUrl}/api/chat`;
    await io?.egress?.check(url);

    const response = await request(url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        model: req.model,
        messages: req.messages,
        stream: false,
        options: { temperature: req.temperature, num_predict: req.max_tokens },
      }),
      signal: io?.signal ?? AbortSignal.timeout(this.timeoutMs),
    });

    if (response.statusCode >= 400) {
      const detail = await response.body.text().catch(() => '');
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Ollama returned ${response.statusCode}: ${detail.slice(0, 500)}`);
    }

    const data = await response.body.json() as {
      message?: { content: string };
      error?: string;
      eval_count?: number;
      prompt_eval_count?: number;
    };
    if (data.error) {
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Ollama returned an error: ${data.error}`);
    }
    return {
      content: data.message?.content ?? '',
      model: req.model,
      usage: {
        prompt_tokens: data.prompt_eval_count ?? 0,
        completion_tokens: data.eval_count ?? 0,
        total_tokens: (data.prompt_eval_count ?? 0) + (data.eval_count ?? 0),
      },
      finish_reason: 'stop',
    };
  }

  async embed(req: EmbeddingRequest, io?: ProviderIO): Promise<EmbeddingResponse> {
    const inputs = Array.isArray(req.input) ? req.input : [req.input];
    const url = `${this.baseUrl}/api/embed`;
    await io?.egress?.check(url);

    const response = await request(url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ model: req.model, input: inputs }),
      signal: io?.signal ?? AbortSignal.timeout(this.timeoutMs),
    });
    if (response.statusCode >= 400) {
      const detail = await response.body.text().catch(() => '');
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `Ollama embed returned ${response.statusCode}: ${detail.slice(0, 500)}`);
    }
    const data = await response.body.json() as { embeddings?: number[][] };
    return { embeddings: data.embeddings ?? [], model: req.model, usage: { total_tokens: 0 } };
  }

  async isAvailable(): Promise<boolean> {
    try {
      const response = await request(`${this.baseUrl}/api/tags`, {
        method: 'GET',
        signal: AbortSignal.timeout(5_000),
      });
      // Drain the body so the socket is released.
      await response.body.text().catch(() => {});
      return response.statusCode === 200;
    } catch {
      return false;
    }
  }
}

/**
 * OpenAI-compatible provider — the universal client.
 *
 * Talks the `/chat/completions` dialect, which covers OpenAI itself plus the
 * vast majority of the market: DeepSeek, Qwen (DashScope compatible mode),
 * Moonshot Kimi, Zhipu GLM, SiliconFlow, Groq, Mistral, Together, xAI,
 * Google Gemini's OpenAI-compat endpoint, and local servers (vLLM, LM Studio,
 * Ollama's `/v1`). Point `baseUrl` at any of them.
 */

import { request } from 'undici';
import { UpstreamError } from '@loop/types';
import type { LLMProvider, CompletionRequest, CompletionResponse, ProviderIO } from './interface.js';

const DEFAULT_TIMEOUT_MS = 120_000;

export class OpenAICompatibleProvider implements LLMProvider {
  readonly name: string;
  readonly defaultModel?: string;

  constructor(
    name: string,
    private apiKey: string | undefined,
    private baseUrl: string = 'https://api.openai.com/v1',
    defaultModel?: string,
    private timeoutMs: number = DEFAULT_TIMEOUT_MS,
  ) {
    this.name = name;
    this.defaultModel = defaultModel;
  }

  async complete(req: CompletionRequest, io?: ProviderIO): Promise<CompletionResponse> {
    const url = `${this.baseUrl}/chat/completions`;
    await io?.egress?.check(url);

    const response = await request(url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        // Ollama/LM Studio/vLLM accept requests without a key; only send the
        // header when a key is configured.
        ...(this.apiKey ? { authorization: `Bearer ${this.apiKey}` } : {}),
      },
      body: JSON.stringify({
        model: req.model,
        messages: req.messages,
        temperature: req.temperature,
        max_tokens: req.max_tokens,
        stream: false,
      }),
      signal: io?.signal ?? AbortSignal.timeout(this.timeoutMs),
    });

    if (response.statusCode >= 400) {
      // Drain the body so the socket returns to the pool, then surface the
      // upstream message — a silent empty reply used to hide auth/model errors.
      const detail = await response.body.text().catch(() => '');
      throw new UpstreamError(
        'UPSTREAM_LLM_UNAVAILABLE',
        `${this.name} chat/completions returned ${response.statusCode}: ${detail.slice(0, 500)}`,
      );
    }

    const data = await response.body.json() as {
      choices?: Array<{ message?: { content: string }; finish_reason?: string }>;
      usage?: { prompt_tokens: number; completion_tokens: number; total_tokens: number };
      error?: { message?: string };
    };
    if (data.error) {
      throw new UpstreamError('UPSTREAM_LLM_UNAVAILABLE', `${this.name} returned an error: ${data.error.message ?? 'unknown'}`);
    }
    return {
      content: data.choices?.[0]?.message?.content ?? '',
      model: req.model,
      usage: data.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
      finish_reason: data.choices?.[0]?.finish_reason ?? 'stop',
    };
  }

  async isAvailable(): Promise<boolean> {
    return this.apiKey !== undefined || isLocalUrl(this.baseUrl);
  }
}

/** Back-compat alias — the original provider name kept as the OpenAI preset. */
export class OpenAIProvider extends OpenAICompatibleProvider {
  constructor(apiKey: string | undefined, baseUrl = 'https://api.openai.com/v1', defaultModel?: string, timeoutMs?: number) {
    super('openai', apiKey, baseUrl, defaultModel, timeoutMs);
  }
}

/** True when the URL points at loopback — local inference servers need no key. */
export function isLocalUrl(url: string): boolean {
  try {
    const parsed = new URL(url);
    return ['localhost', '127.0.0.1', '[::1]', '0.0.0.0'].includes(parsed.hostname) || parsed.hostname === '::1';
  } catch {
    return false;
  }
}

/**
 * LLM router — tries providers in configured fallback chain order.
 * Each provider has a circuit breaker so a failing provider is skipped quickly.
 */

import { createLogger } from '@loop/observability';
import type { LLMProvider, CompletionRequest, CompletionResponse, EmbeddingRequest, EmbeddingResponse, ProviderIO } from './interface.js';

const logger = createLogger({ name: 'loop:llm:router', component: 'llm' });

interface CircuitState {
  failures: number;
  state: 'closed' | 'open' | 'half_open';
  lastFailure: number;
}

/** Public per-provider status for the providers API endpoint. */
export interface ProviderStatus {
  name: string;
  defaultModel?: string;
  circuit: CircuitState['state'];
  failures: number;
}

export class LLMRouter {
  private circuits = new Map<string, CircuitState>();
  private readonly threshold = 5;
  private readonly cooldownMs = 30_000;

  constructor(private providers: LLMProvider[]) {
    for (const p of providers) {
      this.circuits.set(p.name, { failures: 0, state: 'closed', lastFailure: 0 });
    }
  }

  /** Try each provider in order, skipping those whose circuit breaker is open. */
  async complete(req: CompletionRequest, fallbackChain?: string[], io?: ProviderIO): Promise<CompletionResponse> {
    const providers = this.resolveChain(fallbackChain);

    let lastError: Error | undefined;
    for (const provider of providers) {
      const circuit = this.circuits.get(provider.name);
      if (!circuit) continue;

      // Check circuit state
      if (circuit.state === 'open') {
        if (Date.now() - circuit.lastFailure > this.cooldownMs) {
          circuit.state = 'half_open';
        } else {
          logger.debug({ provider: provider.name }, 'Circuit open, skipping');
          continue;
        }
      }

      try {
        // Per-vendor default model: a request without a model name uses the
        // provider's own default (e.g. deepseek → deepseek-chat).
        const effectiveReq: CompletionRequest =
          req.model ? req : { ...req, model: provider.defaultModel ?? 'default' };
        const result = await provider.complete(effectiveReq, io);
        // Success — close circuit
        circuit.failures = 0;
        circuit.state = 'closed';
        return result;
      } catch (err) {
        lastError = err as Error;
        circuit.failures++;
        circuit.lastFailure = Date.now();
        if (circuit.failures >= this.threshold) {
          circuit.state = 'open';
          logger.warn({ provider: provider.name, failures: circuit.failures }, 'Circuit opened');
        }
      }
    }

    throw lastError ?? new Error('No LLM providers available');
  }

  /** Embed via the first provider in the (resolved) chain that supports it. */
  async embed(req: EmbeddingRequest, fallbackChain?: string[], io?: ProviderIO): Promise<EmbeddingResponse> {
    const providers = this.resolveChain(fallbackChain);
    let lastError: Error | undefined;
    for (const provider of providers) {
      if (!provider.embed) continue;
      try {
        return await provider.embed(req, io);
      } catch (err) {
        lastError = err as Error;
      }
    }
    throw lastError ?? new Error('No LLM provider supports embeddings');
  }

  /** Registered provider names, in configured order. */
  listProviders(): ProviderStatus[] {
    return this.providers.map((p) => {
      const circuit = this.circuits.get(p.name);
      return {
        name: p.name,
        ...(p.defaultModel !== undefined ? { defaultModel: p.defaultModel } : {}),
        circuit: circuit?.state ?? 'closed',
        failures: circuit?.failures ?? 0,
      };
    });
  }

  /**
   * Resolve an explicit chain to registered providers. An unknown name is an
   * immediate, explicit error — silently ignoring it used to mean the request
   * hit an unintended fallback vendor.
   */
  private resolveChain(fallbackChain?: string[]): LLMProvider[] {
    if (!fallbackChain || fallbackChain.length === 0) return this.providers;
    const unknown = fallbackChain.filter((name) => !this.providers.some((p) => p.name === name));
    if (unknown.length > 0) {
      throw new Error(`Unknown LLM provider(s): ${unknown.join(', ')}. Configured: ${this.providers.map((p) => p.name).join(', ')}`);
    }
    return fallbackChain
      .map((name) => this.providers.find((p) => p.name === name))
      .filter(Boolean) as LLMProvider[];
  }
}

