import { randomUUID } from 'node:crypto';
import { AsyncLocalStorage } from 'node:async_hooks';

export interface CorrelationContext {
  request_id: string;
  execution_id?: string;
  node_execution_id?: string;
  trace_id?: string;
}

const storage = new AsyncLocalStorage<CorrelationContext>();

/** Generate a fresh request ID (UUIDv4). */
export function generateRequestId(): string {
  return randomUUID();
}

/** Run `fn` with a correlation context available to all downstream code. */
export function runWithCorrelation<T>(ctx: CorrelationContext, fn: () => T): T {
  return storage.run(ctx, fn);
}

/** Read the current correlation context (or undefined if outside a request). */
export function getCorrelationContext(): CorrelationContext | undefined {
  return storage.getStore();
}

/**
 * V1.6 M1 (F-2, SP2): span exporters.
 *
 * Two best-effort sinks for finished spans:
 *  - `ConsoleSpanExporter` — the default; writes one structured log line per
 *    span (injectable sink for tests).
 *  - `OtlpHttpSpanExporter` — fire-and-forget OTLP/HTTP JSON POST to
 *    `OTLP_ENDPOINT`; failures degrade silently to a debug log and can never
 *    break the caller.
 *
 * Exporters never throw and never block the caller — tracing is observability,
 * not business logic.
 */

import { createLogger } from './logger.js';
import type { SpanData } from './tracing.js';

const logger = createLogger({ name: 'loop:tracing:exporter', component: 'observability' });

/** A sink for finished spans. Must not throw; must not block. */
export interface SpanExporter {
  export(span: SpanData): void;
}

// ─── Console ─────────────────────────────────────────────────────────────────

export interface ConsoleSpanExporterOptions {
  /** Receives each finished span; defaults to a structured pino log line. */
  sink?: (span: SpanData) => void;
}

/** Default exporter — emits one structured log line per finished span. */
export class ConsoleSpanExporter implements SpanExporter {
  private readonly sink: (span: SpanData) => void;

  constructor(options: ConsoleSpanExporterOptions = {}) {
    this.sink =
      options.sink ??
      ((span: SpanData): void => {
        logger.info({ span }, 'trace span');
      });
  }

  export(span: SpanData): void {
    try {
      this.sink(span);
    } catch {
      // best-effort — a broken sink must never surface to the caller.
    }
  }
}

// ─── OTLP/HTTP ───────────────────────────────────────────────────────────────

export interface OtlpHttpSpanExporterOptions {
  /** OTLP HTTP collector base URL, e.g. `http://otel:4318`. */
  endpoint: string;
  /** Injectable fetch implementation (tests). Defaults to global `fetch`. */
  fetchImpl?: typeof fetch;
  /** Abort budget per export (default 2000ms) — exports must not hang. */
  timeoutMs?: number;
}

/**
 * Best-effort OTLP/HTTP JSON exporter. Each `export()` fires a POST to
 * `<endpoint>/v1/traces` and forgets it: network errors, non-2xx responses and
 * timeouts all degrade to a debug log. Spans are encoded in the OTLP JSON
 * representation (resourceSpans → scopeSpans → spans).
 */
export class OtlpHttpSpanExporter implements SpanExporter {
  private readonly url: string;
  private readonly fetchImpl: typeof fetch;
  private readonly timeoutMs: number;

  constructor(options: OtlpHttpSpanExporterOptions) {
    this.url = `${options.endpoint.replace(/\/+$/, '')}/v1/traces`;
    this.fetchImpl = options.fetchImpl ?? fetch;
    this.timeoutMs = options.timeoutMs ?? 2000;
  }

  export(span: SpanData): void {
    const body = JSON.stringify(toOtlpJson(span));
    const controller = new AbortController();
    const timer = setTimeout(() => {
      controller.abort();
    }, this.timeoutMs);
    void this.fetchImpl(this.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body,
      signal: controller.signal,
    })
      .catch((err: unknown) => {
        logger.debug({ error: String(err), url: this.url }, 'OTLP span export failed — degraded');
      })
      .finally(() => {
        clearTimeout(timer);
      });
  }
}

// ─── OTLP JSON encoding ──────────────────────────────────────────────────────

/** Normalise an arbitrary trace id (UUID or hex) to 32 lowercase hex chars. */
function toHex32(id: string): string {
  const hex = id.replace(/[^0-9a-fA-F]/g, '').toLowerCase().slice(0, 32);
  return hex.padEnd(32, '0');
}

function toOtlpAnyValue(value: unknown): Record<string, unknown> {
  if (typeof value === 'string') return { stringValue: value };
  if (typeof value === 'boolean') return { boolValue: value };
  if (typeof value === 'number') {
    return Number.isInteger(value) ? { intValue: String(value) } : { doubleValue: value };
  }
  return { stringValue: JSON.stringify(value) ?? String(value) };
}

/** Encode a span as an OTLP/HTTP JSON payload (single-span batch). */
export function toOtlpJson(span: SpanData): Record<string, unknown> {
  const startNano = String(BigInt(span.start_ms) * 1_000_000n);
  const endNano = String(BigInt(span.start_ms + (span.duration_ms ?? 0)) * 1_000_000n);
  const attributes = Object.entries(span.attrs ?? {}).map(([key, value]) => ({
    key,
    value: toOtlpAnyValue(value),
  }));
  return {
    resourceSpans: [
      {
        resource: {
          attributes: [{ key: 'service.name', value: { stringValue: 'odw-loop' } }],
        },
        scopeSpans: [
          {
            scope: { name: '@loop/observability' },
            spans: [
              {
                traceId: toHex32(span.trace_id),
                spanId: span.span_id,
                ...(span.parent_span_id !== undefined ? { parentSpanId: span.parent_span_id } : {}),
                name: span.name,
                kind: 1, // SPAN_KIND_INTERNAL
                startTimeUnixNano: startNano,
                endTimeUnixNano: endNano,
                attributes,
                status: { code: span.status === 'error' ? 2 : 1 },
              },
            ],
          },
        ],
      },
    ],
  };
}

import pino from 'pino';
import { getCorrelationContext } from './correlation.js';

/**
 * V1.5 M1 (F-3, TR1): pino mixin that injects the active correlation context
 * (trace_id, request_id) into every structured log line. Best-effort — when no
 * context is active (e.g. background work outside a request) it adds nothing, so
 * existing log output is unchanged. This is what makes a single `trace_id`
 * correlate every log emitted while handling a traced request.
 */
export function correlationMixin(): Record<string, unknown> {
  const ctx = getCorrelationContext();
  if (ctx === undefined) return {};
  const fields: Record<string, unknown> = {};
  if (ctx.trace_id !== undefined) fields['trace_id'] = ctx.trace_id;
  if (ctx.request_id !== undefined) fields['request_id'] = ctx.request_id;
  return fields;
}

export interface LoopLogger {
  info(obj: unknown, msg?: string): void;
  info(msg: string): void;
  warn(obj: unknown, msg?: string): void;
  warn(msg: string): void;
  error(obj: unknown, msg?: string): void;
  error(msg: string): void;
  debug(obj: unknown, msg?: string): void;
  debug(msg: string): void;
  fatal(obj: unknown, msg?: string): void;
  fatal(msg: string): void;
  trace(obj: unknown, msg?: string): void;
  trace(msg: string): void;
  child(bindings: Record<string, unknown>): LoopLogger;
}

export interface LoggerOptions {
  name: string;
  level?: string;
  component?: string;
}

/**
 * Create a Pino-based structured JSON logger.
 * Log format matches TSD §12.3: JSON with level, time, pid, hostname, msg, and any
 * extra fields (execution_id, request_id, etc.) that callers bind via child loggers.
 */
export function createLogger(opts: LoggerOptions): LoopLogger {
  const level = opts.level ?? process.env['LOOP_LOG_LEVEL'] ?? 'info';
  const logger = (pino as unknown as (opts: Record<string, unknown>) => LoopLogger)({
    name: opts.name,
    level,
    base: opts.component ? { component: opts.component } : undefined,
    // V1.5 M1 (F-3, TR1): inject trace_id/request_id from the active correlation
    // context into every log line (best-effort, no-op outside a request).
    mixin: correlationMixin,
  });
  return logger;
}

/**
 * Prometheus metrics for Loop (§16.1).
 *
 * Uses prom-client for metric definitions.  When prom-client is unavailable (e.g. in
 * lightweight test environments) the module falls back to a no-op registry so imports
 * never fail at load time.
 */

import { createLogger } from './logger.js';

const logger = createLogger({ name: 'loop:metrics', component: 'observability' });

// ──────────────────────────────────────────────────────────────────────────────
// prom-client types (loaded dynamically so the package stays optional at runtime)
// ──────────────────────────────────────────────────────────────────────────────

type Counter<T extends string = string> = {
  inc(labels?: Record<T, string | number>, value?: number): void;
  inc(value?: number): void;
};
type Histogram<T extends string = string> = {
  observe(labels: Record<T, string | number>, value: number): void;
  observe(value: number): void;
};
type Gauge<T extends string = string> = {
  set(labels: Record<T, string | number>, value: number): void;
  set(value: number): void;
  inc(labels?: Record<T, string | number>, value?: number): void;
  dec(labels?: Record<T, string | number>, value?: number): void;
};

export interface LoopMetrics {
  executionsTotal: Counter<'workflow_id' | 'status'>;
  executionDuration: Histogram<'workflow_id'>;
  nodeDuration: Histogram<'node_type' | 'workflow_id'>;
  nodeErrorsTotal: Counter<'node_type' | 'error_type'>;
  connectorCallsTotal: Counter<'connector_type' | 'status'>;
  connectorLatency: Histogram<'connector_type'>;
  triggerFiresTotal: Counter<'trigger_type' | 'workflow_id'>;
  sandboxExecutionsTotal: Counter<'status'>;
  sandboxDuration: Histogram<never>;
  circuitBreakerState: Gauge<'connector_type'>;
  activeExecutions: Gauge<never>;
  egressBlockedTotal: Counter<'domain'>;
  webhookReceivedTotal: Counter<'trigger_id' | 'status'>;
  apiRequestsTotal: Counter<'method' | 'route' | 'status_code'>;
  apiRequestDuration: Histogram<'method' | 'route'>;
}

let cached: LoopMetrics | undefined;

function tryLoadPromClient(): unknown {
  try {
    // Dynamic require to keep prom-client optional
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    return require('prom-client');
  } catch {
    return undefined;
  }
}

/**
 * Build (or return cached) metrics registry.
 * If prom-client is not installed the returned object is a set of no-op stubs so
 * business code can call metrics unconditionally.
 */
export function metricsRegistry(): LoopMetrics {
  if (cached) return cached;

  const client = tryLoadPromClient() as
    | {
        Counter: new (cfg: {
          name: string;
          help: string;
          labelNames: string[];
        }) => Counter<string>;
        Histogram: new (cfg: {
          name: string;
          help: string;
          labelNames: string[];
          buckets?: number[];
        }) => Histogram<string>;
        Gauge: new (cfg: {
          name: string;
          help: string;
          labelNames: string[];
        }) => Gauge<string>;
        register: { metrics(): Promise<string> };
      }
    | undefined;

  if (!client) {
    logger.debug('prom-client not available — metrics are no-op stubs');
    const noopCounter = () =>
      ({ inc: () => {} }) as unknown as Counter<string>;
    const noopHistogram = () =>
      ({ observe: () => {} }) as unknown as Histogram<string>;
    const noopGauge = () =>
      ({ set: () => {}, inc: () => {}, dec: () => {} }) as unknown as Gauge<string>;
    cached = {
      executionsTotal: noopCounter(),
      executionDuration: noopHistogram(),
      nodeDuration: noopHistogram(),
      nodeErrorsTotal: noopCounter(),
      connectorCallsTotal: noopCounter(),
      connectorLatency: noopHistogram(),
      triggerFiresTotal: noopCounter(),
      sandboxExecutionsTotal: noopCounter(),
      sandboxDuration: noopHistogram(),
      circuitBreakerState: noopGauge(),
      activeExecutions: noopGauge(),
      egressBlockedTotal: noopCounter(),
      webhookReceivedTotal: noopCounter(),
      apiRequestsTotal: noopCounter(),
      apiRequestDuration: noopHistogram(),
    };
    return cached;
  }

  cached = {
    executionsTotal: new client.Counter({
      name: 'loop_executions_total',
      help: 'Total workflow executions',
      labelNames: ['workflow_id', 'status'],
    }),
    executionDuration: new client.Histogram({
      name: 'loop_execution_duration_seconds',
      help: 'Execution duration',
      labelNames: ['workflow_id'],
      buckets: [0.1, 0.5, 1, 5, 10, 30, 60, 120, 300],
    }),
    nodeDuration: new client.Histogram({
      name: 'loop_node_duration_seconds',
      help: 'Per-node execution duration',
      labelNames: ['node_type', 'workflow_id'],
      buckets: [0.01, 0.05, 0.1, 0.5, 1, 5, 10, 30],
    }),
    nodeErrorsTotal: new client.Counter({
      name: 'loop_node_errors_total',
      help: 'Node execution errors',
      labelNames: ['node_type', 'error_type'],
    }),
    connectorCallsTotal: new client.Counter({
      name: 'loop_connector_calls_total',
      help: 'Connector API calls',
      labelNames: ['connector_type', 'status'],
    }),
    connectorLatency: new client.Histogram({
      name: 'loop_connector_latency_seconds',
      help: 'Connector call latency',
      labelNames: ['connector_type'],
      buckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5],
    }),
    triggerFiresTotal: new client.Counter({
      name: 'loop_trigger_fires_total',
      help: 'Trigger fires',
      labelNames: ['trigger_type', 'workflow_id'],
    }),
    sandboxExecutionsTotal: new client.Counter({
      name: 'loop_sandbox_executions_total',
      help: 'Sandbox code executions',
      labelNames: ['status'],
    }),
    sandboxDuration: new client.Histogram({
      name: 'loop_sandbox_duration_seconds',
      help: 'Sandbox execution duration',
      labelNames: [],
      buckets: [0.05, 0.1, 0.5, 1, 5, 10, 30],
    }),
    circuitBreakerState: new client.Gauge({
      name: 'loop_circuit_breaker_state',
      help: 'Circuit breaker state (0=closed,1=open,2=half_open)',
      labelNames: ['connector_type'],
    }),
    activeExecutions: new client.Gauge({
      name: 'loop_active_executions',
      help: 'Currently running executions',
      labelNames: [],
    }),
    egressBlockedTotal: new client.Counter({
      name: 'loop_egress_blocked_total',
      help: 'Egress requests blocked by policy',
      labelNames: ['domain'],
    }),
    webhookReceivedTotal: new client.Counter({
      name: 'loop_webhook_received_total',
      help: 'Webhooks received',
      labelNames: ['trigger_id', 'status'],
    }),
    apiRequestsTotal: new client.Counter({
      name: 'loop_api_requests_total',
      help: 'HTTP API requests',
      labelNames: ['method', 'route', 'status_code'],
    }),
    apiRequestDuration: new client.Histogram({
      name: 'loop_api_request_duration_seconds',
      help: 'API request duration',
      labelNames: ['method', 'route'],
      buckets: [0.005, 0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5],
    }),
  } as unknown as LoopMetrics;

  return cached;
}

/** Render all metrics in Prometheus text format. */
export async function collectMetrics(): Promise<string> {
  const client = tryLoadPromClient() as { register: { metrics(): Promise<string> } } | undefined;
  if (!client) return '';
  return client.register.metrics();
}

/** Alias kept for convenience in HTTP route handlers. */
export const renderMetrics = collectMetrics;

/**
 * V1.6 M1 (F-2, SP1): lightweight distributed-tracing spans.
 *
 * Builds on the V1.5 `trace_id` propagation (correlation.ts) and adds a real
 * span model: `startSpan(name, attrs?)` / `span.end(status?)` with an
 * AsyncLocalStorage span stack so child spans started inside a parent's
 * context are auto-parented into a trace tree.
 *
 * - Sampling: `TRACE_SAMPLE_RATE` (0.0–1.0, default 1.0 = sample everything).
 *   The decision is made once per trace root and inherited by every child, so
 *   a trace is either fully sampled or fully dropped. Unsampled spans are
 *   no-ops: `setAttr`/`end` do nothing and nothing is exported.
 * - Export: finished sampled spans go to the configured `SpanExporter`
 *   (`TRACE_EXPORTER=console|otlp|none`, default console). Export is
 *   best-effort and can never throw into the caller.
 * - The active correlation context's `trace_id` (inbound `X-Trace-Id`) is
 *   reused as the span trace id when no parent span exists, so spans and V1.5
 *   structured logs share one trace id.
 *
 * Everything here is best-effort: tracing must never change execution results.
 */

import { AsyncLocalStorage } from 'node:async_hooks';
import { randomBytes } from 'node:crypto';

import { createLogger } from './logger.js';
import { getCorrelationContext } from './correlation.js';
import { ConsoleSpanExporter, OtlpHttpSpanExporter, type SpanExporter } from './exporters.js';

const logger = createLogger({ name: 'loop:tracing', component: 'observability' });

// ─── Model ───────────────────────────────────────────────────────────────────

export type SpanStatus = 'unset' | 'ok' | 'error';

/** Finished-span record handed to exporters. */
export interface SpanData {
  name: string;
  trace_id: string;
  span_id: string;
  parent_span_id?: string;
  start_ms: number;
  duration_ms?: number;
  attrs?: Record<string, unknown>;
  status: SpanStatus;
}

/** Live span handle returned by `startSpan`. */
export interface Span {
  /** The underlying record — mutated in place as the span progresses. */
  readonly data: SpanData;
  /** False for no-op spans dropped by sampling (or a `none` exporter). */
  readonly sampled: boolean;
  /** Attach a key/value attribute. No-op once ended or when unsampled. */
  setAttr(key: string, value: unknown): void;
  /**
   * Finish the span: stamps `duration_ms` + status (default `ok`) and exports
   * it. Idempotent — a second call is ignored.
   */
  end(status?: SpanStatus): void;
}

// ─── Configuration ───────────────────────────────────────────────────────────

export type TraceExporterKind = 'console' | 'otlp' | 'none';

export interface TracingConfig {
  sampleRate: number;
  exporterKind: TraceExporterKind;
  otlpEndpoint?: string;
}

/** Programmatic overrides (tests / embedders); merged over the env vars. */
export interface TracingOverrides {
  sampleRate?: number;
  exporterKind?: TraceExporterKind;
  otlpEndpoint?: string;
  /** Exporter instance override — wins over `exporterKind` (used by tests). */
  exporter?: SpanExporter;
}

let overrides: TracingOverrides = {};
let cachedExporterKey = '';
let cachedExporter: SpanExporter | undefined;

/** Merge programmatic overrides (shallow). */
export function configureTracing(next: TracingOverrides): void {
  overrides = { ...overrides, ...next };
}

/** Clear all overrides and the exporter cache (test hook). */
export function resetTracing(): void {
  overrides = {};
  cachedExporterKey = '';
  cachedExporter = undefined;
}

function parseSampleRate(raw: string | undefined): number {
  if (raw === undefined || raw.length === 0) return 1.0;
  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) return 1.0;
  return Math.min(1, Math.max(0, parsed));
}

function parseExporterKind(raw: string | undefined): TraceExporterKind {
  if (raw === 'console' || raw === 'otlp' || raw === 'none') return raw;
  return 'console';
}

/** Resolve the effective config: overrides win, env vars fill the rest. */
export function getTracingConfig(): TracingConfig {
  const sampleRate =
    overrides.sampleRate ?? parseSampleRate(process.env['TRACE_SAMPLE_RATE']);
  const exporterKind = overrides.exporterKind ?? parseExporterKind(process.env['TRACE_EXPORTER']);
  const otlpEndpoint = overrides.otlpEndpoint ?? process.env['OTLP_ENDPOINT'];
  return {
    sampleRate,
    exporterKind,
    ...(otlpEndpoint !== undefined ? { otlpEndpoint } : {}),
  };
}

function resolveExporter(config: TracingConfig): SpanExporter | undefined {
  if (overrides.exporter !== undefined) return overrides.exporter;
  if (config.exporterKind === 'none') return undefined;
  const key = `${config.exporterKind}:${config.otlpEndpoint ?? ''}`;
  if (key === cachedExporterKey && cachedExporter !== undefined) return cachedExporter;
  const exporter: SpanExporter =
    config.exporterKind === 'otlp'
      ? new OtlpHttpSpanExporter({ endpoint: config.otlpEndpoint ?? 'http://localhost:4318' })
      : new ConsoleSpanExporter();
  cachedExporterKey = key;
  cachedExporter = exporter;
  return exporter;
}

// ─── Span stack (AsyncLocalStorage) ─────────────────────────────────────────

interface SpanContext {
  data: SpanData;
  sampled: boolean;
}

const spanStorage = new AsyncLocalStorage<SpanContext>();
const contextBySpan = new WeakMap<Span, SpanContext>();

/**
 * Trace-level sampling: a child inherits its parent's decision so a trace is
 * never partially sampled; a root decides by `Math.random() < rate`.
 */
function decideSampling(parent: SpanContext | undefined, rate: number): boolean {
  if (parent !== undefined) return parent.sampled;
  if (rate >= 1) return true;
  if (rate <= 0) return false;
  return Math.random() < rate;
}

/**
 * Start a span. When called inside an active span context (see `runInSpan` /
 * `withSpan`) the new span is parented to it and shares its trace id; at a
 * root, the V1.5 correlation `trace_id` is reused when present.
 */
export function startSpan(name: string, attrs?: Record<string, unknown>): Span {
  const config = getTracingConfig();
  const parent = spanStorage.getStore();
  const sampled = decideSampling(parent, config.sampleRate);
  const correlation = getCorrelationContext();
  const traceId = parent?.data.trace_id ?? correlation?.trace_id ?? randomBytes(16).toString('hex');

  const data: SpanData = {
    name,
    trace_id: traceId,
    span_id: randomBytes(8).toString('hex'),
    ...(parent !== undefined ? { parent_span_id: parent.data.span_id } : {}),
    start_ms: Date.now(),
    status: 'unset',
  };
  // Unsampled spans are true no-ops: they record nothing (attrs included).
  if (sampled && attrs !== undefined && Object.keys(attrs).length > 0) {
    data.attrs = { ...attrs };
  }

  const context: SpanContext = { data, sampled };
  let ended = false;

  const span: Span = {
    data,
    sampled,
    setAttr(key: string, value: unknown): void {
      if (!sampled || ended) return;
      data.attrs = { ...(data.attrs ?? {}), [key]: value };
    },
    end(status?: SpanStatus): void {
      if (ended) return;
      ended = true;
      if (!sampled) return; // no-op span — nothing to stamp, nothing to export
      data.duration_ms = Date.now() - data.start_ms;
      if (status !== undefined) {
        data.status = status;
      } else if (data.status === 'unset') {
        data.status = 'ok';
      }
      exportSpan(data);
    },
  };

  contextBySpan.set(span, context);
  return span;
}

/** Best-effort export — swallows everything so tracing never breaks callers. */
function exportSpan(data: SpanData): void {
  try {
    const exporter = resolveExporter(getTracingConfig());
    exporter?.export(data);
  } catch (err) {
    logger.debug({ error: String(err) }, 'Span export failed — degraded');
  }
}

/**
 * Run `fn` with `span` as the active span: any span started while `fn` runs
 * (including across awaited promises) is parented to it.
 */
export function runInSpan<T>(span: Span, fn: () => T): T {
  const context = contextBySpan.get(span);
  if (context === undefined) return fn();
  return spanStorage.run(context, fn);
}

/**
 * Start a span, run the async `fn` inside its context, and end the span
 * automatically — `ok` on resolve, `error` (plus `error.message` attr) on
 * reject. The outcome is always re-thrown unchanged.
 */
export async function withSpan<T>(
  name: string,
  attrs: Record<string, unknown> | undefined,
  fn: (span: Span) => Promise<T>,
): Promise<T> {
  const span = startSpan(name, attrs);
  try {
    const result = await runInSpan(span, () => fn(span));
    span.end();
    return result;
  } catch (err) {
    span.setAttr('error.message', String(err));
    span.end('error');
    throw err;
  }
}

/**
 * AES-256-GCM encryption with HKDF key derivation (§11.4).
 *
 * Each encrypted field gets its own random IV.  The output format is a JSON string:
 * { "ciphertext": "<base64>", "iv": "<base64>", "tag": "<base64>" }
 */

import { createCipheriv, createDecipheriv, hkdfSync, randomBytes } from 'node:crypto';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12; // 96 bits for GCM
const KEY_LENGTH = 32; // 256 bits
const HKDF_INFO_EXECUTION = 'loop-execution-data';
const HKDF_INFO_SECRETS = 'loop-secrets';

export interface EncryptedPayload {
  ciphertext: string; // base64
  iv: string; // base64
  tag: string; // base64
}

/** Derive a 256-bit sub-key from the master key using HKDF. */
export function deriveKey(masterKey: string, context: 'execution' | 'secrets'): Buffer {
  const info = context === 'execution' ? HKDF_INFO_EXECUTION : HKDF_INFO_SECRETS;
  const salt = Buffer.alloc(0); // No salt — master key already has entropy
  const derived = hkdfSync('sha256', masterKey, salt, info, KEY_LENGTH);
  return Buffer.from(derived);
}

/** Encrypt a value using AES-256-GCM. */
export function encrypt(plaintext: string, key: Buffer): EncryptedPayload {
  const iv = randomBytes(IV_LENGTH);
  const cipher = createCipheriv(ALGORITHM, key, iv);
  const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    ciphertext: encrypted.toString('base64'),
    iv: iv.toString('base64'),
    tag: tag.toString('base64'),
  };
}

/** Decrypt a value encrypted by `encrypt()`. */
export function decrypt(payload: EncryptedPayload, key: Buffer): string {
  const iv = Buffer.from(payload.iv, 'base64');
  const ciphertext = Buffer.from(payload.ciphertext, 'base64');
  const tag = Buffer.from(payload.tag, 'base64');
  const decipher = createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(tag);
  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return decrypted.toString('utf8');
}

/**
 * Secrets manager — CRUD on top of the StateStore with encryption at rest.
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';
import { deriveKey, encrypt, decrypt, type EncryptedPayload } from './encryption.js';

const logger = createLogger({ name: 'loop:secrets', component: 'secrets' });

export class SecretsManager {
  private executionKey: Buffer;
  private secretsKey: Buffer;

  constructor(
    private store: StateStore,
    masterKey: string,
  ) {
    this.executionKey = deriveKey(masterKey, 'execution');
    this.secretsKey = deriveKey(masterKey, 'secrets');
  }

  /** Create or update a secret (encrypted). */
  async set(params: {
    name: string;
    value: string;
    scope: 'global' | 'workflow' | 'connector';
    scope_id?: string;
    created_by: string;
  }): Promise<{ id: string }> {
    const encrypted = encrypt(params.value, this.secretsKey);
    const payload = JSON.stringify(encrypted);

    const existing = await this.store.secrets.getByName(params.name, params.scope, params.scope_id);
    if (existing) {
      await this.store.secrets.update(existing.id, payload);
      logger.info({ name: params.name, scope: params.scope }, 'Secret updated');
      return { id: existing.id };
    }

    const id = randomUUID();
    const createParams: { id: string; name: string; encrypted_value: string; scope: 'global' | 'workflow' | 'connector'; created_by: string; scope_id?: string } = {
      id,
      name: params.name,
      encrypted_value: payload,
      scope: params.scope,
      created_by: params.created_by,
    };
    if (params.scope_id !== undefined) createParams.scope_id = params.scope_id;
    await this.store.secrets.create(createParams);
    logger.info({ name: params.name, scope: params.scope }, 'Secret created');
    return { id };
  }

  /** Read and decrypt a secret by name. */
  async get(name: string, scope?: string, scope_id?: string): Promise<string | null> {
    const row = await this.store.secrets.getByName(name, scope, scope_id);
    if (!row) return null;
    const payload: EncryptedPayload = JSON.parse(row.encrypted_value);
    return decrypt(payload, this.secretsKey);
  }

  /** List secrets (metadata only — values stay encrypted). */
  async list(scope?: string, scope_id?: string) {
    return this.store.secrets.list(scope, scope_id);
  }

  /** Delete a secret. */
  async delete(id: string): Promise<void> {
    await this.store.secrets.delete(id);
  }

  /** Encrypt execution I/O data. */
  encryptExecutionData(data: unknown): string {
    return JSON.stringify(encrypt(JSON.stringify(data), this.executionKey));
  }

  /** Decrypt execution I/O data. */
  decryptExecutionData(encrypted: string): unknown {
    const payload: EncryptedPayload = JSON.parse(encrypted);
    return JSON.parse(decrypt(payload, this.executionKey));
  }
}

/**
 * Abstract StateStore interface — every CRUD operation every Loop module needs.
 * SQLite and PostgreSQL adapters both implement this contract.
 */

import type {
  Workflow,
  WorkflowDefinition,
  WorkflowDefinitionVersion,
  WorkflowExecution,
  NodeExecution,
  WorkflowTrigger,
  Connector,
  ExecutionEvent,
  ExecutionEventType,
} from '@loop/types';

// ─── Shared pagination / filtering ────────────────────────────────────────────

export interface PaginationParams {
  page: number;
  per_page: number;
}

export interface PaginatedResult<T> {
  data: T[];
  total: number;
  page: number;
  per_page: number;
  total_pages: number;
}

export interface WorkflowFilter {
  status?: 'draft' | 'active' | 'archived';
  tag?: string;
  search?: string;
  sort?: string; // e.g. "updated_at:desc"
}

export interface ExecutionFilter {
  workflow_id?: string;
  status?: string;
  trigger_type?: string;
  started_after?: string;
  started_before?: string;
}

// ─── StateStore interface ─────────────────────────────────────────────────────

export interface StateStore {
  /** Initialise connection / run migrations. */
  initialise(): Promise<void>;

  /** Tear down connection. */
  close(): Promise<void>;

  // ── Workflows ─────────────────────────────────────────────────────────────

  workflows: {
    create(data: {
      id: string;
      name: string;
      description: string;
      definition: WorkflowDefinition;
      created_by: string;
      tags?: string[];
    }): Promise<Workflow>;

    getById(id: string): Promise<Workflow | null>;

    list(
      filter: WorkflowFilter,
      pagination: PaginationParams,
    ): Promise<PaginatedResult<Workflow>>;

    update(
      id: string,
      data: {
        name?: string;
        description?: string;
        definition?: WorkflowDefinition;
        status?: 'draft' | 'active' | 'archived';
        tags?: string[];
        updated_by: string;
      },
    ): Promise<Workflow>;

    /** Soft-delete: set status = 'archived'. */
    archive(id: string): Promise<void>;

    /** Hard-delete (for tests / cleanup). */
    delete(id: string): Promise<void>;
  };

  // ── Workflow Definitions (version snapshots) ──────────────────────────────

  workflowDefinitions: {
    create(data: {
      id: string;
      workflow_id: string;
      version: number;
      definition: WorkflowDefinition;
      commit_hash: string;
      created_by: string;
      change_summary?: string;
    }): Promise<WorkflowDefinitionVersion>;

    listByWorkflow(workflowId: string): Promise<WorkflowDefinitionVersion[]>;

    getByWorkflowAndVersion(
      workflowId: string,
      version: number,
    ): Promise<WorkflowDefinitionVersion | null>;
  };

  // ── Executions ────────────────────────────────────────────────────────────

  executions: {
    create(data: {
      id: string;
      workflow_id: string;
      workflow_version: number;
      trigger_type: 'manual' | 'cron' | 'webhook' | 'event';
      trigger_payload?: Record<string, unknown>;
      initiated_by?: string;
    }): Promise<WorkflowExecution>;

    getById(id: string): Promise<WorkflowExecution | null>;

    list(
      filter: ExecutionFilter,
      pagination: PaginationParams,
    ): Promise<PaginatedResult<WorkflowExecution>>;

    /**
     * Update lifecycle fields. Omitted fields are preserved (never overwritten
     * with NULL) so e.g. completing an execution keeps its `started_at`.
     * Pass `error: null` explicitly to clear a stored error.
     */
    updateStatus(
      id: string,
      data: {
        status: WorkflowExecution['status'];
        started_at?: string;
        completed_at?: string;
        duration_ms?: number;
        error?: string | null;
      },
    ): Promise<void>;

    /**
     * Guarded terminal transition: applies `status` (succeeded/failed/cancelled)
     * only while the execution is still `pending`/`running`, and returns whether
     * it was applied. Prevents terminal states from clobbering each other —
     * e.g. a late executor completion overwriting an API-initiated cancel.
     */
    completeIfActive(
      id: string,
      data: {
        status: 'succeeded' | 'failed' | 'cancelled';
        completed_at?: string;
        duration_ms?: number;
        error?: string | null;
      },
    ): Promise<boolean>;

    findInterrupted(): Promise<WorkflowExecution[]>;
  };

  // ── Node Executions ───────────────────────────────────────────────────────

  nodeExecutions: {
    create(data: {
      id: string;
      execution_id: string;
      node_id: string;
      node_type: string;
      input?: Record<string, unknown>;
      /** V1.1 M1 (F2): `${execution_id}:${node_id}` — optional, backward compatible. */
      idempotency_key?: string;
    }): Promise<NodeExecution>;

    listByExecution(executionId: string): Promise<NodeExecution[]>;

    /**
     * V1.1 M1 (F2 idempotency): look up a node execution by its idempotency key.
     * Returns null when no row carries the key (or the store has no opted-in
     * rows), letting callers fall back to a fresh execution.
     */
    findByIdempotencyKey(key: string): Promise<NodeExecution | null>;

    /**
     * Update lifecycle fields. Omitted fields are preserved (never overwritten
     * with NULL) so e.g. a succeeded node keeps its `started_at`.
     * Pass `error: null` explicitly to clear a stored error.
     */
    updateStatus(
      id: string,
      data: {
        status: NodeExecution['status'];
        started_at?: string;
        completed_at?: string;
        output?: Record<string, unknown>;
        error?: string | null;
        retry_count?: number;
        metadata?: Record<string, unknown>;
      },
    ): Promise<void>;
  };

  // ── Execution Events (V1.1 M1 — append-only event log) ──────────────────

  events: {
    /** Append an execution lifecycle / node event. Append-only. */
    append(data: {
      id: string;
      execution_id: string;
      event_type: ExecutionEventType;
      node_id?: string;
      payload?: Record<string, unknown>;
      created_at?: number;
    }): Promise<void>;

    /** List all events for an execution, ordered by creation time ascending. */
    listByExecution(executionId: string): Promise<ExecutionEvent[]>;
  };

  // ── Triggers ──────────────────────────────────────────────────────────────

  triggers: {
    create(data: {
      id: string;
      workflow_id: string;
      trigger_type: 'cron' | 'webhook' | 'event' | 'manual';
      config: Record<string, unknown>;
    }): Promise<WorkflowTrigger>;

    getById(id: string): Promise<WorkflowTrigger | null>;

    listByWorkflow(workflowId: string): Promise<WorkflowTrigger[]>;

    listEnabled(): Promise<WorkflowTrigger[]>;

    update(
      id: string,
      data: { config?: Record<string, unknown>; enabled?: boolean },
    ): Promise<void>;

    delete(id: string): Promise<void>;
  };

  // ── Audit (append-only) ───────────────────────────────────────────────────

  audit: {
    write(event: {
      id: string;
      actor: string;
      action: string;
      resource_type: string;
      resource_id?: string;
      details?: Record<string, unknown>;
      ip_address?: string;
    }): Promise<void>;

    list(filter: {
      actor?: string;
      action?: string;
      resource_type?: string;
      resource_id?: string;
      after?: string;
      before?: string;
    }, pagination: PaginationParams): Promise<PaginatedResult<{
      id: string;
      timestamp: string;
      actor: string;
      action: string;
      resource_type: string;
      resource_id: string | null;
      details: Record<string, unknown>;
      ip_address: string | null;
    }>>;
  };

  // ── Users ─────────────────────────────────────────────────────────────────

  users: {
    create(data: {
      id: string;
      username: string;
      password_hash: string;
      email: string;
      role?: 'read' | 'write' | 'admin';
      display_name?: string;
    }): Promise<{
      id: string;
      username: string;
      email: string;
      role: string;
      display_name: string;
      created_at: string;
      is_active: boolean;
    }>;

    getById(id: string): Promise<{
      id: string;
      username: string;
      email: string;
      role: string;
      password_hash: string;
      display_name: string;
      is_active: boolean;
      last_login_at: string | null;
    } | null>;

    getByUsername(username: string): Promise<{
      id: string;
      username: string;
      email: string;
      role: string;
      password_hash: string;
      display_name: string;
      is_active: boolean;
      last_login_at: string | null;
    } | null>;

    updateLastLogin(id: string): Promise<void>;

    list(): Promise<Array<{
      id: string;
      username: string;
      email: string;
      role: string;
      display_name: string;
      is_active: boolean;
      created_at: string;
      last_login_at: string | null;
    }>>;

    updateRole(id: string, role: 'read' | 'write' | 'admin'): Promise<void>;

    deactivate(id: string): Promise<void>;
  };

  // ── Secrets ───────────────────────────────────────────────────────────────

  secrets: {
    create(data: {
      id: string;
      name: string;
      encrypted_value: string;
      scope: 'global' | 'workflow' | 'connector';
      scope_id?: string;
      created_by: string;
    }): Promise<void>;

    getByName(name: string, scope?: string, scopeId?: string): Promise<{
      id: string;
      name: string;
      encrypted_value: string;
      scope: string;
      scope_id: string | null;
    } | null>;

    list(scope?: string, scopeId?: string): Promise<Array<{
      id: string;
      name: string;
      scope: string;
      scope_id: string | null;
      created_at: string;
    }>>;

    update(id: string, encrypted_value: string): Promise<void>;

    delete(id: string): Promise<void>;
  };

  // ── Egress Policies ───────────────────────────────────────────────────────

  egressPolicies: {
    create(data: {
      id: string;
      name: string;
      rule_type: 'allow' | 'deny';
      target_type: 'domain' | 'ip_range' | 'region';
      target_value: string;
      priority?: number;
    }): Promise<void>;

    listEnabled(): Promise<Array<{
      id: string;
      name: string;
      rule_type: 'allow' | 'deny';
      target_type: 'domain' | 'ip_range' | 'region';
      target_value: string;
      priority: number;
      enabled: boolean;
    }>>;

    list(): Promise<Array<{
      id: string;
      name: string;
      rule_type: 'allow' | 'deny';
      target_type: 'domain' | 'ip_range' | 'region';
      target_value: string;
      priority: number;
      enabled: boolean;
      created_at: string;
    }>>;

    update(
      id: string,
      data: {
        name?: string;
        rule_type?: 'allow' | 'deny';
        target_type?: 'domain' | 'ip_range' | 'region';
        target_value?: string;
        priority?: number;
        enabled?: boolean;
      },
    ): Promise<void>;

    delete(id: string): Promise<void>;
  };

  // ── Connectors ────────────────────────────────────────────────────────────

  connectors: {
    create(data: {
      id: string;
      connector_type: Connector['connector_type'];
      name: string;
      config: Record<string, unknown>;
    }): Promise<Connector>;

    getById(id: string): Promise<Connector | null>;

    list(): Promise<Connector[]>;

    update(
      id: string,
      data: {
        name?: string;
        config?: Record<string, unknown>;
        status?: 'connected' | 'disconnected' | 'error';
        last_health_check?: string;
      },
    ): Promise<void>;

    delete(id: string): Promise<void>;
  };
}

/**
 * Migration runner — applies SQL migrations idempotently on startup.
 * Uses the schema_migrations table to track applied versions.
 */

import { createHash } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { SqliteConnection } from './sqlite/connection.js';
import * as schema from './schema.js';
import { MIGRATIONS, type Migration } from './migrations/index.js';

const logger = createLogger({ name: 'loop:state:migrate', component: 'state' });

/**
 * Run all pending migrations.
 * Each migration is applied inside a transaction and tracked in schema_migrations.
 */
export async function runMigrations(conn: SqliteConnection): Promise<void> {
  const { db, client } = conn;

  // Ensure the migrations tracking table exists (bootstrap)
  client.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version TEXT PRIMARY KEY,
      applied_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
      checksum TEXT NOT NULL
    )
  `);

  const appliedRows = db.select().from(schema.schemaMigrations).all();
  const appliedSet = new Set(appliedRows.map((r) => r.version));

  for (const migration of MIGRATIONS) {
    if (appliedSet.has(migration.version)) {
      logger.debug({ version: migration.version }, 'Migration already applied');
      continue;
    }

    const checksum = createHash('sha256').update(migration.sql).digest('hex');
    logger.info({ version: migration.version, checksum: checksum.slice(0, 12) }, 'Applying migration');

    // Apply the migration and its tracking row atomically. Without the
    // explicit transaction a mid-migration failure left the database
    // half-migrated and untracked, so the next startup replayed DDL that had
    // already run and crashed on "table already exists".
    client.exec('BEGIN');
    try {
      client.exec(migration.sql);
      db.insert(schema.schemaMigrations)
        .values({ version: migration.version, checksum })
        .run();
      client.exec('COMMIT');
    } catch (err) {
      client.exec('ROLLBACK');
      throw err;
    }
  }

  logger.info('All migrations applied');
}

export type { Migration };

/**
 * PostgreSQL connection management with connection pooling.
 */

import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres';
import { Pool } from 'pg';
import { createLogger } from '@loop/observability';
import * as schema from '../schema.js';

const logger = createLogger({ name: 'loop:state:postgres', component: 'state' });

export interface PostgresConnection {
  db: NodePgDatabase<typeof schema>;
  pool: Pool;
  close(): Promise<void>;
}

export interface PostgresConnectionOptions {
  host: string;
  port: number;
  database: string;
  user: string;
  password: string;
  ssl?: boolean;
  poolSize?: number;
}

export function createPostgresConnection(opts: PostgresConnectionOptions): PostgresConnection {
  const pool = new Pool({
    host: opts.host,
    port: opts.port,
    database: opts.database,
    user: opts.user,
    password: opts.password,
    // TLS with certificate verification by default — `ssl: true` previously
    // disabled verification (rejectUnauthorized: false), letting any MITM
    // intercept a supposedly encrypted connection.
    ssl: opts.ssl ? { rejectUnauthorized: true } : false,
    max: opts.poolSize ?? 20,
    idleTimeoutMillis: 30000,
    connectionTimeoutMillis: 2000,
  });

  pool.on('error', (err) => {
    logger.error({ error: String(err) }, 'PostgreSQL pool error');
  });

  logger.info({ host: opts.host, port: opts.port, database: opts.database }, 'PostgreSQL connection pool created');

  const db = drizzle(pool, { schema });

  return {
    db,
    pool,
    async close() {
      await pool.end();
      logger.info('PostgreSQL connection pool closed');
    },
  };
}

/**
 * PostgreSQL implementation of the StateStore interface (Scale tier).
 * Mirrors the SQLite implementation but uses PostgreSQL-specific features (JSONB, GIN indexes).
 */

import { createLogger } from '@loop/observability';
import type { WorkflowDefinition } from '@loop/types';
import type {
  StateStore,
  PaginationParams,
  WorkflowFilter,
  ExecutionFilter,
} from '../interface.js';
import { runPostgresMigrations } from './migrations.js';
import type { PostgresConnection } from './connection.js';

const logger = createLogger({ name: 'loop:state:postgres', component: 'state' });

function safeJsonParse(raw: unknown): Record<string, unknown> {
  if (typeof raw === 'string') {
    try { return JSON.parse(raw) as Record<string, unknown>; } catch { return {}; }
  }
  if (raw && typeof raw === 'object') return raw as Record<string, unknown>;
  return {};
}

/**
 * Normalise a PostgreSQL TIMESTAMP value to an ISO-8601 string. node-postgres
 * returns TIMESTAMP columns as `Date` objects by default, but a mock client (or
 * a driver configured to return strings) may hand back a string — both are
 * accepted so the adapter mirrors the SQLite semantics (ISO strings) regardless.
 */
function toIsoString(raw: unknown): string {
  if (raw instanceof Date) return raw.toISOString();
  return String(raw);
}

/** Nullable variant of {@link toIsoString} for optional timestamp columns. */
function toNullableIsoString(raw: unknown): string | null {
  if (raw === null || raw === undefined) return null;
  if (raw instanceof Date) return raw.toISOString();
  return String(raw);
}

// ─── Row mappers (mirror the SQLite adapters' output shapes) ──────────────────

function mapWorkflowDefinition(row: Record<string, unknown>) {
  return {
    id: row.id as string,
    workflow_id: row.workflow_id as string,
    version: row.version as number,
    definition: safeJsonParse(row.definition) as unknown as WorkflowDefinition,
    commit_hash: row.commit_hash as string,
    created_by: row.created_by as string,
    created_at: toIsoString(row.created_at),
    change_summary: (row.change_summary as string | null) ?? '',
  };
}

function mapExecution(row: Record<string, unknown>) {
  return {
    id: row.id as string,
    workflow_id: row.workflow_id as string,
    workflow_version: row.workflow_version as number,
    trigger_type: row.trigger_type as 'manual' | 'cron' | 'webhook' | 'event',
    trigger_payload: safeJsonParse(row.trigger_payload),
    status: row.status as 'pending' | 'running' | 'succeeded' | 'failed' | 'cancelled' | 'paused',
    started_at: toNullableIsoString(row.started_at),
    completed_at: toNullableIsoString(row.completed_at),
    duration_ms: (row.duration_ms as number | null) ?? null,
    error: (row.error as string | null) ?? null,
    initiated_by: (row.initiated_by as string | null) ?? null,
  };
}

function mapNodeExecution(row: Record<string, unknown>) {
  return {
    id: row.id as string,
    execution_id: row.execution_id as string,
    node_id: row.node_id as string,
    node_type: row.node_type as string,
    status: row.status as 'pending' | 'running' | 'succeeded' | 'failed' | 'skipped',
    input: safeJsonParse(row.input),
    output: safeJsonParse(row.output),
    error: (row.error as string | null) ?? null,
    started_at: toNullableIsoString(row.started_at),
    completed_at: toNullableIsoString(row.completed_at),
    retry_count: (row.retry_count as number | null) ?? 0,
    metadata: safeJsonParse(row.metadata),
    idempotency_key: (row.idempotency_key as string | null) ?? null,
  };
}

function mapTrigger(row: Record<string, unknown>) {
  return {
    id: row.id as string,
    workflow_id: row.workflow_id as string,
    trigger_type: row.trigger_type as 'cron' | 'webhook' | 'event' | 'manual',
    config: safeJsonParse(row.config),
    enabled: row.enabled as boolean,
    created_at: toIsoString(row.created_at),
    updated_at: toIsoString(row.updated_at),
  };
}

function mapConnector(row: Record<string, unknown>) {
  return {
    id: row.id as string,
    connector_type: row.connector_type as 'vault' | 'desk' | 'recap' | 'generic',
    name: row.name as string,
    config: safeJsonParse(row.config),
    status: row.status as 'connected' | 'disconnected' | 'error',
    last_health_check: toNullableIsoString(row.last_health_check),
    created_at: toIsoString(row.created_at),
    updated_at: toIsoString(row.updated_at),
  };
}

export class PostgresStateStore implements StateStore {
  private conn: PostgresConnection;

  constructor(conn: PostgresConnection) {
    this.conn = conn;
  }

  async initialise(): Promise<void> {
    await runPostgresMigrations(this.conn);
    logger.info('State store initialised (PostgreSQL)');
  }

  async close(): Promise<void> {
    await this.conn.close();
  }

  private get db() { return this.conn.db; }

  // PostgreSQL implementation mirrors SQLite but uses PostgreSQL-specific queries.
  // Due to the identical interface, the CRUD operations are structurally the same.
  // The main differences are:
  // - JSONB columns (native JSON support with indexing)
  // - GIN indexes for full-text search
  // - Connection pooling
  // - BYTEA for encrypted values

  workflows = {
    create: async (data: { id: string; name: string; description: string; definition: WorkflowDefinition; created_by: string; tags?: string[] }) => {
      const now = new Date().toISOString();
      await this.conn.pool.query(
        `INSERT INTO workflows (id, name, description, definition, version, status, tags, created_by, updated_by, created_at, updated_at)
         VALUES ($1, $2, $3, $4, 1, 'draft', $5, $6, $6, $7, $7)`,
        [data.id, data.name, data.description, JSON.stringify(data.definition), JSON.stringify(data.tags ?? []), data.created_by, now],
      );
      const result = await this.conn.pool.query('SELECT * FROM workflows WHERE id = $1', [data.id]);
      if (result.rows.length === 0) throw new Error('Failed to create workflow');
      const row = result.rows[0] as Record<string, unknown>;
      return { id: row.id as string, name: row.name as string, description: row.description as string, definition: safeJsonParse(row.definition) as unknown as WorkflowDefinition, version: row.version as number, status: row.status as 'draft' | 'active' | 'archived', tags: safeJsonParse(row.tags) as unknown as string[], created_by: row.created_by as string, updated_by: row.updated_by as string, created_at: row.created_at as string, updated_at: row.updated_at as string };
    },

    getById: async (id: string) => {
      const result = await this.conn.pool.query('SELECT * FROM workflows WHERE id = $1', [id]);
      if (result.rows.length === 0) return null;
      const row = result.rows[0] as Record<string, unknown>;
      return { id: row.id as string, name: row.name as string, description: row.description as string, definition: safeJsonParse(row.definition) as unknown as WorkflowDefinition, version: row.version as number, status: row.status as 'draft' | 'active' | 'archived', tags: safeJsonParse(row.tags) as unknown as string[], created_by: row.created_by as string, updated_by: row.updated_by as string, created_at: row.created_at as string, updated_at: row.updated_at as string };
    },

    list: async (filter: WorkflowFilter, pagination: PaginationParams) => {
      const conditions: string[] = [];
      const params: unknown[] = [];
      let paramIdx = 1;
      if (filter.status) { conditions.push(`status = $${paramIdx}`); params.push(filter.status); paramIdx++; }
      if (filter.tag) { conditions.push(`tags @> $${paramIdx}`); params.push(JSON.stringify([filter.tag])); paramIdx++; }
      if (filter.search) { conditions.push(`to_tsvector('english', name || ' ' || description) @@ plainto_tsquery('english', $${paramIdx})`); params.push(filter.search); paramIdx++; }
      const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
      const countResult = await this.conn.pool.query(`SELECT count(*)::int AS count FROM workflows ${whereClause}`, params);
      const total = (countResult.rows[0] as { count: number }).count ?? 0;
      const [sortField, sortDir] = (filter.sort ?? 'updated_at:desc').split(':');
      const sortCol = sortField === 'created_at' ? 'created_at' : 'updated_at';
      const orderDir = sortDir === 'asc' ? 'ASC' : 'DESC';
      const offset = (pagination.page - 1) * pagination.per_page;
      const dataResult = await this.conn.pool.query(
        `SELECT * FROM workflows ${whereClause} ORDER BY ${sortCol} ${orderDir} LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
        [...params, pagination.per_page, offset],
      );
      const data = dataResult.rows.map((r: Record<string, unknown>) => ({ id: r.id as string, name: r.name as string, description: r.description as string, definition: safeJsonParse(r.definition) as unknown as WorkflowDefinition, version: r.version as number, status: r.status as 'draft' | 'active' | 'archived', tags: safeJsonParse(r.tags) as unknown as string[], created_by: r.created_by as string, updated_by: r.updated_by as string, created_at: r.created_at as string, updated_at: r.updated_at as string }));
      return { data, total, page: pagination.page, per_page: pagination.per_page, total_pages: Math.ceil(total / pagination.per_page) };
    },

    update: async (id: string, data: { name?: string; description?: string; definition?: WorkflowDefinition; status?: 'draft' | 'active' | 'archived'; tags?: string[]; updated_by: string }) => {
      const now = new Date().toISOString();
      const setClauses: string[] = ['updated_at = $2', 'updated_by = $3'];
      const params: unknown[] = [id, now, data.updated_by];
      let paramIdx = 4;
      if (data.name !== undefined) { setClauses.push(`name = $${paramIdx}`); params.push(data.name); paramIdx++; }
      if (data.description !== undefined) { setClauses.push(`description = $${paramIdx}`); params.push(data.description); paramIdx++; }
      if (data.definition !== undefined) {
        setClauses.push(`definition = $${paramIdx}`); params.push(JSON.stringify(data.definition)); paramIdx++;
        setClauses.push('version = version + 1');
      }
      if (data.status !== undefined) { setClauses.push(`status = $${paramIdx}`); params.push(data.status); paramIdx++; }
      if (data.tags !== undefined) { setClauses.push(`tags = $${paramIdx}`); params.push(JSON.stringify(data.tags)); paramIdx++; }
      await this.conn.pool.query(`UPDATE workflows SET ${setClauses.join(', ')} WHERE id = $1`, params);
      return (await this.workflows.getById(id))!;
    },

    archive: async (id: string) => {
      await this.conn.pool.query("UPDATE workflows SET status = 'archived' WHERE id = $1", [id]);
    },

    delete: async (id: string) => {
      // Mirror the SQLite adapter: cascade through execution_events too, and
      // match node_executions by the workflow's actual execution ids (a
      // workflow id is never an execution id).
      //
      // A dedicated client is checked out for the whole transaction:
      // pool.query() borrows a DIFFERENT connection per statement, so BEGIN
      // would commit on one connection while the DELETEs run on others — no
      // atomicity, and a connection stuck in an open transaction goes back
      // into the pool (follow-up queries join a phantom transaction).
      const client = await this.conn.pool.connect();
      try {
        const execResult = await client.query('SELECT id FROM workflow_executions WHERE workflow_id = $1', [id]);
        const execIds = (execResult.rows as Array<{ id: string }>).map((r) => r.id);
        await client.query('BEGIN');
        try {
          if (execIds.length > 0) {
            await client.query('DELETE FROM execution_events WHERE execution_id = ANY($1::uuid[])', [execIds]);
            await client.query('DELETE FROM node_executions WHERE execution_id = ANY($1::uuid[])', [execIds]);
          }
          await client.query('DELETE FROM workflow_executions WHERE workflow_id = $1', [id]);
          await client.query('DELETE FROM workflow_definitions WHERE workflow_id = $1', [id]);
          await client.query('DELETE FROM workflow_triggers WHERE workflow_id = $1', [id]);
          await client.query('DELETE FROM workflows WHERE id = $1', [id]);
          await client.query('COMMIT');
        } catch (err) {
          await client.query('ROLLBACK');
          throw err;
        }
      } finally {
        client.release();
      }
    },
  };

  // V1.5 M1 (F-1): the remaining entities are fully implemented below with
  // parameterized ($1...) SQL, mirroring the SQLite adapter's semantics so the
  // PostgreSQL Scale layer reaches parity with the SQLite reference store.

  // ── Workflow Definitions (version snapshots) ──────────────────────────────

  workflowDefinitions = {
    create: async (data: {
      id: string; workflow_id: string; version: number; definition: WorkflowDefinition;
      commit_hash: string; created_by: string; change_summary?: string;
    }) => {
      const now = new Date().toISOString();
      await this.conn.pool.query(
        `INSERT INTO workflow_definitions (id, workflow_id, version, definition, commit_hash, created_by, created_at, change_summary)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
        [data.id, data.workflow_id, data.version, JSON.stringify(data.definition), data.commit_hash, data.created_by, now, data.change_summary ?? ''],
      );
      const result = await this.conn.pool.query('SELECT * FROM workflow_definitions WHERE id = $1', [data.id]);
      if (result.rows.length === 0) throw new Error('Failed to create workflow definition');
      return mapWorkflowDefinition(result.rows[0] as Record<string, unknown>);
    },

    listByWorkflow: async (workflowId: string) => {
      const result = await this.conn.pool.query(
        'SELECT * FROM workflow_definitions WHERE workflow_id = $1 ORDER BY version DESC',
        [workflowId],
      );
      return result.rows.map((r: Record<string, unknown>) => mapWorkflowDefinition(r));
    },

    getByWorkflowAndVersion: async (workflowId: string, version: number) => {
      const result = await this.conn.pool.query(
        'SELECT * FROM workflow_definitions WHERE workflow_id = $1 AND version = $2',
        [workflowId, version],
      );
      if (result.rows.length === 0) return null;
      return mapWorkflowDefinition(result.rows[0] as Record<string, unknown>);
    },
  };

  // ── Executions ────────────────────────────────────────────────────────────

  executions = {
    create: async (data: {
      id: string; workflow_id: string; workflow_version: number;
      trigger_type: 'manual' | 'cron' | 'webhook' | 'event';
      trigger_payload?: Record<string, unknown>; initiated_by?: string;
    }) => {
      await this.conn.pool.query(
        `INSERT INTO workflow_executions (id, workflow_id, workflow_version, trigger_type, trigger_payload, status, initiated_by)
         VALUES ($1, $2, $3, $4, $5, 'pending', $6)`,
        [data.id, data.workflow_id, data.workflow_version, data.trigger_type, JSON.stringify(data.trigger_payload ?? {}), data.initiated_by ?? null],
      );
      const result = await this.conn.pool.query('SELECT * FROM workflow_executions WHERE id = $1', [data.id]);
      if (result.rows.length === 0) throw new Error('Failed to create execution');
      return mapExecution(result.rows[0] as Record<string, unknown>);
    },

    getById: async (id: string) => {
      const result = await this.conn.pool.query('SELECT * FROM workflow_executions WHERE id = $1', [id]);
      if (result.rows.length === 0) return null;
      return mapExecution(result.rows[0] as Record<string, unknown>);
    },

    list: async (filter: ExecutionFilter, pagination: PaginationParams) => {
      const conditions: string[] = [];
      const params: unknown[] = [];
      let paramIdx = 1;
      if (filter.workflow_id) { conditions.push(`workflow_id = $${paramIdx}`); params.push(filter.workflow_id); paramIdx++; }
      if (filter.status) { conditions.push(`status = $${paramIdx}`); params.push(filter.status); paramIdx++; }
      if (filter.trigger_type) { conditions.push(`trigger_type = $${paramIdx}`); params.push(filter.trigger_type); paramIdx++; }
      if (filter.started_after) { conditions.push(`started_at >= $${paramIdx}`); params.push(filter.started_after); paramIdx++; }
      if (filter.started_before) { conditions.push(`started_at <= $${paramIdx}`); params.push(filter.started_before); paramIdx++; }
      const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
      const countResult = await this.conn.pool.query(`SELECT count(*)::int AS count FROM workflow_executions ${whereClause}`, params);
      const total = (countResult.rows[0] as { count: number }).count ?? 0;
      const offset = (pagination.page - 1) * pagination.per_page;
      const dataResult = await this.conn.pool.query(
        `SELECT * FROM workflow_executions ${whereClause} ORDER BY started_at DESC NULLS LAST LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
        [...params, pagination.per_page, offset],
      );
      const data = dataResult.rows.map((r: Record<string, unknown>) => mapExecution(r));
      return { data, total, page: pagination.page, per_page: pagination.per_page, total_pages: Math.ceil(total / pagination.per_page) };
    },

    updateStatus: async (id: string, data: {
      status: 'pending' | 'running' | 'succeeded' | 'failed' | 'cancelled' | 'paused';
      started_at?: string; completed_at?: string; duration_ms?: number; error?: string | null;
    }) => {
      // Preserve-on-omit: omitted fields keep their current value (mirrors the
      // SQLite adapter — unconditional NULLs used to wipe `started_at`).
      const setClauses = ['status = $2'];
      const params: unknown[] = [id, data.status];
      let paramIdx = 3;
      if (data.started_at !== undefined) { setClauses.push(`started_at = $${paramIdx}`); params.push(data.started_at); paramIdx++; }
      if (data.completed_at !== undefined) { setClauses.push(`completed_at = $${paramIdx}`); params.push(data.completed_at); paramIdx++; }
      if (data.duration_ms !== undefined) { setClauses.push(`duration_ms = $${paramIdx}`); params.push(data.duration_ms); paramIdx++; }
      if (data.error !== undefined) { setClauses.push(`error = $${paramIdx}`); params.push(data.error); paramIdx++; }
      await this.conn.pool.query(
        `UPDATE workflow_executions SET ${setClauses.join(', ')} WHERE id = $1`,
        params,
      );
    },

    completeIfActive: async (id: string, data: {
      status: 'succeeded' | 'failed' | 'cancelled';
      completed_at?: string; duration_ms?: number; error?: string | null;
    }) => {
      const setClauses = ['status = $2'];
      const params: unknown[] = [id, data.status];
      let paramIdx = 3;
      if (data.completed_at !== undefined) { setClauses.push(`completed_at = $${paramIdx}`); params.push(data.completed_at); paramIdx++; }
      if (data.duration_ms !== undefined) { setClauses.push(`duration_ms = $${paramIdx}`); params.push(data.duration_ms); paramIdx++; }
      if (data.error !== undefined) { setClauses.push(`error = $${paramIdx}`); params.push(data.error); paramIdx++; }
      const result = await this.conn.pool.query(
        `UPDATE workflow_executions SET ${setClauses.join(', ')} WHERE id = $1 AND status IN ('pending', 'running')`,
        params,
      );
      return (result.rowCount ?? 0) > 0;
    },

    findInterrupted: async () => {
      // 'running' (died mid-execution) AND 'pending' (created but never
      // dispatched — e.g. crash between record creation and executor pickup).
      // Excluding 'pending' leaves those executions stuck forever (bug 12).
      const result = await this.conn.pool.query("SELECT * FROM workflow_executions WHERE status IN ('running', 'pending')");
      return result.rows.map((r: Record<string, unknown>) => mapExecution(r));
    },
  };

  // ── Node Executions ───────────────────────────────────────────────────────

  nodeExecutions = {
    create: async (data: {
      id: string; execution_id: string; node_id: string; node_type: string;
      input?: Record<string, unknown>; idempotency_key?: string;
    }) => {
      await this.conn.pool.query(
        `INSERT INTO node_executions (id, execution_id, node_id, node_type, status, input, idempotency_key)
         VALUES ($1, $2, $3, $4, 'pending', $5, $6)`,
        [data.id, data.execution_id, data.node_id, data.node_type, JSON.stringify(data.input ?? {}), data.idempotency_key ?? null],
      );
      const result = await this.conn.pool.query('SELECT * FROM node_executions WHERE id = $1', [data.id]);
      if (result.rows.length === 0) throw new Error('Failed to create node execution');
      return mapNodeExecution(result.rows[0] as Record<string, unknown>);
    },

    listByExecution: async (executionId: string) => {
      const result = await this.conn.pool.query(
        'SELECT * FROM node_executions WHERE execution_id = $1 ORDER BY started_at ASC NULLS FIRST',
        [executionId],
      );
      return result.rows.map((r: Record<string, unknown>) => mapNodeExecution(r));
    },

    findByIdempotencyKey: async (key: string) => {
      const result = await this.conn.pool.query('SELECT * FROM node_executions WHERE idempotency_key = $1', [key]);
      if (result.rows.length === 0) return null;
      return mapNodeExecution(result.rows[0] as Record<string, unknown>);
    },

    updateStatus: async (id: string, data: {
      status: 'pending' | 'running' | 'succeeded' | 'failed' | 'skipped';
      started_at?: string; completed_at?: string; output?: Record<string, unknown>;
      error?: string | null; retry_count?: number; metadata?: Record<string, unknown>;
    }) => {
      // Mirror the SQLite semantics: omitted fields preserve their current
      // value; output/retry_count/metadata are only overwritten when
      // explicitly supplied.
      const setClauses = ['status = $2'];
      const params: unknown[] = [id, data.status];
      let paramIdx = 3;
      if (data.started_at !== undefined) { setClauses.push(`started_at = $${paramIdx}`); params.push(data.started_at); paramIdx++; }
      if (data.completed_at !== undefined) { setClauses.push(`completed_at = $${paramIdx}`); params.push(data.completed_at); paramIdx++; }
      if (data.output !== undefined) { setClauses.push(`output = $${paramIdx}`); params.push(JSON.stringify(data.output)); paramIdx++; }
      if (data.error !== undefined) { setClauses.push(`error = $${paramIdx}`); params.push(data.error); paramIdx++; }
      if (data.retry_count !== undefined) { setClauses.push(`retry_count = $${paramIdx}`); params.push(data.retry_count); paramIdx++; }
      if (data.metadata !== undefined) { setClauses.push(`metadata = $${paramIdx}`); params.push(JSON.stringify(data.metadata)); paramIdx++; }
      await this.conn.pool.query(`UPDATE node_executions SET ${setClauses.join(', ')} WHERE id = $1`, params);
    },
  };

  // ── Execution Events (V1.1 M1) — fully implemented (used by recovery/executor) ──
  // These must not throw 'not implemented': the engine calls append() on every
  // lifecycle transition, so a throwing stub would break execution on PG.
  events = {
    append: async (data: {
      id: string; execution_id: string;
      event_type: 'execution_started' | 'node_started' | 'node_succeeded' | 'node_failed'
        | 'node_skipped' | 'execution_succeeded' | 'execution_failed' | 'execution_recovered';
      node_id?: string; payload?: Record<string, unknown>; created_at?: number;
    }) => {
      await this.conn.pool.query(
        `INSERT INTO execution_events (id, execution_id, event_type, node_id, payload, created_at)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [data.id, data.execution_id, data.event_type, data.node_id ?? null, JSON.stringify(data.payload ?? {}), data.created_at ?? Date.now()],
      );
    },
    listByExecution: async (executionId: string) => {
      const result = await this.conn.pool.query(
        'SELECT * FROM execution_events WHERE execution_id = $1 ORDER BY created_at ASC',
        [executionId],
      );
      return result.rows.map((r: Record<string, unknown>) => ({
        id: r.id as string, execution_id: r.execution_id as string,
        event_type: r.event_type as 'execution_started' | 'node_started' | 'node_succeeded' | 'node_failed'
          | 'node_skipped' | 'execution_succeeded' | 'execution_failed' | 'execution_recovered',
        node_id: (r.node_id as string | null) ?? null,
        payload: safeJsonParse(r.payload), created_at: Number(r.created_at),
      }));
    },
  };
  // ── Triggers ──────────────────────────────────────────────────────────────

  triggers = {
    create: async (data: { id: string; workflow_id: string; trigger_type: 'cron' | 'webhook' | 'event' | 'manual'; config: Record<string, unknown> }) => {
      const now = new Date().toISOString();
      await this.conn.pool.query(
        `INSERT INTO workflow_triggers (id, workflow_id, trigger_type, config, enabled, created_at, updated_at)
         VALUES ($1, $2, $3, $4, true, $5, $5)`,
        [data.id, data.workflow_id, data.trigger_type, JSON.stringify(data.config), now],
      );
      const result = await this.conn.pool.query('SELECT * FROM workflow_triggers WHERE id = $1', [data.id]);
      if (result.rows.length === 0) throw new Error('Failed to create trigger');
      return mapTrigger(result.rows[0] as Record<string, unknown>);
    },

    getById: async (id: string) => {
      const result = await this.conn.pool.query('SELECT * FROM workflow_triggers WHERE id = $1', [id]);
      if (result.rows.length === 0) return null;
      return mapTrigger(result.rows[0] as Record<string, unknown>);
    },

    listByWorkflow: async (workflowId: string) => {
      const result = await this.conn.pool.query('SELECT * FROM workflow_triggers WHERE workflow_id = $1', [workflowId]);
      return result.rows.map((r: Record<string, unknown>) => mapTrigger(r));
    },

    listEnabled: async () => {
      const result = await this.conn.pool.query('SELECT * FROM workflow_triggers WHERE enabled = true');
      return result.rows.map((r: Record<string, unknown>) => mapTrigger(r));
    },

    update: async (id: string, data: { config?: Record<string, unknown>; enabled?: boolean }) => {
      const setClauses: string[] = ['updated_at = $2'];
      const params: unknown[] = [id, new Date().toISOString()];
      let paramIdx = 3;
      if (data.config !== undefined) { setClauses.push(`config = $${paramIdx}`); params.push(JSON.stringify(data.config)); paramIdx++; }
      if (data.enabled !== undefined) { setClauses.push(`enabled = $${paramIdx}`); params.push(data.enabled); paramIdx++; }
      await this.conn.pool.query(`UPDATE workflow_triggers SET ${setClauses.join(', ')} WHERE id = $1`, params);
    },

    delete: async (id: string) => {
      await this.conn.pool.query('DELETE FROM workflow_triggers WHERE id = $1', [id]);
    },
  };

  // ── Audit (append-only) ───────────────────────────────────────────────────

  audit = {
    write: async (event: { id: string; actor: string; action: string; resource_type: string; resource_id?: string; details?: Record<string, unknown>; ip_address?: string }) => {
      const now = new Date().toISOString();
      let lastErr: unknown;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          await this.conn.pool.query(
            `INSERT INTO audit_events (id, timestamp, actor, action, resource_type, resource_id, details, ip_address)
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
            [event.id, now, event.actor, event.action, event.resource_type, event.resource_id ?? null, JSON.stringify(event.details ?? {}), event.ip_address ?? null],
          );
          return;
        } catch (err) {
          lastErr = err;
          logger.warn({ attempt, error: String(err) }, 'Audit write failed, retrying');
        }
      }
      throw lastErr;
    },

    list: async (filter: { actor?: string; action?: string; resource_type?: string; resource_id?: string; after?: string; before?: string }, pagination: PaginationParams) => {
      const conditions: string[] = [];
      const params: unknown[] = [];
      let paramIdx = 1;
      if (filter.actor) { conditions.push(`actor = $${paramIdx}`); params.push(filter.actor); paramIdx++; }
      if (filter.action) { conditions.push(`action = $${paramIdx}`); params.push(filter.action); paramIdx++; }
      if (filter.resource_type) { conditions.push(`resource_type = $${paramIdx}`); params.push(filter.resource_type); paramIdx++; }
      if (filter.resource_id) { conditions.push(`resource_id = $${paramIdx}`); params.push(filter.resource_id); paramIdx++; }
      if (filter.after) { conditions.push(`timestamp >= $${paramIdx}`); params.push(filter.after); paramIdx++; }
      if (filter.before) { conditions.push(`timestamp <= $${paramIdx}`); params.push(filter.before); paramIdx++; }
      const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
      const countResult = await this.conn.pool.query(`SELECT count(*)::int AS count FROM audit_events ${whereClause}`, params);
      const total = (countResult.rows[0] as { count: number }).count ?? 0;
      const offset = (pagination.page - 1) * pagination.per_page;
      const dataResult = await this.conn.pool.query(
        `SELECT * FROM audit_events ${whereClause} ORDER BY timestamp DESC LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
        [...params, pagination.per_page, offset],
      );
      const data = dataResult.rows.map((r: Record<string, unknown>) => ({
        id: r.id as string, timestamp: toIsoString(r.timestamp), actor: r.actor as string, action: r.action as string,
        resource_type: r.resource_type as string, resource_id: (r.resource_id as string | null) ?? null,
        details: safeJsonParse(r.details), ip_address: (r.ip_address as string | null) ?? null,
      }));
      return { data, total, page: pagination.page, per_page: pagination.per_page, total_pages: Math.ceil(total / pagination.per_page) };
    },
  };

  // ── Users ─────────────────────────────────────────────────────────────────

  users = {
    create: async (data: { id: string; username: string; password_hash: string; email: string; role?: 'read' | 'write' | 'admin'; display_name?: string }) => {
