/**
 * SQLite connection management with WAL mode and safe defaults.
 */

import Database from 'better-sqlite3';
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3';
import { createLogger } from '@loop/observability';
import * as schema from '../schema.js';

const logger = createLogger({ name: 'loop:state:sqlite', component: 'state' });

// ─── V1.6 M1 (F-1, DB3): connection registry + process-exit safety net ──────
//
// The rare high-load SIGSEGV that `scripts/run_with_retry.sh` papers over comes
// from better-sqlite3's native handle being torn down by GC during process
// exit instead of an explicit `db.close()`. Every connection opened here is
// registered, and a synchronous `process.on('exit')` handler releases any
// handles still open when the process terminates — best-effort, never throws.

const openClients = new Set<Database.Database>();
let exitHookInstalled = false;

function installProcessExitHook(): void {
  if (exitHookInstalled) return;
  exitHookInstalled = true;
  process.on('exit', () => {
    closeAllSqliteConnections();
  });
}

/**
 * Best-effort close of every registered open connection (the same routine the
 * process `exit` hook runs). Idempotent; never throws.
 */
export function closeAllSqliteConnections(): void {
  for (const client of openClients) {
    try {
      client.close();
    } catch {
      // best-effort — a handle that refuses close at teardown is exactly the
      // situation this hook exists to tolerate.
    }
  }
  openClients.clear();
}

/** Number of connections currently registered as open (diagnostics / tests). */
export function openSqliteConnectionCount(): number {
  return openClients.size;
}

export interface SqliteConnection {
  db: BetterSQLite3Database<typeof schema>;
  client: Database.Database;
  close(): void;
}

export interface SqliteConnectionOptions {
  /** File path or ':memory:'. */
  path: string;
  /** Enable WAL mode (recommended for concurrent reads). Default true. */
  wal?: boolean;
}

export function createSqliteConnection(opts: SqliteConnectionOptions): SqliteConnection {
  const client = new Database(opts.path);
  openClients.add(client);
  installProcessExitHook();

  // Pragmas for performance and safety
  if (opts.wal !== false) {
    client.pragma('journal_mode = WAL');
  }
  client.pragma('busy_timeout = 5000');
  client.pragma('foreign_keys = ON');
  client.pragma('synchronous = NORMAL');

  logger.info({ path: opts.path, wal: opts.wal !== false }, 'SQLite connection opened');

  const db = drizzle(client, { schema });

  return {
    db,
    client,
    close() {
      // Unregister first so the exit hook never double-closes an explicit close.
      // better-sqlite3's close() is itself idempotent.
      openClients.delete(client);
      client.close();
      logger.info('SQLite connection closed');
    },
  };
}

/**
 * SQLite implementation of the StateStore interface.
 */

import { eq, and, desc, asc, or, sql, inArray } from 'drizzle-orm';
import { createLogger } from '@loop/observability';
import type { WorkflowDefinition } from '@loop/types';
import type {
  StateStore,
  PaginationParams,
  PaginatedResult,
  WorkflowFilter,
  ExecutionFilter,
} from '../interface.js';
import * as schema from '../schema.js';
import { runMigrations } from '../migrate.js';
import type { SqliteConnection } from './connection.js';

const logger = createLogger({ name: 'loop:state:sqlite', component: 'state' });

type WfRow = typeof schema.workflows.$inferSelect;
type WeRow = typeof schema.workflowExecutions.$inferSelect;
type NeRow = typeof schema.nodeExecutions.$inferSelect;

function safeJsonParse(raw: unknown): Record<string, unknown> {
  if (typeof raw === 'string') {
    try { return JSON.parse(raw) as Record<string, unknown>; } catch { return {}; }
  }
  if (raw && typeof raw === 'object') return raw as Record<string, unknown>;
  return {};
}

/**
 * Escape SQL LIKE wildcards so user-supplied search/tag filters match
 * literally. Use together with the `ESCAPE '\'` clause.
 */
function escapeLike(value: string): string {
  return value.replace(/[\\%_]/g, (c) => `\\${c}`);
}

function mapWorkflow(row: WfRow) {
  return {
    id: row.id, name: row.name, description: row.description,
    definition: safeJsonParse(row.definition) as unknown as WorkflowDefinition,
    version: row.version,
    status: row.status as 'draft' | 'active' | 'archived',
    tags: safeJsonParse(row.tags) as unknown as string[],
    created_by: row.created_by, updated_by: row.updated_by,
    created_at: row.created_at, updated_at: row.updated_at,
  };
}

function mapExecution(row: WeRow) {
  return {
    id: row.id, workflow_id: row.workflow_id, workflow_version: row.workflow_version,
    trigger_type: row.trigger_type as 'manual' | 'cron' | 'webhook' | 'event',
    trigger_payload: safeJsonParse(row.trigger_payload),
    status: row.status as 'pending' | 'running' | 'succeeded' | 'failed' | 'cancelled' | 'paused',
    started_at: row.started_at, completed_at: row.completed_at,
    duration_ms: row.duration_ms, error: row.error, initiated_by: row.initiated_by,
  };
}

function mapNodeExecution(row: NeRow) {
  return {
    id: row.id, execution_id: row.execution_id, node_id: row.node_id, node_type: row.node_type,
    status: row.status as 'pending' | 'running' | 'succeeded' | 'failed' | 'skipped',
    input: safeJsonParse(row.input), output: safeJsonParse(row.output),
    error: row.error, started_at: row.started_at, completed_at: row.completed_at,
    retry_count: row.retry_count, metadata: safeJsonParse(row.metadata),
    idempotency_key: row.idempotency_key,
  };
}

type EeRow = typeof schema.executionEvents.$inferSelect;

function mapExecutionEvent(row: EeRow) {
  return {
    id: row.id, execution_id: row.execution_id,
    event_type: row.event_type as
      | 'execution_started' | 'node_started' | 'node_succeeded' | 'node_failed'
      | 'node_skipped' | 'execution_succeeded' | 'execution_failed' | 'execution_recovered',
    node_id: row.node_id, payload: safeJsonParse(row.payload), created_at: row.created_at,
  };
}

export class SqliteStateStore implements StateStore {
  private conn: SqliteConnection;

  constructor(conn: SqliteConnection) {
    this.conn = conn;
  }

  async initialise(): Promise<void> {
    await runMigrations(this.conn);
    logger.info('State store initialised (SQLite)');
  }

  async close(): Promise<void> {
    this.conn.close();
  }

  private get db() { return this.conn.db; }

  // ── Workflows ─────────────────────────────────────────────────────────────

  workflows = {
    create: async (data: {
      id: string; name: string; description: string;
      definition: WorkflowDefinition; created_by: string; tags?: string[];
    }) => {
      const now = new Date().toISOString();
      this.db.insert(schema.workflows).values({
        id: data.id, name: data.name, description: data.description,
        definition: JSON.stringify(data.definition) as never,
        version: 1, status: 'draft',
        tags: JSON.stringify(data.tags ?? []) as never,
        created_by: data.created_by, updated_by: data.created_by,
        created_at: now, updated_at: now,
      }).run();
      const row = this.db.select().from(schema.workflows).where(eq(schema.workflows.id, data.id)).get();
      return mapWorkflow(row!);
    },

    getById: async (id: string) => {
      const row = this.db.select().from(schema.workflows).where(eq(schema.workflows.id, id)).get();
      return row ? mapWorkflow(row) : null;
    },

    list: async (filter: WorkflowFilter, pagination: PaginationParams): Promise<PaginatedResult<ReturnType<typeof mapWorkflow>>> => {
      const conditions = [];
      if (filter.status) conditions.push(eq(schema.workflows.status, filter.status));
      if (filter.tag) conditions.push(sql`${schema.workflows.tags} LIKE ${`%${escapeLike(filter.tag)}%`} ESCAPE ${'\\'}`);
      if (filter.search) {
        const pattern = `%${escapeLike(filter.search)}%`;
        conditions.push(or(
          sql`${schema.workflows.name} LIKE ${pattern} ESCAPE ${'\\'}`,
          sql`${schema.workflows.description} LIKE ${pattern} ESCAPE ${'\\'}`,
        ));
      }
      const where = conditions.length ? and(...conditions) : undefined;
      const countResult = this.db.select({ count: sql<number>`count(*)` }).from(schema.workflows).where(where).get();
      const total = countResult?.count ?? 0;
      const [sortField, sortDir] = (filter.sort ?? 'updated_at:desc').split(':');
      const sortCol = sortField === 'created_at' ? schema.workflows.created_at : schema.workflows.updated_at;
      const orderFn = sortDir === 'asc' ? asc : desc;
      const rows = this.db.select().from(schema.workflows).where(where)
        .orderBy(orderFn(sortCol)).limit(pagination.per_page).offset((pagination.page - 1) * pagination.per_page).all();
      return { data: rows.map(mapWorkflow), total, page: pagination.page, per_page: pagination.per_page, total_pages: Math.ceil(total / pagination.per_page) };
    },

    update: async (id: string, data: {
      name?: string; description?: string; definition?: WorkflowDefinition;
      status?: 'draft' | 'active' | 'archived'; tags?: string[]; updated_by: string;
    }) => {
      const now = new Date().toISOString();
      const updates: Record<string, unknown> = { updated_at: now, updated_by: data.updated_by };
      if (data.name !== undefined) updates.name = data.name;
      if (data.description !== undefined) updates.description = data.description;
      if (data.definition !== undefined) {
        updates.definition = JSON.stringify(data.definition);
        const current = this.db.select().from(schema.workflows).where(eq(schema.workflows.id, id)).get();
        if (current) updates.version = current.version + 1;
      }
      if (data.status !== undefined) updates.status = data.status;
      if (data.tags !== undefined) updates.tags = JSON.stringify(data.tags);
      this.db.update(schema.workflows).set(updates).where(eq(schema.workflows.id, id)).run();
      return (await this.workflows.getById(id))!;
    },

    archive: async (id: string) => {
      this.db.update(schema.workflows).set({ status: 'archived' }).where(eq(schema.workflows.id, id)).run();
    },

    delete: async (id: string) => {
      // Hard-delete the workflow and every dependent row. The previous
      // implementation deleted node_executions by `execution_id = <workflow id>`
      // (matching nothing) and skipped execution_events entirely — with
      // foreign_keys enabled the delete then failed on the
      // execution_events → workflow_executions FK once a workflow had run.
      this.db.transaction((tx) => {
        const execs = tx
          .select({ id: schema.workflowExecutions.id })
          .from(schema.workflowExecutions)
          .where(eq(schema.workflowExecutions.workflow_id, id))
          .all();
        const execIds = execs.map((r) => r.id);
        if (execIds.length > 0) {
          tx.delete(schema.executionEvents).where(inArray(schema.executionEvents.execution_id, execIds)).run();
          tx.delete(schema.nodeExecutions).where(inArray(schema.nodeExecutions.execution_id, execIds)).run();
        }
        tx.delete(schema.workflowExecutions).where(eq(schema.workflowExecutions.workflow_id, id)).run();
        tx.delete(schema.workflowDefinitions).where(eq(schema.workflowDefinitions.workflow_id, id)).run();
        tx.delete(schema.workflowTriggers).where(eq(schema.workflowTriggers.workflow_id, id)).run();
        tx.delete(schema.workflows).where(eq(schema.workflows.id, id)).run();
      });
    },
  };

  // ── Workflow Definitions ──────────────────────────────────────────────────

  workflowDefinitions = {
    create: async (data: {
      id: string; workflow_id: string; version: number; definition: WorkflowDefinition;
      commit_hash: string; created_by: string; change_summary?: string;
    }) => {
      const now = new Date().toISOString();
      this.db.insert(schema.workflowDefinitions).values({
        id: data.id, workflow_id: data.workflow_id, version: data.version,
        definition: JSON.stringify(data.definition) as never,
        commit_hash: data.commit_hash, created_by: data.created_by,
        created_at: now, change_summary: data.change_summary ?? '',
      }).run();
      const row = this.db.select().from(schema.workflowDefinitions).where(eq(schema.workflowDefinitions.id, data.id)).get();
      const r = row!;
      return { id: r.id, workflow_id: r.workflow_id, version: r.version,
        definition: safeJsonParse(r.definition) as unknown as WorkflowDefinition,
        commit_hash: r.commit_hash, created_by: r.created_by, created_at: r.created_at, change_summary: r.change_summary };
    },

    listByWorkflow: async (workflowId: string) => {
      const rows = this.db.select().from(schema.workflowDefinitions)
        .where(eq(schema.workflowDefinitions.workflow_id, workflowId))
        .orderBy(desc(schema.workflowDefinitions.version)).all();
      return rows.map((r) => ({
        id: r.id, workflow_id: r.workflow_id, version: r.version,
        definition: safeJsonParse(r.definition) as unknown as WorkflowDefinition,
        commit_hash: r.commit_hash, created_by: r.created_by, created_at: r.created_at, change_summary: r.change_summary,
      }));
    },

    getByWorkflowAndVersion: async (workflowId: string, version: number) => {
      const row = this.db.select().from(schema.workflowDefinitions)
        .where(and(eq(schema.workflowDefinitions.workflow_id, workflowId), eq(schema.workflowDefinitions.version, version))).get();
      if (!row) return null;
      return { id: row.id, workflow_id: row.workflow_id, version: row.version,
        definition: safeJsonParse(row.definition) as unknown as WorkflowDefinition,
        commit_hash: row.commit_hash, created_by: row.created_by, created_at: row.created_at, change_summary: row.change_summary };
    },
  };

  // ── Executions ────────────────────────────────────────────────────────────

  executions = {
    create: async (data: {
      id: string; workflow_id: string; workflow_version: number;
      trigger_type: 'manual' | 'cron' | 'webhook' | 'event';
      trigger_payload?: Record<string, unknown>; initiated_by?: string;
    }) => {
      this.db.insert(schema.workflowExecutions).values({
        id: data.id, workflow_id: data.workflow_id, workflow_version: data.workflow_version,
        trigger_type: data.trigger_type,
        trigger_payload: JSON.stringify(data.trigger_payload ?? {}) as never,
        status: 'pending', initiated_by: data.initiated_by ?? null,
      }).run();
      const row = this.db.select().from(schema.workflowExecutions).where(eq(schema.workflowExecutions.id, data.id)).get();
      return mapExecution(row!);
    },

    getById: async (id: string) => {
      const row = this.db.select().from(schema.workflowExecutions).where(eq(schema.workflowExecutions.id, id)).get();
      return row ? mapExecution(row) : null;
    },

    list: async (filter: ExecutionFilter, pagination: PaginationParams) => {
      const conditions = [];
      if (filter.workflow_id) conditions.push(eq(schema.workflowExecutions.workflow_id, filter.workflow_id));
      if (filter.status) conditions.push(eq(schema.workflowExecutions.status, filter.status as typeof schema.workflowExecutions.status.enumValues[number]));
      if (filter.trigger_type) conditions.push(eq(schema.workflowExecutions.trigger_type, filter.trigger_type as typeof schema.workflowExecutions.trigger_type.enumValues[number]));
      if (filter.started_after) conditions.push(sql`${schema.workflowExecutions.started_at} >= ${filter.started_after}`);
      if (filter.started_before) conditions.push(sql`${schema.workflowExecutions.started_at} <= ${filter.started_before}`);
      const where = conditions.length ? and(...conditions) : undefined;
      const countResult = this.db.select({ count: sql<number>`count(*)` }).from(schema.workflowExecutions).where(where).get();
      const total = countResult?.count ?? 0;
      const rows = this.db.select().from(schema.workflowExecutions).where(where)
        .orderBy(desc(schema.workflowExecutions.started_at)).limit(pagination.per_page).offset((pagination.page - 1) * pagination.per_page).all();
      return { data: rows.map(mapExecution), total, page: pagination.page, per_page: pagination.per_page, total_pages: Math.ceil(total / pagination.per_page) };
    },

    updateStatus: async (id: string, data: {
      status: 'pending' | 'running' | 'succeeded' | 'failed' | 'cancelled' | 'paused';
      started_at?: string; completed_at?: string; duration_ms?: number; error?: string | null;
    }) => {
      // Omitted fields are preserved — unconditionally writing NULL here used
      // to wipe `started_at`/`duration_ms` on every terminal transition, which
      // broke `ORDER BY started_at` listings and audit trails.
      this.db.update(schema.workflowExecutions).set({
        status: data.status,
        ...(data.started_at !== undefined ? { started_at: data.started_at } : {}),
        ...(data.completed_at !== undefined ? { completed_at: data.completed_at } : {}),
        ...(data.duration_ms !== undefined ? { duration_ms: data.duration_ms } : {}),
        ...(data.error !== undefined ? { error: data.error } : {}),
      }).where(eq(schema.workflowExecutions.id, id)).run();
    },

    completeIfActive: async (id: string, data: {
      status: 'succeeded' | 'failed' | 'cancelled';
      completed_at?: string; duration_ms?: number; error?: string | null;
    }) => {
      const result = this.db.update(schema.workflowExecutions).set({
        status: data.status,
        ...(data.completed_at !== undefined ? { completed_at: data.completed_at } : {}),
        ...(data.duration_ms !== undefined ? { duration_ms: data.duration_ms } : {}),
        ...(data.error !== undefined ? { error: data.error } : {}),
      }).where(and(
        eq(schema.workflowExecutions.id, id),
        inArray(schema.workflowExecutions.status, ['pending', 'running']),
      )).run();
      return result.changes > 0;
    },

    findInterrupted: async () => {
      // Both states are non-terminal and owned by the (now dead) process:
      // 'running' died mid-execution; 'pending' was created but never picked
      // up (e.g. crash between record creation and dispatch). Excluding
      // 'pending' leaves those executions stuck forever (bug 12).
      const rows = this.db
        .select()
        .from(schema.workflowExecutions)
        .where(
          or(
            eq(schema.workflowExecutions.status, 'running'),
            eq(schema.workflowExecutions.status, 'pending'),
          ),
        )
        .all();
      return rows.map(mapExecution);
    },
  };

  // ── Node Executions ───────────────────────────────────────────────────────

  nodeExecutions = {
    create: async (data: { id: string; execution_id: string; node_id: string; node_type: string; input?: Record<string, unknown>; idempotency_key?: string }) => {
      this.db.insert(schema.nodeExecutions).values({
        id: data.id, execution_id: data.execution_id, node_id: data.node_id, node_type: data.node_type,
        status: 'pending', input: JSON.stringify(data.input ?? {}) as never,
        idempotency_key: data.idempotency_key ?? null,
      }).run();
      const row = this.db.select().from(schema.nodeExecutions).where(eq(schema.nodeExecutions.id, data.id)).get();
      return mapNodeExecution(row!);
    },

    listByExecution: async (executionId: string) => {
      const rows = this.db.select().from(schema.nodeExecutions)
        .where(eq(schema.nodeExecutions.execution_id, executionId)).orderBy(schema.nodeExecutions.started_at).all();
      return rows.map(mapNodeExecution);
    },

    findByIdempotencyKey: async (key: string) => {
      const row = this.db.select().from(schema.nodeExecutions)
        .where(eq(schema.nodeExecutions.idempotency_key, key)).get();
      return row ? mapNodeExecution(row) : null;
    },

    updateStatus: async (id: string, data: {
      status: 'pending' | 'running' | 'succeeded' | 'failed' | 'skipped';
      started_at?: string; completed_at?: string; output?: Record<string, unknown>;
      error?: string | null; retry_count?: number; metadata?: Record<string, unknown>;
    }) => {
      // Same preserve-on-omit semantics as executions.updateStatus: writing
      // NULL unconditionally used to erase a node's `started_at` the moment it
      // succeeded.
      this.db.update(schema.nodeExecutions).set({
        status: data.status,
        ...(data.started_at !== undefined ? { started_at: data.started_at } : {}),
        ...(data.completed_at !== undefined ? { completed_at: data.completed_at } : {}),
        ...(data.output !== undefined ? { output: JSON.stringify(data.output) as never } : {}),
        ...(data.error !== undefined ? { error: data.error } : {}),
        ...(data.retry_count !== undefined ? { retry_count: data.retry_count } : {}),
        ...(data.metadata !== undefined ? { metadata: JSON.stringify(data.metadata) as never } : {}),
      }).where(eq(schema.nodeExecutions.id, id)).run();
    },
  };

  // ── Execution Events (V1.1 M1 — append-only) ────────────────────────────

  events = {
    append: async (data: {
      id: string; execution_id: string;
      event_type: 'execution_started' | 'node_started' | 'node_succeeded' | 'node_failed'
        | 'node_skipped' | 'execution_succeeded' | 'execution_failed' | 'execution_recovered';
      node_id?: string; payload?: Record<string, unknown>; created_at?: number;
    }) => {
      this.db.insert(schema.executionEvents).values({
        id: data.id, execution_id: data.execution_id, event_type: data.event_type,
        node_id: data.node_id ?? null,
        payload: JSON.stringify(data.payload ?? {}) as never,
        created_at: data.created_at ?? Date.now(),
      }).run();
    },

    listByExecution: async (executionId: string) => {
      const rows = this.db.select().from(schema.executionEvents)
        .where(eq(schema.executionEvents.execution_id, executionId))
        .orderBy(asc(schema.executionEvents.created_at)).all();
      return rows.map(mapExecutionEvent);
    },
  };

  // ── Triggers ──────────────────────────────────────────────────────────────

  triggers = {
    create: async (data: { id: string; workflow_id: string; trigger_type: 'cron' | 'webhook' | 'event' | 'manual'; config: Record<string, unknown> }) => {
      const now = new Date().toISOString();
      this.db.insert(schema.workflowTriggers).values({
        id: data.id, workflow_id: data.workflow_id, trigger_type: data.trigger_type,
        config: JSON.stringify(data.config) as never, enabled: true, created_at: now, updated_at: now,
      }).run();
      const row = this.db.select().from(schema.workflowTriggers).where(eq(schema.workflowTriggers.id, data.id)).get();
      const r = row!;
      return { id: r.id, workflow_id: r.workflow_id, trigger_type: r.trigger_type as 'cron' | 'webhook' | 'event' | 'manual', config: safeJsonParse(r.config), enabled: r.enabled, created_at: r.created_at, updated_at: r.updated_at };
    },

    getById: async (id: string) => {
      const row = this.db.select().from(schema.workflowTriggers).where(eq(schema.workflowTriggers.id, id)).get();
      if (!row) return null;
      return { id: row.id, workflow_id: row.workflow_id, trigger_type: row.trigger_type as 'cron' | 'webhook' | 'event' | 'manual', config: safeJsonParse(row.config), enabled: row.enabled, created_at: row.created_at, updated_at: row.updated_at };
    },

    listByWorkflow: async (workflowId: string) => {
      const rows = this.db.select().from(schema.workflowTriggers).where(eq(schema.workflowTriggers.workflow_id, workflowId)).all();
      return rows.map((r) => ({ id: r.id, workflow_id: r.workflow_id, trigger_type: r.trigger_type as 'cron' | 'webhook' | 'event' | 'manual', config: safeJsonParse(r.config), enabled: r.enabled, created_at: r.created_at, updated_at: r.updated_at }));
    },

    listEnabled: async () => {
      const rows = this.db.select().from(schema.workflowTriggers).where(eq(schema.workflowTriggers.enabled, true)).all();
      return rows.map((r) => ({ id: r.id, workflow_id: r.workflow_id, trigger_type: r.trigger_type as 'cron' | 'webhook' | 'event' | 'manual', config: safeJsonParse(r.config), enabled: r.enabled, created_at: r.created_at, updated_at: r.updated_at }));
    },

    update: async (id: string, data: { config?: Record<string, unknown>; enabled?: boolean }) => {
      this.db.update(schema.workflowTriggers).set({
        config: data.config ? (JSON.stringify(data.config) as never) : undefined,
        enabled: data.enabled, updated_at: new Date().toISOString(),
      }).where(eq(schema.workflowTriggers.id, id)).run();
    },

    delete: async (id: string) => {
      this.db.delete(schema.workflowTriggers).where(eq(schema.workflowTriggers.id, id)).run();
    },
  };

  // ── Audit ─────────────────────────────────────────────────────────────────

  audit = {
    write: async (event: { id: string; actor: string; action: string; resource_type: string; resource_id?: string; details?: Record<string, unknown>; ip_address?: string }) => {
      const now = new Date().toISOString();
      let lastErr: unknown;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          this.db.insert(schema.auditEvents).values({
            id: event.id, timestamp: now, actor: event.actor, action: event.action,
            resource_type: event.resource_type, resource_id: event.resource_id ?? null,
            details: JSON.stringify(event.details ?? {}) as never,
            ip_address: event.ip_address ?? null,
          }).run();
          return;
        } catch (err) {
          lastErr = err;
          logger.warn({ attempt, error: String(err) }, 'Audit write failed, retrying');
        }
      }
      throw lastErr;
    },

    list: async (filter: { actor?: string; action?: string; resource_type?: string; resource_id?: string; after?: string; before?: string }, pagination: PaginationParams) => {
      const conditions = [];
      if (filter.actor) conditions.push(eq(schema.auditEvents.actor, filter.actor));
      if (filter.action) conditions.push(eq(schema.auditEvents.action, filter.action));
      if (filter.resource_type) conditions.push(eq(schema.auditEvents.resource_type, filter.resource_type));
      if (filter.resource_id) conditions.push(eq(schema.auditEvents.resource_id, filter.resource_id));
      if (filter.after) conditions.push(sql`${schema.auditEvents.timestamp} >= ${filter.after}`);
      if (filter.before) conditions.push(sql`${schema.auditEvents.timestamp} <= ${filter.before}`);
      const where = conditions.length ? and(...conditions) : undefined;
      const countResult = this.db.select({ count: sql<number>`count(*)` }).from(schema.auditEvents).where(where).get();
      const total = countResult?.count ?? 0;
      const rows = this.db.select().from(schema.auditEvents).where(where).orderBy(desc(schema.auditEvents.timestamp)).limit(pagination.per_page).offset((pagination.page - 1) * pagination.per_page).all();
      return {
        data: rows.map((r) => ({ id: r.id, timestamp: r.timestamp, actor: r.actor, action: r.action, resource_type: r.resource_type, resource_id: r.resource_id, details: safeJsonParse(r.details), ip_address: r.ip_address })),
        total, page: pagination.page, per_page: pagination.per_page, total_pages: Math.ceil(total / pagination.per_page),
      };
    },
  };

  // ── Users ─────────────────────────────────────────────────────────────────

  users = {
    create: async (data: { id: string; username: string; password_hash: string; email: string; role?: 'read' | 'write' | 'admin'; display_name?: string }) => {
      const now = new Date().toISOString();
      this.db.insert(schema.users).values({
        id: data.id, username: data.username, password_hash: data.password_hash, email: data.email,
        role: data.role ?? 'read', display_name: data.display_name ?? '', created_at: now, is_active: true,
      }).run();
      const row = this.db.select().from(schema.users).where(eq(schema.users.id, data.id)).get();
      const r = row!;
      return { id: r.id, username: r.username, email: r.email, role: r.role, display_name: r.display_name ?? '', created_at: r.created_at, is_active: r.is_active };
    },

    getById: async (id: string) => {
      const row = this.db.select().from(schema.users).where(eq(schema.users.id, id)).get();
      return row ? { id: row.id, username: row.username, email: row.email, role: row.role, password_hash: row.password_hash, display_name: row.display_name ?? '', is_active: row.is_active, last_login_at: row.last_login_at } : null;
    },

    getByUsername: async (username: string) => {
      const row = this.db.select().from(schema.users).where(eq(schema.users.username, username)).get();
      return row ? { id: row.id, username: row.username, email: row.email, role: row.role, password_hash: row.password_hash, display_name: row.display_name ?? '', is_active: row.is_active, last_login_at: row.last_login_at } : null;
    },

    updateLastLogin: async (id: string) => {
      this.db.update(schema.users).set({ last_login_at: new Date().toISOString() }).where(eq(schema.users.id, id)).run();
    },

    list: async () => {
      const rows = this.db.select().from(schema.users).all();
      return rows.map((r) => ({ id: r.id, username: r.username, email: r.email, role: r.role, display_name: r.display_name ?? '', is_active: r.is_active, created_at: r.created_at, last_login_at: r.last_login_at }));
    },

    updateRole: async (id: string, role: 'read' | 'write' | 'admin') => {
      this.db.update(schema.users).set({ role }).where(eq(schema.users.id, id)).run();
    },

    deactivate: async (id: string) => {
      this.db.update(schema.users).set({ is_active: false }).where(eq(schema.users.id, id)).run();
    },
  };

  // ── Secrets ───────────────────────────────────────────────────────────────

  secrets = {
    create: async (data: { id: string; name: string; encrypted_value: string; scope: 'global' | 'workflow' | 'connector'; scope_id?: string; created_by: string }) => {
      const now = new Date().toISOString();
      this.db.insert(schema.secrets).values({
        id: data.id, name: data.name, encrypted_value: data.encrypted_value,
        scope: data.scope, scope_id: data.scope_id ?? null, created_by: data.created_by,
        created_at: now, updated_at: now,
      }).run();
    },

    getByName: async (name: string, scope?: string, scopeId?: string) => {
      const conditions = [eq(schema.secrets.name, name)];
      if (scope) conditions.push(eq(schema.secrets.scope, scope as typeof schema.secrets.scope.enumValues[number]));
      if (scopeId) conditions.push(eq(schema.secrets.scope_id, scopeId));
      const row = this.db.select().from(schema.secrets).where(and(...conditions)).get();
      return row ? { id: row.id, name: row.name, encrypted_value: row.encrypted_value, scope: row.scope, scope_id: row.scope_id } : null;
    },

    list: async (scope?: string, scopeId?: string) => {
      const conditions = [];
      if (scope) conditions.push(eq(schema.secrets.scope, scope as typeof schema.secrets.scope.enumValues[number]));
      if (scopeId) conditions.push(eq(schema.secrets.scope_id, scopeId));
      const where = conditions.length ? and(...conditions) : undefined;
      const rows = this.db.select().from(schema.secrets).where(where).all();
      return rows.map((r) => ({ id: r.id, name: r.name, scope: r.scope, scope_id: r.scope_id, created_at: r.created_at }));
    },

    update: async (id: string, encrypted_value: string) => {
      this.db.update(schema.secrets).set({ encrypted_value, updated_at: new Date().toISOString() }).where(eq(schema.secrets.id, id)).run();
    },

    delete: async (id: string) => {
      this.db.delete(schema.secrets).where(eq(schema.secrets.id, id)).run();
    },
  };

  // ── Egress Policies ───────────────────────────────────────────────────────

  egressPolicies = {
    create: async (data: { id: string; name: string; rule_type: 'allow' | 'deny'; target_type: 'domain' | 'ip_range' | 'region'; target_value: string; priority?: number }) => {
      this.db.insert(schema.egressPolicies).values({
        id: data.id, name: data.name, rule_type: data.rule_type, target_type: data.target_type,
        target_value: data.target_value, priority: data.priority ?? 0, enabled: true,
      }).run();
    },

    listEnabled: async () => {
      const rows = this.db.select().from(schema.egressPolicies).where(eq(schema.egressPolicies.enabled, true)).orderBy(desc(schema.egressPolicies.priority)).all();
      return rows.map((r) => ({ id: r.id, name: r.name, rule_type: r.rule_type as 'allow' | 'deny', target_type: r.target_type as 'domain' | 'ip_range' | 'region', target_value: r.target_value, priority: r.priority, enabled: r.enabled }));
    },

    list: async () => {
      const rows = this.db.select().from(schema.egressPolicies).orderBy(desc(schema.egressPolicies.priority)).all();
      return rows.map((r) => ({ id: r.id, name: r.name, rule_type: r.rule_type as 'allow' | 'deny', target_type: r.target_type as 'domain' | 'ip_range' | 'region', target_value: r.target_value, priority: r.priority, enabled: r.enabled, created_at: r.created_at }));
    },

    update: async (id: string, data: { name?: string; rule_type?: 'allow' | 'deny'; target_type?: 'domain' | 'ip_range' | 'region'; target_value?: string; priority?: number; enabled?: boolean }) => {
      this.db.update(schema.egressPolicies).set({
        name: data.name, rule_type: data.rule_type, target_type: data.target_type,
        target_value: data.target_value, priority: data.priority, enabled: data.enabled,
      }).where(eq(schema.egressPolicies.id, id)).run();
    },

    delete: async (id: string) => {
      this.db.delete(schema.egressPolicies).where(eq(schema.egressPolicies.id, id)).run();
    },
  };

  // ── Connectors ────────────────────────────────────────────────────────────

  connectors = {
    create: async (data: { id: string; connector_type: 'vault' | 'desk' | 'recap' | 'generic'; name: string; config: Record<string, unknown> }) => {
      const now = new Date().toISOString();
      this.db.insert(schema.connectors).values({
        id: data.id, connector_type: data.connector_type, name: data.name,
        config: JSON.stringify(data.config) as never, status: 'disconnected', created_at: now, updated_at: now,
      }).run();
      const row = this.db.select().from(schema.connectors).where(eq(schema.connectors.id, data.id)).get();
      const r = row!;
      return { id: r.id, connector_type: r.connector_type as 'vault' | 'desk' | 'recap' | 'generic', name: r.name, config: safeJsonParse(r.config), status: r.status as 'connected' | 'disconnected' | 'error', last_health_check: r.last_health_check, created_at: r.created_at, updated_at: r.updated_at };
    },

    getById: async (id: string) => {
      const row = this.db.select().from(schema.connectors).where(eq(schema.connectors.id, id)).get();
      if (!row) return null;
      return { id: row.id, connector_type: row.connector_type as 'vault' | 'desk' | 'recap' | 'generic', name: row.name, config: safeJsonParse(row.config), status: row.status as 'connected' | 'disconnected' | 'error', last_health_check: row.last_health_check, created_at: row.created_at, updated_at: row.updated_at };
    },

    list: async () => {
      const rows = this.db.select().from(schema.connectors).all();
      return rows.map((r) => ({ id: r.id, connector_type: r.connector_type as 'vault' | 'desk' | 'recap' | 'generic', name: r.name, config: safeJsonParse(r.config), status: r.status as 'connected' | 'disconnected' | 'error', last_health_check: r.last_health_check, created_at: r.created_at, updated_at: r.updated_at }));
    },

    update: async (id: string, data: { name?: string; config?: Record<string, unknown>; status?: 'connected' | 'disconnected' | 'error'; last_health_check?: string }) => {
      this.db.update(schema.connectors).set({
        name: data.name, config: data.config ? (JSON.stringify(data.config) as never) : undefined,
        status: data.status, last_health_check: data.last_health_check, updated_at: new Date().toISOString(),
      }).where(eq(schema.connectors.id, id)).run();
    },

    delete: async (id: string) => {
      this.db.delete(schema.connectors).where(eq(schema.connectors.id, id)).run();
    },
  };
}

/**
 * Template registry contracts — the marketplace data model.
 *
 * A template file is a JSON envelope around a WorkflowDefinition. The optional
 * marketplace fields (industry/category/featured/…) are honoured when present;
 * otherwise the registry derives them from the definition's tags via the
 * taxonomy, so legacy template files keep working unchanged.
 */

import type { WorkflowDefinition } from '@loop/types';

/** Vertical a template targets (drives marketplace filtering). */
export const INDUSTRIES = [
  'general',
  'finance',
  'legal',
  'healthcare',
  'education',
  'ecommerce',
  'manufacturing',
  'human-resources',
  'marketing',
  'customer-support',
  'sales',
  'it-operations',
] as const;
export type Industry = (typeof INDUSTRIES)[number];

/** Functional grouping (what kind of automation it is). */
export const CATEGORIES = [
  'automation',
  'approval',
  'monitoring',
  'reporting',
  'knowledge',
  'integration',
] as const;
export type TemplateCategory = (typeof CATEGORIES)[number];

/** Raw on-disk template envelope (marketplace fields all optional). */
export interface TemplateFile {
  /** Marketplace id — derived from the filename when absent. */
  id?: string;
  name: string;
  description: string;
  definition: WorkflowDefinition;
  industry?: Industry;
  category?: TemplateCategory;
  /** Pinned to the top of the gallery when true. */
  featured?: boolean;
  /** Short bullet scenarios shown on the detail card. */
  use_cases?: string[];
  /** Emoji glyph rendered on the marketplace card. */
  icon?: string;
}

/** Gallery-facing summary (definition excluded — cheap to list). */
export interface TemplateSummary {
  id: string;
  name: string;
  description: string;
  industry: Industry;
  category: TemplateCategory;
  featured: boolean;
  icon: string;
  use_cases: string[];
  node_count: number;
  /** Distinct agent prefixes used by the definition (vault/desk/recap/generic/control/code). */
  agents: string[];
  tags: string[];
}

/** Full template for the detail view and instantiation. */
export interface WorkflowTemplate extends TemplateSummary {
  definition: WorkflowDefinition;
}

/** Filters accepted by TemplateRegistry.list(). */
export interface TemplateFilters {
  industry?: Industry | 'all';
  category?: TemplateCategory | 'all';
  /** Case-insensitive substring over name/description/tags/use_cases. */
  search?: string;
  featuredOnly?: boolean;
}

/** Result of preparing a template for creation (name may be overridden). */
export interface InstantiateOptions {
  name?: string;
  description?: string;
}

/**
 * TemplateRegistry — loads template files from disk, validates them, enriches
 * them with marketplace metadata and serves list/get/instantiate queries.
 *
 * Loading strategy: read every `*.json` in the templates directory, parse the
 * envelope, validate the embedded definition against WorkflowDefinitionSchema,
 * and skip (recording) files that fail — a broken template must never take the
 * API down. Marketplace fields absent from a file are derived from its tags via
 * the taxonomy below so legacy templates appear in the gallery automatically.
 */

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { WorkflowDefinitionSchema } from '@loop/types';
import type { WorkflowDefinition } from '@loop/types';
import { CATEGORIES, INDUSTRIES } from './interface.js';
import type {
  Industry,
  InstantiateOptions,
  TemplateCategory,
  TemplateFile,
  TemplateFilters,
  TemplateSummary,
  WorkflowTemplate,
} from './interface.js';

/** Tag patterns → industry, checked in order (first match wins). */
const TAG_INDUSTRY: Array<[RegExp, Industry]> = [
  [/\b(invoice|payment|finance|financial|expense|billing|reconciliation|accounting)\b/i, 'finance'],
  [/\b(legal|contract|compliance|nda|litigation|counsel)\b/i, 'legal'],
  [/\b(health|patient|clinical|hipaa|medical)\b/i, 'healthcare'],
  [/\b(education|course|student|learning|campus)\b/i, 'education'],
  [/\b(ecommerce|e-?commerce|order|inventory|catalog|shop|store|cart)\b/i, 'ecommerce'],
  [/\b(manufacturing|production|factory|equipment|quality|iot|sensor)\b/i, 'manufacturing'],
  [/\b(hr|human[- ]resources|onboarding|employee|recruiting|payroll|leave)\b/i, 'human-resources'],
  [/\b(marketing|campaign|seo|content|social|brand|newsletter)\b/i, 'marketing'],
  [/\b(support|ticket|helpdesk|sla|escalation|customer[- ]service)\b/i, 'customer-support'],
  [/\b(sales|lead|crm|pipeline|prospect|deal)\b/i, 'sales'],
  [/\b(incident|devops|it[- ]ops|infrastructure|monitoring|alerting)\b/i, 'it-operations'],
];

/** Tag patterns → category (first match wins, defaults to automation). */
const TAG_CATEGORY: Array<[RegExp, TemplateCategory]> = [
  [/\bapproval\b/i, 'approval'],
  [/\b(monitor|alert|incident|observ)/i, 'monitoring'],
  [/\b(report|digest|summar|analytics)/i, 'reporting'],
  [/\b(knowledge|rag|ingest|index)/i, 'knowledge'],
  [/\b(sync|integration|webhook)\b/i, 'integration'],
];

/** Default gallery glyph per industry. */
const INDUSTRY_ICON: Record<Industry, string> = {
  general: '⚡',
  finance: '💰',
  legal: '⚖️',
  healthcare: '🏥',
  education: '🎓',
  ecommerce: '🛒',
  manufacturing: '🏭',
  'human-resources': '🧑‍💼',
  marketing: '📣',
  'customer-support': '🎧',
  sales: '📈',
  'it-operations': '🛠️',
};

const AGENT_PREFIXES = ['vault', 'desk', 'recap', 'generic', 'control', 'code'] as const;

function deriveIndustry(tags: readonly string[]): Industry {
  for (const [pattern, industry] of TAG_INDUSTRY) {
    if (tags.some((tag) => pattern.test(tag))) return industry;
  }
  return 'general';
}

function deriveCategory(tags: readonly string[]): TemplateCategory {
  for (const [pattern, category] of TAG_CATEGORY) {
    if (tags.some((tag) => pattern.test(tag))) return category;
  }
  return 'automation';
}

function agentsOf(definition: WorkflowDefinition): string[] {
  const found = new Set<string>();
  for (const node of definition.nodes) {
    const prefix = AGENT_PREFIXES.find((p) => node.type.startsWith(`${p}.`));
    if (prefix) found.add(prefix);
  }
  return [...found].sort();
}

function toKebabId(fileName: string): string {
  return fileName
    .replace(/\.json$/i, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase();
}

/** A template file that failed to load — surfaced via getLoadErrors(). */
export interface TemplateLoadError {
  file: string;
  error: string;
}

export class TemplateRegistry {
  private readonly templates = new Map<string, WorkflowTemplate>();
  private readonly templatesDir: string;
  private readonly loadErrors: TemplateLoadError[] = [];

  constructor(templatesDir?: string) {
    this.templatesDir = this.resolveDir(templatesDir);
    this.load();
  }

  /** Directory search order: explicit arg → env → module-relative → cwd walk-up. */
  private resolveDir(explicit?: string): string {
    const candidates: string[] = [];
    if (explicit) candidates.push(resolve(explicit));
    const envDir = process.env['LOOP_TEMPLATES_DIR'];
    if (envDir) candidates.push(resolve(envDir));
    // dist/registry.js and src/registry.ts are both two levels below the
    // package root, so ../../../templates always points at the repo templates.
    const moduleRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
    candidates.push(join(moduleRoot, 'templates'));
    let cwd = process.cwd();
    for (let i = 0; i < 6; i += 1) {
      candidates.push(join(cwd, 'templates'));
      const parent = dirname(cwd);
      if (parent === cwd) break;
      cwd = parent;
    }
    for (const candidate of candidates) {
      if (existsSync(candidate)) return candidate;
    }
    return candidates[0] ?? join(process.cwd(), 'templates');
  }

  private load(): void {
    if (!existsSync(this.templatesDir)) return;
    const files = readdirSync(this.templatesDir)
      .filter((f) => f.endsWith('.json'))
      .sort();
    for (const file of files) {
      try {
        const raw = JSON.parse(readFileSync(join(this.templatesDir, file), 'utf8')) as TemplateFile;
        const parsed = WorkflowDefinitionSchema.safeParse(raw.definition);
        if (!parsed.success) {
          this.loadErrors.push({
            file,
            error: parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; '),
          });
          continue;
        }
        const id = raw.id ? toKebabId(`${raw.id}`) : toKebabId(file);
        const template = this.toTemplate(raw, parsed.data, id);
        // On id collision the later file wins but keeps a unique key.
        this.templates.set(this.templates.has(id) ? `${id}-${this.templates.size}` : id, template);
      } catch (err) {
        this.loadErrors.push({ file, error: err instanceof Error ? err.message : String(err) });
      }
    }
  }

  private toTemplate(file: TemplateFile, definition: WorkflowDefinition, id: string): WorkflowTemplate {
    const tags = definition.metadata?.tags ?? [];
    const industry: Industry = file.industry && INDUSTRIES.includes(file.industry) ? file.industry : deriveIndustry(tags);
    const category: TemplateCategory =
      file.category && CATEGORIES.includes(file.category) ? file.category : deriveCategory(tags);
    return {
      id,
      name: file.name,
      description: file.description,
      industry,
      category,
      featured: file.featured ?? false,
      icon: file.icon ?? INDUSTRY_ICON[industry],
      use_cases: file.use_cases ?? [],
      node_count: definition.nodes.length,
      agents: agentsOf(definition),
      tags,
      definition,
    };
  }

  /** Gallery listing with optional filters; featured templates sorted first. */
  list(filters: TemplateFilters = {}): TemplateSummary[] {
    const search = filters.search?.trim().toLowerCase();
    const result: TemplateSummary[] = [];
    for (const template of this.templates.values()) {
      if (filters.industry && filters.industry !== 'all' && template.industry !== filters.industry) continue;
      if (filters.category && filters.category !== 'all' && template.category !== filters.category) continue;
      if (filters.featuredOnly && !template.featured) continue;
      if (search) {
        const haystack = [
          template.id,
          template.name,
          template.description,
          ...template.tags,
          ...template.use_cases,
        ]
          .join(' ')
          .toLowerCase();
        if (!haystack.includes(search)) continue;
      }
      const { definition: _definition, ...summary } = template;
      result.push(summary);
    }
    return result.sort((a, b) => {
      if (a.featured !== b.featured) return a.featured ? -1 : 1;
      return a.name.localeCompare(b.name);
    });
  }

  /** Full template (definition included) by id. */
  get(id: string): WorkflowTemplate | undefined {
    return this.templates.get(id);
  }

  /**
   * Prepare a template for creation: deep-copies the definition and overrides
   * the workflow name/description (metadata included) with the user's choices.
   * Returns undefined for unknown ids.
   */
  instantiate(id: string, options: InstantiateOptions = {}): Omit<WorkflowTemplate, 'id' | 'featured'> | undefined {
    const template = this.templates.get(id);
    if (!template) return undefined;
    const definition = structuredClone(template.definition) as WorkflowDefinition;
    const name = options.name?.trim() || template.name;
    const description = options.description?.trim() || template.description;
    definition.metadata = {
      ...definition.metadata,
      name,
      description,
      tags: [...(definition.metadata?.tags ?? [])],
    };
    const { id: _id, featured: _featured, ...rest } = template;
    return { ...rest, name, description, definition };
  }

  /** Number of successfully loaded templates. */
  get size(): number {
    return this.templates.size;
  }

  /** Templates directory actually in use (useful for diagnostics). */
  get dir(): string {
    return this.templatesDir;
  }

  /** Files skipped during load, with the reason — empty when all loaded. */
  getLoadErrors(): readonly TemplateLoadError[] {
    return this.loadErrors;
  }
}

/**
 * Cron trigger handler — schedules periodic workflow executions (§8.1).
 */

import cron from 'node-cron';
import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';

const logger = createLogger({ name: 'loop:triggers:cron', component: 'triggers' });

interface ScheduledJob {
  triggerId: string;
  task: cron.ScheduledTask;
}

/** Runs the execution created by a cron tick (bug 14: records alone were never executed). */
export type CronDispatcher = (params: {
  executionId: string;
  workflowId: string;
  payload: Record<string, unknown>;
}) => Promise<void>;

export class CronTriggerHandler {
  private jobs = new Map<string, ScheduledJob>();

  constructor(
    private store: StateStore,
    private dispatcher?: CronDispatcher,
  ) {}

  /** Initialise — load all enabled cron triggers and register them. */
  async initialise(): Promise<void> {
    const triggers = await this.store.triggers.listEnabled();
    let loadErrors = 0;
    for (const trigger of triggers) {
      if (trigger.trigger_type !== 'cron') continue;
      try {
        this.register(trigger.id, trigger.workflow_id, trigger.config as { expression: string; timezone?: string });
      } catch (err) {
        // One polluted row (e.g. an invalid expression) must not take the
        // whole server down in a restart loop (M6) — skip and log it.
        loadErrors++;
        logger.error({ triggerId: trigger.id, error: String(err) }, 'Skipping invalid cron trigger');
      }
    }
    logger.info({ count: this.jobs.size, skipped: loadErrors }, 'Cron triggers registered');
  }

  /** Register a cron trigger. */
  register(triggerId: string, workflowId: string, config: { expression: string; timezone?: string }): void {
    // Unregister if already exists
    this.unregister(triggerId);

    if (!cron.validate(config.expression)) {
      throw new Error(`Invalid cron expression: ${config.expression}`);
    }

    const task = cron.schedule(config.expression, async () => {
      // Read the current workflow version at fire time (not registration time)
      // so that updated workflows execute their latest definition.
      let workflowVersion = 1;
      try {
        const workflow = await this.store.workflows.getById(workflowId);
        if (workflow) {
          // An archived workflow must not keep producing executions —
          // deletion only flips status, so the guard has to live at fire
          // time (registered schedules outlive the DELETE call).
          if (workflow.status === 'archived') {
            logger.warn({ triggerId, workflowId }, 'Cron trigger skipped: workflow is archived');
            return;
          }
          workflowVersion = workflow.version;
        }
      } catch {
        logger.warn({ workflowId }, 'Failed to read workflow version, defaulting to 1');
      }
      const executionId = randomUUID();
      const payload = { scheduled_at: new Date().toISOString() };
      await this.store.executions.create({
        id: executionId,
        workflow_id: workflowId,
        workflow_version: workflowVersion,
        trigger_type: 'cron',
        trigger_payload: payload,
      });
      logger.info({ triggerId, executionId, workflowVersion }, 'Cron trigger fired');

      // Actually run the workflow — creating the record alone leaves it
      // pending forever (bug 14). Settle to failed if dispatch cannot start.
      if (this.dispatcher) {
        try {
          await this.dispatcher({ executionId, workflowId, payload });
        } catch (err) {
          await this.store.executions
            .updateStatus(executionId, {
              status: 'failed',
              error: `Cron dispatch failed: ${String(err)}`,
              completed_at: new Date().toISOString(),
            })
            .catch(() => {});
          logger.error({ triggerId, executionId, error: String(err) }, 'Cron dispatch failed');
        }
      }
    }, {
      timezone: config.timezone ?? 'UTC',
      scheduled: true,
    });

    this.jobs.set(triggerId, { triggerId, task });
  }

  /** Unregister a cron trigger. */
  unregister(triggerId: string): void {
    const job = this.jobs.get(triggerId);
    if (job) {
      job.task.stop();
      this.jobs.delete(triggerId);
    }
  }

  /** Stop all scheduled jobs. */
  shutdown(): void {
    for (const job of this.jobs.values()) {
      job.task.stop();
    }
    this.jobs.clear();
  }
}

/**
 * Trigger dispatcher — matches incoming events to registered triggers and
 * creates workflow executions (§6.1 steps 1–3).
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import { metricsRegistry } from '@loop/observability';
import type { StateStore } from '@loop/state';

const logger = createLogger({ name: 'loop:triggers:dispatcher', component: 'triggers' });
const metrics = metricsRegistry();

export interface TriggerEvent {
  source: string;
  event_type: string;
  payload: Record<string, unknown>;
}

export class TriggerDispatcher {
  constructor(private store: StateStore) {}

  /** Match an event against all enabled triggers and create executions. */
  async dispatch(event: TriggerEvent): Promise<string[]> {
    const triggers = await this.store.triggers.listEnabled();
    const executionIds: string[] = [];

    for (const trigger of triggers) {
      const config = trigger.config as Record<string, unknown>;

      let matches = false;
      switch (trigger.trigger_type) {
        case 'event':
          matches = config['source'] === event.source && config['event_type'] === event.event_type;
          break;
        case 'webhook':
        case 'cron':
        case 'manual':
          // These are triggered through dedicated handlers, not event matching
          break;
      }

      if (matches) {
        const executionId = randomUUID();
        // Snapshot the workflow's current version at trigger time (M5 parity
        // with the cron/webhook paths) — a hardcoded 1 resolved stale
        // definitions during replay.
        let workflowVersion = 1;
        try {
          const workflow = await this.store.workflows.getById(trigger.workflow_id);
          if (workflow) workflowVersion = workflow.version;
        } catch {
          logger.warn({ workflowId: trigger.workflow_id }, 'Failed to read workflow version, defaulting to 1');
        }
        await this.store.executions.create({
          id: executionId,
          workflow_id: trigger.workflow_id,
          workflow_version: workflowVersion,
          trigger_type: 'event',
          trigger_payload: event.payload,
        });
        executionIds.push(executionId);
        metrics.triggerFiresTotal.inc({ trigger_type: trigger.trigger_type, workflow_id: trigger.workflow_id });
        logger.info({ triggerId: trigger.id, executionId }, 'Trigger matched — execution created');
      }
    }

    return executionIds;
  }
}

/**
 * Event trigger handler — listens for ODW agent events (§9.1–9.3).
 */

import { createLogger } from '@loop/observability';
import { TriggerDispatcher, type TriggerEvent } from './dispatcher.js';

const logger = createLogger({ name: 'loop:triggers:event', component: 'triggers' });

export class EventTriggerHandler {
  constructor(private dispatcher: TriggerDispatcher) {}

  /** Receive an event from an ODW agent and dispatch to matching triggers. */
  async receive(event: TriggerEvent): Promise<string[]> {
    logger.info({ source: event.source, event_type: event.event_type }, 'Event received');
    return this.dispatcher.dispatch(event);
  }
}

/**
 * Manual trigger handler — creates an execution from an API call (§5.3 POST /execute).
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';

const logger = createLogger({ name: 'loop:triggers:manual', component: 'triggers' });

export class ManualTriggerHandler {
  constructor(private store: StateStore) {}

  /** Create a manual execution for a workflow. */
  async trigger(workflowId: string, payload: Record<string, unknown>, userId: string): Promise<string> {
    const executionId = randomUUID();
    // Snapshot the workflow's current version so replay resolves the same
    // definition that actually runs (a hardcoded 1 resolved stale versions).
    let workflowVersion = 1;
    try {
      const workflow = await this.store.workflows.getById(workflowId);
      if (workflow) workflowVersion = workflow.version;
    } catch {
      logger.warn({ workflowId }, 'Failed to read workflow version, defaulting to 1');
    }
    await this.store.executions.create({
      id: executionId,
      workflow_id: workflowId,
      workflow_version: workflowVersion,
      trigger_type: 'manual',
      trigger_payload: payload,
      initiated_by: userId,
    });
    logger.info({ workflowId, executionId, userId }, 'Manual trigger fired');
    return executionId;
  }
}

/**
 * Webhook trigger handler — HMAC-SHA256 signature verification + replay protection (§11.6).
 */

import { createHmac, timingSafeEqual } from 'node:crypto';
import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { StateStore } from '@loop/state';
import { AuthenticationError, NotFoundError } from '@loop/types';

const logger = createLogger({ name: 'loop:triggers:webhook', component: 'triggers' });

/** Rate-limit tracking per webhook trigger. */
const rateLimitBuckets = new Map<string, number[]>();
const RATE_LIMIT_WINDOW_MS = 60_000;
const RATE_LIMIT_MAX = 60;

export class WebhookTriggerHandler {
  constructor(private store: StateStore) {}

  /** Process an incoming webhook. */
  async handle(params: {
    triggerId: string;
    signature: string | null;
    body: unknown;
    rawBody: string;
  }): Promise<{ execution_id: string; workflow_id: string }> {
    // Find the trigger. Disabled triggers report the same 404 as missing ones
    // so unauthenticated callers cannot enumerate valid trigger ids.
    const trigger = await this.store.triggers.getById(params.triggerId);
    if (!trigger || !trigger.enabled) throw new NotFoundError('trigger', params.triggerId);

    const config = trigger.config as { secret?: string };

    // Verify HMAC signature. Mandatory when the trigger has a secret —
    // omitting the header must not bypass verification (tsd §11.6).
    // Triggers without a secret accept unsigned events.
    if (config.secret) {
      if (!params.signature) {
        throw new AuthenticationError('AUTH_INVALID_TOKEN', 'Missing webhook signature');
      }
      const expected = Buffer.from(
        `sha256=${createHmac('sha256', config.secret).update(params.rawBody).digest('hex')}`,
      );
      const provided = Buffer.from(params.signature);
      if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
        throw new AuthenticationError('AUTH_INVALID_TOKEN', 'Invalid webhook signature');
      }
    }

    // Rate limit check
    if (!this.checkRateLimit(params.triggerId)) {
      throw new AuthenticationError('RATE_LIMIT_EXCEEDED', 'Rate limit exceeded (60 events/min)');
    }

    // Create execution
    const executionId = randomUUID();
    // Snapshot the workflow's current version so replay resolves the same
    // definition that actually runs.
    let workflowVersion = 1;
    try {
      const workflow = await this.store.workflows.getById(trigger.workflow_id);
      if (workflow) {
        // Archived workflows must not be triggerable — report the same 404
        // as a disabled trigger so callers cannot probe workflow state.
        if (workflow.status === 'archived') {
          logger.warn({ triggerId: params.triggerId, workflowId: trigger.workflow_id }, 'Webhook trigger skipped: workflow is archived');
          throw new NotFoundError('trigger', params.triggerId);
        }
        workflowVersion = workflow.version;
      }
    } catch (err) {
      if (err instanceof NotFoundError) throw err;
      logger.warn({ workflowId: trigger.workflow_id }, 'Failed to read workflow version, defaulting to 1');
    }
    await this.store.executions.create({
      id: executionId,
      workflow_id: trigger.workflow_id,
      workflow_version: workflowVersion,
      trigger_type: 'webhook',
      trigger_payload: params.body as Record<string, unknown>,
    });

    logger.info({ triggerId: params.triggerId, executionId }, 'Webhook trigger fired');
    return { execution_id: executionId, workflow_id: trigger.workflow_id };
  }

  private checkRateLimit(triggerId: string): boolean {
    const now = Date.now();
    // Long-lived map hygiene: drop fully-expired buckets once the map grows,
    // so deleted triggers do not leak entries forever.
    if (rateLimitBuckets.size > 1_000) {
      for (const [id, times] of rateLimitBuckets) {
        if (times.every((t) => now - t >= RATE_LIMIT_WINDOW_MS)) rateLimitBuckets.delete(id);
      }
    }
    const bucket = rateLimitBuckets.get(triggerId) ?? [];
    const recent = bucket.filter((t) => now - t < RATE_LIMIT_WINDOW_MS);
    if (recent.length >= RATE_LIMIT_MAX) {
      rateLimitBuckets.set(triggerId, recent);
      return false;
    }
    recent.push(now);
    rateLimitBuckets.set(triggerId, recent);
    return true;
  }
}

import type { ZodTypeAny } from 'zod';

/** A registered semantic type. */
export interface TypeRegistration {
  name: string;
  schema: ZodTypeAny;
  description?: string;
}

/**
 * Type registry — central catalogue of semantic types used for port compatibility.
 * Connectors register their custom types here so the authoring UI and engine can
 * validate source→target compatibility at edge creation time.
 */
export class TypeRegistry {
  private types = new Map<string, TypeRegistration>();

  register(reg: TypeRegistration): void {
    this.types.set(reg.name, reg);
  }

  get(name: string): TypeRegistration | undefined {
    return this.types.get(name);
  }

  list(): TypeRegistration[] {
    return [...this.types.values()];
  }

  has(name: string): boolean {
    return this.types.has(name);
  }

  /** Check whether a source output type is compatible with a target input type. */
  isCompatible(sourceType: string, targetType: string): boolean {
    if (sourceType === targetType) return true;
    if (targetType === 'any' || sourceType === 'any') return true;
    // Numeric coercion: number accepts integer and visa-versa
    const numeric = new Set(['number', 'integer', 'float']);
    if (numeric.has(sourceType) && numeric.has(targetType)) return true;
    return false;
  }
}

/** Singleton registry shared across the process. */
export const typeRegistry = new TypeRegistry();

