/**
 * Git operations via isomorphic-git (§7.4 — versioning service).
 *
 * Uses a bare git repository on disk to store workflow definition history.
 * Each workflow update creates a commit with the definition as the commit body.
 */

import git from 'isomorphic-git';
import fs from 'node:fs';
import path from 'node:path';
import { createLogger } from '@loop/observability';

const logger = createLogger({ name: 'loop:versioning:git', component: 'versioning' });

export interface GitBackendOptions {
  /** Path to the bare git repository on disk. */
  repoPath: string;
}

export class GitBackend {
  private repoPath: string;

  constructor(opts: GitBackendOptions) {
    this.repoPath = opts.repoPath;
  }

  /** Initialise the bare repository if it doesn't exist yet. */
  async initialise(): Promise<void> {
    if (!fs.existsSync(this.repoPath)) {
      fs.mkdirSync(this.repoPath, { recursive: true });
    }
    const gitDir = path.join(this.repoPath, '.git');
    if (!fs.existsSync(gitDir)) {
      await git.init({ fs, dir: this.repoPath });
      logger.info({ repoPath: this.repoPath }, 'Git repository initialised');
    }
  }

  /** Commit a workflow definition snapshot. */
  async commit(params: {
    workflow_id: string;
    version: number;
    definition: string;
    author: string;
    message: string;
  }): Promise<string> {
    // Defense-in-depth (A4): the filename is derived from workflow_id and is
    // only ever a server-generated UUID today, but this is a public method —
    // reject anything that could escape the repo path.
    if (!/^[0-9a-fA-F-]{1,64}$/.test(params.workflow_id)) {
      throw new Error(`Invalid workflow_id for git commit: ${params.workflow_id}`);
    }
    const filePath = path.join(this.repoPath, `${params.workflow_id}.json`);
    fs.writeFileSync(filePath, params.definition, 'utf8');

    await git.add({ fs, dir: this.repoPath, filepath: `${params.workflow_id}.json` });

    const sha = await git.commit({
      fs,
      dir: this.repoPath,
      message: params.message,
      author: {
        name: params.author,
        email: `${params.author}@loop.internal`,
      },
    });

    logger.info(
      { workflow_id: params.workflow_id, version: params.version, sha: sha.slice(0, 12) },
      'Git commit created',
    );
    return sha;
  }

  /** List commits for a specific workflow. */
  async log(workflow_id: string): Promise<Array<{ sha: string; message: string; timestamp: number }>> {
    try {
      const commits = await git.log({
        fs,
        dir: this.repoPath,
        filepath: `${workflow_id}.json`,
      });
      return commits.map((c) => ({
        sha: c.oid,
        message: c.commit.message,
        timestamp: c.commit.author.timestamp,
      }));
    } catch {
      return [];
    }
  }

  /** Read the definition at a specific commit. */
  async readAtCommit(workflow_id: string, sha: string): Promise<string | null> {
    try {
      const { blob } = await git.readBlob({
        fs,
        dir: this.repoPath,
        oid: sha,
        filepath: `${workflow_id}.json`,
      });
      return Buffer.from(blob).toString('utf8');
    } catch {
      return null;
    }
  }
}

/**
 * Versioning service — wraps git backend + state store to provide version
 * management for workflow definitions.
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { WorkflowDefinition } from '@loop/types';
import type { StateStore } from '@loop/state';
import { GitBackend } from './git.js';
import { diffDefinitions } from './diff.js';

const logger = createLogger({ name: 'loop:versioning', component: 'versioning' });

export class VersioningService {
  constructor(
    private store: StateStore,
    private git: GitBackend,
  ) {}

  /** Create a new version snapshot for a workflow. */
  async createVersion(params: {
    workflow_id: string;
    version: number;
    definition: WorkflowDefinition;
    created_by: string;
    change_summary?: string;
  }): Promise<{ id: string; commit_hash: string }> {
    // Commit to git
    const commit_hash = await this.git.commit({
      workflow_id: params.workflow_id,
      version: params.version,
      definition: JSON.stringify(params.definition, null, 2),
      author: params.created_by,
      message: params.change_summary ?? `Version ${params.version}`,
    });

    // Store the versioned snapshot
    const id = randomUUID();
    await this.store.workflowDefinitions.create({
      id,
      workflow_id: params.workflow_id,
      version: params.version,
      definition: params.definition,
      commit_hash,
      created_by: params.created_by,
      change_summary: params.change_summary,
    });

    logger.info(
      { workflow_id: params.workflow_id, version: params.version, commit_hash: commit_hash.slice(0, 12) },
      'Version created',
    );

    return { id, commit_hash };
  }

  /** List all versions for a workflow. */
  async listVersions(workflow_id: string) {
    return this.store.workflowDefinitions.listByWorkflow(workflow_id);
  }

  /** Get a specific version. */
  async getVersion(workflow_id: string, version: number) {
    return this.store.workflowDefinitions.getByWorkflowAndVersion(workflow_id, version);
  }

  /** Generate a diff between two versions. */
  async diff(workflow_id: string, fromVersion: number, toVersion: number) {
    const from = await this.getVersion(workflow_id, fromVersion);
    const to = await this.getVersion(workflow_id, toVersion);
    if (!from || !to) return null;
    return diffDefinitions(from.definition, to.definition);
  }
}

/**
 * Workflow authoring service — CRUD + validation + versioning.
 */

import { randomUUID } from 'node:crypto';
import { createLogger } from '@loop/observability';
import type { Workflow, WorkflowDefinition } from '@loop/types';
import { NotFoundError, ValidationError } from '@loop/types';
import type { StateStore } from '@loop/state';
import type { VersioningService } from '@loop/versioning';
import { validateWorkflow } from './validator.js';

const logger = createLogger({ name: 'loop:workflow-authoring', component: 'workflow-authoring' });

export class WorkflowAuthoringService {
  constructor(
    private store: StateStore,
    private versioning: VersioningService,
  ) {}

  /** Create a new workflow. */
  async create(params: {
    name: string;
    description?: string;
    definition: WorkflowDefinition;
    tags?: string[];
    created_by: string;
  }): Promise<Workflow> {
    // Validate topology
    const validation = validateWorkflow(params.definition);
    if (!validation.valid) {
      throw new ValidationError('Invalid workflow topology', validation.errors);
    }

    const id = randomUUID();
    const workflow = await this.store.workflows.create({
      id,
      name: params.name,
      description: params.description ?? '',
      definition: params.definition,
      created_by: params.created_by,
      tags: params.tags,
    });

    // Create initial version snapshot
    await this.versioning.createVersion({
      workflow_id: id,
      version: 1,
      definition: params.definition,
      created_by: params.created_by,
      change_summary: 'Initial version',
    });

    logger.info({ workflow_id: id, name: params.name }, 'Workflow created');
    return workflow;
  }

  /** Get a workflow by ID. */
  async getById(id: string): Promise<Workflow> {
    const workflow = await this.store.workflows.getById(id);
    if (!workflow) throw new NotFoundError('workflow', id);
    return workflow;
  }

  /** List workflows with filtering and pagination. */
  async list(filter: { status?: 'draft' | 'active' | 'archived'; tag?: string; search?: string; sort?: string }, page = 1, per_page = 20) {
    return this.store.workflows.list(filter, { page, per_page });
  }

  /** Update a workflow (creates a new version). */
  async update(
    id: string,
    params: {
      name?: string;
      description?: string;
      definition?: WorkflowDefinition;
      status?: 'draft' | 'active' | 'archived';
      tags?: string[];
      updated_by: string;
    },
  ): Promise<Workflow> {
    await this.getById(id);

    // Validate new definition if provided
    if (params.definition) {
      const validation = validateWorkflow(params.definition);
      if (!validation.valid) {
        throw new ValidationError('Invalid workflow topology', validation.errors);
      }
    }

    const updated = await this.store.workflows.update(id, params);

    // Create version snapshot if definition changed
    if (params.definition) {
      await this.versioning.createVersion({
        workflow_id: id,
        version: updated.version,
        definition: params.definition,
        created_by: params.updated_by,
        change_summary: `Updated by ${params.updated_by}`,
      });
    }

    logger.info({ workflow_id: id, version: updated.version }, 'Workflow updated');
    return updated;
  }

  /** Soft-delete (archive) a workflow. */
  async archive(id: string): Promise<void> {
    await this.getById(id); // ensure it exists
    await this.store.workflows.archive(id);
    logger.info({ workflow_id: id }, 'Workflow archived');
  }

  /** Validate a workflow definition without saving. */
  async validate(definition: WorkflowDefinition) {
    return validateWorkflow(definition);
  }

  /** Get version history for a workflow. */
  async getVersions(workflowId: string) {
    return this.versioning.listVersions(workflowId);
  }

  /** Restore a previous version (creates a new version from the historical definition). */
  async restoreVersion(workflowId: string, version: number, restored_by: string): Promise<Workflow> {
    const historical = await this.versioning.getVersion(workflowId, version);
    if (!historical) throw new NotFoundError('workflow_version', `${workflowId}@${version}`);

    return this.update(workflowId, {
      definition: historical.definition,
      updated_by: restored_by,
    });
  }
}

/**
 * Graph operations for workflow topology validation.
 */

import type { WorkflowNode, WorkflowEdge } from '@loop/types';

/** Detect cycles using DFS. Returns true if the graph has a cycle. */
export function detectCycle(nodes: WorkflowNode[], edges: WorkflowEdge[]): boolean {
  const adj = buildAdjacency(nodes, edges);
  const visited = new Set<string>();
  const stack = new Set<string>();

  function dfs(nodeId: string): boolean {
    if (stack.has(nodeId)) return true; // cycle
    if (visited.has(nodeId)) return false;
    visited.add(nodeId);
    stack.add(nodeId);
    for (const neighbor of adj.get(nodeId) ?? []) {
      if (dfs(neighbor)) return true;
    }
    stack.delete(nodeId);
    return false;
  }

  for (const node of nodes) {
    if (dfs(node.id)) return true;
  }
  return false;
}

/** Check if all nodes are reachable from the first node (or any start node). */
export function isReachable(nodes: WorkflowNode[], edges: WorkflowEdge[]): boolean {
  if (nodes.length === 0) return true;

  const adj = buildAdjacency(nodes, edges);
  const visited = new Set<string>();

  // Start from nodes with in-degree 0 (no incoming edges)
  const inDegree = new Map<string, number>();
  for (const node of nodes) inDegree.set(node.id, 0);
  for (const edge of edges) {
    inDegree.set(edge.target, (inDegree.get(edge.target) ?? 0) + 1);
  }
  const startNodes = nodes.filter((n) => (inDegree.get(n.id) ?? 0) === 0);

  // If no start nodes (all have incoming edges), that's a cycle
  if (startNodes.length === 0) return false;

  // BFS from all start nodes
  const queue = [...startNodes.map((n) => n.id)];
  while (queue.length > 0) {
    const current = queue.shift()!;
    if (visited.has(current)) continue;
    visited.add(current);
    for (const neighbor of adj.get(current) ?? []) {
      if (!visited.has(neighbor)) queue.push(neighbor);
    }
  }

  return visited.size === nodes.length;
}

/** Topological ordering via Kahn's algorithm. */
export function topologicalOrder(nodes: WorkflowNode[], edges: WorkflowEdge[]): string[] {
  const inDegree = new Map<string, number>();
  const adj = new Map<string, string[]>();

  for (const node of nodes) {
    inDegree.set(node.id, 0);
    adj.set(node.id, []);
  }

  for (const edge of edges) {
    adj.get(edge.source)?.push(edge.target);
    inDegree.set(edge.target, (inDegree.get(edge.target) ?? 0) + 1);
  }

  const queue: string[] = [];
  for (const [nodeId, degree] of inDegree) {
    if (degree === 0) queue.push(nodeId);
  }

  const sorted: string[] = [];
  while (queue.length > 0) {
    const current = queue.shift()!;
    sorted.push(current);
    for (const neighbor of adj.get(current) ?? []) {
      const newDegree = (inDegree.get(neighbor) ?? 1) - 1;
      inDegree.set(neighbor, newDegree);
      if (newDegree === 0) queue.push(neighbor);
    }
  }

  if (sorted.length !== nodes.length) {
    throw new Error('Circular dependency detected');
  }
  return sorted;
}

function buildAdjacency(nodes: WorkflowNode[], edges: WorkflowEdge[]): Map<string, string[]> {
  const adj = new Map<string, string[]>();
  for (const node of nodes) adj.set(node.id, []);
  for (const edge of edges) {
    adj.get(edge.source)?.push(edge.target);
  }
  return adj;
}

/**
 * Workflow topology validation — implements the 6 rules from TSD §6.6.
 */

import type { WorkflowDefinition } from '@loop/types';
import { detectCycle, isReachable } from './topology.js';

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export function validateWorkflow(definition: WorkflowDefinition): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];
  const { nodes, edges } = definition;

  if (nodes.length === 0) {
    // Empty workflow is technically valid but worth a warning
    warnings.push('Workflow has no nodes');
    return { valid: true, errors, warnings };
  }

  // Rule 1: No orphan nodes — every node must be reachable from a start node
  if (!isReachable(nodes, edges)) {
    errors.push('Orphan nodes detected: not all nodes are reachable from a start node');
  }

  // Rule 2: No cycles — DAG must be acyclic
  if (detectCycle(nodes, edges)) {
    errors.push('Circular dependency detected: workflow graph must be a DAG');
  }

  // Rule 3: Port compatibility — edges should have compatible types
  const nodeMap = new Map(nodes.map((n) => [n.id, n]));
  for (const edge of edges) {
    if (!nodeMap.has(edge.source)) {
      errors.push(`Edge '${edge.id}' references unknown source node '${edge.source}'`);
    }
    if (!nodeMap.has(edge.target)) {
      errors.push(`Edge '${edge.id}' references unknown target node '${edge.target}'`);
    }
    if (edge.type_compatibility === false) {
      errors.push(`Edge '${edge.id}' has incompatible port types`);
    }
  }

  // Rule 4: Required config — nodes with config schemas should have required fields
  // (This would require connector-specific config schemas; for now we skip deep validation)

  // Rule 5: Variable references — check {{variable}} syntax
  for (const node of nodes) {
    const configStr = JSON.stringify(node.config);
    const varRefs = configStr.match(/\{\{([^}]+)\}\}/g);
    if (varRefs) {
      for (const ref of varRefs) {
        const varName = ref.slice(2, -2).trim();
        // Valid patterns: trigger.payload.*, node_N.output.*, or workflow variables
        if (!varName.startsWith('trigger.') && !varName.match(/^node_\w+\.output\./) && !definition.variables[varName]) {
          warnings.push(`Node '${node.id}': variable reference '${varName}' may not resolve`);
        }
      }
    }
  }

  // Rule 6: Trigger exists — active workflows need at least one trigger
  // (This is checked at the service level, not here, since triggers are separate entities)

  // Additional checks
  const nodeIds = new Set(nodes.map((n) => n.id));
  const duplicateIds = nodes.length - nodeIds.size;
  if (duplicateIds > 0) {
    errors.push(`${duplicateIds} duplicate node ID(s) detected`);
  }

  // Nodes with no outgoing edges (except if they're the only node)
  if (nodes.length > 1) {
    const nodesWithOutgoing = new Set(edges.map((e) => e.source));
    const terminalNodes = nodes.filter((n) => !nodesWithOutgoing.has(n.id));
    if (terminalNodes.length > 0) {
      for (const tn of terminalNodes) {
        warnings.push(`Node '${tn.id}' has no outgoing edges`);
      }
    }
  }

  return { valid: errors.length === 0, errors, warnings };
}

