/**
 * E2E — Crash recovery resumes from the last successful node (V1.1 M1, F1/F2).
 *
 * Scenario:
 *   1. Create a 3-node linear workflow (recap → vault → desk) and an execution.
 *   2. Simulate a crash mid-way: the execution is left `running` with only the
 *      first node `succeeded` (as if the process died before node 2 ran).
 *   3. Run recovery → the execution is reset to `pending` and an
 *      `execution_recovered` event is appended.
 *   4. Re-execute → the engine resumes from the breakpoint: the succeeded node
 *      is SKIPPED (its connector is NOT re-invoked) and only the remaining
 *      nodes run, with downstream interpolation reusing the cached output.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  createTestContext,
  createNode,
  createEdge,
  type TestContext,
} from './helpers';
import type { WorkflowDefinition } from '../../packages/types/src';

function crashRecoveryDefinition(): WorkflowDefinition {
  return {
    version: '1.0',
    nodes: [
      createNode('node_1', 'recap.get_meeting', { id: 'm1' }),
      createNode('node_2', 'vault.create_document', {
        title: 'Meeting summary',
        content: '{{node_1.output.summary}}',
      }),
      createNode('node_3', 'desk.send_response', {
        id: 'conv-1',
        content: '{{node_1.output.summary}}',
      }),
    ],
    edges: [createEdge('node_1', 'node_2'), createEdge('node_2', 'node_3')],
    variables: {},
    metadata: { name: 'crash-recovery', description: 'Resume from breakpoint' },
  };
}

describe('Crash recovery — resume from last successful node (E2E)', () => {
  let ctx: TestContext;

  beforeEach(async () => {
    ctx = await createTestContext();
  });

  afterEach(async () => {
    await ctx.close();
  });

  it('resumes an interrupted execution and only dispatches not-yet-succeeded nodes', async () => {
    const definition = crashRecoveryDefinition();
    const workflowId = 'wf-crash-recovery';
    await ctx.store.workflows.create({
      id: workflowId,
      name: 'Crash recovery',
      description: '',
      definition,
      created_by: 'system',
      tags: ['e2e'],
    });

    const executionId = 'exec-crash-1';
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: workflowId,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });

    // ── Simulate a crash mid-way ──────────────────────────────────────────
    // The execution was running and node_1 had succeeded before the process died.
    await ctx.store.executions.updateStatus(executionId, {
      status: 'running',
      started_at: new Date().toISOString(),
    });
    const node1ExecId = 'ne-node-1';
    await ctx.store.nodeExecutions.create({
      id: node1ExecId,
      execution_id: executionId,
      node_id: 'node_1',
      node_type: 'recap.get_meeting',
      input: { id: 'm1' },
      idempotency_key: `${executionId}:node_1`,
    });
    await ctx.store.nodeExecutions.updateStatus(node1ExecId, {
      status: 'succeeded',
      started_at: new Date().toISOString(),
      completed_at: new Date().toISOString(),
      output: { id: 'm1', summary: 'Discuss Q3 budget' },
    });

    // ── Recovery: reset to pending + record event ─────────────────────────
    const result = await ctx.recovery.recover();
    expect(result.recovered).toBe(1);

    const recoveredExec = await ctx.store.executions.getById(executionId);
    expect(recoveredExec?.status).toBe('pending');

    const recoveredEvents = await ctx.store.events.listByExecution(executionId);
    expect(
      recoveredEvents.some((e) => e.event_type === 'execution_recovered'),
    ).toBe(true);

    // ── Re-execute: resume from the breakpoint ────────────────────────────
    await ctx.executor.execute(executionId, definition, {});

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');

    // The succeeded node's connector (recap) was NOT re-invoked; only the
    // not-yet-succeeded nodes (vault, desk) were dispatched exactly once.
    expect(ctx.mocks.recap.calls).toHaveLength(0);
    expect(ctx.mocks.vault.calls).toHaveLength(1);
    expect(ctx.mocks.desk.calls).toHaveLength(1);

    // Downstream interpolation reused the cached node_1 output (resume basis).
    expect(ctx.mocks.vault.calls[0]!.input).toMatchObject({ content: 'Discuss Q3 budget' });
    expect(ctx.mocks.desk.calls[0]!.input).toMatchObject({ content: 'Discuss Q3 budget' });

    // The idempotency key was forwarded to the dispatched connectors.
    expect(ctx.mocks.vault.calls[0]!.idempotencyKey).toBe(`${executionId}:node_2`);
    expect(ctx.mocks.desk.calls[0]!.idempotencyKey).toBe(`${executionId}:node_3`);

    // A node_skipped event was recorded for the resumed node.
    const events = await ctx.store.events.listByExecution(executionId);
    const skipped = events.filter((e) => e.event_type === 'node_skipped');
    expect(skipped).toHaveLength(1);
    expect(skipped[0]!.node_id).toBe('node_1');

    // All three nodes are represented as succeeded in node_executions.
    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    const byNode = new Map(nodes.map((n) => [n.node_id, n.status]));
    expect(byNode.get('node_1')).toBe('succeeded');
    expect(byNode.get('node_2')).toBe('succeeded');
    expect(byNode.get('node_3')).toBe('succeeded');
  });

  it('a fresh execution (no crash) dispatches every node exactly once', async () => {
    const definition = crashRecoveryDefinition();
    const workflowId = 'wf-fresh';
    await ctx.store.workflows.create({
      id: workflowId,
      name: 'Fresh run',
      description: '',
      definition,
      created_by: 'system',
    });
    const executionId = 'exec-fresh-1';
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: workflowId,
      workflow_version: 1,
      trigger_type: 'manual',
    });

    await ctx.executor.execute(executionId, definition, {});

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');
    expect(ctx.mocks.recap.calls).toHaveLength(1);
    expect(ctx.mocks.vault.calls).toHaveLength(1);
    expect(ctx.mocks.desk.calls).toHaveLength(1);
  });
});

/**
 * E2E — Egress policy enforcement.
 *
 * Verifies that the EgressEngine + EgressInterceptor combination correctly
 * enforces domain-level policies. The interceptor is wired into a workflow's
 * connector call path; the test asserts:
 *
 *   1. With no policies, default-deny blocks external calls.
 *   2. Adding an allow rule for a specific domain permits that domain.
 *   3. Other domains remain blocked.
 *   4. Priority ordering is respected (higher priority wins).
 *   5. Policy cache invalidation reflects live DB changes.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createTestContext, type TestContext } from './helpers';
import { EgressInterceptor } from '../../packages/egress/src/interceptor';

describe('Egress policy enforcement (E2E)', () => {
  let ctx: TestContext;

  beforeEach(async () => {
    ctx = await createTestContext();
  });

  afterEach(async () => {
    await ctx.close();
  });

  it('denies all external calls by default when no policies exist', async () => {
    const decision = await ctx.egressEngine.evaluate('https://api.openai.com/v1/chat');
    expect(decision.allowed).toBe(false);
    expect(decision.reason).toMatch(/No matching allow policy/);
  });

  it('blocks external API call with a deny-all policy', async () => {
    await ctx.store.egressPolicies.create({
      id: 'deny-all',
      name: 'Deny all',
      rule_type: 'deny',
      target_type: 'domain',
      target_value: '*.openai.com',
      priority: 100,
    });
    ctx.egressEngine.invalidateCache();

    const decision = await ctx.egressEngine.evaluate('https://api.openai.com/v1/chat');
    expect(decision.allowed).toBe(false);
    expect(decision.matched_policy).toBe('deny-all');
  });

  it('allows calls to a specific domain after adding an allow rule', async () => {
    // Start with deny-all for openai
    await ctx.store.egressPolicies.create({
      id: 'deny-openai',
      name: 'Deny OpenAI',
      rule_type: 'deny',
      target_type: 'domain',
      target_value: '*.openai.com',
      priority: 100,
    });

    // Add a higher-priority allow rule for a sub-domain
    await ctx.store.egressPolicies.create({
      id: 'allow-platform',
      name: 'Allow platform.openai.com',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'platform.openai.com',
      priority: 200,
    });
    ctx.egressEngine.invalidateCache();

    const allowed = await ctx.egressEngine.evaluate('https://platform.openai.com/v1/chat');
    expect(allowed.allowed).toBe(true);
    expect(allowed.matched_policy).toBe('allow-platform');

    // But api.openai.com is still blocked
    const blocked = await ctx.egressEngine.evaluate('https://api.openai.com/v1/chat');
    expect(blocked.allowed).toBe(false);
  });

  it('respects priority ordering: higher priority wins', async () => {
    await ctx.store.egressPolicies.create({
      id: 'low-deny',
      name: 'Low deny',
      rule_type: 'deny',
      target_type: 'domain',
      target_value: '*.example.com',
      priority: 100,
    });
    await ctx.store.egressPolicies.create({
      id: 'high-allow',
      name: 'High allow',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: '*.example.com',
      priority: 500,
    });
    ctx.egressEngine.invalidateCache();

    const decision = await ctx.egressEngine.evaluate('https://api.example.com/test');
    expect(decision.allowed).toBe(true);
    expect(decision.matched_policy).toBe('high-allow');
  });

  it('invalidating the cache reflects live DB changes', async () => {
    // Initially no allow → blocked
    const before = await ctx.egressEngine.evaluate('https://allowed.example.com');
    expect(before.allowed).toBe(false);

    // Insert allow policy
    await ctx.store.egressPolicies.create({
      id: 'allow-example',
      name: 'Allow example',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'allowed.example.com',
      priority: 100,
    });
    // Without invalidation, cache still denies (within TTL)
    const cached = await ctx.egressEngine.evaluate('https://allowed.example.com');
    expect(cached.allowed).toBe(false);

    // After invalidation
    ctx.egressEngine.invalidateCache();
    const after = await ctx.egressEngine.evaluate('https://allowed.example.com');
    expect(after.allowed).toBe(true);
    expect(after.matched_policy).toBe('allow-example');
  });

  it('EgressInterceptor throws LoopError when egress is blocked', async () => {
    // No allow policies → default deny
    const interceptor = new EgressInterceptor(ctx.egressEngine);

    await expect(
      interceptor.request('https://blocked.example.com/data'),
    ).rejects.toThrow(/Egress blocked/);
  });

  it('EgressInterceptor succeeds when an allow policy exists', async () => {
    // Allow the domain
    await ctx.store.egressPolicies.create({
      id: 'allow-test',
      name: 'Allow test',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'api.allowed.test',
      priority: 100,
    });
    ctx.egressEngine.invalidateCache();

    // We can't easily test a real HTTP call without starting a server.
    // Instead, we verify the engine's decision (the interceptor only proceeds
    // when decision.allowed === true; it then calls undici which may fail
    // for network reasons — we only test the policy decision here).
    const decision = await ctx.egressEngine.evaluate('https://api.allowed.test/data');
    expect(decision.allowed).toBe(true);
  });
});

