/**
 * E2E — Execution recovery after node failure (Scale-tier simulation).
 *
 * Simulates the failure scenario:
 *   1. Start a workflow execution.
 *   2. Some nodes succeed; then the process "crashes" (simulated by leaving
 *      the execution in `running` status with partial node outputs).
 *   3. Build a fresh app (simulating restart).
 *   4. Verify that ExecutionRecovery.recover() processes the interrupted execution:
 *      - If no nodes had succeeded: marks as `failed` (non-recoverable).
 *      - If at least one node had succeeded: resets the execution to `pending`
 *        (a re-runnable state) so the scheduler re-queues it from the last
 *        successful node on the next execution cycle.
 */

import { describe, it, expect, afterEach } from 'vitest';
import {
  createTestContext,
  createNode,
  createEdge,
  type TestContext,
} from './helpers';
import { ExecutionRecovery } from '../../packages/engine/src/recovery';
import { createSqliteConnection, SqliteStateStore } from '../../packages/state/src';

describe('Failover / execution recovery (E2E)', () => {
  let ctx: TestContext;

  afterEach(async () => {
    if (ctx) await ctx.close();
  });

  it('marks execution as failed on restart when no nodes had completed', async () => {
    ctx = await createTestContext();

    // Simulate a workflow that started but crashed before any node completed
    await ctx.store.workflows.create({
      id: 'wf-failover-1',
      name: 'Failover test 1',
      description: '',
      definition: {
        version: '1.0',
        nodes: [createNode('node_1', 'vault.create_document'), createNode('node_2', 'desk.create_task')],
        edges: [createEdge('node_1', 'node_2')],
        variables: {},
        metadata: { name: 'failover-1' },
      },
      created_by: 'system',
    });

    // Simulate partial execution: execution is 'running', one node was created
    // but never completed (status 'pending').
    const executionId = 'exec-crash-1';
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: 'wf-failover-1',
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.updateStatus(executionId, {
      status: 'running',
      started_at: new Date().toISOString(),
    });
    await ctx.store.nodeExecutions.create({
      id: 'node-exec-1',
      execution_id: executionId,
      node_id: 'node_1',
      node_type: 'vault.create_document',
    });
    // Node is still pending (never transitioned to succeeded)

    // Simulate restart — run recovery
    const result = await ctx.recovery.recover();
    expect(result.failed).toBe(1);
    expect(result.recovered).toBe(0);

    // The execution should now be marked as failed
    const final = await ctx.store.executions.getById(executionId);
    expect(final?.status).toBe('failed');
    expect(final?.error).toMatch(/Interrupted by system restart/);
  });

  it('re-queues recoverable execution (reset to pending) on restart when nodes had succeeded', async () => {
    ctx = await createTestContext();

    await ctx.store.workflows.create({
      id: 'wf-failover-2',
      name: 'Failover test 2',
      description: '',
      definition: {
        version: '1.0',
        nodes: [
          createNode('node_1', 'vault.create_document'),
          createNode('node_2', 'desk.create_task'),
          createNode('node_3', 'recap.summarize'),
        ],
        edges: [createEdge('node_1', 'node_2'), createEdge('node_2', 'node_3')],
        variables: {},
        metadata: { name: 'failover-2' },
      },
      created_by: 'system',
    });

    // Simulate a workflow that crashed after node_1 succeeded
    const executionId = 'exec-crash-2';
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: 'wf-failover-2',
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.updateStatus(executionId, {
      status: 'running',
      started_at: new Date().toISOString(),
    });

    // Node 1 succeeded
    await ctx.store.nodeExecutions.create({
      id: 'node-exec-2a',
      execution_id: executionId,
      node_id: 'node_1',
      node_type: 'vault.create_document',
    });
    await ctx.store.nodeExecutions.updateStatus('node-exec-2a', {
      status: 'succeeded',
      started_at: new Date().toISOString(),
      completed_at: new Date().toISOString(),
      output: { document_id: 'doc-1' },
    });

    // Node 2 was started but not finished
    await ctx.store.nodeExecutions.create({
      id: 'node-exec-2b',
      execution_id: executionId,
      node_id: 'node_2',
      node_type: 'desk.create_task',
    });
    await ctx.store.nodeExecutions.updateStatus('node-exec-2b', {
      status: 'running',
      started_at: new Date().toISOString(),
    });

    // Node 3 was never started
    await ctx.store.nodeExecutions.create({
      id: 'node-exec-2c',
      execution_id: executionId,
      node_id: 'node_3',
      node_type: 'recap.summarize',
    });

    const result = await ctx.recovery.recover();
    expect(result.recovered).toBe(1);
    expect(result.failed).toBe(0);

    // Corrected behaviour: a recoverable execution (at least one node had
    // succeeded) is reset to 'pending' — a re-runnable state — so the scheduler
    // re-queues it from the last successful node on the next execution cycle.
    const final = await ctx.store.executions.getById(executionId);
    expect(final?.status).toBe('pending');
  });

  it('handles multiple interrupted executions in one recovery pass', async () => {
    ctx = await createTestContext();

    // Execution A: no nodes completed → failed
    await ctx.store.workflows.create({
      id: 'wf-multi-a',
      name: 'Multi A',
      description: '',
      definition: {
        version: '1.0',
        nodes: [createNode('node_1', 'vault.create_document')],
        edges: [],
        variables: {},
        metadata: { name: 'multi-a' },
      },
      created_by: 'system',
    });
    await ctx.store.executions.create({
      id: 'exec-multi-a',
      workflow_id: 'wf-multi-a',
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.updateStatus('exec-multi-a', {
      status: 'running',
      started_at: new Date().toISOString(),
    });

    // Execution B: node succeeded → recoverable
    await ctx.store.workflows.create({
      id: 'wf-multi-b',
      name: 'Multi B',
      description: '',
      definition: {
        version: '1.0',
        nodes: [createNode('node_1', 'vault.create_document'), createNode('node_2', 'desk.create_task')],
        edges: [createEdge('node_1', 'node_2')],
        variables: {},
        metadata: { name: 'multi-b' },
      },
      created_by: 'system',
    });
    await ctx.store.executions.create({
      id: 'exec-multi-b',
      workflow_id: 'wf-multi-b',
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.updateStatus('exec-multi-b', {
      status: 'running',
      started_at: new Date().toISOString(),
    });
    await ctx.store.nodeExecutions.create({
      id: 'node-exec-b1',
      execution_id: 'exec-multi-b',
      node_id: 'node_1',
      node_type: 'vault.create_document',
    });
    await ctx.store.nodeExecutions.updateStatus('node-exec-b1', {
      status: 'succeeded',
      started_at: new Date().toISOString(),
      completed_at: new Date().toISOString(),
      output: { document_id: 'doc-b' },
    });

    const result = await ctx.recovery.recover();
    expect(result.failed).toBe(1);
    expect(result.recovered).toBe(1);

    const finalA = await ctx.store.executions.getById('exec-multi-a');
    expect(finalA?.status).toBe('failed');

    // Execution B had a succeeded node → recoverable → reset to 'pending'.
    const finalB = await ctx.store.executions.getById('exec-multi-b');
    expect(finalB?.status).toBe('pending');
  });

  it('recovery is idempotent: running it twice has no additional effect', async () => {
    ctx = await createTestContext();

    await ctx.store.workflows.create({
      id: 'wf-idempotent',
      name: 'Idempotent',
      description: '',
      definition: {
        version: '1.0',
        nodes: [createNode('node_1', 'vault.create_document')],
        edges: [],
        variables: {},
        metadata: { name: 'idempotent' },
      },
      created_by: 'system',
    });

    await ctx.store.executions.create({
      id: 'exec-idempotent',
      workflow_id: 'wf-idempotent',
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.updateStatus('exec-idempotent', {
      status: 'running',
      started_at: new Date().toISOString(),
    });

    const first = await ctx.recovery.recover();
    expect(first.failed).toBe(1);

    // Second run: no more interrupted executions
    const second = await ctx.recovery.recover();
    expect(second.failed).toBe(0);
    expect(second.recovered).toBe(0);
  });

  it('new app startup runs recovery automatically', async () => {
    // Create a "persistent" store via a file-backed SQLite so the second
    // buildApp invocation sees the interrupted execution.
    ctx = await createTestContext();

    await ctx.store.workflows.create({
      id: 'wf-auto-recover',
      name: 'Auto recover',
      description: '',
      definition: {
        version: '1.0',
        nodes: [createNode('node_1', 'vault.create_document')],
        edges: [],
        variables: {},
        metadata: { name: 'auto-recover' },
      },
      created_by: 'system',
    });

    await ctx.store.executions.create({
      id: 'exec-auto-recover',
      workflow_id: 'wf-auto-recover',
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.updateStatus('exec-auto-recover', {
      status: 'running',
      started_at: new Date().toISOString(),
    });

    // Close the first context. Recovery is tested via direct invocation since
    // buildApp also opens a git repo which requires filesystem state that is
    // not shared between contexts.
    const recovery = new ExecutionRecovery(ctx.store);
    const result = await recovery.recover();
    expect(result.failed).toBe(1);
  });
});

/**
 * Shared helpers for E2E tests.
 *
 * The production `buildApp()` wires everything together but doesn't expose the
 * services. For realistic end-to-end scenarios — where workflows must actually
 * execute against mock connectors — we build the services directly so the test
 * has full control over the mocks and can invoke the executor.
 */

import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createSqliteConnection, SqliteStateStore } from '../../packages/state/src';
import type { StateStore } from '../../packages/state/src';
import {
  ConnectorRegistry,
  type ConnectorAdapter,
  type ExecuteParams,
  type ExecuteResult,
} from '../../packages/connectors/src';
import type { ConnectorCapabilities } from '../../packages/types';
import { ExecutionExecutor } from '../../packages/engine/src/executor';
import { ExecutionRecovery } from '../../packages/engine/src/recovery';
import { EgressEngine } from '../../packages/egress/src/engine';
import type { WorkflowDefinition, WorkflowNode, WorkflowEdge } from '../../packages/types';

// ─── Mock connector adapter ──────────────────────────────────────────────────

export interface MockAdapter extends ConnectorAdapter {
  readonly type: string;
  calls: ExecuteParams[];
  response: Record<string, unknown>;
  setError(err: Error): void;
  clearError(): void;
  reset(): void;
}

export function createMockAdapter(type: string, defaultResponse: Record<string, unknown> = {}): MockAdapter {
  let response = defaultResponse;
  let error: Error | null = null;
  const calls: ExecuteParams[] = [];

  const adapter: MockAdapter = {
    type,
    calls,
    get response() {
      return response;
    },
    set response(r) {
      response = r;
    },
    setError(err: Error) {
      error = err;
    },
    clearError() {
      error = null;
    },
    reset() {
      calls.length = 0;
      error = null;
    },
    async execute(params: ExecuteParams): Promise<ExecuteResult> {
      calls.push(params);
      if (error) throw error;
      return { output: { ...response } };
    },
    async healthCheck() {
      return error === null;
    },
    getCapabilities(): ConnectorCapabilities {
      return {
        node_types: [`${type}.op`],
        input_types: ['any'],
        output_types: ['any'],
      };
    },
  };

  return adapter;
}

// ─── Test context ────────────────────────────────────────────────────────────

export interface TestContext {
  dataDir: string;
  store: StateStore;
  connectors: ConnectorRegistry;
  executor: ExecutionExecutor;
  recovery: ExecutionRecovery;
  egressEngine: EgressEngine;
  mocks: {
    vault: MockAdapter;
    desk: MockAdapter;
    recap: MockAdapter;
    generic: MockAdapter;
  };
  close(): Promise<void>;
}

export async function createTestContext(): Promise<TestContext> {
  const dataDir = mkdtempSync(path.join(tmpdir(), 'loop-e2e-'));

  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  const store = new SqliteStateStore(conn);
  await store.initialise();

  // Seed a "system" user that workflows reference via created_by / updated_by.
  // The workflows table has FK constraints to the users table.
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: '',
    email: 'system@loop.internal',
    role: 'admin',
    display_name: 'System',
  });

  const vault = createMockAdapter('vault', { uploaded: 1, failed: [], filename: 'meeting-summary.md' });
  const desk = createMockAdapter('desk', { sent: true });
  const recap = createMockAdapter('recap', {
    id: 'm1',
    title: 'Standup',
    summary: 'Meeting summary',
    action_items: ['Follow up on budget'],
  });
  const generic = createMockAdapter('generic', { ok: true });

  const connectors = new ConnectorRegistry();
  connectors.registerAdapter(vault);
  connectors.registerAdapter(desk);
  connectors.registerAdapter(recap);
  connectors.registerAdapter(generic);

  const executor = new ExecutionExecutor(store, connectors, 5);
  const recovery = new ExecutionRecovery(store);
  const egressEngine = new EgressEngine(() => store.egressPolicies.listEnabled());

  return {
    dataDir,
    store,
    connectors,
    executor,
    recovery,
    egressEngine,
    mocks: { vault, desk, recap, generic },
    async close() {
      conn.close();
      try {
        rmSync(dataDir, { recursive: true, force: true });
      } catch {
        // ignore
      }
    },
  };
}

// ─── Factories ───────────────────────────────────────────────────────────────

export function createNode(id: string, type: string, config: Record<string, unknown> = {}): WorkflowNode {
  return { id, type, position: { x: 0, y: 0 }, config };
}

export function createEdge(source: string, target: string): WorkflowEdge {
  return {
    id: `${source}->${target}`,
    source,
    target,
    source_port: 'output',
    target_port: 'input',
    type_compatibility: true,
  };
}

/**
 * Meeting → KB + Support E2E scenario workflow definition.
 *
 * Reads a meeting from Recap, stores its summary in Vault, and posts the
 * summary as a customer-support response via Desk — using the real V1.0
 * connector node types (INTEGRATION_CONTRACT.md §4.3).
 */
export function meetingToTasksDefinition(): WorkflowDefinition {
  return {
    version: '1.0',
    nodes: [
      createNode('node_1', 'recap.get_meeting', {
        id: '{{trigger.payload.meeting_id}}',
      }),
      createNode('node_2', 'vault.create_document', {
        title: 'Meeting summary',
        content: '{{node_1.output.summary}}',
      }),
      createNode('node_3', 'desk.send_response', {
        id: '{{trigger.payload.conversation_id}}',
        agent_id: 'agent-loop',
        content: '{{node_1.output.summary}}',
      }),
    ],
    edges: [createEdge('node_1', 'node_2'), createEdge('node_1', 'node_3')],
    variables: {},
    metadata: { name: 'meeting-to-tasks', description: 'E2E scenario' },
  };
}

/** Poll execution until it leaves pending/running, up to a timeout. */
export async function waitForExecution(
  store: StateStore,
  executionId: string,
  timeoutMs = 5000,
): Promise<{ status: string; error?: string | null }> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const execution = await store.executions.getById(executionId);
    if (!execution) throw new Error(`Execution ${executionId} not found`);
    if (execution.status !== 'pending' && execution.status !== 'running') {
      return { status: execution.status, error: execution.error ?? null };
    }
    await new Promise((r) => setTimeout(r, 20));
  }
  throw new Error(`Timed out waiting for execution ${executionId}`);
}

/**
 * E2E — Meeting → Tasks → KB scenario.
 *
 * Deploys Loop with mocked Vault / Desk / Recap connectors, creates a workflow
 * that extracts a summary from a meeting transcript (Recap), creates a follow-up
 * task in Desk, and stores the summary in Vault. Then triggers execution and
 * verifies the connectors were invoked as expected.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  createTestContext,
  meetingToTasksDefinition,
  waitForExecution,
  type TestContext,
} from './helpers';

describe('Meeting → Tasks → KB (E2E)', () => {
  let ctx: TestContext;

  beforeEach(async () => {
    ctx = await createTestContext();
  });

  afterEach(async () => {
    await ctx.close();
  });

  it('deploys Loop, configures connectors, creates workflow, triggers via webhook, and completes', async () => {
    // 1. Register connector instances with config (mimicking what an admin would do)
    ctx.connectors.registerInstance('recap-prod', 'recap', { base_url: 'https://recap.mock' });
    ctx.connectors.registerInstance('desk-prod', 'desk', { base_url: 'https://desk.mock' });
    ctx.connectors.registerInstance('vault-prod', 'vault', { base_url: 'https://vault.mock' });

    // 2. Create the workflow definition
    const definition = meetingToTasksDefinition();
    const workflowId = 'wf-meeting-tasks';
    await ctx.store.workflows.create({
      id: workflowId,
      name: 'Meeting → Tasks → KB',
      description: 'Extract action items from meeting transcript',
      definition,
      created_by: 'system',
      tags: ['e2e'],
    });

    // 3. Create a webhook trigger bound to this workflow
    const triggerId = 'trig-meeting';
    await ctx.store.triggers.create({
      id: triggerId,
      workflow_id: workflowId,
      trigger_type: 'webhook',
      config: { secret: 'test-webhook-secret' },
    });

    // 4. Trigger via manual (simulating what the webhook handler does on receipt)
    //    The webhook trigger handler in this repo creates an execution record.
    //    Since the executor is not yet wired to auto-run from triggers, we drive
    //    execution directly to demonstrate the full pipeline.
    const executionId = 'exec-meeting-1';
    const triggerPayload = {
      meeting_id: 'm1',
      conversation_id: 'conv-42',
    };
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: workflowId,
      workflow_version: 1,
      trigger_type: 'webhook',
      trigger_payload: triggerPayload,
      initiated_by: 'webhook',
    });

    // 5. Execute the workflow (this is what the engine queue would do)
    await ctx.executor.execute(executionId, definition, triggerPayload);

    // 6. Verify final execution status
    const final = await waitForExecution(ctx.store, executionId);
    expect(final.status).toBe('succeeded');
    expect(final.error).toBeNull();

    // 7. Verify all three connector calls happened
    expect(ctx.mocks.recap.calls).toHaveLength(1);
    expect(ctx.mocks.recap.calls[0]?.operation).toBe('get_meeting');
    expect(ctx.mocks.desk.calls).toHaveLength(1);
    expect(ctx.mocks.desk.calls[0]?.operation).toBe('send_response');
    expect(ctx.mocks.vault.calls).toHaveLength(1);
    expect(ctx.mocks.vault.calls[0]?.operation).toBe('create_document');

    // 8. Verify node execution records show outputs stored
    const nodeExecs = await ctx.store.nodeExecutions.listByExecution(executionId);
    expect(nodeExecs).toHaveLength(3);
    const succeeded = nodeExecs.filter((n) => n.status === 'succeeded');
    expect(succeeded).toHaveLength(3);

    // 9. Verify variable interpolation — Vault and Desk received the meeting
    //    summary (the template `{{node_1.output.summary}}` was resolved to the
    //    string returned by the Recap mock).
    const vaultCall = ctx.mocks.vault.calls[0];
    expect(vaultCall?.input['content']).toBe('Meeting summary');
    expect(vaultCall?.input['title']).toBe('Meeting summary');
    const deskCall = ctx.mocks.desk.calls[0];
    expect(deskCall?.input['content']).toBe('Meeting summary');
    expect(deskCall?.input['id']).toBe('conv-42');
  });

  it('fails the execution when a connector returns an error', async () => {
    // Force Recap to fail
    ctx.mocks.recap.setError(new Error('Recap service unavailable'));

    const definition = meetingToTasksDefinition();
    const workflowId = 'wf-meeting-fail';
    await ctx.store.workflows.create({
      id: workflowId,
      name: 'Failing meeting flow',
      description: '',
      definition,
      created_by: 'system',
    });

    const executionId = 'exec-fail-1';
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: workflowId,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: { transcript: 'test' },
    });

    // Executor rethrows; completeExecution marks it failed first
    await expect(
      ctx.executor.execute(executionId, definition, { transcript: 'test' }),
    ).rejects.toThrow(/Recap service unavailable/);

    const final = await ctx.store.executions.getById(executionId);
    expect(final?.status).toBe('failed');
    expect(final?.error).toMatch(/Recap service unavailable/);

    // Desk and Vault should NOT have been called (Recap failed before them)
    expect(ctx.mocks.desk.calls).toHaveLength(0);
    expect(ctx.mocks.vault.calls).toHaveLength(0);
  });
});

/**
 * E2E — RBAC enforcement.
 *
 * The Loop StateStore supports read/write/admin roles on users. Auth middleware
 * for the HTTP layer is planned but not yet wired in. This test therefore
 * exercises RBAC at the data layer: it verifies that the role model is
 * enforced when code paths honour it, and documents where enforcement is
 * expected but not yet implemented (HTTP middleware).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createTestContext, type TestContext } from './helpers';

/**
 * Simulates an authorisation check that the HTTP middleware would perform.
 * Returns true if the role is allowed to perform the action, false otherwise.
 */
function isAllowed(role: string, action: 'create_workflow' | 'manage_secrets' | 'view_only'): boolean {
  const permissions: Record<string, string[]> = {
    admin: ['create_workflow', 'manage_secrets', 'view_only'],
    write: ['create_workflow', 'view_only'],
    read: ['view_only'],
  };
  return permissions[role]?.includes(action) ?? false;
}

describe('RBAC enforcement (E2E)', () => {
  let ctx: TestContext;

  beforeEach(async () => {
    ctx = await createTestContext();
  });

  afterEach(async () => {
    await ctx.close();
  });

  it('creates users with read, write, and admin roles', async () => {
    const reader = await ctx.store.users.create({
      id: 'user-reader',
      username: 'reader',
      password_hash: 'hashed',
      email: 'reader@loop.test',
      role: 'read',
      display_name: 'Read Only',
    });
    expect(reader.role).toBe('read');

    const writer = await ctx.store.users.create({
      id: 'user-writer',
      username: 'writer',
      password_hash: 'hashed',
      email: 'writer@loop.test',
      role: 'write',
      display_name: 'Writer',
    });
    expect(writer.role).toBe('write');

    const admin = await ctx.store.users.create({
      id: 'user-admin',
      username: 'admin',
      password_hash: 'hashed',
      email: 'admin@loop.test',
      role: 'admin',
      display_name: 'Admin',
    });
    expect(admin.role).toBe('admin');

    const list = await ctx.store.users.list();
    // 3 created + 1 seeded 'system' user from helpers
    expect(list).toHaveLength(4);
  });

  it('read user cannot create workflows (403 semantics)', () => {
    // When HTTP middleware is wired, POST /api/v1/workflows for a read user
    // returns 403 FORBIDDEN_INSUFFICIENT_ROLE. We verify the semantic here.
    expect(isAllowed('read', 'create_workflow')).toBe(false);
  });

  it('write user cannot manage secrets (403 semantics)', () => {
    expect(isAllowed('write', 'manage_secrets')).toBe(false);
  });

  it('admin can do everything', () => {
    expect(isAllowed('admin', 'create_workflow')).toBe(true);
    expect(isAllowed('admin', 'manage_secrets')).toBe(true);
    expect(isAllowed('admin', 'view_only')).toBe(true);
  });

  it('supports role promotion from read → admin', async () => {
    await ctx.store.users.create({
      id: 'user-promote',
      username: 'promote',
      password_hash: 'hashed',
      email: 'promote@loop.test',
      role: 'read',
      display_name: 'Promote Me',
    });

    // Initially read-only
    const before = await ctx.store.users.getById('user-promote');
    expect(before?.role).toBe('read');
    expect(isAllowed(before!.role, 'create_workflow')).toBe(false);

    // Promote to admin
    await ctx.store.users.updateRole('user-promote', 'admin');

    const after = await ctx.store.users.getById('user-promote');
    expect(after?.role).toBe('admin');
    expect(isAllowed(after!.role, 'create_workflow')).toBe(true);
    expect(isAllowed(after!.role, 'manage_secrets')).toBe(true);
  });

  it('deactivated users are flagged inactive', async () => {
    await ctx.store.users.create({
      id: 'user-deact',
      username: 'deact',
      password_hash: 'hashed',
      email: 'deact@loop.test',
      role: 'write',
      display_name: 'Deactivate Me',
    });

    await ctx.store.users.deactivate('user-deact');

    const user = await ctx.store.users.getById('user-deact');
    expect(user?.is_active).toBe(false);
  });
});

/**
 * V1.6 M1 (F-1, DB2): test store lifecycle helpers.
 *
 * better-sqlite3's native handle segfaults non-deterministically during
 * process teardown when it is reclaimed by GC instead of explicitly closed.
 * `withTestStore` guarantees the connection is closed when the test body
 * finishes (success OR failure), and a module-level registry lets the global
 * vitest setup (`tests/setup.ts`) mop up anything a test leaked.
 */

import {
  createSqliteConnection,
  SqliteStateStore,
  type SqliteConnection,
} from '../../packages/state/src/index.js';

export interface TestStore {
  conn: SqliteConnection;
  store: SqliteStateStore;
}

/** Connections handed out by the helpers below and not yet closed. */
const trackedConnections = new Set<SqliteConnection>();

/**
 * Create an initialised in-memory SQLite store, run `fn` with it, and
 * GUARANTEE the connection is closed afterwards — even when `fn` throws.
 * Prefer this over hand-rolled createStore/afterEach pairs in new tests.
 */
export async function withTestStore<T>(fn: (ctx: TestStore) => Promise<T>): Promise<T> {
  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  trackedConnections.add(conn);
  const store = new SqliteStateStore(conn);
  try {
    await store.initialise();
    return await fn({ conn, store });
  } finally {
    trackedConnections.delete(conn);
    try {
      conn.close();
    } catch {
      // best-effort — the registry/exit hook (DB3) is the second line of defence.
    }
  }
}

/**
 * `withTestStore` variant that also seeds the `system` user most suites need
 * (workflow rows carry a `created_by` FK into users).
 */
export async function withSeededTestStore<T>(fn: (ctx: TestStore) => Promise<T>): Promise<T> {
  return withTestStore(async (ctx) => {
    await ctx.store.users.create({
      id: 'system',
      username: 'system',
      password_hash: '',
      email: 'system@loop.internal',
      role: 'admin',
      display_name: 'System',
    });
    return fn(ctx);
  });
}

/**
 * Register a connection created outside `withTestStore` for safety-net
 * teardown. Returns the connection unchanged for inline use:
 * `conn = trackConnection(createSqliteConnection({...}))`.
 */
export function trackConnection(conn: SqliteConnection): SqliteConnection {
  trackedConnections.add(conn);
  return conn;
}

/** Stop tracking a connection (e.g. after the test closed it explicitly). */
export function untrackConnection(conn: SqliteConnection): void {
  trackedConnections.delete(conn);
}

/**
 * Best-effort close of every still-tracked connection. Called by the global
 * vitest setup after each test as a safety net for leaked handles.
 */
export function closeTrackedConnections(): void {
  for (const conn of trackedConnections) {
    try {
      conn.close();
    } catch {
      // best-effort
    }
  }
  trackedConnections.clear();
}

/** Number of connections still tracked as open (diagnostics / tests). */
export function trackedConnectionCount(): number {
  return trackedConnections.size;
}

