/**
 * Build a test Fastify app backed by an in-memory SQLite database and a
 * temp-directory git repo for versioning. Seeds a system user with role 'admin'
 * so workflow foreign keys resolve and workflow authoring has a valid creator.
 */
export async function buildTestApp(configOverrides: Partial<LoopConfig> = {}): Promise<TestApp> {
  const tmpDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'loop-test-'));
  const dbPath = path.join(tmpDataDir, 'test.db');

  const config: LoopConfig = {
    LOOP_PORT: 0,
    LOOP_HOST: '127.0.0.1',
    LOOP_LOG_LEVEL: 'error',
    LOOP_ENV: 'test',
    LOOP_DATA_DIR: tmpDataDir,
    LOOP_ENCRYPTION_KEY: 'test-key-change-me-please-32chars!',
    LOOP_DB_TYPE: 'sqlite',
    LOOP_DB_PATH: dbPath,
    LOOP_DB_SSL: false,
    LOOP_MAX_CONCURRENT: 10,
    LOOP_EXECUTION_TIMEOUT_MS: 5_000,
    LOOP_NODE_TIMEOUT_MS: 1_000,
    LOOP_EVENT_OUTPUT_MAX_BYTES: 65_536,
    LOOP_DEFAULT_RETRY_COUNT: 0,
    LOOP_DEFAULT_BACKOFF: 'fixed',
    LOOP_SANDBOX_TYPE: 'gvisor',
    LOOP_SANDBOX_URL: 'http://localhost:4000',
    LOOP_SANDBOX_MEMORY_MB: 256,
    LOOP_SANDBOX_CPU_SECONDS: 30,
    LOOP_SANDBOX_POOL_SIZE: 1,
    LOOP_LLM_PRIMARY: 'ollama',
    LOOP_LLM_OLLAMA_URL: 'http://localhost:11434',
    LOOP_LLM_FALLBACK_CHAIN: 'ollama',
    LOOP_LLM_TIMEOUT_MS: 2_000,
    LOOP_WORKFLOW_TIMEOUT_MS: 5_000,
    LOOP_EGRESS_UNCONFIGURED_POLICY: 'allow',
    // Integration tests target loopback mocks — mirror a self-hosted suite
    // on a trusted private network (V1.7 private-address blocklist escape).
    LOOP_EGRESS_ALLOW_PRIVATE: true,
    LOOP_JWT_SECRET: 'test-jwt-secret-for-tests-only-32ch',
    LOOP_JWT_ACCESS_TTL: '15m',
    LOOP_JWT_REFRESH_TTL: '7d',
    LOOP_REQUIRE_AUTH: false,
    LOOP_API_KEY_ROLE: 'admin',
    LOOP_EGRESS_DEFAULT_POLICY: 'deny',
    LOOP_AIRGAP_MODE: false,
    LOOP_METRICS_ENABLED: false,
    LOOP_OTEL_ENABLED: false,
    ...configOverrides,
  };

  const Fastify = (await import('fastify')).default;
  const app = Fastify({ logger: false });
  app.setErrorHandler(errorHandler);
  // Register the production raw-body parser so webhook signature tests
  // exercise the same byte-exact path as the real server (apps/api/src/raw-body.ts).
  const { attachRawBodyParser } = await import('../../../apps/api/src/raw-body.js');
  attachRawBodyParser(app);

  // ── State store ─────────────────────────────────────────────────────────
  const conn = createSqliteConnection({ path: dbPath, wal: false });
  const store = new SqliteStateStore(conn);
  await store.initialise();

  // ── Seed system user ────────────────────────────────────────────────────
  // The HTTP routes hardcode `created_by: 'system'` / `updated_by: 'system'`
  // until real auth middleware lands, so seed a user whose *id* is literally
  // 'system' so foreign-key constraints resolve.
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: 'test-hash',
    email: 'system@loop.test',
    role: 'admin',
  });

  // ── Connectors ──────────────────────────────────────────────────────────
  const connectors = new ConnectorRegistry();
  connectors.registerAdapter(new VaultAdapter());
  connectors.registerAdapter(new DeskAdapter());
  // Production parity (apps/api/src/server.ts): the fail-fast node-type
  // validation rejects templates whose adapter is unregistered, so the test
  // app must register the same adapter set as production.
  const { RecapAdapter, GenericAdapter, LlmConnectorAdapter } = await import(
    '../../../packages/connectors/src/index.js'
  );
  connectors.registerAdapter(new RecapAdapter());
  connectors.registerAdapter(new GenericAdapter());
  const llmRouterEarly = createLLMRouter(config);
  connectors.registerAdapter(new LlmConnectorAdapter(llmRouterEarly));

  // ── Versioning + authoring ──────────────────────────────────────────────
  const gitBackend = new GitBackend({ repoPath: path.join(tmpDataDir, 'git') });
  await gitBackend.initialise();
  const versioning = new VersioningService(store, gitBackend);
  const authoring = new WorkflowAuthoringService(store, versioning);

  // ── Engine ──────────────────────────────────────────────────────────────
  const executor = new ExecutionExecutor(store, connectors, 10);

  // ── Triggers ────────────────────────────────────────────────────────────
  const triggerDispatcher = new TriggerDispatcher(store);
  const cronHandler = new CronTriggerHandler(store);
  const webhookHandler = new WebhookTriggerHandler(store);
  const manualHandler = new ManualTriggerHandler(store);

  // ── Egress + secrets + LLM ─────────────────────────────────────────────
  const egressEngine = new EgressEngine(() => store.egressPolicies.listEnabled());
  const egressGate = new EgressGate(egressEngine, {
    airgap: config.LOOP_AIRGAP_MODE,
    unconfiguredPolicy: config.LOOP_EGRESS_UNCONFIGURED_POLICY ?? 'allow',
    allowPrivate: config.LOOP_EGRESS_ALLOW_PRIVATE ?? true,
  });
  const secretsManager = new SecretsManager(store, config.LOOP_ENCRYPTION_KEY);
  const llmRouter = createLLMRouter(config);

  // ── Templates ──────────────────────────────────────────────────────
  // Loads the real repo templates/ directory (resolved module-relative).
  const templates = new TemplateRegistry();

  // ── Routes ──────────────────────────────────────────────────────────────
  registerRoutes(app, {
    store,
    connectors,
    authoring,
    executor,
    triggerDispatcher,
    cronHandler,
    webhookHandler,
    manualHandler,
    egressEngine,
    egressGate,
    secretsManager,
    templates,
    llmRouter,
    config,
  });

  // Health endpoints
  app.get('/health', async () => ({ status: 'ok' }));

  return {
    app,
    store,
    conn,
    connectors,
    authoring,
    executor,
    cronHandler,
    webhookHandler,
    manualHandler,
    triggerDispatcher,
    egressEngine,
    egressGate,
    secretsManager,
    templates,
    llmRouter,
    config,
  };
}

