/**
 * Integration tests — HTTP auth guard (LOOP_REQUIRE_AUTH gate).
 *
 * Verifies the backward-compatible authentication on /api/v1/*:
 *   - LOOP_REQUIRE_AUTH unset/false → endpoints are open (no credentials needed).
 *   - LOOP_REQUIRE_AUTH=true → requests without a valid API key/JWT get 401.
 *   - A valid static API key (x-api-key or Bearer) or JWT → 200.
 *   - Public endpoints (/health) stay open even when auth is enforced.
 *   - The authenticated principal replaces the hardcoded 'system' created_by.
 */

import { describe, it, expect, afterAll } from 'vitest';
import * as jose from 'jose';
import { buildTestApp, type TestApp } from '../_helpers/app.js';

const API_KEY = 'super-secret-loop-api-key';

const VALID_DEFINITION = {
  version: '1.0',
  nodes: [],
  edges: [],
  variables: {},
  metadata: { name: 'auth-guard-wf' },
};

describe('API auth guard (LOOP_REQUIRE_AUTH)', () => {
  const contexts: TestApp[] = [];

  afterAll(async () => {
    for (const ctx of contexts) {
      await ctx.app.close();
      ctx.conn.close();
    }
  });

  async function buildApp(overrides: Parameters<typeof buildTestApp>[0] = {}): Promise<TestApp> {
    const ctx = await buildTestApp(overrides);
    await ctx.app.ready();
    contexts.push(ctx);
    return ctx;
  }

  // ── Backward compatibility: open by default ───────────────────────────────

  it('LOOP_REQUIRE_AUTH unset (default false) → /api/v1/* is open', async () => {
    const ctx = await buildApp();
    const res = await ctx.app.inject({ method: 'GET', url: '/api/v1/workflows' });
    expect(res.statusCode).toBe(200);
  });

  // ── Enforcement: 401 without credentials ──────────────────────────────────

  it('LOOP_REQUIRE_AUTH=true, no credentials → 401', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    const res = await ctx.app.inject({ method: 'GET', url: '/api/v1/workflows' });
    expect(res.statusCode).toBe(401);
    const body = res.json();
    expect(body.success).toBe(false);
    expect(body.error.code).toBe('AUTH_MISSING');
  });

  it('LOOP_REQUIRE_AUTH=true, invalid API key → 401', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    const res = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/workflows',
      headers: { 'x-api-key': 'wrong-key' },
    });
    expect(res.statusCode).toBe(401);
  });

  // ── Valid credentials: 200 ────────────────────────────────────────────────

  it('LOOP_REQUIRE_AUTH=true, valid x-api-key → 200', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    const res = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/workflows',
      headers: { 'x-api-key': API_KEY },
    });
    expect(res.statusCode).toBe(200);
  });

  it('LOOP_REQUIRE_AUTH=true, valid Bearer API key → 200', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    const res = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/workflows',
      headers: { authorization: `Bearer ${API_KEY}` },
    });
    expect(res.statusCode).toBe(200);
  });

  it('LOOP_REQUIRE_AUTH=true, valid JWT bearer → 200', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    const secret = new TextEncoder().encode(ctx.config.LOOP_JWT_SECRET);
    const token = await new jose.SignJWT({ sub: 'system', role: 'admin' })
      .setProtectedHeader({ alg: 'HS256' })
      .setExpirationTime('15m')
      .setIssuedAt()
      .sign(secret);

    const res = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/workflows',
      headers: { authorization: `Bearer ${token}` },
    });
    expect(res.statusCode).toBe(200);
  });

  // ── Public endpoints stay open ────────────────────────────────────────────

  it('LOOP_REQUIRE_AUTH=true, /health remains public → 200', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    const res = await ctx.app.inject({ method: 'GET', url: '/health' });
    expect(res.statusCode).toBe(200);
  });

  // ── Authenticated principal replaces hardcoded created_by ─────────────────

  it('JWT principal is used as created_by on workflow create', async () => {
    const ctx = await buildApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });

    const userId = crypto.randomUUID();
    await ctx.store.users.create({
      id: userId,
      username: 'author',
      password_hash: 'x',
      email: 'author@loop.test',
      role: 'admin',
    });

    const secret = new TextEncoder().encode(ctx.config.LOOP_JWT_SECRET);
    const token = await new jose.SignJWT({ sub: userId, role: 'admin' })
      .setProtectedHeader({ alg: 'HS256' })
      .setExpirationTime('15m')
      .setIssuedAt()
      .sign(secret);

    const res = await ctx.app.inject({
      method: 'POST',
      url: '/api/v1/workflows',
      headers: { authorization: `Bearer ${token}` },
      payload: { name: 'Authored Workflow', definition: VALID_DEFINITION },
    });

    expect(res.statusCode).toBe(201);
    expect(res.json().data.created_by).toBe(userId);
  });
});

/**
 * Integration tests — authentication & RBAC primitives.
 *
 * NOTE: The HTTP routes currently hardcode `created_by: 'system'` and do not
 * yet wire up JWT authentication middleware. These tests exercise the
 * underlying primitives: user store, password verification, and JWT
 * signing/verification. Once auth middleware is added to routes, these tests
 * should be promoted to HTTP-level assertions.
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import { compare, hash } from 'bcrypt';
import * as jose from 'jose';
import {
  buildTestApp,
  seedWorkflow,
  SYSTEM_USER_ID,
  type TestApp,
} from '../_helpers/app.js';

describe('Authentication & RBAC', () => {
  let ctx: TestApp;

  beforeAll(async () => {
    ctx = await buildTestApp();
    await ctx.app.ready();
  });

  afterAll(async () => {
    await ctx.app.close();
    ctx.conn.close();
  });

  // ── POST /api/v1/auth/login — token generation ────────────────────────────

  it('login returns access and refresh tokens for valid credentials', async () => {
    const password = 'correct-horse-battery-staple';
    const passwordHash = await hash(password, 10);

    await ctx.store.users.create({
      id: crypto.randomUUID(),
      username: 'alice',
      password_hash: passwordHash,
      email: 'alice@loop.test',
      role: 'write',
    });

    // Simulate login flow (routes don't yet expose POST /auth/login; this
    // exercises the primitive the route will wrap).
    const user = await ctx.store.users.getByUsername('alice');
    expect(user).not.toBeNull();
    expect(await compare(password, user!.password_hash)).toBe(true);

    // Issue JWT
    const secret = new TextEncoder().encode(ctx.config.LOOP_JWT_SECRET);
    const accessToken = await new jose.SignJWT({
      sub: user!.id,
      role: user!.role,
    })
      .setProtectedHeader({ alg: 'HS256' })
      .setExpirationTime(ctx.config.LOOP_JWT_ACCESS_TTL)
      .setIssuedAt()
      .sign(secret);

    expect(typeof accessToken).toBe('string');
    expect(accessToken.split('.')).toHaveLength(3);

    // Verify JWT
    const { payload } = await jose.jwtVerify(accessToken, secret);
    expect(payload.sub).toBe(user!.id);
    expect(payload.role).toBe('write');
  });

  it('invalid credentials do not authenticate (bcrypt returns false)', async () => {
    const passwordHash = await hash('real-password', 10);
    await ctx.store.users.create({
      id: crypto.randomUUID(),
      username: 'bob',
      password_hash: passwordHash,
      email: 'bob@loop.test',
    });

    const user = await ctx.store.users.getByUsername('bob');
    expect(user).not.toBeNull();
    expect(await compare('wrong-password', user!.password_hash)).toBe(false);
  });

  it('bearer token authorises a request (JWT verification roundtrip)', async () => {
    const secret = new TextEncoder().encode(ctx.config.LOOP_JWT_SECRET);
    const userId = crypto.randomUUID();

    const token = await new jose.SignJWT({ sub: userId, role: 'admin' })
      .setProtectedHeader({ alg: 'HS256' })
      .setExpirationTime('15m')
      .setIssuedAt()
      .sign(secret);

    const { payload } = await jose.jwtVerify(token, secret);
    expect(payload.sub).toBe(userId);
    expect(payload.role).toBe('admin');
  });

  it('invalid or expired JWT is rejected by jose.jwtVerify', async () => {
    const secret = new TextEncoder().encode(ctx.config.LOOP_JWT_SECRET);
    const wrongSecret = new TextEncoder().encode('a-different-secret-at-least-32-chars!');

    const token = await new jose.SignJWT({ sub: 'x', role: 'read' })
      .setProtectedHeader({ alg: 'HS256' })
      .setExpirationTime('15m')
      .setIssuedAt()
      .sign(wrongSecret);

    await expect(jose.jwtVerify(token, secret)).rejects.toThrow();
  });

  // ── RBAC: read role cannot create workflows ───────────────────────────────

  it('RBAC: a "read" role user should be rejected from creating workflows', async () => {
    const readUserId = crypto.randomUUID();
    await ctx.store.users.create({
      id: readUserId,
      username: 'reader',
      password_hash: await hash('reader-password', 10),
      email: 'reader@loop.test',
      role: 'read',
    });

    const user = await ctx.store.users.getByUsername('reader');
    expect(user).not.toBeNull();
    expect(user!.role).toBe('read');

    // Simulate the authorization check that RBAC middleware should perform.
    // Per TSD §11.2, 'read' users cannot mutate workflows.
    const canCreate = user!.role === 'write' || user!.role === 'admin';
    expect(canCreate).toBe(false);
  });

  it('RBAC: "write" and "admin" roles can create workflows', async () => {
    for (const role of ['write', 'admin'] as const) {
      const userId = crypto.randomUUID();
      await ctx.store.users.create({
        id: userId,
        username: `user-${role}`,
        password_hash: await hash('pw', 10),
        email: `${role}@loop.test`,
        role,
      });

      const user = await ctx.store.users.getByUsername(`user-${role}`);
      const canCreate = user!.role === 'write' || user!.role === 'admin';
      expect(canCreate).toBe(true);
    }
  });

  // ── Role escalation / deactivation ────────────────────────────────────────

  it('role can be updated via users.updateRole', async () => {
    const userId = crypto.randomUUID();
    await ctx.store.users.create({
      id: userId,
      username: 'promotable',
      password_hash: 'x',
      email: 'promotable@loop.test',
      role: 'read',
    });

    await ctx.store.users.updateRole(userId, 'admin');
    const updated = await ctx.store.users.getById(userId);
    expect(updated!.role).toBe('admin');
  });

  it('deactivated user cannot authenticate (is_active = false)', async () => {
    const userId = crypto.randomUUID();
    await ctx.store.users.create({
      id: userId,
      username: 'deactivated',
      password_hash: await hash('pw', 10),
      email: 'deactivated@loop.test',
      role: 'write',
    });

    await ctx.store.users.deactivate(userId);
    const user = await ctx.store.users.getById(userId);
    expect(user!.is_active).toBe(false);

    // Middleware should reject inactive users before token verification.
    const canLogin = user!.is_active;
    expect(canLogin).toBe(false);
  });
});

/**
 * Integration tests — execution flow via HTTP (TSD §5.4).
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import type { FastifyInstance } from 'fastify';
import type { WorkflowDefinition } from '../../../packages/types/src/index.js';
import {
  buildTestApp,
  seedWorkflow,
  SYSTEM_USER_ID,
  type TestApp,
} from '../_helpers/app.js';

/**
 * Three-node linear workflow using *stub* node types. The executor falls back
 * to returning input-as-output for nodes whose connector type is not
 * registered, so this avoids real HTTP calls to Vault/Desk adapters.
 */
const STUB_THREE_NODE: WorkflowDefinition = {
  version: '1.0',
  nodes: [
    {
      id: 'node_vault',
      type: 'stub.vault_search',
      position: { x: 0, y: 0 },
      config: { query: 'integration test' },
    },
    {
      id: 'node_transform',
      type: 'stub.transform',
      position: { x: 200, y: 0 },
      config: { mode: 'uppercase' },
    },
    {
      id: 'node_desk',
      type: 'stub.desk_task',
      position: { x: 400, y: 0 },
      config: { title: 'Final task' },
    },
  ],
  edges: [
    { id: 'e1', source: 'node_vault', target: 'node_transform' },
    { id: 'e2', source: 'node_transform', target: 'node_desk' },
  ],
  variables: {},
  metadata: { name: 'stub-e2e-workflow', tags: ['e2e'] },
};

describe('Execution API', () => {
  let ctx: TestApp;
  let app: FastifyInstance;

  beforeAll(async () => {
    ctx = await buildTestApp();
    app = ctx.app;
    await app.ready();
  });

  afterAll(async () => {
    await app.close();
    ctx.conn.close();
  });

  /**
   * Poll an execution until it reaches a terminal state (succeeded/failed/
   * cancelled). POST /execute now runs the executor asynchronously (it used to
   * leave executions stuck 'pending'), so tests must wait for the run to settle
   * rather than asserting the immediate post-trigger state.
   */
  async function waitForTerminal(executionId: string, timeoutMs = 8000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      const exec = await ctx.store.executions.getById(executionId);
      if (exec && (exec.status === 'succeeded' || exec.status === 'failed' || exec.status === 'cancelled')) {
        return exec;
      }
      await new Promise((r) => setTimeout(r, 50));
    }
    throw new Error(`Execution ${executionId} did not reach a terminal state within ${timeoutMs}ms`);
  }

  // ── POST /api/v1/workflows/:id/execute ────────────────────────────────────

  it('POST /api/v1/workflows/:id/execute triggers a manual execution (202)', async () => {
    const wf = await seedWorkflow(ctx.store);

    const res = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/execute`,
      payload: { payload: { key: 'value' } },
    });

    expect(res.statusCode).toBe(202);
    const body = res.json();
    expect(body.success).toBe(true);
    expect(body.data.execution_id).toBeDefined();
    expect(typeof body.data.execution_id).toBe('string');
    expect(body.data.status).toBe('pending');

    // The route now runs the executor asynchronously; the execution transitions
    // pending -> running -> succeeded. Wait for it to settle, then verify.
    const dbExecution = await waitForTerminal(body.data.execution_id);
    expect(dbExecution.workflow_id).toBe(wf.id);
    expect(dbExecution.trigger_type).toBe('manual');
    expect(dbExecution.status).toBe('succeeded');
    expect(dbExecution.trigger_payload).toEqual({ key: 'value' });
  });

  it('POST execute fails for unknown workflow id (FK violation)', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/v1/workflows/00000000-0000-0000-0000-999999999999/execute',
      payload: {},
    });

    // The route does not pre-validate the workflow id. SQLite rejects the
    // insert because workflow_executions.workflow_id references workflows(id),
    // resulting in an unhandled 500. A future improvement would be to
    // validate the workflow exists and return 404.
    expect(res.statusCode).toBeGreaterThanOrEqual(400);
    const body = res.json();
    expect(body.success).toBe(false);
  });

  // ── GET /api/v1/executions/:id ────────────────────────────────────────────

  it('GET /api/v1/executions/:id returns execution with node results', async () => {
    const wf = await seedWorkflow(ctx.store, { definition: STUB_THREE_NODE });

    // Trigger execution — the route runs the executor asynchronously over the
    // full 3-node workflow; wait for it to settle.
    const execRes = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/execute`,
      payload: {},
    });
    const executionId = execRes.json().data.execution_id;
    await waitForTerminal(executionId);

    const res = await app.inject({
      method: 'GET',
      url: `/api/v1/executions/${executionId}`,
    });

    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.success).toBe(true);
    expect(body.data.id).toBe(executionId);
    expect(body.data.workflow_id).toBe(wf.id);
    expect(Array.isArray(body.data.nodes)).toBe(true);
    expect(body.data.nodes).toHaveLength(3);
    expect(body.data.nodes[0].node_type).toBe('stub.vault_search');
    expect(body.data.nodes[0].status).toBe('succeeded');
  });

  // ── GET /api/v1/executions (list) ─────────────────────────────────────────

  it('GET /api/v1/executions lists executions with filter', async () => {
    const wf1 = await seedWorkflow(ctx.store, { name: 'WF-1' });
    const wf2 = await seedWorkflow(ctx.store, { name: 'WF-2' });

    // Create executions for each workflow
    await ctx.store.executions.create({
      id: crypto.randomUUID(),
      workflow_id: wf1.id,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.create({
      id: crypto.randomUUID(),
      workflow_id: wf1.id,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });
    await ctx.store.executions.create({
      id: crypto.randomUUID(),
      workflow_id: wf2.id,
      workflow_version: 1,
      trigger_type: 'cron',
      trigger_payload: {},
    });

    const res = await app.inject({
      method: 'GET',
      url: `/api/v1/executions?workflow_id=${wf1.id}`,
    });

    const body = res.json();
    expect(body.data).toHaveLength(2);
    expect(body.meta.total).toBe(2);
  });

  // ── POST /api/v1/executions/:id/cancel ────────────────────────────────────

  it('POST /api/v1/executions/:id/cancel sets status to cancelled', async () => {
    const wf = await seedWorkflow(ctx.store);
    const exec = await ctx.store.executions.create({
      id: crypto.randomUUID(),
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
    });

    const res = await app.inject({
      method: 'POST',
      url: `/api/v1/executions/${exec.id}/cancel`,
    });

    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.success).toBe(true);
    expect(body.data.status).toBe('cancelled');

    // Confirm DB state
    const updated = await ctx.store.executions.getById(exec.id);
    expect(updated!.status).toBe('cancelled');
  });

  // ── End-to-end: trigger → execute → observe ───────────────────────────────

  it('full cycle: create workflow, trigger execution, run executor, verify nodes', async () => {
    const wf = await seedWorkflow(ctx.store, { definition: STUB_THREE_NODE });

    // 1. Trigger execution — the route now runs the executor asynchronously.
    const triggerRes = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/execute`,
      payload: { payload: { input: 'data' } },
    });
    const executionId = triggerRes.json().data.execution_id;

    // 2. Wait for the asynchronous execution to complete.
    await waitForTerminal(executionId);

    // 3. Fetch execution
    const res = await app.inject({
      method: 'GET',
      url: `/api/v1/executions/${executionId}`,
    });

    const body = res.json();
    expect(body.data.status).toBe('succeeded');
    expect(body.data.nodes.length).toBe(3);

    // Verify execution order (node_executions should be in topological order)
    const nodeTypes = body.data.nodes.map((n: { node_type: string }) => n.node_type);
    expect(nodeTypes).toEqual(['stub.vault_search', 'stub.transform', 'stub.desk_task']);

    // Verify all nodes have output stored
    for (const node of body.data.nodes) {
      expect(node.status).toBe('succeeded');
      expect(node.output).toBeDefined();
    }
  });
});

/**
