  it('400s on invalid override payloads', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/v1/templates/invoice-approval/instantiate',
      payload: { name: '' },
    });
    expect(res.statusCode).toBe(400);
    expect(res.json().error.code).toBe('VALIDATION_ERROR');
  });
});

