/**
 * Integration tests — real-time execution WebSocket (V1.1 M2, W3).
 *
 * Boots the real Fastify app (in-memory SQLite) with the WS route registered,
 * connects a native WebSocket client to `GET /ws/executions/:id`, runs an
 * execution through the real executor, and asserts the client receives live
 * node-status events pushed via the engine EventBus. Also verifies the
 * LOOP_REQUIRE_AUTH gate rejects token-less upgrades.
 *
 * A single EventBus instance is shared explicitly between the executor and the
 * WS route so the test never depends on which module copy a singleton came from.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { buildTestApp, type TestApp } from '../_helpers/app.js';
import { registerExecutionWebSocket } from '../../../apps/api/src/routes/ws.js';
import { ExecutionExecutor } from '../../../packages/engine/src/index.js';
import { EventBus } from '../../../packages/engine/src/eventBus.js';
import type { WorkflowDefinition } from '../../../packages/types/src/index.js';

/** A single passing node — `transform` has no adapter, so it passes input through. */
const ONE_NODE_DEFINITION: WorkflowDefinition = {
  version: '1.0',
  nodes: [{ id: 'node_a', type: 'transform', position: { x: 0, y: 0 }, config: { value: 1 } }],
  edges: [],
  variables: {},
  metadata: { name: 'ws-test-workflow', tags: ['ws'] },
};

interface WsMessage {
  type: string;
  executionId?: string;
  nodeId?: string;
  status?: string;
  nodes?: unknown;
  [key: string]: unknown;
}

/** Open a WebSocket and resolve once it is connected. */
function connect(url: string): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    ws.onopen = () => resolve(ws);
    ws.onerror = () => reject(new Error(`WS connection error: ${url}`));
  });
}

/**
 * Collect messages until `predicate` matches one of them (or timeout).
 * Resolves with the full list gathered; rejects on timeout.
 */
function collectUntil(
  ws: WebSocket,
  predicate: (m: WsMessage) => boolean,
  timeoutMs = 8_000,
): Promise<WsMessage[]> {
  return new Promise((resolve, reject) => {
    const received: WsMessage[] = [];
    const onMessage = (ev: MessageEvent) => {
      const msg = JSON.parse(String(ev.data)) as WsMessage;
      received.push(msg);
      if (predicate(msg)) {
        cleanup();
        resolve(received);
      }
    };
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error(`Timed out waiting for WS message. Received: ${JSON.stringify(received)}`));
    }, timeoutMs);
    const cleanup = () => {
      clearTimeout(timer);
      ws.removeEventListener('message', onMessage);
    };
    ws.addEventListener('message', onMessage);
  });
}

async function seedExecution(ctx: TestApp, definition: WorkflowDefinition): Promise<string> {
  const workflowId = crypto.randomUUID();
  await ctx.store.workflows.create({
    id: workflowId,
    name: 'WS test workflow',
    description: '',
    definition,
    created_by: 'system',
  });
  const executionId = crypto.randomUUID();
  await ctx.store.executions.create({
    id: executionId,
    workflow_id: workflowId,
    workflow_version: 1,
    trigger_type: 'manual',
    trigger_payload: {},
  });
  return executionId;
}

describe('WebSocket /ws/executions/:id — live node status push', () => {
  let ctx: TestApp;
  let app: FastifyInstance;
  let baseUrl: string;
  let bus: EventBus;
  let executor: ExecutionExecutor;

  beforeAll(async () => {
    ctx = await buildTestApp();
    app = ctx.app;
    bus = new EventBus();
    executor = new ExecutionExecutor(ctx.store, ctx.connectors, 10, 1_000, 5_000, bus);
    // Register the WS route on the test app (buildTestApp wires REST only),
    // sharing the exact bus the executor publishes to.
    await registerExecutionWebSocket(app, { config: ctx.config, store: ctx.store, eventBus: bus });
    baseUrl = await app.listen({ port: 0, host: '127.0.0.1' });
  });

  afterAll(async () => {
    await app.close();
    ctx.conn.close();
  });

  it('pushes node status events to a subscribed client during execution', async () => {
    const executionId = await seedExecution(ctx, ONE_NODE_DEFINITION);
    const wsUrl = `${baseUrl.replace('http', 'ws')}/ws/executions/${executionId}`;

    const ws = await connect(wsUrl);
    try {
      // Start collecting, then drive a real execution through the executor.
      const collected = collectUntil(ws, (m) => m.type === 'node_succeeded');
      await executor.execute(executionId, ONE_NODE_DEFINITION, {});
      const messages = await collected;

      // A node_started (running) event was pushed…
      const started = messages.find((m) => m.type === 'node_started');
      expect(started).toBeDefined();
      expect(started?.executionId).toBe(executionId);
      expect(started?.nodeId).toBe('node_a');
      expect(started?.status).toBe('running');

      // …followed by a node_succeeded event for the same node.
      const succeeded = messages.find((m) => m.type === 'node_succeeded');
      expect(succeeded).toBeDefined();
      expect(succeeded?.nodeId).toBe('node_a');
      expect(succeeded?.status).toBe('succeeded');
    } finally {
      ws.close();
    }
  });

  it('sends an initial snapshot message on connect', async () => {
    const executionId = await seedExecution(ctx, ONE_NODE_DEFINITION);
    const wsUrl = `${baseUrl.replace('http', 'ws')}/ws/executions/${executionId}`;

    const ws = await connect(wsUrl);
    try {
      const messages = await collectUntil(ws, (m) => m.type === 'snapshot');
      const snapshot = messages.find((m) => m.type === 'snapshot');
      expect(snapshot?.executionId).toBe(executionId);
      expect(Array.isArray(snapshot?.nodes)).toBe(true);
    } finally {
      ws.close();
    }
  });
});

describe('WebSocket /ws/executions/:id — auth gate (LOOP_REQUIRE_AUTH)', () => {
  const API_KEY = 'ws-test-secret-key';
  let ctx: TestApp;
  let app: FastifyInstance;
  let baseUrl: string;
  let bus: EventBus;
  let executor: ExecutionExecutor;

  beforeAll(async () => {
    ctx = await buildTestApp({ LOOP_REQUIRE_AUTH: true, LOOP_API_KEY: API_KEY });
    app = ctx.app;
    bus = new EventBus();
    executor = new ExecutionExecutor(ctx.store, ctx.connectors, 10, 1_000, 5_000, bus);
    await registerExecutionWebSocket(app, { config: ctx.config, store: ctx.store, eventBus: bus });
    baseUrl = await app.listen({ port: 0, host: '127.0.0.1' });
  });

  afterAll(async () => {
    await app.close();
    ctx.conn.close();
  });

  it('rejects a token-less upgrade with close code 4401', async () => {
    const executionId = crypto.randomUUID();
    const wsUrl = `${baseUrl.replace('http', 'ws')}/ws/executions/${executionId}`;

    const closeInfo = await new Promise<{ code: number }>((resolve, reject) => {
      const ws = new WebSocket(wsUrl);
      const timer = setTimeout(() => reject(new Error('Timed out waiting for close')), 8_000);
      ws.onclose = (ev: CloseEvent) => {
        clearTimeout(timer);
        resolve({ code: ev.code });
      };
      ws.onerror = () => {
        /* the rejection surfaces via onclose */
      };
    });

    expect(closeInfo.code).toBe(4401);
  });

  it('accepts an upgrade authenticated via ?token=<api-key>', async () => {
    const executionId = await seedExecution(ctx, ONE_NODE_DEFINITION);
    const wsUrl = `${baseUrl.replace('http', 'ws')}/ws/executions/${executionId}?token=${API_KEY}`;

    const ws = await connect(wsUrl);
    try {
      const collected = collectUntil(ws, (m) => m.type === 'node_succeeded');
      await executor.execute(executionId, ONE_NODE_DEFINITION, {});
      const messages = await collected;
      expect(messages.some((m) => m.type === 'node_started')).toBe(true);
      expect(messages.some((m) => m.type === 'node_succeeded')).toBe(true);
    } finally {
      ws.close();
    }
  });
});

/**
 * Tiny in-process HTTP server used to exercise the real connector adapters
 * against a programmable upstream. Captures every request so tests can assert
 * method / URL / headers / body, and returns a programmed response.
 */

import { createServer, type Server, type IncomingMessage } from 'node:http';
import type { AddressInfo } from 'node:net';

export interface RecordedRequest {
  method: string;
  url: string;
  headers: IncomingMessage['headers'];
  body: string;
}

export interface MockResponse {
  status?: number;
  /** JSON-serialisable body (sent as application/json). */
  body?: unknown;
  /** Raw string body (takes precedence over `body`). */
  raw?: string;
  contentType?: string;
}

export interface MockServer {
  baseUrl: string;
  requests: RecordedRequest[];
  setHandler(handler: (req: RecordedRequest) => MockResponse): void;
  close(): Promise<void>;
}

export async function startMockServer(defaultResponse: MockResponse = { body: { ok: true } }): Promise<MockServer> {
  const requests: RecordedRequest[] = [];
  let handler: (req: RecordedRequest) => MockResponse = () => defaultResponse;

  const server: Server = createServer((req, res) => {
    let data = '';
    req.on('data', (chunk: Buffer) => {
      data += chunk.toString('utf8');
    });
    req.on('end', () => {
      const recorded: RecordedRequest = {
        method: req.method ?? 'GET',
        url: req.url ?? '/',
        headers: req.headers,
        body: data,
      };
      requests.push(recorded);

      const result = handler(recorded);
      const status = result.status ?? 200;
      if (result.raw !== undefined) {
        res.writeHead(status, { 'content-type': result.contentType ?? 'text/plain' });
        res.end(result.raw);
      } else {
        res.writeHead(status, { 'content-type': result.contentType ?? 'application/json' });
        res.end(JSON.stringify(result.body ?? {}));
      }
    });
  });

  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  const address = server.address() as AddressInfo;

  return {
    baseUrl: `http://127.0.0.1:${address.port}`,
    requests,
    setHandler: (h) => {
      handler = h;
    },
    close: () =>
      new Promise<void>((resolve) => {
        server.close(() => resolve());
      }),
  };
}

/**
 * Integration tests — Desk connector (real adapter against a mock upstream).
 *
 * Exercises the real DeskAdapter's operation → endpoint mapping against an
 * in-process HTTP server mimicking the Desk agent inbox API
 * (INTEGRATION_CONTRACT.md §2).
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import { DeskAdapter } from '../../../packages/connectors/src/desk/adapter.js';
import { startMockServer, type MockServer } from './_mock-server.js';

describe('Desk connector integration', () => {
  let server: MockServer;
  let adapter: DeskAdapter;
  let config: Record<string, unknown>;

  beforeAll(async () => {
    server = await startMockServer();
    adapter = new DeskAdapter();
    config = { base_url: server.baseUrl };
  });

  beforeEach(() => {
    server.requests.length = 0;
    server.setHandler(() => ({ body: { ok: true } }));
  });

  afterAll(async () => {
    await server.close();
  });

  it('list_conversations → GET /api/v1/agents/conversations', async () => {
    server.setHandler(() => ({ body: [{ id: 'c1' }, { id: 'c2' }] }));

    const result = await adapter.execute({ operation: 'list_conversations', input: {}, config });

    expect(server.requests[0]?.method).toBe('GET');
    expect(server.requests[0]?.url).toBe('/api/v1/agents/conversations');
    expect(result.output).toHaveLength(2);
  });

  it('get_conversation → GET /api/v1/agents/conversations/{id}', async () => {
    server.setHandler(() => ({ body: { id: 'c9', messages: [] } }));

    const result = await adapter.execute({ operation: 'get_conversation', input: { id: 'c9' }, config });

    expect(server.requests[0]?.url).toBe('/api/v1/agents/conversations/c9');
    expect(result.output['id']).toBe('c9');
  });

  it('send_response → POST .../respond with agent_id query & content JSON body', async () => {
    // Contract evolution (2026-10): the reply text moves from the query string
    // to the JSON body — long replies exceeded URL limits and leaked into
    // access logs. agent_id stays a query parameter (FastAPI Query(...)).
    server.setHandler(() => ({ body: { sent: true } }));

    await adapter.execute({
      operation: 'send_response',
      input: { id: 'c5', agent_id: 'agent-1', content: 'Hello there' },
      config,
    });

    const req = server.requests[0];
    expect(req?.method).toBe('POST');
    expect(req?.url).toContain('/api/v1/agents/conversations/c5/respond?');
    const url = new URL(req?.url ?? '', server.baseUrl);
    expect(url.searchParams.get('agent_id')).toBe('agent-1');
    expect(url.searchParams.get('content')).toBeNull();
    expect(JSON.parse(req?.body ?? '{}')).toEqual({ content: 'Hello there' });
  });

  it('takeover → POST .../takeover?agent_id=… (query param, Desk API contract)', async () => {
    // Regression (combo C-B07): Desk reads agent_id from the QUERY string
    // (FastAPI Query(...)); the old body-based call was always 422.
    server.setHandler(() => ({ body: { taken_over: true } }));

    await adapter.execute({ operation: 'takeover', input: { id: 'c5', agent_id: 'agent-1' }, config });

    const req = server.requests[0];
    expect(req?.method).toBe('POST');
    expect(req?.url).toContain('/api/v1/agents/conversations/c5/takeover?');
    const url = new URL(req?.url ?? '', server.baseUrl);
    expect(url.searchParams.get('agent_id')).toBe('agent-1');
    expect(req?.body ?? '').toBe('');
  });

  it('resolve → POST .../resolve?agent_id=… (query param, Desk API contract)', async () => {
    server.setHandler(() => ({ body: { resolved: true } }));

    await adapter.execute({ operation: 'resolve', input: { id: 'c5', agent_id: 'agent-1' }, config });

    expect(server.requests[0]?.method).toBe('POST');
    expect(server.requests[0]?.url).toContain('/api/v1/agents/conversations/c5/resolve?');
    const url = new URL(server.requests[0]?.url ?? '', server.baseUrl);
    expect(url.searchParams.get('agent_id')).toBe('agent-1');
  });

  it('throws UpstreamError on non-2xx responses', async () => {
    server.setHandler(() => ({ status: 404, body: { detail: 'not found' } }));

    await expect(
      adapter.execute({ operation: 'get_conversation', input: { id: 'nope' }, config }),
    ).rejects.toThrow(/Desk returned 404/);
  });

  it('healthCheck returns true on 200 and false otherwise', async () => {
    server.setHandler(() => ({ body: { status: 'ok' } }));
    expect(await adapter.healthCheck(server.baseUrl)).toBe(true);

    server.setHandler(() => ({ status: 503, body: {} }));
    expect(await adapter.healthCheck(server.baseUrl)).toBe(false);
  });

  it('advertises the real Desk node types', () => {
    const caps = adapter.getCapabilities();
    expect(caps.node_types).toEqual(
      expect.arrayContaining([
        'desk.list_conversations',
        'desk.get_conversation',
        'desk.send_response',
        'desk.takeover',
        'desk.resolve',
      ]),
    );
    expect(caps.node_types).not.toContain('desk.create_task');
  });
});

