/**
 * Integration tests — end-to-end workflow execution through the real engine.
 *
 * Uses stub node types (no real adapters registered) so execution exercises
 * the engine's dispatch path without making external HTTP calls. The executor
 * falls back to returning input-as-output for unknown node types.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import {
  buildTestApp,
  seedWorkflow,
  type TestApp,
} from '../_helpers/app.js';
import type { WorkflowDefinition } from '../../../packages/types/src/index.js';

/**
 * Three-node linear workflow using stub node types. The executor returns input
 * as output for nodes with no registered adapter, which is enough to assert
 * ordering and output storage.
 */
const STUB_THREE_NODE: WorkflowDefinition = {
  version: '1.0',
  nodes: [
    {
      id: 'node_vault',
      type: 'stub.vault_search',
      position: { x: 0, y: 0 },
      config: { query: 'integration test' },
    },
    {
      id: 'node_transform',
      type: 'stub.transform',
      position: { x: 200, y: 0 },
      config: { mode: 'uppercase' },
    },
    {
      id: 'node_desk',
      type: 'stub.desk_task',
      position: { x: 400, y: 0 },
      config: { title: 'Final task' },
    },
  ],
  edges: [
    { id: 'e1', source: 'node_vault', target: 'node_transform' },
    { id: 'e2', source: 'node_transform', target: 'node_desk' },
  ],
  variables: {},
  metadata: { name: 'e2e-stub-workflow', tags: ['e2e'] },
};

describe('End-to-end workflow execution', () => {
  let ctx: TestApp;

  beforeAll(async () => {
    ctx = await buildTestApp();
    await ctx.app.ready();
  });

  afterAll(async () => {
    await ctx.app.close();
    ctx.conn.close();
  });

  it('executes a 3-node workflow in topological order', async () => {
    // 1. Create workflow
    const wf = await seedWorkflow(ctx.store, {
      name: 'E2E Workflow',
      definition: STUB_THREE_NODE,
    });

    // 2. Create execution record directly
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: { trigger_key: 'trigger_value' },
    });

    // 3. Run executor
    await ctx.executor.execute(executionId, STUB_THREE_NODE, {
      trigger_key: 'trigger_value',
    });

    // 4. Verify execution succeeded
    const execution = await ctx.store.executions.getById(executionId);
    expect(execution).not.toBeNull();
    expect(execution!.status).toBe('succeeded');
    expect(execution!.duration_ms).toBeGreaterThanOrEqual(0);
    expect(execution!.error).toBeNull();

    // 5. Verify node executions
    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    expect(nodes).toHaveLength(3);

    // Verify topological order: vault → transform → desk
    expect(nodes[0].node_id).toBe('node_vault');
    expect(nodes[0].node_type).toBe('stub.vault_search');
    expect(nodes[1].node_id).toBe('node_transform');
    expect(nodes[1].node_type).toBe('stub.transform');
    expect(nodes[2].node_id).toBe('node_desk');
    expect(nodes[2].node_type).toBe('stub.desk_task');

    // 6. Verify each node has status 'succeeded' and stored outputs
    for (const node of nodes) {
      expect(node.status).toBe('succeeded');
      expect(node.started_at).toBeDefined();
      expect(node.completed_at).toBeDefined();
      expect(node.output).toBeDefined();
      expect(typeof node.output).toBe('object');
    }

    // 7. Verify inputs are stored
    expect(nodes[0].input).toMatchObject({ query: 'integration test' });
    expect(nodes[1].input).toMatchObject({ mode: 'uppercase' });
    expect(nodes[2].input).toMatchObject({ title: 'Final task' });
  });

  it('marks execution as failed when a node fails', async () => {
    // Workflow with a single node that references a connector type whose
    // adapter we register to throw.
    const failDefinition: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'n_fail',
          type: 'stub.always_fails',
          position: { x: 0, y: 0 },
          config: {},
          retry: { max_attempts: 0, backoff: 'fixed', initial_delay_ms: 0 },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: 'fail-workflow' },
    };

    // Register a failing adapter
    ctx.connectors.registerAdapter({
      type: 'stub',
      async execute() {
        throw new Error('Simulated node failure');
      },
      async healthCheck() {
        return false;
      },
      getCapabilities() {
        return { node_types: ['stub.always_fails'], input_types: [], output_types: [] };
      },
    });

    const wf = await seedWorkflow(ctx.store, { definition: failDefinition });
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
    });

    await expect(ctx.executor.execute(executionId, failDefinition, {})).rejects.toThrow(
      /Simulated node failure/,
    );

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution!.status).toBe('failed');
    expect(execution!.error).toMatch(/Simulated node failure/);

    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    expect(nodes).toHaveLength(1);
    expect(nodes[0].status).toBe('failed');
    expect(nodes[0].error).toMatch(/Simulated node failure/);
  });

  it('empty workflow completes immediately with status "succeeded"', async () => {
    const emptyDefinition: WorkflowDefinition = {
      version: '1.0',
      nodes: [],
      edges: [],
      variables: {},
      metadata: { name: 'empty' },
    };

    const wf = await seedWorkflow(ctx.store, { definition: emptyDefinition });
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
    });

    await ctx.executor.execute(executionId, emptyDefinition, {});

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution!.status).toBe('succeeded');

    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    expect(nodes).toHaveLength(0);
  });

  it('outputs from upstream nodes are available via nodeOutputs map', async () => {
    // Use a workflow with two nodes. Uses connector types distinct from the
    // failing adapter registered in the previous test — the connector registry
    // is shared across tests in this suite.
    const twoNodeDefinition: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        { id: 'first', type: 'echo.a', position: { x: 0, y: 0 }, config: { x: 1 } },
        { id: 'second', type: 'echo.b', position: { x: 100, y: 0 }, config: { y: 2 } },
      ],
      edges: [{ id: 'e', source: 'first', target: 'second' }],
      variables: {},
      metadata: { name: 'two-node' },
    };

    const wf = await seedWorkflow(ctx.store, { definition: twoNodeDefinition });
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
    });

    await ctx.executor.execute(executionId, twoNodeDefinition, {});

    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    expect(nodes).toHaveLength(2);
    // Both succeeded — inputs persisted
    expect(nodes[0].node_type).toBe('echo.a');
    expect(nodes[1].node_type).toBe('echo.b');
    expect(nodes[0].input).toMatchObject({ x: 1 });
    expect(nodes[1].input).toMatchObject({ y: 2 });
  });
});

/**
 * Integration tests — replay output persistence (V1.4 M2, F-2).
 *
 * Runs the real engine against an in-memory SQLite store and asserts that:
 *  - a `node_succeeded` event persists the node output (size-capped) and
 *    `reconstructExecution` folds it back into `NodeSnapshot.output`;
 *  - an oversized output is persisted as a `{__truncated__, size, preview}`
 *    marker instead of the full payload (events table is not bloated);
 *  - old events without an `output` field still fold to `output === undefined`
 *    (backward compatible).
 */

import { describe, it, expect, afterEach } from 'vitest';
import {
  createSqliteConnection,
  SqliteStateStore,
  type SqliteConnection,
} from '../../../packages/state/src/index.js';
import { ConnectorRegistry, type ConnectorAdapter } from '../../../packages/connectors/src/index.js';
import {
  ExecutionExecutor,
  EventBus,
  reconstructExecution,
  foldExecutionEvents,
} from '../../../packages/engine/src/index.js';
import type {
  WorkflowDefinition,
  ConnectorCapabilities,
  ExecutionEvent,
} from '../../../packages/types/src/index.js';

/** Adapter that always succeeds with a caller-supplied output. */
function outputAdapter(type: string, output: Record<string, unknown>): ConnectorAdapter {
  return {
    type,
    async execute() {
      return { output };
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
}

async function createStore(): Promise<{ conn: SqliteConnection; store: SqliteStateStore }> {
  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  const store = new SqliteStateStore(conn);
  await store.initialise();
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: '',
    email: 'system@loop.internal',
    role: 'admin',
  });
  return { conn, store };
}

async function seedExecution(store: SqliteStateStore, definition: WorkflowDefinition): Promise<string> {
  const workflowId = crypto.randomUUID();
  await store.workflows.create({
    id: workflowId,
    name: 'Replay output test',
    description: '',
    definition,
    created_by: 'system',
  });
  const executionId = crypto.randomUUID();
  await store.executions.create({
    id: executionId,
    workflow_id: workflowId,
    workflow_version: 1,
    trigger_type: 'manual',
    trigger_payload: {},
  });
  return executionId;
}

function node(id: string, type: string): WorkflowDefinition['nodes'][number] {
  return { id, type, position: { x: 0, y: 0 }, config: {} };
}

function event(
  executionId: string,
  seq: number,
  eventType: ExecutionEvent['event_type'],
  nodeId: string | undefined,
  payload: Record<string, unknown> = {},
): ExecutionEvent {
  return {
    id: `${executionId}-${seq}`,
    execution_id: executionId,
    event_type: eventType,
    ...(nodeId !== undefined ? { node_id: nodeId } : {}),
    payload,
    created_at: 1_700_000_000_000 + seq * 1000,
  };
}

describe('replay output persistence (V1.4 M2, F-2)', () => {
  const conns: SqliteConnection[] = [];
  afterEach(() => {
    while (conns.length > 0) conns.pop()!.close();
  });

  it('persists node outputs in node_succeeded events and reconstructs them', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(outputAdapter('alpha', { ok: true, value: 42 }));
    connectors.registerAdapter(outputAdapter('beta', { items: ['x', 'y'] }));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('node_a', 'alpha.op'), node('node_b', 'beta.op')],
      edges: [{ id: 'e', source: 'node_a', target: 'node_b' }],
      variables: {},
      metadata: { name: 'outputs' },
    };
    const executionId = await seedExecution(store, definition);

    // Generous, explicit cap so both outputs are stored in full.
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, new EventBus(), 5, 65_536);
    await executor.execute(executionId, definition, {});

    // O1: the persisted node_succeeded events carry the output in their payload.
    const events = await store.events.listByExecution(executionId);
    const succeededA = events.find((e) => e.event_type === 'node_succeeded' && e.node_id === 'node_a');
    expect(succeededA?.payload['output']).toEqual({ ok: true, value: 42 });
    expect(typeof succeededA?.payload['duration_ms']).toBe('number');

    // O2: reconstruction folds the persisted output back into the snapshot.
    const snap = await reconstructExecution(store, executionId);
    expect(snap.status).toBe('succeeded');
    expect(snap.nodeStates.get('node_a')).toMatchObject({ status: 'succeeded', output: { ok: true, value: 42 } });
    expect(snap.nodeStates.get('node_b')).toMatchObject({ status: 'succeeded', output: { items: ['x', 'y'] } });
  });

  it('stores an oversized output as a truncated marker (size cap enforced)', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const big = 'x'.repeat(2_000); // serialises well past the 64-byte cap below
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(outputAdapter('big', { big }));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('node_big', 'big.op')],
      edges: [],
      variables: {},
      metadata: { name: 'oversized' },
    };
    const executionId = await seedExecution(store, definition);

    // Tiny 64-byte cap forces truncation of the ~2KB output.
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, new EventBus(), 5, 64);
    await executor.execute(executionId, definition, {});

    // The persisted event carries the marker, NOT the full output.
    const events = await store.events.listByExecution(executionId);
    const succeeded = events.find((e) => e.event_type === 'node_succeeded' && e.node_id === 'node_big');
    const payloadOutput = succeeded?.payload['output'] as Record<string, unknown> | undefined;
    expect(payloadOutput?.['__truncated__']).toBe(true);
    expect(typeof payloadOutput?.['size']).toBe('number');
    expect(Number(payloadOutput?.['size'])).toBeGreaterThan(64);
    expect(typeof payloadOutput?.['preview']).toBe('string');
    expect(payloadOutput?.['big']).toBeUndefined(); // full output NOT persisted

    // Reconstruction preserves the truncation marker verbatim.
    const snap = await reconstructExecution(store, executionId);
    expect(snap.nodeStates.get('node_big')).toMatchObject({
      status: 'succeeded',
      output: { __truncated__: true },
    });
  });

  it('folds old events without an output to output === undefined (backward compatible)', () => {
    const execId = 'exec-legacy';
    const events = [
      event(execId, 1, 'execution_started', undefined),
      // Legacy node_succeeded payload: only duration_ms, no output field.
      event(execId, 2, 'node_succeeded', 'node_a', { duration_ms: 12 }),
      event(execId, 3, 'execution_succeeded', undefined),
    ];

    const snap = foldExecutionEvents(execId, events);
    expect(snap.status).toBe('succeeded');
    expect(snap.nodeStates.get('node_a')?.status).toBe('succeeded');
    expect(snap.nodeStates.get('node_a')?.output).toBeUndefined();
  });
});

/**
 * Integration tests — `workflow.invoke` sub-workflow invocation end-to-end
 * (V1.2 M3, F-Loop-1).
 *
 * Runs through the real engine + SQLite store wired by `buildTestApp`. Child
 * nodes use stub types (input-as-output fallback) so no external HTTP calls are
 * made. Covers the PRD DoD: a parent invokes a child and a downstream parent
 * node consumes the child's output; recursion depth is bounded.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { buildTestApp, seedWorkflow, type TestApp } from '../_helpers/app.js';
import type { WorkflowDefinition } from '../../../packages/types/src/index.js';

/** Structural view of a thrown LoopError (avoids cross-module instanceof). */
interface ThrownLoopError {
  code: string;
  message: string;
}

/** A single stub node that surfaces `trigger.payload.greeting` as its output. */
function stubLeaf(name: string): WorkflowDefinition {
  return {
    version: '1.0',
    nodes: [
      {
        id: 'node_c1',
        type: 'stub.leaf',
        position: { x: 0, y: 0 },
        config: { value: '{{trigger.payload.greeting}}' },
      },
    ],
    edges: [],
    variables: {},
    metadata: { name },
  };
}

/** Wrap `leaf` in `depth` nested `workflow.invoke` definitions (distinct names). */
function nestedInvokeChain(depth: number, leaf: WorkflowDefinition): WorkflowDefinition {
  let current = leaf;
  for (let i = 0; i < depth; i++) {
    current = {
      version: '1.0',
      nodes: [
        {
          id: 'node_invoke',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { definition: current },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: `chain-${i}` },
    };
  }
  return current;
}

describe('Sub-workflow invocation (workflow.invoke)', () => {
  let ctx: TestApp;

  beforeAll(async () => {
    ctx = await buildTestApp();
    await ctx.app.ready();
  });

  afterAll(async () => {
    await ctx.app.close();
    ctx.conn.close();
  });

  it('parent → child → downstream: consumes the child output end-to-end', async () => {
    const child = stubLeaf('child');
    const parent: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'node_sub',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { definition: child, inputs: { greeting: 'hello-from-parent' } },
        },
        {
          id: 'node_downstream',
          type: 'stub.sink',
          position: { x: 200, y: 0 },
          config: { received: '{{node_sub.output.outputs.node_c1.value}}' },
        },
      ],
      edges: [{ id: 'e1', source: 'node_sub', target: 'node_downstream' }],
      variables: {},
      metadata: { name: 'parent-e2e', tags: ['e2e'] },
    };

    const wf = await seedWorkflow(ctx.store, { name: 'Parent E2E', definition: parent });
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });

    await ctx.executor.execute(executionId, parent, {});

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');

    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    const invokeRow = nodes.find((n) => n.node_id === 'node_sub');
    const downstreamRow = nodes.find((n) => n.node_id === 'node_downstream');

    // The invoke node returns the child's outputs + status.
    expect(invokeRow?.status).toBe('succeeded');
    expect(invokeRow?.output).toMatchObject({ status: 'succeeded' });
    expect(invokeRow?.output['outputs']).toMatchObject({ node_c1: { value: 'hello-from-parent' } });

    // The downstream parent node consumed the child output via interpolation.
    expect(downstreamRow?.status).toBe('succeeded');
    expect(downstreamRow?.output).toMatchObject({ received: 'hello-from-parent' });

    // The child ran as its own execution row (parent + child = ≥2 executions).
    const all = await ctx.store.executions.list({}, { page: 1, per_page: 50 });
    expect(all.total).toBeGreaterThanOrEqual(2);
  });

  it('invokes a stored sub-workflow by workflow_id', async () => {
    const child = stubLeaf('stored-child');
    const childWf = await seedWorkflow(ctx.store, { name: 'Stored child', definition: child });

    const parent: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'node_sub',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { workflow_id: childWf.id, inputs: { greeting: 'by-id' } },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: 'parent-by-id', tags: ['e2e'] },
    };
    const wf = await seedWorkflow(ctx.store, { name: 'Parent by id', definition: parent });
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });

    await ctx.executor.execute(executionId, parent, {});

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');

    const nodes = await ctx.store.nodeExecutions.listByExecution(executionId);
    const invokeRow = nodes.find((n) => n.node_id === 'node_sub');
    expect(invokeRow?.output['outputs']).toMatchObject({ node_c1: { value: 'by-id' } });
  });

  it('bounds recursion depth with SUBWORKFLOW_DEPTH_EXCEEDED', async () => {
    // 7 nested invokes around a leaf exceeds the default ceiling of 5.
    const definition = nestedInvokeChain(7, stubLeaf('leaf'));
    const wf = await seedWorkflow(ctx.store, { name: 'Deep chain', definition });
    const executionId = crypto.randomUUID();
    await ctx.store.executions.create({
      id: executionId,
      workflow_id: wf.id,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });

    const err = (await ctx.executor.execute(executionId, definition, {}).catch((e: unknown) => e)) as ThrownLoopError;
    expect(err.code).toBe('SUBWORKFLOW_DEPTH_EXCEEDED');
    expect(err.message).toMatch(/exceeds the maximum of 5/);

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution?.status).toBe('failed');
  });
});

/**
 * Integration tests — egress policy enforcement.
 *
 * Creates egress policies via the state store, then uses the EgressEngine to
 * evaluate whether URLs are allowed. This verifies the policy loader, cache,
 * priority ordering, and default-deny behaviour.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import {
  createSqliteConnection,
  SqliteStateStore,
  type SqliteConnection,
} from '../../../packages/state/src/index.js';
import { EgressEngine, EgressInterceptor } from '../../../packages/egress/src/index.js';
import { LoopError } from '../../../packages/types/src/index.js';

// Mock the resolver so tests are deterministic (no real DNS).
vi.mock('../../../packages/egress/src/resolver.js', () => ({
  resolveIP: (hostname: string): string => {
    if (/^\d{1,3}(\.\d{1,3}){3}$/.test(hostname)) return hostname;
    const map: Record<string, string> = {
      'allowed.example.com': '93.184.216.10',
      'blocked.example.com': '198.51.100.20',
      'partner.api.test': '203.0.113.50',
      'subdomain.partner.api.test': '203.0.113.51',
    };
    return map[hostname] ?? hostname;
  },
  lookupRegion: (ip: string): string => {
    if (ip.startsWith('203.0.113.')) return 'EU';
    if (ip.startsWith('93.184.')) return 'US';
    if (ip.startsWith('198.51.')) return 'RU';
    return '';
  },
}));

describe('Egress policy enforcement', () => {
  let conn: SqliteConnection;
  let store: SqliteStateStore;
  let engine: EgressEngine;

  beforeEach(async () => {
    conn = createSqliteConnection({ path: ':memory:', wal: false });
    store = new SqliteStateStore(conn);
    await store.initialise();
    engine = new EgressEngine(() => store.egressPolicies.listEnabled());
  });

  // V1.6 M1 (F-1, DB2): release the native SQLite handle after every test so it
  // is never left for GC teardown at process exit.
  afterEach(() => {
    conn.close();
  });

  it('default deny — URL without a matching allow policy is blocked', async () => {
    const decision = await engine.evaluate('https://unknown.example.com/anything');
    expect(decision.allowed).toBe(false);
    expect(decision.reason).toMatch(/default deny|No matching allow policy/i);
  });

  it('allow policy for a specific domain permits the URL', async () => {
    await store.egressPolicies.create({
      id: 'p1',
      name: 'Allow allowed.example.com',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'allowed.example.com',
      priority: 10,
    });
    engine.invalidateCache();

    const decision = await engine.evaluate('https://allowed.example.com/resource');
    expect(decision.allowed).toBe(true);
    expect(decision.matched_policy).toBe('p1');
  });

  it('deny policy overrides lower-priority allow policy', async () => {
    await store.egressPolicies.create({
      id: 'p-allow',
      name: 'Allow partner.api.test',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'partner.api.test',
      priority: 10,
    });
    await store.egressPolicies.create({
      id: 'p-deny',
      name: 'Block partner.api.test',
      rule_type: 'deny',
      target_type: 'domain',
      target_value: 'partner.api.test',
      priority: 100,
    });
    engine.invalidateCache();

    const decision = await engine.evaluate('https://partner.api.test/x');
    expect(decision.allowed).toBe(false);
    expect(decision.matched_policy).toBe('p-deny');
  });

  it('wildcard domain policy matches subdomains', async () => {
    await store.egressPolicies.create({
      id: 'wc',
      name: 'Allow partner.api.test and subdomains',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: '*.partner.api.test',
      priority: 10,
    });
    engine.invalidateCache();

    const decision = await engine.evaluate('https://subdomain.partner.api.test/endpoint');
    expect(decision.allowed).toBe(true);
    expect(decision.matched_policy).toBe('wc');
  });

  it('deny policy blocks a domain while allowing others', async () => {
    await store.egressPolicies.create({
      id: 'deny-blocked',
      name: 'Deny blocked.example.com',
      rule_type: 'deny',
      target_type: 'domain',
      target_value: 'blocked.example.com',
      priority: 50,
    });
    await store.egressPolicies.create({
      id: 'allow-all',
      name: 'Allow everything else',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: '*.example.com',
      priority: 10,
    });
    engine.invalidateCache();

    const allowedDecision = await engine.evaluate('https://allowed.example.com/');
    expect(allowedDecision.allowed).toBe(true);

    const blockedDecision = await engine.evaluate('https://blocked.example.com/');
    expect(blockedDecision.allowed).toBe(false);
    expect(blockedDecision.matched_policy).toBe('deny-blocked');
  });

  it('disabled policy is ignored', async () => {
    await store.egressPolicies.create({
      id: 'p-disabled',
      name: 'Disabled allow',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'allowed.example.com',
      priority: 100,
    });
    await store.egressPolicies.update('p-disabled', { enabled: false });
    engine.invalidateCache();

    // Despite the policy matching the domain, it's disabled, so default deny applies.
    const decision = await engine.evaluate('https://allowed.example.com/');
    expect(decision.allowed).toBe(false);
  });

  it('EgressInterceptor throws LoopError when egress is blocked', async () => {
    // No allow policy → default deny
    const interceptor = new EgressInterceptor(engine);

    await expect(
      interceptor.request('https://blocked.example.com/anything'),
    ).rejects.toThrow(/Egress blocked/);

    try {
      await interceptor.request('https://blocked.example.com/anything');
    } catch (err) {
      // Verify via duck-typing because module identity can differ across
      // pnpm's module graph.
      const loopErr = err as { name?: string; code?: string; statusCode?: number };
      expect(loopErr.name).toBe('LoopError');
      expect(loopErr.code).toBe('NODE_EGRESS_BLOCKED');
      expect(loopErr.statusCode).toBe(403);
    }
  });

  it('egressPolicies.listEnabled only returns enabled policies', async () => {
    await store.egressPolicies.create({
      id: 'e1',
      name: 'Enabled',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'x.test',
      priority: 10,
    });
    await store.egressPolicies.create({
      id: 'e2',
      name: 'Disabled',
      rule_type: 'allow',
      target_type: 'domain',
      target_value: 'y.test',
      priority: 20,
    });
    await store.egressPolicies.update('e2', { enabled: false });

    const enabled = await store.egressPolicies.listEnabled();
    expect(enabled).toHaveLength(1);
    expect(enabled[0].id).toBe('e1');

    const all = await store.egressPolicies.list();
    expect(all).toHaveLength(2);
  });

  it('invalid URL is rejected with reason "Invalid URL"', async () => {
    const decision = await engine.evaluate('not a valid url');
    expect(decision.allowed).toBe(false);
    expect(decision.reason).toBe('Invalid URL');
  });

  it('engine caches policies and reloads after invalidateCache', async () => {
    let loadCount = 0;
    const countingEngine = new EgressEngine(async () => {
      loadCount++;
      return store.egressPolicies.listEnabled();
    });

    await countingEngine.evaluate('https://allowed.example.com/');
    await countingEngine.evaluate('https://allowed.example.com/other');
    // Cache hit on second call
    expect(loadCount).toBe(1);

    countingEngine.invalidateCache();
    await countingEngine.evaluate('https://allowed.example.com/');
    expect(loadCount).toBe(2);
  });
});

/**
 * Integration tests — database migration pipeline.
 *
 * Runs the full migration pipeline against a fresh in-memory SQLite database
 * via `SqliteStateStore.initialise()` and verifies that every expected table
 * and index exists. Also checks that migrations are idempotent.
 */

import { describe, it, expect } from 'vitest';
import {
  createSqliteConnection,
  SqliteStateStore,
  type SqliteConnection,
} from '../../../packages/state/src/index.js';

const EXPECTED_TABLES = [
  'users',
  'workflows',
  'workflow_definitions',
  'workflow_executions',
  'node_executions',
  'workflow_triggers',
  'audit_events',
  'secrets',
  'egress_policies',
  'connectors',
  'schema_migrations',
];

const EXPECTED_INDEXES = [
  'idx_workflows_status_updated',
  'idx_workflows_created_by',
  'idx_wf_defs_workflow',
  'idx_exec_workflow_started',
  'idx_exec_status_started',
  'idx_exec_started',
