  'idx_node_exec_node',
  'idx_audit_timestamp',
  'idx_audit_resource',
  'idx_audit_actor',
];

describe('Database migrations (integration)', () => {
  it('applies migrations to a fresh SQLite database and creates all tables', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();

    const tables = conn.client
      .prepare(
        `SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name`,
      )
      .all() as Array<{ name: string }>;

    const tableNames = tables.map((t) => t.name);
    for (const expected of EXPECTED_TABLES) {
      expect(tableNames, `table '${expected}' should exist`).toContain(expected);
    }

    conn.close();
  });

  it('creates all expected indexes', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();

    const indexes = conn.client
      .prepare(`SELECT name FROM sqlite_master WHERE type='index' AND name IS NOT NULL`)
      .all() as Array<{ name: string }>;

    const indexNames = new Set(indexes.map((i) => i.name));
    for (const expected of EXPECTED_INDEXES) {
      expect(indexNames, `index '${expected}' should exist`).toContain(expected);
    }

    conn.close();
  });

  it('migrations are idempotent (re-running does not error or duplicate)', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();
    await store.initialise();
    await store.initialise();

    const migrations = conn.client
      .prepare(`SELECT version, COUNT(*) as cnt FROM schema_migrations GROUP BY version`)
      .all() as Array<{ version: string; cnt: number }>;

    for (const row of migrations) {
      expect(row.cnt).toBe(1);
    }
    expect(migrations.length).toBeGreaterThan(0);

    conn.close();
  });

  it('records version and checksum for each applied migration', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();

    const rows = conn.client
      .prepare(`SELECT version, checksum, applied_at FROM schema_migrations`)
      .all() as Array<{ version: string; checksum: string; applied_at: string }>;

    for (const row of rows) {
      expect(row.version).toMatch(/^\d+$/);
      expect(row.checksum).toMatch(/^[a-f0-9]{64}$/);
      expect(row.applied_at).toBeTruthy();
    }

    conn.close();
  });

  it('tables have the expected column structure (workflows)', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();

    const columns = conn.client
      .prepare(`PRAGMA table_info(workflows)`)
      .all() as Array<{ name: string; type: string; notnull: number }>;

    const colNames = columns.map((c) => c.name);
    expect(colNames).toEqual(
      expect.arrayContaining([
        'id',
        'name',
        'description',
        'definition',
        'version',
        'status',
        'tags',
        'created_by',
        'updated_by',
        'created_at',
        'updated_at',
      ]),
    );

    conn.close();
  });

  it('foreign keys are enforced (insert with invalid FK fails)', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();

    // workflows.created_by references users(id); inserting without a user
    // should throw because foreign_keys = ON.
    expect(() =>
      conn.client
        .prepare(
          `INSERT INTO workflows (id, name, description, definition, version, status, tags, created_by, updated_by)
           VALUES ('x', 'n', '', '{}', 1, 'draft', '[]', 'nonexistent', 'nonexistent')`,
        )
        .run(),
    ).toThrow();

    conn.close();
  });

  it('state store can perform CRUD after migration', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    const store = new SqliteStateStore(conn);
    await store.initialise();

    // Seed a user (needed for workflow FK)
    await store.users.create({
      id: 'u-1',
      username: 'test',
      password_hash: 'x',
      email: 'test@loop.test',
      role: 'admin',
    });

    const wf = await store.workflows.create({
      id: 'w-1',
      name: 'Test Workflow',
      description: '',
      definition: {
        version: '1.0',
        nodes: [],
        edges: [],
        variables: {},
        metadata: {},
      },
      created_by: 'u-1',
    });

    expect(wf.id).toBe('w-1');
    expect(wf.status).toBe('draft');
    expect(wf.version).toBe(1);

    const fetched = await store.workflows.getById('w-1');
    expect(fetched).not.toBeNull();
    expect(fetched!.name).toBe('Test Workflow');

    conn.close();
  });
});

/**
 * Integration tests — trigger → execution flow.
 *
 * Creates a webhook trigger, sends a webhook request with a valid HMAC
 * signature, and verifies an execution is created for the workflow.
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import { createHmac } from 'node:crypto';
import type { FastifyInstance } from 'fastify';
import { buildTestApp, seedWorkflow, type TestApp } from '../_helpers/app.js';

function hmacSignature(secret: string, body: string): string {
  return `sha256=${createHmac('sha256', secret).update(body).digest('hex')}`;
}

describe('Trigger → Execution flow', () => {
  let ctx: TestApp;
  let app: FastifyInstance;

  beforeAll(async () => {
    ctx = await buildTestApp();
    app = ctx.app;
    await app.ready();
  });

  afterAll(async () => {
    await app.close();
    ctx.conn.close();
  });

  beforeEach(async () => {
    // Clean workflows & triggers between tests
    const existing = await ctx.store.workflows.list({}, { page: 1, per_page: 100 });
    for (const wf of existing.data) {
      try { await ctx.store.workflows.delete(wf.id); } catch { /* ignore */ }
    }
  });

  it('POST /webhooks/:triggerId with valid signature creates an execution', async () => {
    // 1. Create a workflow
    const wf = await seedWorkflow(ctx.store, { name: 'Webhook-Triggered' });

    // 2. Create a webhook trigger with a known secret
    const webhookSecret = 'super-secret-webhook-key';
    const triggerRes = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/triggers`,
      payload: {
        trigger_type: 'webhook',
        config: { secret: webhookSecret, path: '/webhook' },
      },
    });
    expect(triggerRes.statusCode).toBe(201);
    const triggerId = triggerRes.json().data.id;

    // 3. Fire the webhook with valid HMAC signature
    const payload = { event: 'user.signup', user_id: 'u-123' };
    const rawBody = JSON.stringify(payload);
    const signature = hmacSignature(webhookSecret, rawBody);

    const webhookRes = await app.inject({
      method: 'POST',
      url: `/webhooks/${triggerId}`,
      headers: { 'x-loop-signature': signature, 'content-type': 'application/json' },
      payload,
    });

    expect(webhookRes.statusCode).toBe(200);
    const body = webhookRes.json();
    expect(body.accepted).toBe(true);
    expect(body.execution_id).toBeDefined();

    // 4. Verify execution was created
    const execution = await ctx.store.executions.getById(body.execution_id);
    expect(execution).not.toBeNull();
    expect(execution!.workflow_id).toBe(wf.id);
    expect(execution!.trigger_type).toBe('webhook');
    expect(execution!.trigger_payload).toMatchObject(payload);

    // 5. The webhook dispatch must actually RUN the workflow (bug 13):
    // poll until the execution reaches a terminal state. MINIMAL_DEFINITION
    // has zero nodes, so a dispatched execution succeeds almost immediately —
    // before the fix the record stayed 'pending' forever.
    let finalStatus = execution!.status;
    for (let i = 0; i < 50 && (finalStatus === 'pending' || finalStatus === 'running'); i++) {
      await new Promise((r) => setTimeout(r, 100));
      const current = await ctx.store.executions.getById(body.execution_id);
      finalStatus = current!.status;
    }
    expect(finalStatus).toBe('succeeded');
  });

  it('POST /webhooks/:triggerId with invalid signature is rejected', async () => {
    const wf = await seedWorkflow(ctx.store);
    const webhookSecret = 'another-secret';
    const triggerRes = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/triggers`,
      payload: { trigger_type: 'webhook', config: { secret: webhookSecret } },
    });
    const triggerId = triggerRes.json().data.id;

    const payload = { event: 'x' };
    const rawBody = JSON.stringify(payload);
    const badSignature = hmacSignature('wrong-secret', rawBody);

    const webhookRes = await app.inject({
      method: 'POST',
      url: `/webhooks/${triggerId}`,
      headers: { 'x-loop-signature': badSignature, 'content-type': 'application/json' },
      payload,
    });

    // Signature mismatch → 401
    expect(webhookRes.statusCode).toBe(401);
    const body = webhookRes.json();
    expect(body.success).toBe(false);
    expect(body.error.code).toBe('AUTH_INVALID_TOKEN');
  });

  it('POST /webhooks/:triggerId verifies the signature over the RAW bytes, not re-serialized JSON', async () => {
    // Regression (2026-09-12): the rawBody parser attached the buffer to the
    // wrong object, so the route silently fell back to JSON.stringify(request.body)
    // and any non-canonical JSON (extra whitespace / key order) failed HMAC.
    // Send a spaced body signed over its exact bytes — re-serialization would
    // strip the space and reject a legitimate sender.
    const wf = await seedWorkflow(ctx.store);
    const webhookSecret = 'raw-bytes-secret';
    const triggerRes = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/triggers`,
      payload: { trigger_type: 'webhook', config: { secret: webhookSecret } },
    });
    const triggerId = triggerRes.json().data.id;

    const spacedBody = '{"event": "user.signup",  "user_id": "u-123"}';
    const signature = hmacSignature(webhookSecret, spacedBody);

    const webhookRes = await app.inject({
      method: 'POST',
      url: `/webhooks/${triggerId}`,
      headers: { 'x-loop-signature': signature, 'content-type': 'application/json' },
      payload: spacedBody, // string payload → sent byte-exact
    });

    expect(webhookRes.statusCode).toBe(200);
    expect(webhookRes.json().accepted).toBe(true);
  });

  it('POST /webhooks/:triggerId for unknown trigger returns 404', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/webhooks/00000000-0000-0000-0000-999999999999',
      headers: { 'x-loop-signature': 'sha256=abc' },
      payload: {},
    });

    expect(res.statusCode).toBe(404);
    const body = res.json();
    expect(body.success).toBe(false);
    expect(body.error.code).toBe('NOT_FOUND_TRIGGER');
  });

  it('disabled webhook trigger is rejected', async () => {
    const wf = await seedWorkflow(ctx.store);
    const triggerRes = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/triggers`,
      payload: { trigger_type: 'webhook', config: { secret: 's' } },
    });
    const triggerId = triggerRes.json().data.id;
    await ctx.store.triggers.update(triggerId, { enabled: false });

    const payload = { event: 'y' };
    const rawBody = JSON.stringify(payload);
    const signature = hmacSignature('s', rawBody);

    const res = await app.inject({
      method: 'POST',
      url: `/webhooks/${triggerId}`,
      headers: { 'x-loop-signature': signature },
      payload,
    });

    // Disabled triggers answer 404 (same as missing) so unauthenticated
    // callers cannot enumerate valid trigger ids.
    expect(res.statusCode).toBe(404);
  });

  it('POST /api/v1/workflows/:id/triggers creates a trigger (round-trip)', async () => {
    const wf = await seedWorkflow(ctx.store);

    const res = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/triggers`,
      payload: { trigger_type: 'cron', config: { expression: '*/5 * * * *', timezone: 'UTC' } },
    });

    expect(res.statusCode).toBe(201);
    const body = res.json();
    expect(body.data.workflow_id).toBe(wf.id);
    expect(body.data.trigger_type).toBe('cron');
    expect(body.data.config).toMatchObject({ expression: '*/5 * * * *' });

    // List triggers
    const listRes = await app.inject({
      method: 'GET',
      url: `/api/v1/workflows/${wf.id}/triggers`,
    });
    expect(listRes.statusCode).toBe(200);
    expect(listRes.json().data).toHaveLength(1);
  });

  it('manual trigger creates an execution via POST /execute', async () => {
    const wf = await seedWorkflow(ctx.store);

    const res = await app.inject({
      method: 'POST',
      url: `/api/v1/workflows/${wf.id}/execute`,
      payload: { payload: { manual: true } },
    });

    expect(res.statusCode).toBe(202);
    const executionId = res.json().data.execution_id;

    const execution = await ctx.store.executions.getById(executionId);
    expect(execution!.trigger_type).toBe('manual');
    expect(execution!.trigger_payload).toEqual({ manual: true });
  });
});

/**
 * V1.6 M1 (F-1, DB2): global vitest setup — DB lifecycle safety net.
 *
 * Wired via `setupFiles` in all three vitest configs (unit / integration /
 * e2e). After every test, any SQLite connection still tracked by the
 * `tests/helpers/testStore.ts` helpers is closed best-effort, so a test that
 * leaks a store can no longer leave a native better-sqlite3 handle open for
 * GC to tear down (the root cause of the rare teardown SIGSEGV). Combined
 * with the process-exit hook in `packages/state/src/sqlite/connection.ts`
 * (DB3), every handle is released either explicitly, by this net, or at
 * process exit.
 */

import { afterEach } from 'vitest';

import { closeTrackedConnections } from './helpers/testStore.js';

afterEach(() => {
  closeTrackedConnections();
});

/**
 * Unit tests — V1.7 auth issuance (L-8): login route + bootstrap admin +
 * scrypt password helpers.
 */

import { describe, it, expect, afterEach } from 'vitest';
import Fastify from 'fastify';
import { createSqliteConnection, SqliteStateStore, type SqliteConnection } from '../../../packages/state/src';
import { registerAuthRoutes, bootstrapAdminUser, hashPassword, verifyPassword } from '../../../apps/api/src/routes/auth';
import { createAuthGuard } from '../../../apps/api/src/middleware/auth';
import type { LoopConfig } from '../../../apps/api/src/config';

function testConfig(overrides: Partial<LoopConfig> = {}): LoopConfig {
  return {
    LOOP_REQUIRE_AUTH: true,
    LOOP_JWT_SECRET: 'unit-test-jwt-secret-0123456789abcdef',
    LOOP_API_KEY: undefined,
    LOOP_API_KEY_ROLE: 'admin',
    LOOP_BOOTSTRAP_ADMIN_USERNAME: 'admin',
    LOOP_BOOTSTRAP_ADMIN_PASSWORD: 'bootstrap-pass-123',
    LOOP_BOOTSTRAP_ADMIN_EMAIL: 'admin@test.local',
    ...overrides,
  } as unknown as LoopConfig;
}

const conns: SqliteConnection[] = [];
afterEach(async () => {
  for (const conn of conns.splice(0)) await conn.close();
});

async function buildServer(config: LoopConfig) {
  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  conns.push(conn);
  const store = new SqliteStateStore(conn);
  await store.initialise();
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: '',
    email: 'system@loop.internal',
    role: 'admin',
    display_name: 'System',
  });
  await bootstrapAdminUser(store, config);
  const app = Fastify();
  app.addHook('onRequest', createAuthGuard(config));
  registerAuthRoutes(app, { store, config });
  return { app, store };
}

describe('scrypt password helpers', () => {
  it('hashes and verifies', () => {
    const hash = hashPassword('s3cret!');
    expect(hash.startsWith('scrypt$')).toBe(true);
    expect(verifyPassword('s3cret!', hash)).toBe(true);
    expect(verifyPassword('wrong', hash)).toBe(false);
  });

  it('rejects malformed stored hashes without throwing', () => {
    expect(verifyPassword('x', 'not-a-hash')).toBe(false);
    expect(verifyPassword('x', 'scrypt$zz$zz')).toBe(false);
  });
});

describe('bootstrapAdminUser', () => {
  it('seeds the first admin and is idempotent', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    conns.push(conn);
    const store = new SqliteStateStore(conn);
    await store.initialise();
    const cfg = testConfig();
    await bootstrapAdminUser(store, cfg);
    const user = await store.users.getByUsername('admin');
    expect(user?.role).toBe('admin');
    expect(verifyPassword('bootstrap-pass-123', user!.password_hash)).toBe(true);
    // Second run must not duplicate or reset.
    await bootstrapAdminUser(store, cfg);
    expect(await store.users.getByUsername('admin')).toBeTruthy();
  });

  it('is a no-op without bootstrap env', async () => {
    const conn = createSqliteConnection({ path: ':memory:', wal: false });
    conns.push(conn);
    const store = new SqliteStateStore(conn);
    await store.initialise();
    await bootstrapAdminUser(store, testConfig({ LOOP_BOOTSTRAP_ADMIN_USERNAME: undefined }));
    expect(await store.users.getByUsername('nobody')).toBeNull();
  });
});

describe('POST /api/v1/auth/login', () => {
  it('issues a JWT with the mapped role for valid credentials', async () => {
    const cfg = testConfig();
    const { app } = await buildServer(cfg);
    const res = await app.inject({ method: 'POST', url: '/api/v1/auth/login', payload: { username: 'admin', password: 'bootstrap-pass-123' } });
    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.data.token).toBeTruthy();
    expect(body.data.user.role).toBe('admin');
    // The issued token must satisfy the auth guard on a protected route.
    const guarded = await app.inject({
      method: 'GET',
      url: '/api/v1/workflows',
      headers: { authorization: `Bearer ${body.data.token}` },
    });
    expect(guarded.statusCode).not.toBe(401);
    await app.close();
  });

  it('rejects bad credentials uniformly', async () => {
    const cfg = testConfig();
    const { app } = await buildServer(cfg);
    const res = await app.inject({ method: 'POST', url: '/api/v1/auth/login', payload: { username: 'admin', password: 'nope' } });
    expect(res.statusCode).toBe(401);
    const unknown = await app.inject({ method: 'POST', url: '/api/v1/auth/login', payload: { username: 'ghost', password: 'nope' } });
    expect(unknown.statusCode).toBe(401);
    expect(unknown.json().error.message).toBe(res.json().error.message);
    await app.close();
  });

  it('locks out after repeated failures', async () => {
    const cfg = testConfig();
    const { app } = await buildServer(cfg);
    for (let i = 0; i < 5; i += 1) {
      await app.inject({ method: 'POST', url: '/api/v1/auth/login', payload: { username: 'admin', password: 'wrong' } });
    }
    const locked = await app.inject({ method: 'POST', url: '/api/v1/auth/login', payload: { username: 'admin', password: 'bootstrap-pass-123' } });
    expect(locked.statusCode).toBe(401);
    expect(locked.body).toMatch(/Too many failed attempts/);
    await app.close();
  });

  it('requires both fields', async () => {
    const cfg = testConfig();
    const { app } = await buildServer(cfg);
    const res = await app.inject({ method: 'POST', url: '/api/v1/auth/login', payload: { username: 'admin' } });
    expect(res.statusCode).toBe(401);
    await app.close();
  });
});

/**
 * Unit tests — V1.3 RBAC role resolution + route classification (F-RBAC-Loop).
 *
 * Covers the pure helpers in the auth middleware:
 *   - normalizeRole / roleSatisfies (role hierarchy),
 *   - roleFromClaims (JWT `role` / `roles` claim resolution),
 *   - requiredRoleFor (method + path → minimum role, with public exemptions).
 */

import { describe, it, expect } from 'vitest';
import type { JWTPayload } from 'jose';
import {
  normalizeRole,
  roleSatisfies,
  roleFromClaims,
  requiredRoleFor,
  isProtectedPath,
} from '../../../apps/api/src/middleware/auth';

describe('RBAC — role hierarchy helpers', () => {
  it('normalizeRole accepts known roles and rejects others', () => {
    expect(normalizeRole('admin')).toBe('admin');
    expect(normalizeRole('editor')).toBe('editor');
    expect(normalizeRole('viewer')).toBe('viewer');
    expect(normalizeRole('superuser')).toBeUndefined();
    expect(normalizeRole(undefined)).toBeUndefined();
    expect(normalizeRole(42)).toBeUndefined();
  });

  it('roleSatisfies enforces admin > editor > viewer', () => {
    expect(roleSatisfies('admin', 'viewer')).toBe(true);
    expect(roleSatisfies('admin', 'editor')).toBe(true);
    expect(roleSatisfies('admin', 'admin')).toBe(true);
    expect(roleSatisfies('editor', 'editor')).toBe(true);
    expect(roleSatisfies('editor', 'viewer')).toBe(true);
    expect(roleSatisfies('editor', 'admin')).toBe(false);
    expect(roleSatisfies('viewer', 'viewer')).toBe(true);
    expect(roleSatisfies('viewer', 'editor')).toBe(false);
    expect(roleSatisfies('viewer', 'admin')).toBe(false);
  });
});

describe('RBAC — roleFromClaims (JWT)', () => {
  it('reads a scalar role claim', () => {
    expect(roleFromClaims({ role: 'editor' } as JWTPayload)).toBe('editor');
    expect(roleFromClaims({ role: 'admin' } as JWTPayload)).toBe('admin');
  });

  it('ignores an invalid scalar role claim and falls back', () => {
    expect(roleFromClaims({ role: 'root' } as JWTPayload)).toBe('viewer');
  });

  it('reads an array roles claim, picking the highest privilege', () => {
    expect(roleFromClaims({ roles: ['viewer', 'editor'] } as JWTPayload)).toBe('editor');
    expect(roleFromClaims({ roles: ['viewer', 'admin', 'editor'] } as JWTPayload)).toBe('admin');
  });

  it('prefers the scalar role claim over the array', () => {
    expect(roleFromClaims({ role: 'viewer', roles: ['admin'] } as JWTPayload)).toBe('viewer');
  });

  it('defaults to least privilege (viewer) when no role claim is present', () => {
    expect(roleFromClaims({ sub: 'user-1' } as JWTPayload)).toBe('viewer');
    expect(roleFromClaims({ roles: ['nope'] } as JWTPayload)).toBe('viewer');
  });
});

describe('RBAC — requiredRoleFor (route classification)', () => {
  it('exempts public prefixes', () => {
    expect(requiredRoleFor('GET', '/health')).toBeNull();
    expect(requiredRoleFor('GET', '/ready')).toBeNull();
    expect(requiredRoleFor('GET', '/metrics')).toBeNull();
    expect(requiredRoleFor('POST', '/webhooks/abc')).toBeNull();
  });

  it('reads need viewer+', () => {
    expect(requiredRoleFor('GET', '/api/v1/workflows')).toBe('viewer');
    expect(requiredRoleFor('GET', '/api/v1/executions/123')).toBe('viewer');
    expect(requiredRoleFor('GET', '/api/v1/connectors')).toBe('viewer');
    expect(requiredRoleFor('GET', '/api/v1/executions/123/replay')).toBe('viewer');
  });

  it('writes need editor+', () => {
    expect(requiredRoleFor('POST', '/api/v1/workflows')).toBe('editor');
    expect(requiredRoleFor('PUT', '/api/v1/workflows/1')).toBe('editor');
    expect(requiredRoleFor('DELETE', '/api/v1/workflows/1')).toBe('editor');
    expect(requiredRoleFor('POST', '/api/v1/workflows/1/execute')).toBe('editor');
    expect(requiredRoleFor('POST', '/api/v1/executions/1/replay?dryRun=false')).toBe('editor');
  });

  it('admin routes need admin', () => {
    expect(requiredRoleFor('GET', '/api/v1/audit')).toBe('admin');
  });

  it('ignores non-api paths', () => {
    expect(requiredRoleFor('GET', '/')).toBeNull();
    expect(isProtectedPath('/health')).toBe(false);
    expect(isProtectedPath('/api/v1/workflows')).toBe(true);
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import { loadConfig } from '../../../apps/api/src/config.js';

/**
 * V1.6 correctness regression: boolean env vars must parse conventional
 * truthy/falsy strings correctly. `z.coerce.boolean()` treated the string
 * "false" as true (Boolean("false") === true), so e.g. LOOP_REQUIRE_AUTH=false
 * wrongly enabled auth. These tests lock in the fixed booleanEnv behavior.
 */
describe('config boolean env parsing', () => {
  const saved = { ...process.env };

  afterEach(() => {
    process.env = { ...saved };
  });

  const parseWith = (vars: Record<string, string>) => {
    process.env = { ...saved, ...vars };
    return loadConfig();
  };

  it('treats "false"/"0"/"no"/"off" as false', () => {
    for (const v of ['false', '0', 'no', 'off', 'FALSE', 'No']) {
      const cfg = parseWith({ LOOP_REQUIRE_AUTH: v, LOOP_METRICS_ENABLED: v });
      expect(cfg.LOOP_REQUIRE_AUTH, `REQUIRE_AUTH=${v}`).toBe(false);
      expect(cfg.LOOP_METRICS_ENABLED, `METRICS_ENABLED=${v}`).toBe(false);
    }
  });

  it('treats "true"/"1"/"yes"/"on" as true', () => {
    for (const v of ['true', '1', 'yes', 'on', 'TRUE']) {
      const cfg = parseWith({ LOOP_REQUIRE_AUTH: v, LOOP_OTEL_ENABLED: v });
      expect(cfg.LOOP_REQUIRE_AUTH, `REQUIRE_AUTH=${v}`).toBe(true);
      expect(cfg.LOOP_OTEL_ENABLED, `OTEL_ENABLED=${v}`).toBe(true);
    }
  });

  it('falls back to defaults when unset (REQUIRE_AUTH false, METRICS_ENABLED true)', () => {
    const env = { ...saved };
    delete env.LOOP_REQUIRE_AUTH;
    delete env.LOOP_METRICS_ENABLED;
    delete env.LOOP_DB_SSL;
    process.env = env;
    const cfg = loadConfig();
    expect(cfg.LOOP_REQUIRE_AUTH).toBe(false);
    expect(cfg.LOOP_METRICS_ENABLED).toBe(true);
    expect(cfg.LOOP_DB_SSL).toBe(false);
  });

  it('parses LOOP_DB_SSL="false" as false (would previously be true)', () => {
    const cfg = parseWith({ LOOP_DB_SSL: 'false' });
    expect(cfg.LOOP_DB_SSL).toBe(false);
  });
});

import { describe, expect, it } from 'vitest';
import { errorHandler } from '../../../apps/api/src/middleware/errorHandler.js';
import type { FastifyError, FastifyReply, FastifyRequest } from 'fastify';

/**
 * V1.6 load-test regression: @fastify/rate-limit raises a FastifyError with
 * statusCode 429 (code FST_RATE_LIMIT). The handler must map it to the proper
 * RATE_LIMIT_EXCEEDED envelope code, not INTERNAL_ERROR.
 */
function mockReply() {
  const reply = {
    statusCode: 0,
    body: undefined as unknown,
    status(code: number) {
      this.statusCode = code;
      return this;
    },
    send(payload: unknown) {
      this.body = payload;
      return this;
    },
  };
  return reply as unknown as FastifyReply & { statusCode: number; body: any };
}

const mockRequest = {} as FastifyRequest;

function fastifyError(statusCode: number, code?: string, message = 'Rate limit exceeded'): FastifyError {
  const err = new Error(message) as FastifyError;
  err.statusCode = statusCode;
  if (code) err.code = code;
  return err;
}

describe('errorHandler rate-limit mapping', () => {
  it('maps statusCode 429 to RATE_LIMIT_EXCEEDED', () => {
    const reply = mockReply();
    errorHandler(fastifyError(429), mockRequest, reply);
    expect(reply.statusCode).toBe(429);
    expect((reply.body as any).success).toBe(false);
    expect((reply.body as any).error.code).toBe('RATE_LIMIT_EXCEEDED');
  });

  it('maps code FST_RATE_LIMIT to RATE_LIMIT_EXCEEDED', () => {
    const reply = mockReply();
    errorHandler(fastifyError(429, 'FST_RATE_LIMIT'), mockRequest, reply);
    expect(reply.statusCode).toBe(429);
    expect((reply.body as any).error.code).toBe('RATE_LIMIT_EXCEEDED');
  });

  it('does not treat a generic 500 as rate-limited', () => {
    const reply = mockReply();
    errorHandler(fastifyError(500, undefined, 'boom'), mockRequest, reply);
    expect(reply.statusCode).toBe(500);
    expect((reply.body as any).error.code).toBe('INTERNAL_ERROR');
  });
});

/**
 * Unit tests — V1.5 M1 (F-3) distributed tracing, Loop side.
 *
 * TR1: the trace middleware reads/generates X-Trace-Id and runs the request
 *      lifecycle inside a correlation context carrying trace_id; the pino mixin
 *      stamps trace_id/request_id onto structured logs while a context is active.
 */

import { describe, it, expect } from 'vitest';
import type { FastifyRequest, FastifyReply } from 'fastify';
import { traceIdHook } from '../../../apps/api/src/middleware/traceId';
import { correlationMixin } from '../../../packages/observability/src/logger';
import {
  runWithCorrelation,
  getCorrelationContext,
} from '../../../packages/observability/src/correlation';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function mockRequest(headers: Record<string, string> = {}, extra: Record<string, unknown> = {}): FastifyRequest {
  return { headers, ...extra } as unknown as FastifyRequest;
}

const reply = {} as FastifyReply;

describe('traceIdHook (TR1)', () => {
  it('reuses the inbound X-Trace-Id header when present', () => {
    const request = mockRequest({ 'x-trace-id': 'trace-abc-123' }, { requestId: 'req-1' });
    let seen: ReturnType<typeof getCorrelationContext>;
    traceIdHook(request, reply, () => {
      seen = getCorrelationContext();
    });

    expect((request as unknown as Record<string, unknown>)['traceId']).toBe('trace-abc-123');
    expect(seen!).toEqual({ request_id: 'req-1', trace_id: 'trace-abc-123' });
  });

  it('generates a UUIDv4 trace_id when no header is supplied', () => {
    const request = mockRequest({}, { requestId: 'req-2' });
    let seen: ReturnType<typeof getCorrelationContext>;
    traceIdHook(request, reply, () => {
      seen = getCorrelationContext();
    });

    const traceId = (request as unknown as Record<string, unknown>)['traceId'] as string;
    expect(traceId).toMatch(UUID_RE);
    expect(seen!).toEqual({ request_id: 'req-2', trace_id: traceId });
  });

  it('falls back to the trace_id as request_id when neither request nor header provides one', () => {
    const request = mockRequest({});
    let seen: ReturnType<typeof getCorrelationContext>;
    traceIdHook(request, reply, () => {
      seen = getCorrelationContext();
    });

    const traceId = (request as unknown as Record<string, unknown>)['traceId'] as string;
    expect(seen!.request_id).toBe(traceId);
    expect(seen!.trace_id).toBe(traceId);
  });
});

describe('correlationMixin (TR1 — structured log injection)', () => {
  it('adds nothing when no correlation context is active', () => {
    expect(correlationMixin()).toEqual({});
  });

  it('injects trace_id and request_id while a context is active', () => {
    const fields = runWithCorrelation({ request_id: 'req-9', trace_id: 'trace-9' }, () => correlationMixin());
    expect(fields).toEqual({ trace_id: 'trace-9', request_id: 'req-9' });
  });

  it('omits trace_id when the context has none', () => {
    const fields = runWithCorrelation({ request_id: 'req-10' }, () => correlationMixin());
    expect(fields).toEqual({ request_id: 'req-10' });
  });
});

import { describe, it, expect, afterAll } from 'vitest';
import * as http from 'node:http';
import { DeskAdapter } from '../../../packages/connectors/src/desk/adapter';

describe('DeskAdapter — takeover/resolve contract', () => {
  const seen: { url?: string; body: string }[] = [];
  const server = http.createServer((req, res) => {
    let body = '';
    req.on('data', (d) => (body += d));
    req.on('end', () => {
      seen.push({ url: req.url, body });
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ success: true }));
    });
  });
  beforeAll(async () => {
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  });
  afterAll(async () => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  });

  it('sends agent_id as a query parameter for takeover (Desk API contract)', async () => {
    const port = (server.address() as { port: number }).port;
    const adapter = new DeskAdapter();
    const result = await adapter.execute({
      operation: 'takeover',
      input: { id: 'conv-1', agent_id: 'agent-9' },
      config: { base_url: `http://127.0.0.1:${port}` },
    } as never);
    expect(result.output).toEqual({ success: true });
    const last = seen[seen.length - 1];
    expect(last.url).toContain('/api/v1/agents/conversations/conv-1/takeover?');
    expect(last.url).toContain('agent_id=agent-9');
    expect(last.body).toBe(''); // body must not be required by the Desk API
  });

  it('accepts conversation_id as the id alias for resolve', async () => {
    const port = (server.address() as { port: number }).port;
    const adapter = new DeskAdapter();
    await adapter.execute({
      operation: 'resolve',
      input: { conversation_id: 'conv-2', agent_id: 'agent-9' },
