describe('EgressGate private blocklist (unconfigured allow)', () => {
  it('blocks loopback and metadata targets even with unconfiguredPolicy allow', async () => {
    const g = gate();
    await expect(g.check('http://127.0.0.1:9200/_search')).rejects.toThrow(/private\/reserved/);
    await expect(g.check('http://169.254.169.254/latest/meta-data/iam/')).rejects.toThrow(/private\/reserved/);
    await expect(g.check('http://10.0.0.5:8080/admin')).rejects.toThrow(/private\/reserved/);
  });

  it('allows public targets under the unconfigured allow policy', async () => {
    const g = gate();
    await expect(g.check('https://example.com/')).resolves.toBeUndefined();
  });

  it('honours the explicit allowPrivate escape hatch for self-hosted suites', async () => {
    const g = gate(true);
    await expect(g.check('http://127.0.0.1:8765/query')).resolves.toBeUndefined();
    await expect(g.check('http://192.168.1.10:8000/health')).resolves.toBeUndefined();
  });

  it('blocks localhost hostnames that resolve to loopback', async () => {
    const g = gate();
    // `localhost` resolves to 127.0.0.1/::1 on every supported platform.
    await expect(g.check('http://localhost:8765/query')).rejects.toThrow(/private\/reserved/);
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { CircuitBreaker } from '../../../packages/engine/src/circuitBreaker';

describe('CircuitBreaker', () => {
  let cb: CircuitBreaker;

  beforeEach(() => {
    // V1.5 M1 (F-4', TH2): the cooldown transition is pure logic keyed off
    // Date.now(). Drive it with fake timers instead of real `setTimeout` waits
    // so the suite stays stable under high load (no wall-clock races). Every
    // assertion below is preserved — only the wait mechanism changed.
    vi.useFakeTimers();
    cb = new CircuitBreaker('test-circuit', 3, 1000); // threshold=3, cooldown=1000ms
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  describe('CLOSED state', () => {
    it('should start in CLOSED state', () => {
      expect(cb.getState()).toBe('closed');
    });

    it('should pass requests through in CLOSED state', async () => {
      const fn = vi.fn().mockResolvedValue('success');

      const result = await cb.execute(fn);

      expect(result).toBe('success');
      expect(fn).toHaveBeenCalledTimes(1);
      expect(cb.getState()).toBe('closed');
    });

    it('should allow multiple successful requests', async () => {
      const fn = vi.fn().mockResolvedValue('success');

      await cb.execute(fn);
      await cb.execute(fn);
      await cb.execute(fn);

      expect(fn).toHaveBeenCalledTimes(3);
      expect(cb.getState()).toBe('closed');
    });
  });

  describe('Transition to OPEN', () => {
    it('should transition to OPEN after threshold failures', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('fail'));

      await expect(cb.execute(fn)).rejects.toThrow('fail');
      expect(cb.getState()).toBe('closed');
      expect(cb.getState() === 'closed').toBe(true);

      await expect(cb.execute(fn)).rejects.toThrow('fail');
      expect(cb.getState()).toBe('closed');

      await expect(cb.execute(fn)).rejects.toThrow('fail');
      expect(cb.getState()).toBe('open');
    });

    it('should not transition to OPEN before reaching threshold', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('fail'));

      await expect(cb.execute(fn)).rejects.toThrow('fail');
      expect(cb.getState()).toBe('closed');

      await expect(cb.execute(fn)).rejects.toThrow('fail');
      expect(cb.getState()).toBe('closed');
    });
  });

  describe('OPEN state', () => {
    it('should reject requests immediately when OPEN', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      await expect(cb.execute(fn)).rejects.toThrow('fail');

      // Now should reject without calling fn
      const successFn = vi.fn().mockResolvedValue('success');
      await expect(cb.execute(successFn)).rejects.toThrow(/Circuit breaker .* is open/);
      expect(successFn).not.toHaveBeenCalled();
    });

    it('should stay OPEN within cooldown period', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      await expect(cb.execute(fn)).rejects.toThrow('fail');

      expect(cb.getState()).toBe('open');

      // Try immediately (within cooldown)
      const testFn = vi.fn().mockResolvedValue('success');
      await expect(cb.execute(testFn)).rejects.toThrow(/is open/);
      expect(testFn).not.toHaveBeenCalled();
    });
  });

  describe('Transition to HALF_OPEN', () => {
    it('should transition to HALF_OPEN after cooldown', async () => {
      const cbShort = new CircuitBreaker('test', 2, 50); // 50ms cooldown
      const fn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state
      await expect(cbShort.execute(fn)).rejects.toThrow('fail');
      await expect(cbShort.execute(fn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('open');

      // Wait for cooldown (fake timers — advance the mocked clock past the 50ms cooldown)
      await vi.advanceTimersByTimeAsync(100);

      // Should transition to HALF_OPEN on next call
      const successFn = vi.fn().mockResolvedValue('success');
      const result = await cbShort.execute(successFn);

      expect(result).toBe('success');
      expect(cbShort.getState()).toBe('closed');
      expect(successFn).toHaveBeenCalled();
    });
  });

  describe('HALF_OPEN state', () => {
    it('should transition to CLOSED on successful test request', async () => {
      const cbShort = new CircuitBreaker('test', 1, 50);
      const failFn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state
      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('open');

      // Wait for cooldown (fake timers — advance the mocked clock past the 50ms cooldown)
      await vi.advanceTimersByTimeAsync(100);

      // Successful test request should close circuit
      const successFn = vi.fn().mockResolvedValue('success');
      await cbShort.execute(successFn);

      expect(cbShort.getState()).toBe('closed');
    });

    it('should transition back to OPEN on failed test request', async () => {
      const cbShort = new CircuitBreaker('test', 1, 50);
      const failFn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state
      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('open');

      // Wait for cooldown (fake timers — advance the mocked clock past the 50ms cooldown)
      await vi.advanceTimersByTimeAsync(100);

      // Failed test request should reopen circuit
      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('open');
    });

    it('should reset failure count on successful HALF_OPEN request', async () => {
      const cbShort = new CircuitBreaker('test', 2, 50);
      const failFn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state with 2 failures (reaching threshold)
      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('closed');
      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('open');

      // Wait for cooldown (fake timers — advance the mocked clock past the 50ms cooldown)
      await vi.advanceTimersByTimeAsync(100);

      // Successful request should reset counter and close circuit
      const successFn = vi.fn().mockResolvedValue('success');
      await cbShort.execute(successFn);
      expect(cbShort.getState()).toBe('closed');

      // Should now allow 2 more failures before opening again
      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('closed');

      await expect(cbShort.execute(failFn)).rejects.toThrow('fail');
      expect(cbShort.getState()).toBe('open');
    });
  });

  describe('Reset functionality', () => {
    it('should reset circuit to CLOSED state', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('fail'));

      // Trigger OPEN state
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      await expect(cb.execute(fn)).rejects.toThrow('fail');
      expect(cb.getState()).toBe('open');

      // Reset
      cb.reset();
      expect(cb.getState()).toBe('closed');

      // Should now allow requests
      const successFn = vi.fn().mockResolvedValue('success');
      await cb.execute(successFn);
      expect(successFn).toHaveBeenCalled();
    });
  });

  describe('Error propagation', () => {
    it('should propagate errors from wrapped function', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('specific error'));

      await expect(cb.execute(fn)).rejects.toThrow('specific error');
    });

    it('should propagate custom error types', async () => {
      class CustomError extends Error {
        constructor(message: string) {
          super(message);
          this.name = 'CustomError';
        }
      }

      const fn = vi.fn().mockRejectedValue(new CustomError('custom error'));

      await expect(cb.execute(fn)).rejects.toBeInstanceOf(CustomError);
    });
  });
});

/**
 * Unit tests — EventBus in-process pub/sub (V1.1 M2, W1).
 *
 * Verifies publish/subscribe semantics, per-execution isolation, the returned
 * unsubscribe function, per-execution cleanup, and that a throwing listener is
 * isolated so it can never break the publisher or sibling subscribers.
 */

import { describe, it, expect, vi } from 'vitest';
import { EventBus, type ExecutionBusEvent } from '../../../packages/engine/src/eventBus';

function event(executionId: string, overrides: Partial<ExecutionBusEvent> = {}): ExecutionBusEvent {
  return {
    type: 'node_started',
    executionId,
    nodeId: 'node_a',
    nodeType: 'vault.search',
    status: 'running',
    timestamp: new Date().toISOString(),
    ...overrides,
  };
}

describe('EventBus — publish / subscribe / cleanup', () => {
  it('delivers a published event to subscribers of that execution', () => {
    const bus = new EventBus();
    const listener = vi.fn();
    bus.subscribe('exec-1', listener);

    const evt = event('exec-1');
    bus.publish(evt);

    expect(listener).toHaveBeenCalledTimes(1);
    expect(listener).toHaveBeenCalledWith(evt);
  });

  it('does not deliver events across different executionIds', () => {
    const bus = new EventBus();
    const l1 = vi.fn();
    const l2 = vi.fn();
    bus.subscribe('exec-1', l1);
    bus.subscribe('exec-2', l2);

    bus.publish(event('exec-1'));

    expect(l1).toHaveBeenCalledTimes(1);
    expect(l2).not.toHaveBeenCalled();
  });

  it('supports multiple subscribers per execution', () => {
    const bus = new EventBus();
    const a = vi.fn();
    const b = vi.fn();
    bus.subscribe('exec-1', a);
    bus.subscribe('exec-1', b);

    bus.publish(event('exec-1'));

    expect(a).toHaveBeenCalledTimes(1);
    expect(b).toHaveBeenCalledTimes(1);
    expect(bus.subscriberCount('exec-1')).toBe(2);
  });

  it('returns an unsubscribe function that removes exactly that listener', () => {
    const bus = new EventBus();
    const keep = vi.fn();
    const drop = vi.fn();
    bus.subscribe('exec-1', keep);
    const unsub = bus.subscribe('exec-1', drop);

    unsub();
    bus.publish(event('exec-1'));

    expect(keep).toHaveBeenCalledTimes(1);
    expect(drop).not.toHaveBeenCalled();
    expect(bus.subscriberCount('exec-1')).toBe(1);
  });

  it('unsubscribe is idempotent and drops the empty bucket', () => {
    const bus = new EventBus();
    const listener = vi.fn();
    const unsub = bus.subscribe('exec-1', listener);

    unsub();
    unsub(); // second call is a no-op
    expect(bus.subscriberCount('exec-1')).toBe(0);

    bus.publish(event('exec-1'));
    expect(listener).not.toHaveBeenCalled();
  });

  it('clear() removes every subscriber for an execution only', () => {
    const bus = new EventBus();
    const a = vi.fn();
    const b = vi.fn();
    const other = vi.fn();
    bus.subscribe('exec-1', a);
    bus.subscribe('exec-1', b);
    bus.subscribe('exec-2', other);

    bus.clear('exec-1');

    expect(bus.subscriberCount('exec-1')).toBe(0);
    expect(bus.subscriberCount('exec-2')).toBe(1);
    bus.publish(event('exec-1'));
    bus.publish(event('exec-2'));
    expect(a).not.toHaveBeenCalled();
    expect(b).not.toHaveBeenCalled();
    expect(other).toHaveBeenCalledTimes(1);
  });

  it('isolates a throwing listener so siblings still receive the event', () => {
    const bus = new EventBus();
    const bad = vi.fn(() => {
      throw new Error('listener boom');
    });
    const good = vi.fn();
    bus.subscribe('exec-1', bad);
    bus.subscribe('exec-1', good);

    // Must not throw despite the bad listener.
    expect(() => bus.publish(event('exec-1'))).not.toThrow();
    expect(bad).toHaveBeenCalledTimes(1);
    expect(good).toHaveBeenCalledTimes(1);
  });

  it('publishing to an execution with no subscribers is a no-op', () => {
    const bus = new EventBus();
    expect(() => bus.publish(event('exec-ghost'))).not.toThrow();
    expect(bus.subscriberCount('exec-ghost')).toBe(0);
  });
});

/**
 * Unit tests — EventLog best-effort recording (V1.1 M1, F1).
 *
 * recordEvent must write through to StateStore.events.append on the happy path
 * and must NEVER throw when the store fails — a lost event cannot break a run.
 */

import { describe, it, expect, vi } from 'vitest';
import { recordEvent } from '../../../packages/engine/src/eventLog';
import type { StateStore } from '../../../packages/state/src';

/** Build a StateStore stub whose events.append is the given impl. */
function storeWithAppend(append: StateStore['events']['append']): StateStore {
  return { events: { append, listByExecution: async () => [] } } as unknown as StateStore;
}

describe('EventLog — recordEvent (best-effort)', () => {
  it('writes an event through to the store', async () => {
    const append = vi.fn(async () => {});
    const store = storeWithAppend(append);

    await recordEvent(store, 'exec-1', 'node_succeeded', 'node_a', { duration_ms: 5 });

    expect(append).toHaveBeenCalledTimes(1);
    const arg = append.mock.calls[0]![0];
    expect(arg.execution_id).toBe('exec-1');
    expect(arg.event_type).toBe('node_succeeded');
    expect(arg.node_id).toBe('node_a');
    expect(arg.payload).toMatchObject({ duration_ms: 5 });
    expect(typeof arg.id).toBe('string');
    expect(typeof arg.created_at).toBe('number');
  });

  it('swallows store write failures (never breaks execution)', async () => {
    const append = vi.fn(async () => {
      throw new Error('disk full');
    });
    const store = storeWithAppend(append);

    // Must resolve, not reject, even though the underlying write throws.
    await expect(recordEvent(store, 'exec-1', 'execution_failed')).resolves.toBeUndefined();
    expect(append).toHaveBeenCalledTimes(1);
  });

  it('omits node_id for execution-level events', async () => {
    const append = vi.fn(async () => {});
    const store = storeWithAppend(append);

    await recordEvent(store, 'exec-1', 'execution_started');

    expect(append.mock.calls[0]![0].node_id).toBeUndefined();
  });
});

