}

describe('ExecutionExecutor — EventBus status fan-out', () => {
  const conns: SqliteConnection[] = [];

  afterEach(() => {
    while (conns.length > 0) {
      conns.pop()!.close();
    }
  });

  it('publishes node_started → node_succeeded and execution lifecycle for a passing node', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(okAdapter('vault'));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('node_a', 'vault.op')],
      edges: [],
      variables: {},
      metadata: { name: 'events-ok' },
    };
    const executionId = await seedExecution(store, definition);

    const bus = new EventBus();
    const events: ExecutionBusEvent[] = [];
    bus.subscribe(executionId, (e) => events.push(e));

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, bus);
    await executor.execute(executionId, definition, {});

    const types = events.map((e) => e.type);
    expect(types).toContain('execution_started');
    expect(types).toContain('node_started');
    expect(types).toContain('node_succeeded');
    expect(types).toContain('execution_succeeded');

    const started = events.find((e) => e.type === 'node_started');
    expect(started?.nodeId).toBe('node_a');
    expect(started?.nodeType).toBe('vault.op');
    expect(started?.status).toBe('running');

    const succeeded = events.find((e) => e.type === 'node_succeeded');
    expect(succeeded?.status).toBe('succeeded');
    expect(succeeded?.output).toMatchObject({ ok: true });
    expect(typeof succeeded?.durationMs).toBe('number');

    // Every event is scoped to this execution.
    expect(events.every((e) => e.executionId === executionId)).toBe(true);
  });

  it('publishes node_failed and execution_failed when a node throws', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(failingAdapter('desk'));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('node_x', 'desk.op')],
      edges: [],
      variables: {},
      metadata: { name: 'events-fail' },
    };
    const executionId = await seedExecution(store, definition);

    const bus = new EventBus();
    const events: ExecutionBusEvent[] = [];
    bus.subscribe(executionId, (e) => events.push(e));

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, bus);
    await expect(executor.execute(executionId, definition, {})).rejects.toThrow(/adapter exploded/);

    const failed = events.find((e) => e.type === 'node_failed');
    expect(failed?.nodeId).toBe('node_x');
    expect(failed?.status).toBe('failed');
    expect(failed?.error).toMatch(/adapter exploded/);

    const execFailed = events.find((e) => e.type === 'execution_failed');
    expect(execFailed?.status).toBe('failed');
    expect(execFailed?.error).toMatch(/adapter exploded/);
  });

  it('still succeeds with no subscribers attached (publish is a no-op)', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(okAdapter('vault'));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('node_a', 'vault.op')],
      edges: [],
      variables: {},
      metadata: { name: 'events-noop' },
    };
    const executionId = await seedExecution(store, definition);

    // A bus with zero subscribers — execution must be unaffected.
    const bus = new EventBus();
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, bus);
    await executor.execute(executionId, definition, {});

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');
  });
});

/**
 * Unit tests — V1.1 M1 executor reliability:
 *   - F1 resume: a re-run skips already-succeeded nodes (no duplicate dispatch),
 *   - F2 idempotency: re-executing the same execution reuses succeeded outputs,
 *   - F3 workflow-level timeout: a hung run fails with reason workflow_timeout.
 */

import { describe, it, expect, afterEach } from 'vitest';
import {
  createSqliteConnection,
  SqliteStateStore,
  type SqliteConnection,
} from '../../../packages/state/src';
import { ConnectorRegistry, type ConnectorAdapter } from '../../../packages/connectors/src';
import { ExecutionExecutor } from '../../../packages/engine/src/executor';
import type { WorkflowDefinition, ConnectorCapabilities } from '../../../packages/types/src';

/** Adapter that counts execute() invocations. */
function createCountingAdapter(type: string, hang = false): { adapter: ConnectorAdapter; counter: { calls: number } } {
  const counter = { calls: 0 };
  const adapter: ConnectorAdapter = {
    type,
    async execute() {
      counter.calls += 1;
      if (hang) {
        return new Promise<never>(() => {
          /* never settles */
        });
      }
      return { output: { ok: true, n: counter.calls } };
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
  return { adapter, counter };
}

async function createStore(): Promise<{ conn: SqliteConnection; store: SqliteStateStore }> {
  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  const store = new SqliteStateStore(conn);
  await store.initialise();
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: '',
    email: 'system@loop.internal',
    role: 'admin',
  });
  return { conn, store };
}

async function seedExecution(store: SqliteStateStore, definition: WorkflowDefinition): Promise<string> {
  const workflowId = crypto.randomUUID();
  await store.workflows.create({
    id: workflowId,
    name: 'Resume test',
    description: '',
    definition,
    created_by: 'system',
  });
  const executionId = crypto.randomUUID();
  await store.executions.create({
    id: executionId,
    workflow_id: workflowId,
    workflow_version: 1,
    trigger_type: 'manual',
  });
  return executionId;
}

function node(id: string, type: string) {
  return { id, type, position: { x: 0, y: 0 }, config: {} };
}

const TWO_NODE: WorkflowDefinition = {
  version: '1.0',
  nodes: [node('a', 'track.op'), node('b', 'track.op')],
  edges: [{ id: 'e', source: 'a', target: 'b' }],
  variables: {},
  metadata: { name: 'two-node' },
};

describe('ExecutionExecutor — resume (V1.1 M1 F1)', () => {
  const conns: SqliteConnection[] = [];
  afterEach(() => {
    while (conns.length > 0) conns.pop()!.close();
  });

  it('skips already-succeeded nodes and dispatches only the rest', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter, counter } = createCountingAdapter('track');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    const executionId = await seedExecution(store, TWO_NODE);

    // Simulate a prior interrupted run: node 'a' already succeeded.
    const neId = crypto.randomUUID();
    await store.nodeExecutions.create({
      id: neId,
      execution_id: executionId,
      node_id: 'a',
      node_type: 'track.op',
      idempotency_key: `${executionId}:a`,
    });
    await store.nodeExecutions.updateStatus(neId, {
      status: 'succeeded',
      output: { ok: true, cached: true },
      completed_at: new Date().toISOString(),
    });

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await executor.execute(executionId, TWO_NODE, {});

    // Only node 'b' was dispatched; 'a' was reused.
    expect(counter.calls).toBe(1);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');

    // A node_skipped event was recorded for 'a'.
    const events = await store.events.listByExecution(executionId);
    const skipped = events.filter((e) => e.event_type === 'node_skipped');
    expect(skipped).toHaveLength(1);
    expect(skipped[0]!.node_id).toBe('a');
  });

  it('re-executing a completed run re-dispatches nothing (idempotent)', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter, counter } = createCountingAdapter('track');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    const executionId = await seedExecution(store, TWO_NODE);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);

    await executor.execute(executionId, TWO_NODE, {});
    expect(counter.calls).toBe(2);

    // Second run over the same execution: both nodes already succeeded → skipped.
    await executor.execute(executionId, TWO_NODE, {});
    expect(counter.calls).toBe(2); // unchanged

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');
  });

  it('writes a stable idempotency key per node execution', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter } = createCountingAdapter('track');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    const executionId = await seedExecution(store, TWO_NODE);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await executor.execute(executionId, TWO_NODE, {});

    const nodes = await store.nodeExecutions.listByExecution(executionId);
    const keys = nodes.map((n) => n.idempotency_key).sort();
    expect(keys).toEqual([`${executionId}:a`, `${executionId}:b`]);
  });
});

describe('ExecutionExecutor — workflow timeout (V1.1 M1 F3)', () => {
  const conns: SqliteConnection[] = [];
  afterEach(() => {
    while (conns.length > 0) conns.pop()!.close();
  });

  it('fails the execution with reason workflow_timeout when the deadline elapses', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter } = createCountingAdapter('hang', true);
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    // Per-definition workflow timeout (200ms) overrides the large executor default.
    // V1.5 M1 (F-4', TH2): widened 50ms→200ms so the deadline timer is not starved
    // under high load; the node still hangs, so the workflow timeout always wins.
    const definition: WorkflowDefinition = {
      ...TWO_NODE,
      nodes: [node('stuck', 'hang.op')],
      edges: [],
      settings: { workflow_timeout_ms: 200 },
    };
    const executionId = await seedExecution(store, definition);

    // Node timeout is large so the NODE-level timer never fires first.
    const executor = new ExecutionExecutor(store, connectors, 10, 60_000);
    await expect(executor.execute(executionId, definition, {})).rejects.toThrow(/workflow_timeout/);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('failed');
    expect(execution?.error).toMatch(/workflow_timeout/);

    const events = await store.events.listByExecution(executionId);
    const failed = events.find((e) => e.event_type === 'execution_failed');
    expect(failed).toBeDefined();
    expect(failed!.payload).toMatchObject({ reason: 'workflow_timeout' });
  });

  it('does not time out a fast workflow when the deadline is generous', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter } = createCountingAdapter('track');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    const definition: WorkflowDefinition = { ...TWO_NODE, settings: { workflow_timeout_ms: 60_000 } };
    const executionId = await seedExecution(store, definition);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);

    await executor.execute(executionId, definition, {});
    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');
  });
});

/**
 * Unit tests — `workflow.invoke` sub-workflow invocation (V1.2 M3, F-Loop-1).
 *
 * Verifies the engine-built-in node (NOT a connector):
 *   - S1: a parent invokes an inline child that runs on the same executor and
 *         returns `{ outputs, status: 'succeeded' }`; a failing child fails the
 *         parent node.
 *   - S2: recursion is bounded by `maxSubWorkflowDepth` (SUBWORKFLOW_DEPTH_EXCEEDED),
 *         plus a visited-set cycle guard for self-invoking workflows.
 *   - S3: parent `input.inputs` maps onto the child `trigger.payload`, and the
 *         child's outputs are reachable by a downstream parent node via the
 *         usual `{{node_X.output.*}}` interpolation.
 *   - S4: every child event is tagged with `parentExecutionId` on the shared bus.
 */

import { describe, it, expect, afterEach } from 'vitest';
import { createSqliteConnection, SqliteStateStore, type SqliteConnection } from '../../../packages/state/src';
import { ConnectorRegistry, type ConnectorAdapter } from '../../../packages/connectors/src';
import { ExecutionExecutor } from '../../../packages/engine/src/executor';
import { EventBus, type ExecutionBusEvent } from '../../../packages/engine/src/eventBus';
import { LoopError } from '../../../packages/types/src/errors';
import type { WorkflowDefinition, ConnectorCapabilities } from '../../../packages/types/src';

/** Recording adapter: captures every resolved input, echoes a `value` output. */
function recordingAdapter(type: string, calls: Record<string, unknown>[]): ConnectorAdapter {
  return {
    type,
    async execute({ input }) {
      calls.push(input);
      const value = input['echo'] ?? input['received'] ?? null;
      return { output: { value, ok: true } };
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
}

function failingAdapter(type: string): ConnectorAdapter {
  return {
    type,
    async execute() {
      throw new Error('child adapter exploded');
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
}

interface Ctx {
  conn: SqliteConnection;
  store: SqliteStateStore;
}

async function createStore(): Promise<Ctx> {
  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  const store = new SqliteStateStore(conn);
  await store.initialise();
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: '',
    email: 'system@loop.internal',
    role: 'admin',
    display_name: 'System',
  });
  return { conn, store };
}

async function seedExecution(store: SqliteStateStore, definition: WorkflowDefinition): Promise<string> {
  const workflowId = `wf-${crypto.randomUUID()}`;
  await store.workflows.create({
    id: workflowId,
    name: 'Sub-workflow unit test',
    description: '',
    definition,
    created_by: 'system',
  });
  const executionId = `exec-${crypto.randomUUID()}`;
  await store.executions.create({
    id: executionId,
    workflow_id: workflowId,
    workflow_version: 1,
    trigger_type: 'manual',
    trigger_payload: {},
  });
  return executionId;
}

/** A single mock-connector node that echoes `trigger.payload.greeting`. */
function leafDefinition(name: string): WorkflowDefinition {
  return {
    version: '1.0',
    nodes: [
      {
        id: 'node_c1',
        type: 'mock.op',
        position: { x: 0, y: 0 },
        config: { echo: '{{trigger.payload.greeting}}' },
      },
    ],
    edges: [],
    variables: {},
    metadata: { name },
  };
}

/**
 * Wrap `leaf` in `depth` nested `workflow.invoke` definitions (distinct names so
 * the cycle guard does not fire — only the depth ceiling does). The outermost
 * wrapper is what the test executes as the root.
 */
function nestedInvokeChain(depth: number, leaf: WorkflowDefinition): WorkflowDefinition {
  let current = leaf;
  for (let i = 0; i < depth; i++) {
    current = {
      version: '1.0',
      nodes: [
        {
          id: 'node_invoke',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { definition: current },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: `chain-${i}` },
    };
  }
  return current;
}

describe('ExecutionExecutor — workflow.invoke sub-workflows (V1.2 M3)', () => {
  const conns: SqliteConnection[] = [];

  afterEach(() => {
    while (conns.length > 0) {
      conns.pop()!.close();
    }
  });

  it('S1/S3: invokes an inline child, maps inputs, and exposes child outputs downstream', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const calls: Record<string, unknown>[] = [];
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(recordingAdapter('mock', calls));

    const child = leafDefinition('child');
    const parent: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'node_sub',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { definition: child, inputs: { greeting: 'hello-from-parent' } },
        },
        {
          id: 'node_downstream',
          type: 'mock.op',
          position: { x: 200, y: 0 },
          config: { received: '{{node_sub.output.outputs.node_c1.value}}' },
        },
      ],
      edges: [{ id: 'e1', source: 'node_sub', target: 'node_downstream' }],
      variables: {},
      metadata: { name: 'parent' },
    };
    const executionId = await seedExecution(store, parent);

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await executor.execute(executionId, parent, {});

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');

    // S3 input mapping: the child node saw the parent-supplied payload value.
    expect(calls).toContainEqual({ echo: 'hello-from-parent' });
    // S3 output return: the downstream parent node consumed the child output
    // via {{node_sub.output.outputs.node_c1.value}} interpolation.
    expect(calls).toContainEqual({ received: 'hello-from-parent' });

    // The invoke node's stored output carries the child's outputs + status.
    const nodeExecs = await store.nodeExecutions.listByExecution(executionId);
    const invokeRow = nodeExecs.find((n) => n.node_id === 'node_sub');
    expect(invokeRow?.status).toBe('succeeded');
    expect(invokeRow?.output).toMatchObject({ status: 'succeeded' });
    expect(invokeRow?.output['outputs']).toMatchObject({ node_c1: { value: 'hello-from-parent' } });

    // The child ran as its own execution (a separate execution row exists).
    const allExecutions = await store.executions.list({}, { page: 1, per_page: 10 });
    expect(allExecutions.total).toBeGreaterThanOrEqual(2);
  });

  it('S1: a failing child fails the parent node and the execution', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(failingAdapter('mock'));

    const child = leafDefinition('failing-child');
    const parent: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'node_sub',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { definition: child, inputs: { greeting: 'x' } },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: 'parent-fail' },
    };
    const executionId = await seedExecution(store, parent);

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await expect(executor.execute(executionId, parent, {})).rejects.toThrow(/child adapter exploded/);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('failed');
  });

  it('S2: exceeding maxSubWorkflowDepth throws SUBWORKFLOW_DEPTH_EXCEEDED', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(recordingAdapter('mock', []));

    // 5 nested invokes around a leaf, but the executor caps recursion at 2.
    const definition = nestedInvokeChain(5, leafDefinition('leaf'));
    const executionId = await seedExecution(store, definition);

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, new EventBus(), 2);
    const err = await executor.execute(executionId, definition, {}).catch((e: unknown) => e);

    expect(err).toBeInstanceOf(LoopError);
    expect((err as LoopError).code).toBe('SUBWORKFLOW_DEPTH_EXCEEDED');
    expect((err as LoopError).message).toMatch(/exceeds the maximum of 2/);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('failed');
  });

  it('S2: a self-invoking stored workflow is stopped by the cycle guard', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(recordingAdapter('mock', []));

    const workflowId = `wf-${crypto.randomUUID()}`;
    const selfDef: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'node_loop',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { workflow_id: workflowId },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: 'self-invoking' },
    };
    await store.workflows.create({
      id: workflowId,
      name: 'self-invoking',
      description: '',
      definition: selfDef,
      created_by: 'system',
    });
    const executionId = `exec-${crypto.randomUUID()}`;
    await store.executions.create({
      id: executionId,
      workflow_id: workflowId,
      workflow_version: 1,
      trigger_type: 'manual',
      trigger_payload: {},
    });

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    const err = await executor.execute(executionId, selfDef, {}).catch((e: unknown) => e);

    expect(err).toBeInstanceOf(LoopError);
    expect((err as LoopError).code).toBe('SUBWORKFLOW_DEPTH_EXCEEDED');
    expect((err as LoopError).message).toMatch(/cycle detected/);
  });

  it('S4: tags every child event with parentExecutionId on the shared bus', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const calls: Record<string, unknown>[] = [];
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(recordingAdapter('mock', calls));

    const child = leafDefinition('child-events');
    const parent: WorkflowDefinition = {
      version: '1.0',
      nodes: [
        {
          id: 'node_sub',
          type: 'workflow.invoke',
          position: { x: 0, y: 0 },
          config: { definition: child, inputs: { greeting: 'hi' } },
        },
      ],
      edges: [],
      variables: {},
      metadata: { name: 'parent-events' },
    };
    const executionId = await seedExecution(store, parent);

    const bus = new EventBus();
    const all: ExecutionBusEvent[] = [];
    const original = bus.publish.bind(bus);
    bus.publish = (event: ExecutionBusEvent): void => {
      all.push(event);
      original(event);
    };

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000, 30_000, bus);
    await executor.execute(executionId, parent, {});

    // Child events are tagged with the parent execution id...
    const childEvents = all.filter((e) => e.parentExecutionId === executionId);
    expect(childEvents.length).toBeGreaterThan(0);
    expect(childEvents.some((e) => e.type === 'execution_started')).toBe(true);
    expect(childEvents.some((e) => e.type === 'node_succeeded')).toBe(true);
    // ...and belong to a DIFFERENT (child) execution.
    expect(childEvents.every((e) => e.executionId !== executionId)).toBe(true);

    // Root events are NOT tagged with a parent.
    const rootStarted = all.find((e) => e.type === 'execution_started' && e.executionId === executionId);
    expect(rootStarted?.parentExecutionId).toBeUndefined();
  });
});

/**
 * V1.6 M1 (F-2, SP3): executor span tree.
 *
 * A successful run emits one `loop.execution` root span parenting one
 * `loop.node` span per dispatched node; a failing run marks the execution and
 * failing node spans `error`; with sampling off the executor emits no spans
 * and behaves identically. Tracing never changes execution results.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';

import type { SqliteStateStore } from '../../../packages/state/src/index.js';
import { ConnectorRegistry, type ConnectorAdapter } from '../../../packages/connectors/src/index.js';
import { ExecutionExecutor } from '../../../packages/engine/src/executor.js';
import { EventBus } from '../../../packages/engine/src/eventBus.js';
import {
  configureTracing,
  resetTracing,
  type SpanData,
  type SpanExporter,
} from '../../../packages/observability/src/index.js';
import type { WorkflowDefinition, ConnectorCapabilities } from '../../../packages/types/src/index.js';
import { withSeededTestStore } from '../../helpers/testStore.js';

function okAdapter(type: string): ConnectorAdapter {
  return {
    type,
    async execute() {
      return { output: { ok: true } };
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
}

function failingAdapter(type: string): ConnectorAdapter {
  return {
    type,
    async execute() {
      throw new Error('adapter exploded');
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
}

async function seedExecution(store: SqliteStateStore, definition: WorkflowDefinition): Promise<string> {
  const workflowId = `wf-${crypto.randomUUID()}`;
  await store.workflows.create({
    id: workflowId,
    name: 'Tracing executor test',
    description: '',
    definition,
    created_by: 'system',
  });
  const executionId = `exec-${crypto.randomUUID()}`;
  await store.executions.create({
    id: executionId,
    workflow_id: workflowId,
    workflow_version: 1,
    trigger_type: 'manual',
    trigger_payload: {},
  });
  return executionId;
}

function node(id: string, type: string) {
  return { id, type, position: { x: 0, y: 0 }, config: {} };
}

/** Two-node chain: node_a → node_b. */
const CHAIN_DEFINITION: WorkflowDefinition = {
  version: '1.0',
  nodes: [node('node_a', 'mock.op'), node('node_b', 'mock.op')],
  edges: [{ id: 'a->b', source: 'node_a', target: 'node_b' }],
  variables: {},
  metadata: { name: 'tracing-chain' },
};

describe('ExecutionExecutor — span tree (V1.6 F-2)', () => {
  let spans: SpanData[];
  const exporter: SpanExporter = {
    export(span: SpanData): void {
      spans.push(span);
    },
  };

  beforeEach(() => {
    spans = [];
    resetTracing();
    configureTracing({ exporter, sampleRate: 1 });
  });

  afterEach(() => {
    resetTracing();
  });

  it('emits an execution span parenting one span per node', async () => {
    await withSeededTestStore(async ({ store }) => {
      const connectors = new ConnectorRegistry();
      connectors.registerAdapter(okAdapter('mock'));
      const executor = new ExecutionExecutor(store, connectors, 5, 2000, 10_000, new EventBus());

      const executionId = await seedExecution(store, CHAIN_DEFINITION);
      await executor.execute(executionId, CHAIN_DEFINITION, {});

      const executionSpans = spans.filter((s) => s.name === 'loop.execution');
      const nodeSpans = spans.filter((s) => s.name === 'loop.node');
      expect(executionSpans).toHaveLength(1);
      expect(nodeSpans).toHaveLength(2);

      const executionSpan = executionSpans[0]!;
      expect(executionSpan.parent_span_id).toBeUndefined();
      expect(executionSpan.status).toBe('ok');
      expect(executionSpan.attrs?.['execution.id']).toBe(executionId);
      expect(executionSpan.attrs?.['workflow.id']).toBe('tracing-chain');
      expect(executionSpan.duration_ms).toBeGreaterThanOrEqual(0);

      // Every node span is a child of the execution span, same trace.
      for (const ns of nodeSpans) {
        expect(ns.parent_span_id).toBe(executionSpan.span_id);
        expect(ns.trace_id).toBe(executionSpan.trace_id);
        expect(ns.status).toBe('ok');
      }
      const nodeIds = nodeSpans.map((s) => s.attrs?.['node.id']).sort();
      expect(nodeIds).toEqual(['node_a', 'node_b']);
      for (const ns of nodeSpans) {
        expect(ns.attrs?.['node.type']).toBe('mock.op');
      }
    });
  });

  it('marks the execution and failing node spans error without changing the outcome', async () => {
    await withSeededTestStore(async ({ store }) => {
      const connectors = new ConnectorRegistry();
      connectors.registerAdapter(failingAdapter('bad'));
      const executor = new ExecutionExecutor(store, connectors, 5, 2000, 10_000, new EventBus());

      const definition: WorkflowDefinition = {
        version: '1.0',
        nodes: [node('node_x', 'bad.op')],
        edges: [],
        variables: {},
        metadata: { name: 'tracing-failure' },
      };
      const executionId = await seedExecution(store, definition);

      // Execution still fails exactly as before tracing existed.
      await expect(executor.execute(executionId, definition, {})).rejects.toThrow('adapter exploded');

      const executionSpan = spans.find((s) => s.name === 'loop.execution');
      const nodeSpan = spans.find((s) => s.name === 'loop.node');
      expect(executionSpan?.status).toBe('error');
      expect(executionSpan?.attrs?.['error.message']).toContain('adapter exploded');
      expect(nodeSpan?.status).toBe('error');
      expect(nodeSpan?.parent_span_id).toBe(executionSpan?.span_id);
    });
  });

  it('sampling off — no spans emitted, execution result unchanged', async () => {
    configureTracing({ exporter, sampleRate: 0 });

    await withSeededTestStore(async ({ store }) => {
      const connectors = new ConnectorRegistry();
      connectors.registerAdapter(okAdapter('mock'));
      const executor = new ExecutionExecutor(store, connectors, 5, 2000, 10_000, new EventBus());

      const executionId = await seedExecution(store, CHAIN_DEFINITION);
      await executor.execute(executionId, CHAIN_DEFINITION, {});

      const execution = await store.executions.getById(executionId);
      expect(execution?.status).toBe('succeeded');
      expect(spans).toHaveLength(0);
    });
  });
});

/**
 * Unit tests — ExecutionExecutor parallel level scheduling + node timeout (§6.2).
 *
 * Uses an in-memory SQLite store and timing/concurrency-tracking mock adapters
 * to verify that:
 *   - independent nodes in the same topological level run concurrently,
 *   - `maxConcurrent` bounds the in-flight node count,
 *   - a node that exceeds its timeout fails the execution (NODE_TIMEOUT).
 */

import { describe, it, expect, afterEach } from 'vitest';
import { createSqliteConnection, SqliteStateStore, type SqliteConnection } from '../../../packages/state/src';
import { ConnectorRegistry, type ConnectorAdapter } from '../../../packages/connectors/src';
import { ExecutionExecutor } from '../../../packages/engine/src/executor';
import type { WorkflowDefinition, ConnectorCapabilities } from '../../../packages/types/src';

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Mock adapter that tracks concurrency and adds a configurable per-call delay. */
function createTrackingAdapter(type: string, delayMs: number): {
  adapter: ConnectorAdapter;
  stats: { inFlight: number; maxInFlight: number; calls: number };
} {
  const stats = { inFlight: 0, maxInFlight: 0, calls: 0 };
  const adapter: ConnectorAdapter = {
    type,
    async execute() {
      stats.calls += 1;
      stats.inFlight += 1;
      stats.maxInFlight = Math.max(stats.maxInFlight, stats.inFlight);
      try {
        await sleep(delayMs);
        return { output: { ok: true } };
      } finally {
        stats.inFlight -= 1;
      }
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
  return { adapter, stats };
}

/** Mock adapter whose execute() never resolves — used to trigger the timeout. */
function createHangingAdapter(type: string): ConnectorAdapter {
  return {
    type,
    async execute() {
      return new Promise<never>(() => {
        /* never settles */
      });
    },
    async healthCheck() {
      return true;
    },
    getCapabilities(): ConnectorCapabilities {
      return { node_types: [`${type}.op`], input_types: ['any'], output_types: ['any'] };
    },
  };
}

interface Ctx {
  conn: SqliteConnection;
  store: SqliteStateStore;
}

async function createStore(): Promise<Ctx> {
  const conn = createSqliteConnection({ path: ':memory:', wal: false });
  const store = new SqliteStateStore(conn);
  await store.initialise();
  await store.users.create({
    id: 'system',
    username: 'system',
    password_hash: '',
    email: 'system@loop.internal',
    role: 'admin',
