describe('ExecutionExecutor — parallel levels & timeout', () => {
  const conns: SqliteConnection[] = [];

  afterEach(async () => {
    while (conns.length > 0) {
      conns.pop()!.close();
    }
  });

  it('runs independent nodes in the same level concurrently', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter, stats } = createTrackingAdapter('slow', 80);
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    // Two independent roots → both land in level 0 and run in parallel.
    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('a', 'slow.op'), node('b', 'slow.op')],
      edges: [],
      variables: {},
      metadata: { name: 'parallel' },
    };
    const executionId = await seedExecution(store, definition);

    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    const started = Date.now();
    await executor.execute(executionId, definition, {});
    const elapsed = Date.now() - started;

    expect(stats.calls).toBe(2);
    // Both nodes were in flight at once → genuine parallelism. This event-driven
    // counter is the authoritative proof of concurrency (it never flakes under load).
    expect(stats.maxInFlight).toBe(2);
    // V1.5 M1 (F-4', TH2): wall-clock sanity bound only. The previous 160ms ceiling
    // (just under the ~160ms sequential cost) raced OS scheduling jitter under high
    // load; the generous 1500ms cap still asserts the run completes promptly (well
    // under the 5000ms node timeout) while parallelism is proven by maxInFlight above.
    expect(elapsed).toBeLessThan(1500);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');
  });

  it('respects maxConcurrent by batching nodes within a level', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const { adapter, stats } = createTrackingAdapter('slow', 40);
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(adapter);

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('a', 'slow.op'), node('b', 'slow.op'), node('c', 'slow.op')],
      edges: [],
      variables: {},
      metadata: { name: 'batched' },
    };
    const executionId = await seedExecution(store, definition);

    // maxConcurrent = 1 → nodes run one at a time despite sharing a level.
    const executor = new ExecutionExecutor(store, connectors, 1, 5_000);
    await executor.execute(executionId, definition, {});

    expect(stats.calls).toBe(3);
    expect(stats.maxInFlight).toBe(1);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('succeeded');
  });

  it('fails the execution with NODE_TIMEOUT when a node exceeds its timeout', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(createHangingAdapter('hang'));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('stuck', 'hang.op')],
      edges: [],
      variables: {},
      metadata: { name: 'timeout' },
    };
    const executionId = await seedExecution(store, definition);

    // V1.5 M1 (F-4', TH2): node timeout widened 50ms→200ms so the timer is not
    // starved under high load; the adapter still never resolves, so the timeout
    // race is deterministic. The assertion is unchanged apart from the value.
    const executor = new ExecutionExecutor(store, connectors, 10, 200);

    await expect(executor.execute(executionId, definition, {})).rejects.toThrow(/timed out after 200ms/);

    const execution = await store.executions.getById(executionId);
    expect(execution?.status).toBe('failed');
    expect(execution?.error).toMatch(/timed out/);

    const nodeExecs = await store.nodeExecutions.listByExecution(executionId);
    expect(nodeExecs).toHaveLength(1);
    expect(nodeExecs[0]!.status).toBe('failed');
    expect(nodeExecs[0]!.error).toMatch(/timed out/);
  });

  it('honours a per-node timeout_ms override', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(createHangingAdapter('hang'));

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [{ id: 'stuck', type: 'hang.op', position: { x: 0, y: 0 }, config: {}, timeout_ms: 200 }],
      edges: [],
      variables: {},
      metadata: { name: 'per-node-timeout' },
    };
    const executionId = await seedExecution(store, definition);

    // Executor-wide timeout is large, but the node override (200ms) wins.
    // V1.5 M1 (F-4', TH2): override widened 30ms→200ms for high-load stability;
    // it still differs from the 60_000ms executor default, so the override is proven.
    const executor = new ExecutionExecutor(store, connectors, 10, 60_000);
    await expect(executor.execute(executionId, definition, {})).rejects.toThrow(/timed out after 200ms/);
  });
});

/**
 * Regression tests for the BranchNode condition evaluator (S5).
 *
 * The evaluator previously compiled condition strings with `new Function`,
 * letting a workflow author execute arbitrary JavaScript in the API process.
 * It now uses a restricted parser: comparisons, &&/||/! and literals only.
 */

import { describe, it, expect, vi } from 'vitest';
import { BranchNode, LoopNode } from '../../../packages/engine/src/nodes/index';

vi.mock('@loop/observability', () => ({
  createLogger: () => ({ debug: () => {}, info: () => {}, warn: () => {}, error: () => {} }),
}));

describe('BranchNode — restricted condition evaluator (S5)', () => {
  const branches = (condition: string) => [{ id: 'yes', condition }];

  it('evaluates numeric comparisons against interpolated values', () => {
    expect(BranchNode.evaluate(branches('{{ctx.count}} > 5'), { ctx: { count: 7 } })).toBe('yes');
    expect(BranchNode.evaluate(branches('{{ctx.count}} > 5'), { ctx: { count: 3 } })).toBeNull();
    expect(BranchNode.evaluate(branches('{{ctx.count}} <= 5'), { ctx: { count: 3 } })).toBe('yes');
  });

  it('evaluates string equality', () => {
    expect(BranchNode.evaluate(branches('{{ctx.status}} == "active"'), { ctx: { status: 'active' } })).toBe('yes');
    expect(BranchNode.evaluate(branches('{{ctx.status}} != "active"'), { ctx: { status: 'paused' } })).toBe('yes');
  });

  it('supports && / || / ! and parentheses', () => {
    expect(BranchNode.evaluate(branches('{{ctx.a}} > 1 && {{ctx.b}} < 2'), { ctx: { a: 2, b: 1 } })).toBe('yes');
    expect(BranchNode.evaluate(branches('{{ctx.a}} > 1 || {{ctx.b}} < 2'), { ctx: { a: 0, b: 1 } })).toBe('yes');
    expect(BranchNode.evaluate(branches('{{ctx.a}} > 1 || {{ctx.b}} < 2'), { ctx: { a: 0, b: 9 } })).toBeNull();
    expect(BranchNode.evaluate(branches('!{{ctx.flag}}'), { ctx: { flag: false } })).toBe('yes');
    expect(BranchNode.evaluate(branches('({{ctx.a}} == 1 || {{ctx.b}} == 2) && {{ctx.c}}'), { ctx: { a: 1, b: 0, c: true } })).toBe('yes');
  });

  it('evaluates bare booleans and literals', () => {
    expect(BranchNode.evaluate(branches('true'), {})).toBe('yes');
    expect(BranchNode.evaluate(branches('false'), {})).toBeNull();
  });

  it('does NOT execute JavaScript — injections fail closed to false', () => {
    const malicious = 'process.exit(1)';
    expect(BranchNode.evaluate(branches(malicious), {})).toBeNull();

    const exfiltration = 'globalThis.require("node:child_process")';
    expect(BranchNode.evaluate(branches(exfiltration), {})).toBeNull();

    const constructor = '{{ctx.x}}.constructor("return 1")()';
    expect(BranchNode.evaluate(branches(constructor), { ctx: { x: 1 } })).toBeNull();
  });

  it('fails closed on malformed conditions', () => {
    expect(BranchNode.evaluate(branches('{{ctx.a}} >'), { ctx: { a: 1 } })).toBeNull();
    expect(BranchNode.evaluate(branches('(true'), {})).toBeNull();
    expect(BranchNode.evaluate(branches('"unterminated'), {})).toBeNull();
  });
});

describe('LoopNode', () => {
  it('continues only while the condition holds and stops at max iterations', () => {
    expect(LoopNode.shouldContinue('{{i}} < 3', { i: 1 }, 0)).toBe(true);
    expect(LoopNode.shouldContinue('{{i}} < 3', { i: 5 }, 0)).toBe(false);
    // An unresolved reference must NOT satisfy the comparison.
    expect(LoopNode.shouldContinue('{{missing}} < 3', {}, 0)).toBe(false);
    expect(LoopNode.shouldContinue('true', {}, 1000)).toBe(false);
  });
});

