    trigger_type: 'manual',
    trigger_payload: {},
  });
  return executionId;
}

function node(id: string, type: string) {
  return { id, type, position: { x: 0, y: 0 }, config: {} };
}

function event(
  executionId: string,
  seq: number,
  event_type: ExecutionEvent['event_type'],
  node_id: string | undefined,
  payload: Record<string, unknown> = {},
): ExecutionEvent {
  return {
    id: `${executionId}-${seq}`,
    execution_id: executionId,
    event_type,
    ...(node_id !== undefined ? { node_id } : {}),
    payload,
    created_at: 1_700_000_000_000 + seq * 1000,
  };
}

const TWO_NODE: WorkflowDefinition = {
  version: '1.0',
  nodes: [node('a', 'ok.op'), node('b', 'bad.op')],
  edges: [{ id: 'e', source: 'a', target: 'b' }],
  variables: {},
  metadata: { name: 'two-node' },
};

describe('replay — foldExecutionEvents (R1, pure)', () => {
  it('folds an event sequence into the correct snapshot', () => {
    const execId = 'exec-fold';
    const events = [
      event(execId, 1, 'execution_started', undefined),
      event(execId, 2, 'node_started', 'a'),
      event(execId, 3, 'node_succeeded', 'a', { output: { ok: true } }),
      event(execId, 4, 'node_started', 'b'),
      event(execId, 5, 'node_failed', 'b', { error: 'boom' }),
      event(execId, 6, 'execution_failed', undefined, { error: 'boom', reason: 'node_error' }),
    ];

    const snap = foldExecutionEvents(execId, events);

    expect(snap.executionId).toBe(execId);
    expect(snap.status).toBe('failed');
    expect(snap.startedAt).toBe(new Date(1_700_000_001_000).toISOString());
    expect(snap.endedAt).toBe(new Date(1_700_000_006_000).toISOString());
    expect(snap.error).toBe('boom');

    expect(snap.nodeStates.get('a')).toMatchObject({ status: 'succeeded', output: { ok: true } });
    expect(snap.nodeStates.get('b')).toMatchObject({ status: 'failed', error: 'boom' });

    expect(snap.timeline).toHaveLength(6);
    expect(snap.timeline[0]).toMatchObject({ type: 'execution_started' });
    expect(snap.timeline[5]).toMatchObject({ type: 'execution_failed', detail: 'boom' });
  });

  it('folds a fully-succeeded execution and a skipped node', () => {
    const execId = 'exec-ok';
    const events = [
      event(execId, 1, 'execution_started', undefined, { resumed: true }),
      event(execId, 2, 'node_skipped', 'a', { reason: 'already_succeeded' }),
      event(execId, 3, 'node_started', 'b'),
      event(execId, 4, 'node_succeeded', 'b'),
      event(execId, 5, 'execution_succeeded', undefined),
    ];

    const snap = foldExecutionEvents(execId, events);
    expect(snap.status).toBe('succeeded');
    expect(snap.nodeStates.get('a')).toMatchObject({ status: 'skipped' });
    expect(snap.nodeStates.get('b')).toMatchObject({ status: 'succeeded' });
  });

  it('is deterministic — same events yield an equal snapshot', () => {
    const execId = 'exec-det';
    const events = [
      event(execId, 1, 'execution_started', undefined),
      event(execId, 2, 'node_succeeded', 'a', { output: { v: 1 } }),
      event(execId, 3, 'execution_succeeded', undefined),
    ];
    const first = foldExecutionEvents(execId, events);
    const second = foldExecutionEvents(execId, events);
    expect(second).toEqual(first);
  });
});

describe('replay — reconstructExecution (R1, store-backed)', () => {
  const conns: SqliteConnection[] = [];
  afterEach(() => {
    while (conns.length > 0) conns.pop()!.close();
  });

  it('reconstructs from persisted execution_events after a real run', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(okAdapter('ok').adapter);
    connectors.registerAdapter(failingAdapter('bad').adapter);

    const executionId = await seedExecution(store, TWO_NODE);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await expect(executor.execute(executionId, TWO_NODE, {})).rejects.toThrow(/bad exploded/);

    const snap = await reconstructExecution(store, executionId);
    expect(snap.status).toBe('failed');
    expect(snap.nodeStates.get('a')?.status).toBe('succeeded');
    expect(snap.nodeStates.get('b')?.status).toBe('failed');
    expect(snap.timeline.some((t) => t.type === 'execution_failed')).toBe(true);
  });
});

describe('replay — replayExecution dry-run (R2)', () => {
  const conns: SqliteConnection[] = [];
  afterEach(() => {
    while (conns.length > 0) conns.pop()!.close();
  });

  it('dry-run does NOT invoke connectors and yields correct decisions (failed run)', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const ok = okAdapter('ok');
    const bad = failingAdapter('bad');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(ok.adapter);
    connectors.registerAdapter(bad.adapter);

    const executionId = await seedExecution(store, TWO_NODE);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await expect(executor.execute(executionId, TWO_NODE, {})).rejects.toThrow(/bad exploded/);

    const callsBefore = { ok: ok.counter.calls, bad: bad.counter.calls };
    expect(callsBefore.ok).toBe(1);
    expect(callsBefore.bad).toBe(1);

    // DEFAULT dry-run (no options) — must be side-effect-free.
    const result = await replayExecution(executor, store, executionId);
    expect(result.dryRun).toBe(true);
    expect(result.snapshot.status).toBe('failed');

    // Connectors were NOT called again by the dry-run.
    expect(ok.counter.calls).toBe(callsBefore.ok);
    expect(bad.counter.calls).toBe(callsBefore.bad);

    const byNode = new Map(result.decisions.map((d) => [d.nodeId, d.decision]));
    expect(byNode.get('a')).toBe('skipped-because-succeeded');
    expect(byNode.get('b')).toBe('failed');
    expect(result.rerun).toBeUndefined();
  });

  it('dry-run marks every node skipped-because-succeeded for a completed run', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const ok = okAdapter('ok');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(ok.adapter);

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('a', 'ok.op'), node('b', 'ok.op')],
      edges: [{ id: 'e', source: 'a', target: 'b' }],
      variables: {},
      metadata: { name: 'all-ok' },
    };
    const executionId = await seedExecution(store, definition);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await executor.execute(executionId, definition, {});
    expect(ok.counter.calls).toBe(2);

    const result = await replayExecution(executor, store, executionId, { dryRun: true });
    expect(ok.counter.calls).toBe(2); // unchanged — no side effects
    expect(result.decisions.every((d) => d.decision === 'skipped-because-succeeded')).toBe(true);
  });

  it('dry-run marks never-reached nodes as would-run', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(okAdapter('ok').adapter);

    // Execution created but never run → no events at all.
    const executionId = await seedExecution(store, TWO_NODE);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);

    const result = await replayExecution(executor, store, executionId, { dryRun: true });
    expect(result.snapshot.status).toBe('pending');
    expect(result.decisions.every((d) => d.decision === 'would-run')).toBe(true);
  });

  it('computeReplayDecisions orders decisions topologically', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);
    const executionId = await seedExecution(store, TWO_NODE);
    const snap = await reconstructExecution(store, executionId);
    const decisions = computeReplayDecisions(TWO_NODE, snap);
    expect(decisions.map((d) => d.nodeId)).toEqual(['a', 'b']);
  });

  it('dryRun=false re-executes via the resume path, skipping succeeded nodes', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);

    const ok = okAdapter('ok');
    const connectors = new ConnectorRegistry();
    connectors.registerAdapter(ok.adapter);

    const definition: WorkflowDefinition = {
      version: '1.0',
      nodes: [node('a', 'ok.op'), node('b', 'ok.op')],
      edges: [{ id: 'e', source: 'a', target: 'b' }],
      variables: {},
      metadata: { name: 'rerun-ok' },
    };
    const executionId = await seedExecution(store, definition);
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await executor.execute(executionId, definition, {});
    expect(ok.counter.calls).toBe(2);

    // Real re-run: both nodes already succeeded → resume skips both (no dispatch).
    const result = await replayExecution(executor, store, executionId, { dryRun: false });
    expect(result.dryRun).toBe(false);
    expect(result.rerun?.status).toBe('succeeded');
    expect(result.rerun?.outputs).toHaveProperty('a');
    expect(result.rerun?.outputs).toHaveProperty('b');
    expect(ok.counter.calls).toBe(2); // unchanged — succeeded nodes skipped
  });

  it('throws NOT_FOUND for an unknown execution', async () => {
    const { conn, store } = await createStore();
    conns.push(conn);
    const connectors = new ConnectorRegistry();
    const executor = new ExecutionExecutor(store, connectors, 10, 5_000);
    await expect(replayExecution(executor, store, crypto.randomUUID())).rejects.toThrow(/not found/);
  });
});

import { describe, it, expect, vi } from 'vitest';
import { executeWithRetry, calculateBackoff } from '../../../packages/engine/src/retry';
import type { RetryConfig } from '../../../packages/engine/src/retry';

describe('executeWithRetry', () => {
  it('should succeed on first try without retries', async () => {
    const fn = vi.fn().mockResolvedValue('success');
    const config: RetryConfig = {
      max_attempts: 3,
      backoff: 'exponential',
      initial_delay_ms: 100,
    };

    const result = await executeWithRetry(fn, config);

    expect(result).toBe('success');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('should succeed after 2 retries', async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error('fail 1'))
      .mockRejectedValueOnce(new Error('fail 2'))
      .mockResolvedValue('success');

    const config: RetryConfig = {
      max_attempts: 3,
      backoff: 'exponential',
      initial_delay_ms: 10,
    };

    const result = await executeWithRetry(fn, config);

    expect(result).toBe('success');
    expect(fn).toHaveBeenCalledTimes(3);
  });

  it('should fail after max attempts exhausted', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('persistent failure'));
    const config: RetryConfig = {
      max_attempts: 3,
      backoff: 'exponential',
      initial_delay_ms: 10,
    };

    await expect(executeWithRetry(fn, config)).rejects.toThrow('persistent failure');
    expect(fn).toHaveBeenCalledTimes(4); // 1 initial + 3 retries
  });

  it('should call onRetry callback for each retry', async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error('fail 1'))
      .mockRejectedValueOnce(new Error('fail 2'))
      .mockResolvedValue('success');

    const config: RetryConfig = {
      max_attempts: 3,
      backoff: 'exponential',
      initial_delay_ms: 10,
    };

    const onRetry = vi.fn();

    await executeWithRetry(fn, config, onRetry);

    expect(onRetry).toHaveBeenCalledTimes(2);
    expect(onRetry).toHaveBeenNthCalledWith(1, 1, expect.any(Error));
    expect(onRetry).toHaveBeenNthCalledWith(2, 2, expect.any(Error));
  });

  it('should respect zero max_attempts (no retries)', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('fail'));
    const config: RetryConfig = {
      max_attempts: 0,
      backoff: 'exponential',
      initial_delay_ms: 100,
    };

    await expect(executeWithRetry(fn, config)).rejects.toThrow('fail');
    expect(fn).toHaveBeenCalledTimes(1);
  });
});

describe('calculateBackoff', () => {
  describe('Exponential backoff', () => {
    it('should calculate exponential backoff correctly', () => {
      const baseDelay = 100;

      expect(calculateBackoff('exponential', baseDelay, 0)).toBe(100); // 100 * 2^0
      expect(calculateBackoff('exponential', baseDelay, 1)).toBe(200); // 100 * 2^1
      expect(calculateBackoff('exponential', baseDelay, 2)).toBe(400); // 100 * 2^2
      expect(calculateBackoff('exponential', baseDelay, 3)).toBe(800); // 100 * 2^3
    });

    it('should apply jitter when enabled', () => {
      const baseDelay = 100;
      const delay1 = calculateBackoff('exponential', baseDelay, 2, true);
      const delay2 = calculateBackoff('exponential', baseDelay, 2, true);

      // With jitter, delays should vary (within ±10% of 400)
      expect(delay1).toBeGreaterThanOrEqual(360);
      expect(delay1).toBeLessThanOrEqual(440);
      expect(delay2).toBeGreaterThanOrEqual(360);
      expect(delay2).toBeLessThanOrEqual(440);
      // They should likely be different (though not guaranteed due to randomness)
    });
  });

  describe('Linear backoff', () => {
    it('should calculate linear backoff correctly', () => {
      const baseDelay = 100;

      expect(calculateBackoff('linear', baseDelay, 0)).toBe(100); // 100 * (0+1)
      expect(calculateBackoff('linear', baseDelay, 1)).toBe(200); // 100 * (1+1)
      expect(calculateBackoff('linear', baseDelay, 2)).toBe(300); // 100 * (2+1)
      expect(calculateBackoff('linear', baseDelay, 3)).toBe(400); // 100 * (3+1)
    });

    it('should apply jitter when enabled', () => {
      const baseDelay = 100;
      const delay = calculateBackoff('linear', baseDelay, 2, true);

      // With jitter, delay should vary (within ±10% of 300)
      expect(delay).toBeGreaterThanOrEqual(270);
      expect(delay).toBeLessThanOrEqual(330);
    });
  });

  describe('Fixed backoff', () => {
    it('should return constant delay regardless of attempt', () => {
      const baseDelay = 100;

      expect(calculateBackoff('fixed', baseDelay, 0)).toBe(100);
      expect(calculateBackoff('fixed', baseDelay, 1)).toBe(100);
      expect(calculateBackoff('fixed', baseDelay, 2)).toBe(100);
      expect(calculateBackoff('fixed', baseDelay, 3)).toBe(100);
    });

    it('should apply jitter when enabled', () => {
      const baseDelay = 100;
      const delay = calculateBackoff('fixed', baseDelay, 5, true);

      // With jitter, delay should vary (within ±10% of 100)
      expect(delay).toBeGreaterThanOrEqual(90);
      expect(delay).toBeLessThanOrEqual(110);
    });
  });

  describe('Edge cases', () => {
    it('should handle unknown backoff strategy as fixed', () => {
      const delay = calculateBackoff('unknown', 100, 5);
      expect(delay).toBe(100);
    });

    it('should ensure delay is never negative', () => {
      const delay = calculateBackoff('exponential', 0, 0);
      expect(delay).toBe(0);
    });

    it('should round delay to nearest integer', () => {
      const delay = calculateBackoff('linear', 100, 0, true);
      expect(Number.isInteger(delay)).toBe(true);
    });
  });
});

import { describe, it, expect } from 'vitest';
import { topologicalSort, computeLevels } from '../../../packages/engine/src/scheduler';
import { ValidationError } from '../../../packages/types/src/errors';
import type { WorkflowNode, WorkflowEdge } from '../../../packages/types/src/schemas/workflow';

function createNode(id: string): WorkflowNode {
  return {
    id,
    type: 'test',
    position: { x: 0, y: 0 },
    config: {},
  };
}

function createEdge(source: string, target: string): WorkflowEdge {
  return {
    id: `${source}-${target}`,
    source,
    target,
    source_port: 'output',
    target_port: 'input',
    type_compatibility: true,
  };
}

describe('topologicalSort', () => {
  it('should sort diamond DAG correctly (A→B, A→C, B→D, C→D)', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C'), createNode('D')];
    const edges = [
      createEdge('A', 'B'),
      createEdge('A', 'C'),
      createEdge('B', 'D'),
      createEdge('C', 'D'),
    ];

    const sorted = topologicalSort(nodes, edges);
    const ids = sorted.map((n) => n.id);

    // A must come before B and C
    expect(ids.indexOf('A')).toBeLessThan(ids.indexOf('B'));
    expect(ids.indexOf('A')).toBeLessThan(ids.indexOf('C'));
    // B and C must come before D
    expect(ids.indexOf('B')).toBeLessThan(ids.indexOf('D'));
    expect(ids.indexOf('C')).toBeLessThan(ids.indexOf('D'));
    // All nodes present
    expect(sorted).toHaveLength(4);
  });

  it('should throw ValidationError on cycle detection', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C')];
    const edges = [createEdge('A', 'B'), createEdge('B', 'C'), createEdge('C', 'A')];

    try {
      topologicalSort(nodes, edges);
      expect.fail('Should have thrown ValidationError');
    } catch (err) {
      expect(err).toBeInstanceOf(Error);
      expect((err as Error).message).toMatch(/Circular dependency detected/);
      expect((err as Error).name).toBe('ValidationError');
    }
  });

  it('should return empty array for empty workflow', () => {
    const nodes: WorkflowNode[] = [];
    const edges: WorkflowEdge[] = [];

    const sorted = topologicalSort(nodes, edges);
    expect(sorted).toEqual([]);
    expect(sorted).toHaveLength(0);
  });

  it('should handle linear chain (A→B→C→D)', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C'), createNode('D')];
    const edges = [createEdge('A', 'B'), createEdge('B', 'C'), createEdge('C', 'D')];

    const sorted = topologicalSort(nodes, edges);
    const ids = sorted.map((n) => n.id);

    expect(ids).toEqual(['A', 'B', 'C', 'D']);
  });

  it('should handle disconnected nodes', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C')];
    const edges: WorkflowEdge[] = [];

    const sorted = topologicalSort(nodes, edges);
    expect(sorted).toHaveLength(3);
    expect(sorted.map((n) => n.id)).toEqual(expect.arrayContaining(['A', 'B', 'C']));
  });
});

describe('computeLevels', () => {
  it('should group nodes by execution level for parallel execution', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C'), createNode('D')];
    const edges = [
      createEdge('A', 'B'),
      createEdge('A', 'C'),
      createEdge('B', 'D'),
      createEdge('C', 'D'),
    ];

    const levels = computeLevels(nodes, edges);

    // Level 0: A (no dependencies)
    expect(levels[0]).toHaveLength(1);
    expect(levels[0][0].id).toBe('A');

    // Level 1: B and C (can run in parallel)
    expect(levels[1]).toHaveLength(2);
    const level1Ids = levels[1].map((n) => n.id);
    expect(level1Ids).toContain('B');
    expect(level1Ids).toContain('C');

    // Level 2: D (depends on B and C)
    expect(levels[2]).toHaveLength(1);
    expect(levels[2][0].id).toBe('D');
  });

  it('should return empty array for empty workflow', () => {
    const nodes: WorkflowNode[] = [];
    const edges: WorkflowEdge[] = [];

    const levels = computeLevels(nodes, edges);
    expect(levels).toEqual([]);
  });

  it('should handle linear chain as separate levels', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C')];
    const edges = [createEdge('A', 'B'), createEdge('B', 'C')];

    const levels = computeLevels(nodes, edges);

    expect(levels).toHaveLength(3);
    expect(levels[0][0].id).toBe('A');
    expect(levels[1][0].id).toBe('B');
    expect(levels[2][0].id).toBe('C');
  });

  it('should handle all independent nodes in one level', () => {
    const nodes = [createNode('A'), createNode('B'), createNode('C')];
    const edges: WorkflowEdge[] = [];

    const levels = computeLevels(nodes, edges);

    expect(levels).toHaveLength(1);
    expect(levels[0]).toHaveLength(3);
  });
});

describe('Performance test', () => {
  // V1.5 M1 (F-4', TH2): the bound was 50ms, which flakes under high load because
  // `Date.now()` wall-clock measurement is at the mercy of OS scheduling/GC pauses.
  // A 200-node linear DAG sorts in well under 1ms normally; the generous 1000ms
  // ceiling still guards against a pathological regression without load flakiness.
  // The assertion is retained — only the margin widened.
  it('should handle 200-node DAG in less than 1000ms', () => {
    // Create a complex DAG with 200 nodes
    const nodes: WorkflowNode[] = [];
    const edges: WorkflowEdge[] = [];

    for (let i = 0; i < 200; i++) {
      nodes.push(createNode(`node-${i}`));
    }

    // Create a realistic DAG structure
    for (let i = 0; i < 199; i++) {
      edges.push(createEdge(`node-${i}`, `node-${i + 1}`));
    }

    const start = Date.now();
    const sorted = topologicalSort(nodes, edges);
    const duration = Date.now() - start;

    expect(sorted).toHaveLength(200);
    expect(duration).toBeLessThan(1000);
  });
});

